INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "画家は下絵が描いてから、色を重ねました。", "corrected_sentence": "画家は下絵を描いてから、色を重ねました。", "error_description": "「描く」の対象は「を」で示す。「が」は誤りで、下絵は描かれるものなので「を」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生は下絵を読んで、構図を直しました。", "corrected_sentence": "先生は下絵を見て、構図を直しました。", "error_description": "下絵とつながる動詞は「見る」。「読む」は誤りで、ここでは内容を見て判断している。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「使い分ける」の目的語（使うかばん）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示すので、「かばんに使い分けます」では目的語を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「かばんが使い分けます」ではかばんが主体になり、文の意味が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、「かばんへ使い分けます」では目的語を示せない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「使い分ける」の目的語（使うかばん）を示す格助詞。", "に": "位置や相手を示すので、「かばんに使い分けます」では目的語を示せない。", "が": "主語を示す。「かばんが使い分けます」ではかばんが主体になり、文の意味が成り立たない。", "へ": "方向を示すので、「かばんへ使い分けます」では目的語を示せない。"}, "error_tags": {"に": "位置・相手（〜に）", "が": "主語（〜が）", "へ": "方向（〜へ）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「使い分ける」の目的語（ボール）を示す格助詞。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同を示す。「ボールと使い分けています」では目的語を示せず、文の意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「ボールから使い分けています」では目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「ボールより使い分けています」では比べる対象になり、目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「使い分ける」の目的語（ボール）を示す格助詞。", "と": "並列・共同を示す。「ボールと使い分けています」では目的語を示せず、文の意味が通らない。", "から": "起点を示す。「ボールから使い分けています」では目的語にならない。", "より": "比較を示す。「ボールより使い分けています」では比べる対象になり、目的語にはならない。"}, "error_tags": {"と": "並列・共同（〜と）", "から": "起点（〜から）", "より": "比較（〜より）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "使うものを、場面に合わせて、ちがうものに変えること。", "primary_collocate": null, "pronunciation": "つかいわける", "ipa": "tsɯkaiwakeɾɯ", "syllable_count": 6, "sentences": [{"text": "雨の日と晴れの日で、くつを使い分けています。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "雨(あめ)の日(ひ)と晴(は)れの日(ひ)で、くつを使(つか)い分(わ)けています。", "sentence_source": "generated"}, {"text": "学校用と家用で、かばんを使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "学校用(がっこうよう)と家用(いえよう)で、かばんを使(つか)い分(わ)けます。", "sentence_source": "generated"}, {"text": "姉は場面に合わせて、ペンの色を使い分けています。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "姉(あね)は場面(ばめん)に合(あ)わせて、ペンの色(いろ)を使(つか)い分(わ)けています。", "sentence_source": "generated"}, {"text": "夏と冬でコップを使い分けると、気分が変わります。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "夏(なつ)と冬(ふゆ)でコップを使(つか)い分(わ)けると、気分(きぶん)が変(か)わります。", "sentence_source": "generated"}, {"text": "友だちの中には、話す相手によって言い方を使い分ける人がいます。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "友(とも)だちの中(なか)には、話(はな)す相手(あいて)によって言(い)い方(かた)を使(つか)い分(わ)ける人(ひと)がいます。", "sentence_source": "generated"}, {"text": "洗たくでは、白い服と色のある服で洗剤を使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "洗(せん)たくでは、白(しろ)い服(ふく)と色(いろ)のある服(ふく)で洗剤(せんざい)を使(つか)い分(わ)けます。", "sentence_source": "generated"}, {"text": "母は料理に合わせて、お皿を使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "母(はは)は料理(りょうり)に合(あ)わせて、お皿(さら)を使(つか)い分(わ)けます。", "sentence_source": "generated"}, {"text": "弟はサッカーと野球で、ボールを使い分けています。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "弟(おとうと)はサッカーと野球(やきゅう)で、ボールを使(つか)い分(わ)けています。", "sentence_source": "generated"}, {"text": "仕事用と遊び用で、メールのアドレスを使い分けています。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "仕事用(しごとよう)と遊(あそ)び用(よう)で、メールのアドレスを使(つか)い分(わ)けています。", "sentence_source": "generated"}, {"text": "台所では、場所によってスポンジを使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "台所(だいどころ)では、場所(ばしょ)によってスポンジを使(つか)い分(わ)けます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い分ける", "label": "辞書形"}, {"form": "使い分けます", "label": "丁寧形"}, {"form": "使い分けた", "label": "過去形"}, {"form": "使い分けて", "label": "て形"}, {"form": "使い分けない", "label": "否定形"}, {"form": "使い分けられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "場面に合わせて使う物を別の物に変える(日常の持ち物・道具)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い分けて", "is_correct": true, "explanation": "て形。「くつを使い分けています」の「使い分けて」にあたり、「います」に続く形。"}, {"text": "使い分けない", "is_correct": false, "explanation": "否定形。「くつを使い分けないいます」となり、「います」に続かないので入らない。"}, {"text": "使い分けた", "is_correct": false, "explanation": "過去形。「使い分けたいます」となり、「ている」の形にならない。"}, {"text": "使い分けろ", "is_correct": false, "explanation": "命令形。「使い分けろいます」となり、「ている」の形に続けられない。"}], "explanations": {"使い分けて": "て形。「くつを使い分けています」の「使い分けて」にあたり、「います」に続く形。", "使い分けない": "否定形。「くつを使い分けないいます」となり、「います」に続かないので入らない。", "使い分けた": "過去形。「使い分けたいます」となり、「ている」の形にならない。", "使い分けろ": "命令形。「使い分けろいます」となり、「ている」の形に続けられない。"}, "sentence_index": 0, "correct_answer": "使い分けて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "使わなくなった家具を使い分けることにしました。", "explanation": "ここは〈処分する〉の意味。使い分けるは場面に応じて使うものを選ぶことで、要らなくなったものを捨てる意味はないので合わない。"}, {"text": "古くなったくつを使い分けて、新しいものにしました。", "explanation": "ここは〈取り替える〉の意味。使い分けるは使うものを場面ごとに変えることで、古いものを新しいものに替える意味はないので合わない。"}, {"text": "壊れた時計を、ついに使い分けて直しました。", "explanation": "ここは〈修理する〉の意味。使い分けるは場面に応じて物を選んで使うことで、壊れた物を直す意味は含まないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い分けます", "is_correct": true, "explanation": "丁寧形。「母は料理に合わせて、お皿を〜」と述べる文の述語として、文末を締める形。"}, {"text": "使い分け", "is_correct": false, "explanation": "連用形。文を終えられず、「お皿を使い分け。」は文として不完全。"}, {"text": "使い分けたり", "is_correct": false, "explanation": "たり形は並列の途中の形。文末に置くと文が不完全になる。"}, {"text": "使い分けなければ", "is_correct": false, "explanation": "仮定・必要の形。「なければ」で続くため文末には入らず、この文の述語にならない。"}], "explanations": {"使い分けます": "丁寧形。「母は料理に合わせて、お皿を〜」と述べる文の述語として、文末を締める形。", "使い分け": "連用形。文を終えられず、「お皿を使い分け。」は文として不完全。", "使い分けたり": "たり形は並列の途中の形。文末に置くと文が不完全になる。", "使い分けなければ": "仮定・必要の形。「なければ」で続くため文末には入らず、この文の述語にならない。"}, "sentence_index": 6, "correct_answer": "使い分けます"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "石けんが足りなくなったので、同じ石けんを使い分けました。", "explanation": "ここは〈買い足す〉の意味。使い分けるは場面に応じて物を変えることで、足りなくなったものを買い増す意味はないので合わない。"}, {"text": "古いペンを、最後まで使い分けた。", "explanation": "ここは〈使いつぶす〉の意味。使い分けるは場面ごとに物を選ぶことで、一つの物を使い切るまで使う意味は含まないので合わない。"}, {"text": "郵便物を地域ごとに使い分けました。", "explanation": "ここは〈仕分ける〉の意味。使い分けるは物を場面に応じて変えて使うことで、郵便物を分類する意味には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晴れの日と雨の日で、傘に使い分けています。", "corrected_sentence": "晴れの日と雨の日で、傘を使い分けています。", "error_description": "「使い分ける」は他動詞なので、使うものは「を」で示す。「に」にすると目的語が示せず、自然な文にならない。誤りは「に」、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "使い分けます", "is_correct": true, "explanation": "丁寧形。文末を締める形で、「かばんを使い分けます。」と文が完結する。"}, {"text": "使い分けて", "is_correct": false, "explanation": "て形。文末に置くと文が終わらず、「かばんを使い分けて。」は不完全な文になる。"}, {"text": "使い分け", "is_correct": false, "explanation": "連用形。文末に置くと文が終わらず、不完全な文になる。"}, {"text": "使い分けたり", "is_correct": false, "explanation": "たり形。並列の途中で使う形で、文末に置くと文が完結しない。"}], "correct_form": "使い分けます", "base_form": "使い分ける", "form_label": "丁寧形", "sentence_index": 1, "explanations": {"使い分けます": "丁寧形。文末を締める形で、「かばんを使い分けます。」と文が完結する。", "使い分けて": "て形。文末に置くと文が終わらず、「かばんを使い分けて。」は不完全な文になる。", "使い分け": "連用形。文末に置くと文が終わらず、不完全な文になる。", "使い分けたり": "たり形。並列の途中で使う形で、文末に置くと文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51875, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用事によって、財布とポーチを使い分けるています。", "corrected_sentence": "用事によって、財布とポーチを使い分けています。", "error_description": "「使い分けている」は連用形「使い分け」に「ている」を続けた形。辞書形「使い分ける」に「ている」を続けた「使い分けるている」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "使い分けて", "is_correct": true, "explanation": "て形。「使い分けています」の「使い分けて」にあたり、「いる」に続く形。"}, {"text": "使い分ける", "is_correct": false, "explanation": "辞書形。「ています」に続けると形が合わず、この位置には入らない。"}, {"text": "使い分けよう", "is_correct": false, "explanation": "意志形。「ています」に続けられず、この文の事実を述べる内容と合わない。"}, {"text": "使い分け", "is_correct": false, "explanation": "連用形。「使い分けいます」となり、「て」が抜けて「ています」にならない。"}], "correct_form": "使い分けて", "base_form": "使い分ける", "form_label": "て形", "sentence_index": 7, "explanations": {"使い分けて": "て形。「使い分けています」の「使い分けて」にあたり、「いる」に続く形。", "使い分ける": "辞書形。「ています」に続けると形が合わず、この位置には入らない。", "使い分けよう": "意志形。「ています」に続けられず、この文の事実を述べる内容と合わない。", "使い分け": "連用形。「使い分けいます」となり、「て」が抜けて「ています」にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「使い分ける」の目的語（使う言葉）を示す格助詞。"}, {"text": "に", "is_correct": false, "explanation": "位置や相手を示すので、「言葉に使い分けて」では目的語を示せない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「言葉が使い分けている」では言葉が主体になり、文の意味が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾を示す。名詞同士を結ぶ助詞なので、動詞の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「使い分ける」の目的語（使う言葉）を示す格助詞。", "に": "位置や相手を示すので、「言葉に使い分けて」では目的語を示せない。", "が": "主語を示す。「言葉が使い分けている」では言葉が主体になり、文の意味が成り立たない。", "の": "連体修飾を示す。名詞同士を結ぶ助詞なので、動詞の目的語にはならない。"}, "error_tags": {"に": "位置・相手（〜に）", "が": "主語（〜が）", "の": "連体修飾（〜の）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「使い分ける」の目的語（「は」と「が」）を示す格助詞。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示すので、「〜へ使い分ける」では目的語を示せない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「「は」と「が」から使い分ける」は目的語にならない。"}, {"text": "と", "is_correct": false, "explanation": "並列・共同を示す。「「は」と「が」と使い分ける」では目的語を示せず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "他動詞「使い分ける」の目的語（「は」と「が」）を示す格助詞。", "へ": "方向を示すので、「〜へ使い分ける」では目的語を示せない。", "から": "起点を示す。「「は」と「が」から使い分ける」は目的語にならない。", "と": "並列・共同を示す。「「は」と「が」と使い分ける」では目的語を示せず、文が成り立たない。"}, "error_tags": {"へ": "方向（〜へ）", "から": "起点（〜から）", "と": "並列・共同（〜と）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "目的や状況に応じて、適切なものを選んで使うこと。", "primary_collocate": null, "pronunciation": "つかいわける", "ipa": "tsɯkaiwakeɾɯ", "syllable_count": 6, "sentences": [{"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "使い分ける", "complexity_tier": "T4", "furigana": "特(とく)に多色印刷(たしょくいんさつ)の場合(ばあい)、色(いろ)ごとに異(こと)なる版木(はんぎ)を使(つか)い分(わ)ける必要(ひつよう)があり、職人(しょくにん)たちの高度(こうど)な技術(ぎじゅつ)と協力(きょうりょく)が不可欠(ふかけつ)です。", "sentence_source": "mined"}, {"text": "私は相手によって、丁寧な言葉とくだけた言葉を使い分けています。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "私(わたし)は相手(あいて)によって、丁寧(ていねい)な言葉(ことば)とくだけた言葉(ことば)を使(つか)い分(わ)けています。", "sentence_source": "generated"}, {"text": "料理では、肉用と野菜用の包丁を使い分けると衛生的です。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "料理(りょうり)では、肉用(にくよう)と野菜用(やさいよう)の包丁(ほうちょう)を使(つか)い分(わ)けると衛生的(えいせいてき)です。", "sentence_source": "generated"}, {"text": "天気に合わせて、傘とレインコートを使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "天気(てんき)に合(あ)わせて、傘(かさ)とレインコートを使(つか)い分(わ)けます。", "sentence_source": "generated"}, {"text": "彼は仕事用と私用で、二つの携帯電話を使い分けている。", "target_word": "使い分けて", "complexity_tier": "T3", "furigana": "彼(かれ)は仕事用(しごとよう)と私用(しよう)で、二(ふた)つの携帯電話(けいたいでんわ)を使(つか)い分(わ)けている。", "sentence_source": "generated"}, {"text": "筆を使い分けるので、線の太さを自由に変えられます。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "筆(ふで)を使(つか)い分(わ)けるので、線(せん)の太(ふと)さを自由(じゆう)に変(か)えられます。", "sentence_source": "generated"}, {"text": "敬語は、話す相手によって使い分けなければなりません。", "target_word": "使い分けなければ", "complexity_tier": "T3", "furigana": "敬語(けいご)は、話(はな)す相手(あいて)によって使(つか)い分(わ)けなければなりません。", "sentence_source": "generated"}, {"text": "「は」と「が」を使い分けるのが難しいと感じる学習者は多いです。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "「は」と「が」を使(つか)い分(わ)けるのが難(むずか)しいと感(かん)じる学習者(がくしゅうしゃ)は多(おお)いです。", "sentence_source": "generated"}, {"text": "用途ごとにノートを使い分けると、あとで探しやすくなります。", "target_word": "使い分ける", "complexity_tier": "T3", "furigana": "用途(ようと)ごとにノートを使(つか)い分(わ)けると、あとで探(さが)しやすくなります。", "sentence_source": "generated"}, {"text": "季節ごとに、うすい毛布と厚い毛布を使い分けます。", "target_word": "使い分けます", "complexity_tier": "T3", "furigana": "季節(きせつ)ごとに、うすい毛布(もうふ)と厚(あつ)い毛布(もうふ)を使(つか)い分(わ)けます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い分ける", "label": "辞書形"}, {"form": "使い分けます", "label": "丁寧形"}, {"form": "使い分けた", "label": "過去形"}, {"form": "使い分けて", "label": "て形"}, {"form": "使い分けない", "label": "否定形"}, {"form": "使い分けられる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "目的や状況に応じて適切なものを選んで使う(言葉・道具・技術など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い分ける", "is_correct": true, "explanation": "辞書形。「必要があり」の「必要」を修飾する連体形として、動詞の辞書形がここに入る。"}, {"text": "使い分けよう", "is_correct": false, "explanation": "意志形。「必要」を修飾できず、「使い分けよう必要」は成立しない。"}, {"text": "使い分けて", "is_correct": false, "explanation": "て形は「必要」を修飾できない。「使い分けて必要があり」は文として成立しない。"}, {"text": "使い分けます", "is_correct": false, "explanation": "丁寧形は名詞を直接修飾できない。「使い分けます必要」は文法的におかしい。"}], "explanations": {"使い分ける": "辞書形。「必要があり」の「必要」を修飾する連体形として、動詞の辞書形がここに入る。", "使い分けよう": "意志形。「必要」を修飾できず、「使い分けよう必要」は成立しない。", "使い分けて": "て形は「必要」を修飾できない。「使い分けて必要があり」は文として成立しない。", "使い分けます": "丁寧形は名詞を直接修飾できない。「使い分けます必要」は文法的におかしい。"}, "sentence_index": 0, "correct_answer": "使い分ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "紙皿は一度きりなので、使い分けることにしています。", "explanation": "ここは〈使い捨てる〉の意味。使い分けるは場面に応じて複数のものから選んで使うことで、一度使って捨てる意味はないので合わない。"}, {"text": "双子は見た目が似ていて、親でも使い分けるのが難しい。", "explanation": "ここは〈区別する〉の意味。使い分けるは目的に応じて物や言葉を選んで使うことで、人を見分ける意味には使わないので合わない。"}, {"text": "一本のペンを何度も使い分けている。", "explanation": "ここは〈使い回す〉の意味。使い分けるは複数の物を場面で選び分けることで、一つの物を繰り返し使う場合には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い分けなければ", "is_correct": true, "explanation": "未然形に「なければ」を付けた形。「なければなりません」で「〜しなければならない」の意味を作る。"}, {"text": "使い分けろ", "is_correct": false, "explanation": "命令形。「なければ」には続かず、「〜しなければならない」の形にならない。"}, {"text": "使い分けよう", "is_correct": false, "explanation": "意志形。「なければ」に続けられず、この文の必要性を表す形にならない。"}, {"text": "使い分けたり", "is_correct": false, "explanation": "たり形は並列の形。「なければ」に続けられず、文が成り立たない。"}], "explanations": {"使い分けなければ": "未然形に「なければ」を付けた形。「なければなりません」で「〜しなければならない」の意味を作る。", "使い分けろ": "命令形。「なければ」には続かず、「〜しなければならない」の形にならない。", "使い分けよう": "意志形。「なければ」に続けられず、この文の必要性を表す形にならない。", "使い分けたり": "たり形は並列の形。「なければ」に続けられず、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "使い分けなければ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い椅子を、使い分けて直しました。", "explanation": "ここは〈修理する〉の意味。使い分けるは場面に応じて物を選んで使うことで、壊れた物を直す意味は含まないので合わない。"}, {"text": "会社のお金を使い分けて、解雇された。", "explanation": "ここは〈使い込む〉の意味。使い分けるは場面に合わせて物を選ぶことで、他人のお金を勝手に使う意味はないので合わない。"}, {"text": "古くなった冷蔵庫を使い分けました。", "explanation": "ここは〈買い替える〉の意味。使い分けるは同じ物を取り替えるのではなく、目的や場面に応じて選んで使うことを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "気温によって、上着とマフラーに使い分けます。", "corrected_sentence": "気温によって、上着とマフラーを使い分けます。", "error_description": "「使い分ける」は他動詞なので、使うものは「を」で示す。「に」にすると目的語が示せず、自然な文にならない。誤りは「に」、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "使い分けて", "is_correct": true, "explanation": "て形。「使い分けています」の「使い分けて」にあたり、「いる」に続く形。"}, {"text": "使い分けた", "is_correct": false, "explanation": "過去形。「使い分けている」の「て」の形ではなく、「ています」には続かない。"}, {"text": "使い分けない", "is_correct": false, "explanation": "否定形。文の内容（実際にいくつも使い分けている）と反対の意味になり合わない。"}, {"text": "使い分けられる", "is_correct": false, "explanation": "可能形。「できる」の意味になり、実際に使い分けている事実を述べる文には合わない。"}], "correct_form": "使い分けて", "base_form": "使い分ける", "form_label": "て形", "sentence_index": 1, "explanations": {"使い分けて": "て形。「使い分けています」の「使い分けて」にあたり、「いる」に続く形。", "使い分けた": "過去形。「使い分けている」の「て」の形ではなく、「ています」には続かない。", "使い分けない": "否定形。文の内容（実際にいくつも使い分けている）と反対の意味になり合わない。", "使い分けられる": "可能形。「できる」の意味になり、実際に使い分けている事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51876, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用途によって道具を使い分けなければありません。", "corrected_sentence": "用途によって道具を使い分けなければなりません。", "error_description": "「なければなりません」の「なり」を「あり」にすると「なければありません」となり、文として成り立たない。誤りは「あり」、正しくは「なり」（〜しなければならない）。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "使い分ける", "is_correct": true, "explanation": "辞書形。「使い分けるのが難しい」の「のが」に続き、名詞句を作る基本形。"}, {"text": "使い分け", "is_correct": false, "explanation": "連用形。「使い分けのが」と名詞句を作れず、文法的に不自然。"}, {"text": "使い分けたり", "is_correct": false, "explanation": "たり形。「〜たりのが」の形は成立せず、この位置には入らない。"}, {"text": "使い分けろ", "is_correct": false, "explanation": "命令形。この位置では命令になり、「難しいと感じる」という内容と合わない。"}], "correct_form": "使い分ける", "base_form": "使い分ける", "form_label": "辞書形", "sentence_index": 7, "explanations": {"使い分ける": "辞書形。「使い分けるのが難しい」の「のが」に続き、名詞句を作る基本形。", "使い分け": "連用形。「使い分けのが」と名詞句を作れず、文法的に不自然。", "使い分けたり": "たり形。「〜たりのが」の形は成立せず、この位置には入らない。", "使い分けろ": "命令形。この位置では命令になり、「難しいと感じる」という内容と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
