INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「絵画の中の海」と名詞を修飾してつなぐ助詞で、自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す助詞で、「絵画が中の海」は名詞のつながりとして合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す助詞で、「絵画を中の海」は成り立たないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す助詞で、「絵画に中の海」は名詞のつながりとして合わない。"}], "correct_answer": "の", "explanations": {"の": "「絵画の中の海」と名詞を修飾してつなぐ助詞で、自然に続く。", "が": "主語を示す助詞で、「絵画が中の海」は名詞のつながりとして合わない。", "を": "目的語を示す助詞で、「絵画を中の海」は成り立たないので合わない。", "に": "位置を示す助詞で、「絵画に中の海」は名詞のつながりとして合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "位置"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "紙やキャンバスに、えのぐやペンでかいた絵のことです。", "primary_collocate": null, "pronunciation": "かいが", "ipa": "kaiɡa", "syllable_count": 3, "sentences": [{"text": "私の部屋には、母がかいた絵画がかざってあります。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "私[わたし]の部屋[へや]には、母[はは]がかいた絵画[かいが]がかざってあります。", "sentence_source": "generated"}, {"text": "駅の近くの美術館で、絵画の展覧会が開かれています。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くの美術館[びじゅつかん]で、絵画[かいが]の展覧会[てんらんかい]が開[ひら]かれています。", "sentence_source": "generated"}, {"text": "この絵画はキャンバスに、青いえのぐでかかれています。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "この絵画[かいが]はキャンバスに、青[あお]いえのぐでかかれています。", "sentence_source": "generated"}, {"text": "兄は絵画の教室に通っていて、夏休みに賞をもらいました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "兄は絵画[かいが]の教室に通っていて、夏休みに賞をもらいました。", "sentence_source": "generated"}, {"text": "雨の日は外へ出ないで、家で絵画を見て過ごしました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]へ出[で]ないで、家[いえ]で絵画[かいが]を見[み]て過[す]ごしました。", "sentence_source": "generated"}, {"text": "美術の授業で、有名な絵画について調べました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "美術[びじゅつ]の授業[じゅぎょう]で、有名[ゆうめい]な絵画[かいが]について調[しら]べました。", "sentence_source": "generated"}, {"text": "あの絵画は高すぎて、わたしには買えません。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "あの絵画[かいが]は高[たか]すぎて、わたしには買[か]えません。", "sentence_source": "generated"}, {"text": "絵画の中の海は青くて、本当に波の音が聞こえそうです。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "絵画[かいが]の中[なか]の海[うみ]は青[あお]くて、本当[ほんとう]に波[なみ]の音[おと]が聞[き]こえそうです。", "sentence_source": "generated"}, {"text": "小さな町の図書館にも、地元の人の絵画が飾られています。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "小[ちい]さな町[まち]の図書館[としょかん]にも、地元[じもと]の人[ひと]の絵画[かいが]が飾[かざ]られています。", "sentence_source": "generated"}, {"text": "先生は、絵画をていねいに運ぶように言いました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "先生[せんせい]は、絵画[かいが]をていねいに運[はこ]ぶように言[い]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵画", "label": "基本形"}], "register": "中立（丁寧体中心）", "sense_fingerprint": "紙やキャンバスにえのぐやペンでかかれた絵そのものを指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵画", "is_correct": true, "explanation": "絵の具で描かれた作品で、「母がかいた」「かざってある」と自然につながる。"}, {"text": "写真", "is_correct": false, "explanation": "撮るものなので「かいた」とは合わず、文が成り立たないので合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音で表すもので、「かいた」「かざってある」とは合わない。"}, {"text": "彫刻", "is_correct": false, "explanation": "彫って作る立体作品で、「かいた」とは合わないので合わない。"}], "explanations": {"絵画": "絵の具で描かれた作品で、「母がかいた」「かざってある」と自然につながる。", "写真": "撮るものなので「かいた」とは合わず、文が成り立たないので合わない。", "音楽": "音で表すもので、「かいた」「かざってある」とは合わない。", "彫刻": "彫って作る立体作品で、「かいた」とは合わないので合わない。"}, "sentence_index": 0, "correct_answer": "絵画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は夏休みに、絵画を三冊読みました。", "explanation": "〈小説〉の意味。読むのは小説などの本で、絵画は読むものではないので合わない。"}, {"text": "妹は毎晩、絵画を聴いて眠ります。", "explanation": "〈音楽〉の意味。聴くのは音楽で、絵画は聴く対象にならないので合わない。"}, {"text": "父は毎週、絵画を彫って家具を作ります。", "explanation": "〈彫刻〉の意味。彫るのは木や石などで、絵画は彫って作らないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵画", "is_correct": true, "explanation": "高価で買える作品なので、「あの」「高すぎて買えません」と合う。"}, {"text": "天気", "is_correct": false, "explanation": "天候の状態で、値段が高すぎて買えるものではないので合わない。"}, {"text": "技法", "is_correct": false, "explanation": "描き方の方法で、物として買えないので「買えません」と合わない。"}, {"text": "描写", "is_correct": false, "explanation": "表現の仕方で、買える対象ではないので「買えません」と合わない。"}], "explanations": {"絵画": "高価で買える作品なので、「あの」「高すぎて買えません」と合う。", "天気": "天候の状態で、値段が高すぎて買えるものではないので合わない。", "技法": "描き方の方法で、物として買えないので「買えません」と合わない。", "描写": "表現の仕方で、買える対象ではないので「買えません」と合わない。"}, "sentence_index": 6, "correct_answer": "絵画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "楽団は新しい絵画を演奏しました。", "explanation": "〈曲〉の意味。演奏するのは曲で、絵画は演奏できないので合わない。"}, {"text": "祖母は昔の絵画を歌ってくれました。", "explanation": "〈歌〉の意味。歌うのは歌詞や曲で、絵画は歌えないので合わない。"}, {"text": "先生は絵画を朗読しました。", "explanation": "〈詩〉の意味。朗読は詩や文章を声に出すことで、絵画は朗読できないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この美術館では、地元の画家の絵画を展示されています。", "corrected_sentence": "この美術館では、地元の画家の絵画が展示されています。", "error_description": "「展示されています」は自動詞的に主語を取る。「を」は誤りで、正しくは「絵画が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51877, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、昔の絵画の集めるのが趣味です。", "corrected_sentence": "祖母は、昔の絵画を集めるのが趣味です。", "error_description": "「集める」の目的語は「を」で示す。「の」は誤りで、正しくは「絵画を集める」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「見る」の目的語を示す格助詞で、「絵画を見ました」と自然につながる。"}, {"text": "に", "is_correct": false, "explanation": "「見る」の目的語には使えず、「絵画に見ました」は不自然で合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「見る」の対象を表せないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "名詞を修飾する助詞で、「絵画の見ました」は文として成り立たないので合わない。"}], "correct_answer": "を", "explanations": {"を": "「見る」の目的語を示す格助詞で、「絵画を見ました」と自然につながる。", "に": "「見る」の目的語には使えず、「絵画に見ました」は不自然で合わない。", "へ": "方向を示す助詞で、「見る」の対象を表せないので合わない。", "の": "名詞を修飾する助詞で、「絵画の見ました」は文として成り立たないので合わない。"}, "error_tags": {"に": "目的語ではない", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「燃える」は主語が動作を受ける自動詞なので「絵画が燃えて」と自然につながる。"}, {"text": "を", "is_correct": false, "explanation": "「燃える」は目的語を取らない自動詞なので、「絵画を燃えて」は成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を示す助詞で、「絵画に燃えて」は文として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「絵画へ燃えて」は文として合わない。"}], "correct_answer": "が", "explanations": {"が": "「燃える」は主語が動作を受ける自動詞なので「絵画が燃えて」と自然につながる。", "を": "「燃える」は目的語を取らない自動詞なので、「絵画を燃えて」は成り立たない。", "に": "場所や相手を示す助詞で、「絵画に燃えて」は文として合わない。", "へ": "方向を示す助詞で、「絵画へ燃えて」は文として合わない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵の具や鉛筆などを使って、紙や布などに描かれた作品。", "primary_collocate": null, "pronunciation": "かいが", "ipa": "kaiɡa", "syllable_count": 3, "sentences": [{"text": "こうして、一枚の絵画が完成します。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "こうして、一枚[いちまい]の絵画[かいが]が完成[かんせい]します。", "sentence_source": "mined"}, {"text": "美術館で、有名な画家の絵画を見ました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、有名[ゆうめい]な画家[がか]の絵画[かいが]を見[み]ました。", "sentence_source": "generated"}, {"text": "この絵画は三百年前に描かれたもので、とても貴重です。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "この絵画[かいが]は三百年前[さんびゃくねんまえ]に描[か]かれたもので、とても貴重[きちょう]です。", "sentence_source": "generated"}, {"text": "祖父は絵画が好きで、毎週末に美術館へ行きます。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "祖父[そふ]は絵画[かいが]が好[す]きで、毎週末[まいしゅうまつ]に美術館[びじゅつかん]へ行[い]きます。", "sentence_source": "generated"}, {"text": "壁に大きな絵画がかかっているので、部屋が明るく見えます。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "壁[かべ]に大[おお]きな絵画[かいが]がかかっているので、部屋[へや]が明[あか]るく見[み]えます。", "sentence_source": "generated"}, {"text": "彼は美術大学で、ルネサンス期の絵画の歴史を研究しています。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "彼は美術大学で、ルネサンス期の絵画[かいが]の歴史を研究しています。", "sentence_source": "generated"}, {"text": "展覧会では、世界中の絵画が集められました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]では、世界中[せかいじゅう]の絵画[かいが]が集[あつ]められました。", "sentence_source": "generated"}, {"text": "火事で、古い絵画が何枚も燃えてしまいました。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "火事[かじ]で、古[ふる]い絵画[かいが]が何枚[なんまい]も燃[も]えてしまいました。", "sentence_source": "generated"}, {"text": "絵画は色の使い方によって、見る人の気持ちが変わります。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "絵画[かいが]は色[いろ]の使[つか]い方[かた]によって、見[み]る人[ひと]の気持[きも]ちが変[か]わります。", "sentence_source": "generated"}, {"text": "この絵画の作者はだれか、まだわかっていません。", "target_word": "絵画", "complexity_tier": "T3", "furigana": "この絵画[かいが]の作者[さくしゃ]はだれか、まだわかっていません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵画", "label": "基本形"}], "register": "中立（書き言葉寄り）", "sense_fingerprint": "絵の具や鉛筆などで紙や布に描かれた作品そのものを指す名詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵画", "is_correct": true, "explanation": "絵の具で描かれた作品で「一枚」と数えられ、「完成する」ともつながる。"}, {"text": "技法", "is_correct": false, "explanation": "描き方の方法を指し、「一枚」と数えたり完成させたりする対象ではないので合わない。"}, {"text": "描写", "is_correct": false, "explanation": "対象を描き表す行為や表現で、作品として「一枚」と数えられないので合わない。"}, {"text": "陶器", "is_correct": false, "explanation": "焼き物で、紙に絵の具で描いた作品ではなく、「一枚」とも数えないので合わない。"}], "explanations": {"絵画": "絵の具で描かれた作品で「一枚」と数えられ、「完成する」ともつながる。", "技法": "描き方の方法を指し、「一枚」と数えたり完成させたりする対象ではないので合わない。", "描写": "対象を描き表す行為や表現で、作品として「一枚」と数えられないので合わない。", "陶器": "焼き物で、紙に絵の具で描いた作品ではなく、「一枚」とも数えないので合わない。"}, "sentence_index": 0, "correct_answer": "絵画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は旅行で撮ったフィルムを現像して、絵画を焼き増ししました。", "explanation": "〈写真〉の意味。焼き増しは写真を複製することで、絵画は焼き増しできないので合わない。"}, {"text": "祖父は木の板に絵画を彫って、年賀状を作ります。", "explanation": "〈版画〉の意味。板に彫って刷るのが版画で、絵画は彫って作らないので合わない。"}, {"text": "祖父は孫のために、絵画の読み聞かせをしています。", "explanation": "〈絵本〉の意味。読み聞かせは絵本や物語を声に出して読むことで、絵画は読み聞かせの対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵画", "is_correct": true, "explanation": "作品として「世界中の」から「集められる」対象になり、文脈に合う。"}, {"text": "筆致", "is_correct": false, "explanation": "筆の運びや画面の表情を指し、物として集められるものではないので合わない。"}, {"text": "画風", "is_correct": false, "explanation": "作風や様式を指す抽象的な語で、「集められました」とは結びつかないので合わない。"}, {"text": "天候", "is_correct": false, "explanation": "天気の状態を指し、集める対象ではないので「集められました」と合わない。"}], "explanations": {"絵画": "作品として「世界中の」から「集められる」対象になり、文脈に合う。", "筆致": "筆の運びや画面の表情を指し、物として集められるものではないので合わない。", "画風": "作風や様式を指す抽象的な語で、「集められました」とは結びつかないので合わない。", "天候": "天気の状態を指し、集める対象ではないので「集められました」と合わない。"}, "sentence_index": 6, "correct_answer": "絵画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵画はピアノで演奏されるように作られています。", "explanation": "〈曲〉の意味。演奏されるのは曲で、絵画は演奏できないので合わない。"}, {"text": "先生は生徒に、古い絵画を朗読しました。", "explanation": "〈詩〉の意味。朗読は詩や文章を声に出す行為で、絵画は朗読できないので合わない。"}, {"text": "彼は絵画を聴きながら、勉強しています。", "explanation": "〈音楽〉の意味。聴くのは音楽で、絵画は聴く対象にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は絵画を得意で、学校の展覧会に出す作品を毎日描いています。", "corrected_sentence": "妹は絵画が得意で、学校の展覧会に出す作品を毎日描いています。", "error_description": "「得意」の対象は「が」で示す。「絵画を得意」は誤りで、正しくは「絵画が得意」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51878, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父の書斎には、海を描いた絵画に二点かざってあります。", "corrected_sentence": "父の書斎には、海を描いた絵画を二点かざってあります。", "error_description": "「かざる」の対象は「を」で示す。「に」は場所を表すので誤り。正しくは「絵画を二点かざってあります」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "目的語の格で、「専門に演じる」の対象として色事を示す。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格で、「専門に演じる」の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、演じる対象として合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格で、演じる対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "目的語の格で、「専門に演じる」の対象として色事を示す。", "で": "手段・場所の格で、「専門に演じる」の対象を示せない。", "へ": "方向の格で、演じる対象として合わない。", "から": "起点の格で、演じる対象を示せない。"}, "error_tags": {"で": "手段・場所の格で、対象にならない", "へ": "方向の格で、対象にならない", "から": "起点の格で、対象にならない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "並列の「と」で、「色事と争い」が並んで場面の内容を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格で、入り混じる文の並列にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格で、「入り混じる」の相手として並列にならない。"}, {"text": "より", "is_correct": false, "explanation": "比較の格で、並列にはならない。"}], "correct_answer": "と", "explanations": {"と": "並列の「と」で、「色事と争い」が並んで場面の内容を示す。", "を": "目的語の格で、入り混じる文の並列にはならない。", "から": "起点の格で、「入り混じる」の相手として並列にならない。", "より": "比較の格で、並列にはならない。"}, "error_tags": {"を": "目的語の格で、並列にならない", "から": "起点の格で、並列にならない", "より": "比較の格で、並列にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "男女の恋愛や情愛にまつわること。特に、色っぽい出来事や関係を指します。", "primary_collocate": null, "pronunciation": "いろごと", "ipa": "iɾoɡoto", "syllable_count": 4, "sentences": [{"text": "芸能界の色事が週刊誌に載り、大きな話題になった。", "target_word": "色事", "complexity_tier": "T3", "furigana": "芸能界[げいのうかい]の色事[いろごと]が週刊誌[しゅうかんし]に載[の]り、大[おお]きな話題[わだい]になった。", "sentence_source": "generated"}, {"text": "歌舞伎には、色事を専門に演じる役柄がある。", "target_word": "色事", "complexity_tier": "T3", "furigana": "歌舞伎[かぶき]には、色事[いろごと]を専門[せんもん]に演[えん]じる役柄[やくがら]がある。", "sentence_source": "generated"}, {"text": "その映画は、大人の色事を静かに描いている。", "target_word": "色事", "complexity_tier": "T3", "furigana": "その映画[えいが]は、大人[おとな]の色事[いろごと]を静[しず]かに描[えが]いている。", "sentence_source": "generated"}, {"text": "色事が原因で、二人の友情は終わってしまった。", "target_word": "色事", "complexity_tier": "T3", "furigana": "色事[いろごと]が原因[げんいん]で、二人[ふたり]の友情[ゆうじょう]は終[お]わってしまった。", "sentence_source": "generated"}, {"text": "社長は色事の失敗で、地位を失った。", "target_word": "色事", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は色事[いろごと]の失敗[しっぱい]で、地位[ちい]を失[うしな]った。", "sentence_source": "generated"}, {"text": "色事を扱う作品なので、子どもには見せられない。", "target_word": "色事", "complexity_tier": "T3", "furigana": "色事[いろごと]を扱[あつか]う作品[さくひん]なので、子[こ]どもには見[み]せられない。", "sentence_source": "generated"}, {"text": "彼の色事は有名で、知らない人はいないほどだ。", "target_word": "色事", "complexity_tier": "T3", "furigana": "彼[かれ]の色事[いろごと]は有名[ゆうめい]で、知[し]らない人[ひと]はいないほどだ。", "sentence_source": "generated"}, {"text": "時代劇には、色事と争いが入り混じる場面が多い。", "target_word": "色事", "complexity_tier": "T3", "furigana": "時代劇[じだいげき]には、色事[いろごと]と争[あらそ]いが入[い]り混[ま]じる場面[ばめん]が多[おお]い。", "sentence_source": "generated"}, {"text": "色事の話になると、老人たちは急に元気になった。", "target_word": "色事", "complexity_tier": "T3", "furigana": "色事[いろごと]の話[はなし]になると、老人[ろうじん]たちは急[きゅう]に元気[げんき]になった。", "sentence_source": "generated"}, {"text": "作家は自分の色事を隠さず、小説に書いた。", "target_word": "色事", "complexity_tier": "T3", "furigana": "作家[さっか]は自分[じぶん]の色事[いろごと]を隠[かく]さず、小説[しょうせつ]に書[か]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色事", "label": "基本形"}, {"form": "色事が", "label": "主格"}, {"form": "色事を", "label": "目的格"}, {"form": "色事の", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "男女の色っぽい出来事や情事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色事", "is_correct": true, "explanation": "芸能人の情事を指し、週刊誌に載って話題になる対象として自然。"}, {"text": "体調", "is_correct": false, "explanation": "健康状態を指し、週刊誌に載る話題の主語として不自然。"}, {"text": "天気", "is_correct": false, "explanation": "空模様を指し、週刊誌記事の主語にはならない。"}, {"text": "寿命", "is_correct": false, "explanation": "生きる期間を指し、この文の話題としては合わない。"}], "explanations": {"色事": "芸能人の情事を指し、週刊誌に載って話題になる対象として自然。", "体調": "健康状態を指し、週刊誌に載る話題の主語として不自然。", "天気": "空模様を指し、週刊誌記事の主語にはならない。", "寿命": "生きる期間を指し、この文の話題としては合わない。"}, "sentence_index": 0, "correct_answer": "色事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "色事の勉強で、水彩画の重ね方を学んだ。", "explanation": "ここは〈色〉（色彩）の意味。色事は男女の恋の出来事なので、絵の技法の話には使わない。"}, {"text": "あの色事は背が高くて、女性に人気がある。", "explanation": "ここは〈色男〉（容姿の美しい男性）の意味。色事は出来事や関係を指し、人を表す語としては合わない。"}, {"text": "色事に一言書いてもらった。", "explanation": "ここは〈色紙〉の意味。色事は紙ではないので、書き込みの対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色事", "is_correct": true, "explanation": "男女の情事を指し、「彼の〜は有名」の話題として自然。"}, {"text": "体重", "is_correct": false, "explanation": "身体の数値を指し、有名になる対象として不自然。"}, {"text": "湿疹", "is_correct": false, "explanation": "皮膚の病気で、有名になる対象とは言えない。"}, {"text": "騒音", "is_correct": false, "explanation": "騒ぎの音で、有名になる対象として不自然。"}], "explanations": {"色事": "男女の情事を指し、「彼の〜は有名」の話題として自然。", "体重": "身体の数値を指し、有名になる対象として不自然。", "湿疹": "皮膚の病気で、有名になる対象とは言えない。", "騒音": "騒ぎの音で、有名になる対象として不自然。"}, "sentence_index": 6, "correct_answer": "色事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は色事で、隣の席の女性を見ていた。", "explanation": "ここは〈色目〉（流し目）の意味。色事は関係や出来事を指し、目つきを表さないので合わない。"}, {"text": "この本は色事刷りで、絵が鮮やかだ。", "explanation": "ここは〈色刷り〉（多色で刷ること）の意味。色事は男女の情愛を指し、印刷の方法を表さないので合わない。"}, {"text": "作家は色事の靴を、二足ずつ買うことにした。", "explanation": "ここは〈色違い〉の意味。色事は恋の出来事で、靴の種類を表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "色事を噂になると、仕事を失う人もいる。", "corrected_sentence": "色事が噂になると、仕事を失う人もいる。", "error_description": "正しくは「色事が」（主語）。「噂になる」は主語に「が」を取るので、「色事を」は目的語の形で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51880, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色事を噂を、彼は笑って受け流した。", "corrected_sentence": "色事の噂を、彼は笑って受け流した。", "error_description": "正しくは「色事の噂」（連体修飾の「の」）。「色事を」と「噂を」が並んで目的語が重なっている。「噂」を修飾するには「の」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
