INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51881, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "会社や商品の名前やイメージを、みんなに覚えてもらうための工夫や活動のこと。", "primary_collocate": null, "pronunciation": "ぶらんでぃんぐ", "ipa": "bɯɾandʲiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "この会社はブランディングがじょうずで、名前をみんなが知っている。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]はブランディングがじょうずで、名前[なまえ]をみんなが知[し]っている。", "sentence_source": "generated"}, {"text": "新しいお菓子の名前を覚えてもらうために、ブランディングを始めた。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "新[あたら]しいお菓子[かし]の名前[なまえ]を覚[おぼ]えてもらうために、ブランディングを始[はじ]めた。", "sentence_source": "generated"}, {"text": "ブランディングのおかげで、小さな店でも有名になった。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングのおかげで、小[ちい]さな店[みせ]でも有名[ゆうめい]になった。", "sentence_source": "generated"}, {"text": "兄は会社でブランディングの仕事をしている。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "兄[あに]は会社[かいしゃ]でブランディングの仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "ブランディングを変えたら、店のイメージが明るくなった。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングを変[か]えたら、店[みせ]のイメージが明[あか]るくなった。", "sentence_source": "generated"}, {"text": "商品がいいだけでなく、ブランディングも大切だ。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "商品[しょうひん]がいいだけでなく、ブランディングも大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "ブランディングに失敗して、だれも商品の名前を覚えなかった。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングに失敗[しっぱい]して、だれも商品[しょうひん]の名前[なまえ]を覚[おぼ]えなかった。", "sentence_source": "generated"}, {"text": "私はブランディングについて、大学で勉強しています。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "私[わたし]はブランディングについて、大学[だいがく]で勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "有名なブランディングの例を、先生が授業で紹介してくれた。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "有名[ゆうめい]なブランディングの例[れい]を、先生[せんせい]が授業[じゅぎょう]で紹介[しょうかい]してくれた。", "sentence_source": "generated"}, {"text": "ブランディングには、ロゴや色などの工夫が必要です。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングには、ロゴや色[いろ]などの工夫[くふう]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブランディング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "会社・商品の名前やイメージを人々に覚えてもらうための工夫・活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51881, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブランディング", "is_correct": true, "explanation": "会社がじょうずな分野として、名前を覚えてもらう工夫を指す語。ここに入る。"}, {"text": "砂時計", "is_correct": false, "explanation": "「砂時計がじょうずで」は意味が通らない。"}, {"text": "寒さ", "is_correct": false, "explanation": "「寒さがじょうずで」は文脈に合わない。"}, {"text": "雨粒", "is_correct": false, "explanation": "「雨粒がじょうずで」は不自然。"}], "explanations": {"ブランディング": "会社がじょうずな分野として、名前を覚えてもらう工夫を指す語。ここに入る。", "砂時計": "「砂時計がじょうずで」は意味が通らない。", "寒さ": "「寒さがじょうずで」は文脈に合わない。", "雨粒": "「雨粒がじょうずで」は不自然。"}, "sentence_index": 0, "correct_answer": "ブランディング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝、ブランディングを胸につけて会議に出た。", "explanation": "ブランディングは企業が名前やイメージを覚えてもらう活動で、身につける物にはならないので合わない。"}, {"text": "地震の時は、ブランディングの練習が役に立つ。", "explanation": "ブランディングは企業のイメージづくりの活動で、防災の練習の名前にはならないので合わない。"}, {"text": "毎朝、ブランディングの予報を見てから家を出る。", "explanation": "ブランディングは企業の活動の名称で、天気の予報には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51881, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブランディング", "is_correct": true, "explanation": "名前を覚えてもらう工夫の語で、失敗した対象として自然に入る。"}, {"text": "眼鏡", "is_correct": false, "explanation": "「眼鏡に失敗して」は文脈に合わない。"}, {"text": "湿気", "is_correct": false, "explanation": "「湿気に失敗して」は意味が通らない。"}, {"text": "座布団", "is_correct": false, "explanation": "「座布団に失敗して」は不自然。"}], "explanations": {"ブランディング": "名前を覚えてもらう工夫の語で、失敗した対象として自然に入る。", "眼鏡": "「眼鏡に失敗して」は文脈に合わない。", "湿気": "「湿気に失敗して」は意味が通らない。", "座布団": "「座布団に失敗して」は不自然。"}, "sentence_index": 6, "correct_answer": "ブランディング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝起きたら、まずブランディングを測る習慣がある。", "explanation": "ブランディングは企業の活動で、体温のように測れる対象ではないので合わない。"}, {"text": "この荷物は、ブランディングで送ると安い。", "explanation": "ブランディングは活動の名称で、荷物を送る手段にはならないので合わない。"}, {"text": "寒い朝は、温かいブランディングを淹れて、ゆっくり読書する。", "explanation": "ブランディングは活動の名称で、飲み物として淹れる対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51881, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい店は、ロゴとキャッチコピーでブランディングが行った。", "corrected_sentence": "新しい店は、ロゴとキャッチコピーでブランディングを行った。", "error_description": "「行う」の目的語は「ブランディングを」。「が」は主語を示すので、この文では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51881, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母の店は、看板の色を変えてブランディングを成功した。", "corrected_sentence": "祖母の店は、看板の色を変えてブランディングに成功した。", "error_description": "「成功する」は「に」を取る。「を」は誤りで、この文では不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ブランディングに成功する」の「成功する」が取る「に」。"}, {"text": "を", "is_correct": false, "explanation": "「成功する」は「を」を取らないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体の「の」で、「ブランディングの成功して」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」で、「成功へ」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「ブランディングに成功する」の「成功する」が取る「に」。", "を": "「成功する」は「を」を取らないので合わない。", "の": "連体の「の」で、「ブランディングの成功して」は文が成り立たない。", "へ": "方向の「へ」で、「成功へ」は意味が通らない。"}, "error_tags": {"を": "目的格", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ブランディングに力を入れる」の「に」。"}, {"text": "が", "is_correct": false, "explanation": "「力を入れる」の主語にはならず、「ブランディングが力を入れた」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」で、「ブランディングと力を入れた」は意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「力を入れる」の前に「を」を重ねると不自然で、「ブランディングを力を入れ」は文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ブランディングに力を入れる」の「に」。", "が": "「力を入れる」の主語にはならず、「ブランディングが力を入れた」は不自然。", "と": "共同の「と」で、「ブランディングと力を入れた」は意味が通らない。", "を": "「力を入れる」の前に「を」を重ねると不自然で、「ブランディングを力を入れ」は文が成り立たない。"}, "error_tags": {"が": "主格", "と": "共同", "を": "目的格（二重）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "企業や商品のブランド価値を高めるための戦略的な活動。ロゴや色、メッセージなどを統一して、消費者に強い印象を与えること。", "primary_collocate": null, "pronunciation": "ぶらんでぃんぐ", "ipa": "bɯɾandʲiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "企業はブランディングにおいて、色彩理論を巧みに利用している。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "企業[きぎょう]はブランディングにおいて、色彩[しきさい]理論[りろん]を巧[たく]みに利用[りよう]している。", "sentence_source": "mined"}, {"text": "新しい会社は、ブランディングに成功して、一年で有名になった。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "新[あたら]しい会社[かいしゃ]は、ブランディングに成功[せいこう]して、一年[いちねん]で有名[ゆうめい]になった。", "sentence_source": "generated"}, {"text": "ロゴと色を統一したのは、ブランディングの一部です。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ロゴと色[いろ]を統一[とういつ]したのは、ブランディングの一部[いちぶ]です。", "sentence_source": "generated"}, {"text": "ブランディングが弱いと、商品の良さが消費者に伝わりにくい。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングが弱[よわ]いと、商品[しょうひん]の良[よ]さが消費者[しょうひしゃ]に伝[つた]わりにくい。", "sentence_source": "generated"}, {"text": "彼女は化粧品会社でブランディングを担当している。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は化粧品[けしょうひん]会社[がいしゃ]でブランディングを担当[たんとう]している。", "sentence_source": "generated"}, {"text": "この店は、ブランディングを見直したことで若い客が増えた。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "この店[みせ]は、ブランディングを見直[みなお]したことで若[わか]い客[きゃく]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "広告のメッセージがばらばらだと、ブランディングはうまくいかない。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "広告[こうこく]のメッセージがばらばらだと、ブランディングはうまくいかない。", "sentence_source": "generated"}, {"text": "老舗の旅館が、海外向けのブランディングに力を入れ始めた。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "老舗[しにせ]の旅館[りょかん]が、海外[かいがい]向[む]けのブランディングに力[ちから]を入[い]れ始[はじ]めた。", "sentence_source": "generated"}, {"text": "商品の質は同じでも、ブランディングの差で売れ行きが変わる。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "商品[しょうひん]の質[しつ]は同[おな]じでも、ブランディングの差[さ]で売[う]れ行[ゆ]きが変[か]わる。", "sentence_source": "generated"}, {"text": "ブランディングでは、一貫した印象を与えることが何より大切だ。", "target_word": "ブランディング", "complexity_tier": "T3", "furigana": "ブランディングでは、一貫[いっかん]した印象[いんしょう]を与[あた]えることが何[なに]より大切[たいせつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ブランディング", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "企業・商品のブランド価値を高める戦略的活動(ロゴ・色・メッセージの統一)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ブランディング", "is_correct": true, "explanation": "企業が色彩理論を使う戦略的活動の分野を指す語。ここにだけ入る。"}, {"text": "登山", "is_correct": false, "explanation": "「企業は登山において」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「企業は天気において」は文脈に合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "「企業は散歩において」は不自然。"}], "explanations": {"ブランディング": "企業が色彩理論を使う戦略的活動の分野を指す語。ここにだけ入る。", "登山": "「企業は登山において」は意味が通らない。", "天気": "「企業は天気において」は文脈に合わない。", "散歩": "「企業は散歩において」は不自然。"}, "sentence_index": 0, "correct_answer": "ブランディング"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は誕生日に、ブランディングのバッグを買ってくれた。", "explanation": "ここは〈ブランド品〉の意味。ブランディングは企業の活動で、持ち物の品名には使わないので合わない。"}, {"text": "大雨の日はブランディングを避けて、地下鉄で通勤した。", "explanation": "ここは〈交通〉の意味。ブランディングは企業の戦略で、道路や乗り物の状況には使わないので合わない。"}, {"text": "寒い日は厚いブランディングを選ぶと、体が温まる。", "explanation": "ここは〈服装〉の意味。ブランディングは印象づくりの活動で、着る物には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ブランディング", "is_correct": true, "explanation": "広告のメッセージを統一する戦略の語で、ここに入る。"}, {"text": "方言", "is_correct": false, "explanation": "「方言はうまくいかない」は文脈に合わない。"}, {"text": "寝不足", "is_correct": false, "explanation": "「寝不足はうまくいかない」は文脈に合わない。"}, {"text": "雨季", "is_correct": false, "explanation": "「雨季はうまくいかない」は意味が通らない。"}], "explanations": {"ブランディング": "広告のメッセージを統一する戦略の語で、ここに入る。", "方言": "「方言はうまくいかない」は文脈に合わない。", "寝不足": "「寝不足はうまくいかない」は文脈に合わない。", "雨季": "「雨季はうまくいかない」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "ブランディング"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年の夏は暑さが厳しいので、ブランディングを控えて家にいた。", "explanation": "ここは〈外出〉の意味。ブランディングは企業活動で、出かけることには使わないので合わない。"}, {"text": "ブランディングはくしゃみで伝染しやすい。", "explanation": "ここは〈伝染〉の意味。ブランディングは病気ではないので、うつる意味では使わないので合わない。"}, {"text": "毎月、ブランディングを一万円ずつ貯金している。", "explanation": "ここは〈貯金〉の意味。ブランディングは企業の活動で、お金をためる対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品の発売に合わせて、ブランディングに強化した。", "corrected_sentence": "新製品の発売に合わせて、ブランディングを強化した。", "error_description": "「強化する」の目的語は「ブランディングを」。「に」は誤りで、この文では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51882, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店は地元の食材を使い、ブランディングを力を入れた。", "corrected_sentence": "店は地元の食材を使い、ブランディングに力を入れた。", "error_description": "「力を入れる」の相手は「ブランディングに」。「を」にすると不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
