INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51883, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "赤は、いろのなまえです。", "primary_collocate": null, "pronunciation": "あか", "ipa": "aka", "syllable_count": 2, "sentences": [{"text": "日本の郵便ポストの色は赤です。", "target_word": "赤", "complexity_tier": "T2", "furigana": "日本[にほん]の郵便[ゆうびん]ポストの色[いろ]は赤[あか]です。", "sentence_source": "generated"}, {"text": "赤のペンで名前を書きました。", "target_word": "赤", "complexity_tier": "T2", "furigana": "赤[あか]のペンで名前[なまえ]を書[か]きました。", "sentence_source": "generated"}, {"text": "トマトは赤で、バナナは黄色です。", "target_word": "赤", "complexity_tier": "T2", "furigana": "トマトは赤[あか]で、バナナは黄色[きいろ]です。", "sentence_source": "generated"}, {"text": "信号が赤になったので、止まりました。", "target_word": "赤", "complexity_tier": "T2", "furigana": "信号[しんごう]が赤[あか]になったので、止[と]まりました。", "sentence_source": "generated"}, {"text": "妹は赤の帽子をかぶっています。", "target_word": "赤", "complexity_tier": "T2", "furigana": "妹[いもうと]は赤[あか]の帽子[ぼうし]をかぶっています。", "sentence_source": "generated"}, {"text": "赤と白のリボンをもらいました。", "target_word": "赤", "complexity_tier": "T2", "furigana": "赤[あか]と白[しろ]のリボンをもらいました。", "sentence_source": "generated"}, {"text": "この花は赤だから、とてもよく目立つ。", "target_word": "赤", "complexity_tier": "T3", "furigana": "この花[はな]は赤[あか]だから、とてもよく目立[めだ]つ。", "sentence_source": "generated"}, {"text": "赤にするか青にするか、まだ決められない。", "target_word": "赤", "complexity_tier": "T3", "furigana": "赤[あか]にするか青[あお]にするか、まだ決[き]められない。", "sentence_source": "generated"}, {"text": "りんごの赤はきれいで、おいしそうに見える。", "target_word": "赤", "complexity_tier": "T3", "furigana": "りんごの赤[あか]はきれいで、おいしそうに見[み]える。", "sentence_source": "generated"}, {"text": "郵便ポストは赤なので、すぐ見つかります。", "target_word": "赤", "complexity_tier": "T3", "furigana": "郵便[ゆうびん]ポストは赤[あか]なので、すぐ見[み]つかります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "色の名前(トマトや信号の色)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51883, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緑", "is_correct": false, "explanation": "郵便ポストの色は赤で、緑は事実と合わない。"}, {"text": "赤", "is_correct": true, "explanation": "日本の郵便ポストの色は赤。空欄に入るのはこの語。"}, {"text": "白", "is_correct": false, "explanation": "郵便ポストの色は赤で、白は事実と合わない。"}, {"text": "黒", "is_correct": false, "explanation": "郵便ポストの色は赤で、黒は事実と合わない。"}], "explanations": {"緑": "郵便ポストの色は赤で、緑は事実と合わない。", "赤": "日本の郵便ポストの色は赤。空欄に入るのはこの語。", "白": "郵便ポストの色は赤で、白は事実と合わない。", "黒": "郵便ポストの色は赤で、黒は事実と合わない。"}, "sentence_index": 0, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年は会社が大きな赤を出した。", "explanation": "ここは〈赤字〉の意味。「赤を出す」は損失を出すことで、色名の赤ではない。"}, {"text": "男の子ばかりのクラスで、彼女は赤一点の存在だった。", "explanation": "〈紅一点〉の〈紅〉を〈赤〉に替えたもの。〈紅一点〉は決まった四字熟語で、〈赤一点〉とは言わない。"}, {"text": "彼女は唇に赤を引いて、街へ出かけた。", "explanation": "唇に色をのせる意味では〈紅〉を引く（紅を引く）と言う。色名の〈赤〉を引くとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51883, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緑", "is_correct": false, "explanation": "緑は葉の色で周囲に溶け込みやすく、「よく目立つ」理由として合わない。"}, {"text": "茶色", "is_correct": false, "explanation": "茶色は地味な色で、「よく目立つ」理由として合わない。"}, {"text": "赤", "is_correct": true, "explanation": "赤は目を引く色で、「よく目立つ」理由として成り立つ。空欄の答え。"}, {"text": "紺", "is_correct": false, "explanation": "紺は暗く目立ちにくい色で、「よく目立つ」理由として合わない。"}], "explanations": {"緑": "緑は葉の色で周囲に溶け込みやすく、「よく目立つ」理由として合わない。", "茶色": "茶色は地味な色で、「よく目立つ」理由として合わない。", "赤": "赤は目を引く色で、「よく目立つ」理由として成り立つ。空欄の答え。", "紺": "紺は暗く目立ちにくい色で、「よく目立つ」理由として合わない。"}, "sentence_index": 6, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の帳簿は赤が続き、閉店を考えた。", "explanation": "ここは〈赤字〉の意味。帳簿の赤は損失を指し、色名の赤ではない。"}, {"text": "あの人は赤の他人だが、道を親切に教えてくれた。", "explanation": "ここは〈全くの他人〉の意味。「赤の他人」は決まった言い方で、色の意味ではない。"}, {"text": "彼は学生時代、周りから赤と呼ばれていた。", "explanation": "ここは〈共産主義者〉の意味。人を指す俗称で、色名の赤ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51883, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は赤でいちばん好きだと言っていました。", "corrected_sentence": "妹は赤がいちばん好きだと言っていました。", "error_description": "「好きだ」は対象を「が」で示す。「で」は手段を表すので、この文では誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51883, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "りんごの赤くが、おいしそうだ。", "corrected_sentence": "りんごの赤が、おいしそうだ。", "error_description": "「赤」は名詞なので「りんごの赤が」と続ける。「赤くが」の「く」は形容詞の連用形で、名詞に付けると誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
