INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51884, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "赤は、色の名前です。情熱や危険を連想させる色で、信号などにも使われます。", "primary_collocate": null, "pronunciation": "あか", "ipa": "aka", "syllable_count": 2, "sentences": [{"text": "例えば、赤は情熱や緊急を、青は信頼を連想させる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "例[たと]えば、赤[あか]は情熱[じょうねつ]や緊急[きんきゅう]を、青[あお]は信頼[しんらい]を連想[れんそう]させる。", "sentence_source": "mined"}, {"text": "信号が赤に変わったので、車は止まった。", "target_word": "赤", "complexity_tier": "T3", "furigana": "信号[しんごう]が赤[あか]に変[か]わったので、車[くるま]は止[と]まった。", "sentence_source": "generated"}, {"text": "彼女は赤のドレスを着て、パーティーに現れた。", "target_word": "赤", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は赤[あか]のドレスを着[き]て、パーティーに現[あらわ]れた。", "sentence_source": "generated"}, {"text": "赤は危険を知らせる色として、標識によく使われる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "赤[あか]は危険[きけん]を知[し]らせる色[いろ]として、標識[ひょうしき]によく使[つか]われる。", "sentence_source": "generated"}, {"text": "白いシャツに赤を合わせると、明るい印象になる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "白[しろ]いシャツに赤[あか]を合[あ]わせると、明[あか]るい印象[いんしょう]になる。", "sentence_source": "generated"}, {"text": "この旗は、白地の中央に赤が大きく使われている。", "target_word": "赤", "complexity_tier": "T3", "furigana": "この旗[はた]は、白地[しろじ]の中央[ちゅうおう]に赤[あか]が大[おお]きく使[つか]われている。", "sentence_source": "generated"}, {"text": "青と赤を混ぜると、紫に近い色ができる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "青[あお]と赤[あか]を混[ま]ぜると、紫[むらさき]に近[ちか]い色[いろ]ができる。", "sentence_source": "generated"}, {"text": "秋になると、山の木々は赤と黄色に染まる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木々[きぎ]は赤[あか]と黄色[きいろ]に染[そ]まる。", "sentence_source": "generated"}, {"text": "看板の赤が目立つので、遠くからでも店がわかる。", "target_word": "赤", "complexity_tier": "T3", "furigana": "看板[かんばん]の赤[あか]が目立[めだ]つので、遠[とお]くからでも店[みせ]がわかる。", "sentence_source": "generated"}, {"text": "試験の答案には、先生が赤で丸をつけてくれた。", "target_word": "赤", "complexity_tier": "T3", "furigana": "試験[しけん]の答案[とうあん]には、先生[せんせい]が赤[あか]で丸[まる]をつけてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "色の名前。情熱や危険を連想させ、信号などに使われる色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51884, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白", "is_correct": false, "explanation": "白も色名として文法上は置けるが、情熱や緊急を連想させる色は赤で、白はこの対比の答えにならない。"}, {"text": "赤", "is_correct": true, "explanation": "情熱や緊急を連想させる色は赤。空欄に入るのはこの語。"}, {"text": "黒", "is_correct": false, "explanation": "黒は威厳や不安を表す色で、情熱や緊急の対比としては合わない。"}, {"text": "緑", "is_correct": false, "explanation": "緑は安全や自然を連想させる色で、情熱や緊急の対比としては合わない。"}], "explanations": {"白": "白も色名として文法上は置けるが、情熱や緊急を連想させる色は赤で、白はこの対比の答えにならない。", "赤": "情熱や緊急を連想させる色は赤。空欄に入るのはこの語。", "黒": "黒は威厳や不安を表す色で、情熱や緊急の対比としては合わない。", "緑": "緑は安全や自然を連想させる色で、情熱や緊急の対比としては合わない。"}, "sentence_index": 0, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年は会社が大きな赤を出した。", "explanation": "ここは〈赤字〉の意味。「赤を出す」は損失を出すことで、色名の赤ではない。"}, {"text": "男性ばかりの班で、彼女は赤一点の存在だった。", "explanation": "〈紅一点〉の〈紅〉を〈赤〉に替えたもの。〈紅一点〉は決まった四字熟語で、〈赤一点〉とは言わない。"}, {"text": "彼は学生時代、周りから赤と呼ばれていた。", "explanation": "ここは〈共産主義者〉の意味。人を指す俗称で、色名の赤ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51884, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄色", "is_correct": false, "explanation": "青と黄色を混ぜると緑になり、紫にはならない。"}, {"text": "赤", "is_correct": true, "explanation": "青と混ぜて紫に近い色になるのは赤。空欄に入るのはこの語。"}, {"text": "橙", "is_correct": false, "explanation": "青と橙を混ぜても紫にはならず、茶色っぽい色になる。"}, {"text": "茶色", "is_correct": false, "explanation": "青と茶色を混ぜても紫にはならず、暗いくすんだ色になる。"}], "explanations": {"黄色": "青と黄色を混ぜると緑になり、紫にはならない。", "赤": "青と混ぜて紫に近い色になるのは赤。空欄に入るのはこの語。", "橙": "青と橙を混ぜても紫にはならず、茶色っぽい色になる。", "茶色": "青と茶色を混ぜても紫にはならず、暗いくすんだ色になる。"}, "sentence_index": 6, "correct_answer": "赤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の帳簿は赤が続き、閉店を考えた。", "explanation": "ここは〈赤字〉の意味。帳簿の赤は損失を指し、色名の赤ではない。"}, {"text": "あの人は赤の他人だが、道を親切に教えてくれた。", "explanation": "ここは〈全くの他人〉の意味。「赤の他人」は決まった言い方で、色の意味ではない。"}, {"text": "祖父は戦時中、周りから赤と見られて苦労した。", "explanation": "ここは〈共産主義者〉の意味。人を指す俗称で、色名の赤ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51884, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "信号が赤が変わったので、バスは急停止した。", "corrected_sentence": "信号が赤に変わったので、バスは急停止した。", "error_description": "「変わる」は「に」で変化後の状態を示す。「赤が変わった」は「が」が誤りで、正しくは「赤に変わった」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51884, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は赤く服を着て、パーティーに現れた。", "corrected_sentence": "彼女は赤い服を着て、パーティーに現れた。", "error_description": "名詞「服」を修飾するには形容詞の連体形「赤い」が必要。「赤く」は連用形で、「着る」を修飾してしまうため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
