INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51885, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "空の色のような色。", "primary_collocate": null, "pronunciation": "あお", "ipa": "ao", "syllable_count": 2, "sentences": [{"text": "空は青で、雲は白です。", "target_word": "青", "complexity_tier": "T2", "furigana": "空[そら]は青[あお]で、雲[くも]は白[しろ]です。", "sentence_source": "generated"}, {"text": "わたしは青のくつを買いました。", "target_word": "青", "complexity_tier": "T2", "furigana": "わたしは青[あお]のくつを買[か]いました。", "sentence_source": "generated"}, {"text": "青と赤のどちらが好きですか。", "target_word": "青", "complexity_tier": "T2", "furigana": "青[あお]と赤[あか]のどちらが好[す]きですか。", "sentence_source": "generated"}, {"text": "海の青はとてもきれいでした。", "target_word": "青", "complexity_tier": "T2", "furigana": "海[うみ]の青[あお]はとてもきれいでした。", "sentence_source": "generated"}, {"text": "弟は青の自転車に乗っています。", "target_word": "青", "complexity_tier": "T2", "furigana": "弟[おとうと]は青[あお]の自転車[じてんしゃ]に乗[の]っています。", "sentence_source": "generated"}, {"text": "青のペンで絵に色をぬった。", "target_word": "青", "complexity_tier": "T2", "furigana": "青[あお]のペンで絵[え]に色[いろ]をぬった。", "sentence_source": "generated"}, {"text": "プールの水は、光があたって青に見える。", "target_word": "青", "complexity_tier": "T3", "furigana": "プールの水[みず]は、光[ひかり]があたって青[あお]に見[み]える。", "sentence_source": "generated"}, {"text": "新しいかばんは青にしようと思う。", "target_word": "青", "complexity_tier": "T3", "furigana": "新[あたら]しいかばんは青[あお]にしようと思[おも]う。", "sentence_source": "generated"}, {"text": "青の絵の具がなくなったので、買いに行った。", "target_word": "青", "complexity_tier": "T3", "furigana": "青[あお]の絵[え]の具[ぐ]がなくなったので、買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "雨がやむと、空は青に戻った。", "target_word": "青", "complexity_tier": "T3", "furigana": "雨[あめ]がやむと、空[そら]は青[あお]に戻[もど]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "青", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "空や海のような色の名前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51885, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤", "is_correct": false, "explanation": "赤は空の色ではなく、この文の空欄には合わない。"}, {"text": "緑", "is_correct": false, "explanation": "緑は草木の色で、空を表す色ではない。"}, {"text": "青", "is_correct": true, "explanation": "空の色として文中の空欄に入るのは青。"}, {"text": "茶色", "is_correct": false, "explanation": "茶色は土や木の色で、空の色としては合わない。"}], "explanations": {"赤": "赤は空の色ではなく、この文の空欄には合わない。", "緑": "緑は草木の色で、空を表す色ではない。", "青": "空の色として文中の空欄に入るのは青。", "茶色": "茶色は土や木の色で、空の色としては合わない。"}, "sentence_index": 0, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その原稿は青紙に戻されて、書き直しになった。", "explanation": "〈白紙に戻す〉の〈白〉を〈青〉に替えたもの。〈白紙〉は白で言い、〈青紙〉とは言わない。"}, {"text": "今シーズンは青星が続き、チームは苦しんだ。", "explanation": "勝ち負けは〈白星〉〈黒星〉で言う。〈青〉は星の勝敗には使わないので、〈青星〉は合わない。"}, {"text": "彼とは青の他人で、ほとんど話したことがない。", "explanation": "〈赤の他人〉の〈赤〉を〈青〉に替えたもの。まったくの他人を表す決まった言い方は〈赤の他人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51885, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茶色", "is_correct": false, "explanation": "茶色は泥水の色で、澄んだプールの水の描写に合わない。"}, {"text": "桃色", "is_correct": false, "explanation": "桃色は水が光を受けても見せる色ではなく、プールの水の描写として不自然。"}, {"text": "青", "is_correct": true, "explanation": "光が当たったプールの水が見せる色は青。空欄の答え。"}, {"text": "肌色", "is_correct": false, "explanation": "肌色は人の肌の色で、水の色を表す語としては合わない。"}], "explanations": {"茶色": "茶色は泥水の色で、澄んだプールの水の描写に合わない。", "桃色": "桃色は水が光を受けても見せる色ではなく、プールの水の描写として不自然。", "青": "光が当たったプールの水が見せる色は青。空欄の答え。", "肌色": "肌色は人の肌の色で、水の色を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議は青熱の議論になり、夜遅くまで続いた。", "explanation": "〈白熱〉の〈白〉を〈青〉に替えたもの。熱気を表すのは〈白熱〉で、〈青熱〉とは言わない。"}, {"text": "紺屋の青袴のように、職人の家はいつも身なりに無頓着だ。", "explanation": "ことわざ〈紺屋の白袴〉の〈白〉を〈青〉に替えたもの。決まった言い方は〈白袴〉で、〈青袴〉とは言わない。"}, {"text": "影で糸を引いていたのは、青幕の男だった。", "explanation": "〈黒幕〉の〈黒〉を〈青〉に替えたもの。陰で操る人は〈黒幕〉と言い、〈青幕〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51885, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は青にスーツを着ています。", "corrected_sentence": "父は青のスーツを着ています。", "error_description": "「青の〜」で色を修飾するには助詞「の」が必要。「青に」は誤りで、正しくは「青のスーツ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51885, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空は青くきれいだ。", "corrected_sentence": "空は青くてきれいだ。", "error_description": "形容詞「青い」を別の形容詞に続けるには連用形＋「て」が必要。「青くきれい」は誤りで、正しくは「青くてきれい」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
