INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51886, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "三原色の一つ。澄んだ空や海のような色。", "primary_collocate": null, "pronunciation": "あお", "ipa": "ao", "syllable_count": 2, "sentences": [{"text": "例えば、赤は情熱や緊急を、青は信頼を連想させる。", "target_word": "青", "complexity_tier": "T3", "furigana": "例[たと]えば、赤[あか]は情熱[じょうねつ]や緊急[きんきゅう]を、青[あお]は信頼[しんらい]を連想[れんそう]させる。", "sentence_source": "mined"}, {"text": "青は光の三原色の一つで、赤や緑と組み合わせて使う。", "target_word": "青", "complexity_tier": "T3", "furigana": "青[あお]は光[ひかり]の三原色[さんげんしょく]の一[ひと]つで、赤[あか]や緑[みどり]と組[く]み合[あ]わせて使[つか]う。", "sentence_source": "generated"}, {"text": "夏の海は、澄んだ青がどこまでも広がっていた。", "target_word": "青", "complexity_tier": "T3", "furigana": "夏[なつ]の海[うみ]は、澄[す]んだ青[あお]がどこまでも広[ひろ]がっていた。", "sentence_source": "generated"}, {"text": "画面の青を強くすると、全体が冷たい印象になる。", "target_word": "青", "complexity_tier": "T3", "furigana": "画面[がめん]の青[あお]を強[つよ]くすると、全体[ぜんたい]が冷[つめ]たい印象[いんしょう]になる。", "sentence_source": "generated"}, {"text": "雨が上がると、澄んだ青が空いっぱいに広がった。", "target_word": "青", "complexity_tier": "T3", "furigana": "雨[あめ]が上[あ]がると、澄[す]んだ青[あお]が空[そら]いっぱいに広[ひろ]がった。", "sentence_source": "generated"}, {"text": "彼は青のジャケットに白いシャツを合わせた。", "target_word": "青", "complexity_tier": "T3", "furigana": "彼[かれ]は青[あお]のジャケットに白[しろ]いシャツを合[あ]わせた。", "sentence_source": "generated"}, {"text": "空の青と雲の白が、きれいな対比をなしていた。", "target_word": "青", "complexity_tier": "T3", "furigana": "空[そら]の青[あお]と雲[くも]の白[しろ]が、きれいな対比[たいひ]をなしていた。", "sentence_source": "generated"}, {"text": "青と黄色を混ぜると、緑色になる。", "target_word": "青", "complexity_tier": "T3", "furigana": "青[あお]と黄色[きいろ]を混[ま]ぜると、緑色[みどりいろ]になる。", "sentence_source": "generated"}, {"text": "この絵は、深い青を使って静かな夜を描いている。", "target_word": "青", "complexity_tier": "T3", "furigana": "この絵[え]は、深[ふか]い青[あお]を使[つか]って静[しず]かな夜[よる]を描[えが]いている。", "sentence_source": "generated"}, {"text": "制服のネクタイは、紺ではなく明るい青に決まった。", "target_word": "青", "complexity_tier": "T3", "furigana": "制服[せいふく]のネクタイは、紺[こん]ではなく明[あか]るい青[あお]に決[き]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "青", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "三原色の一つ。澄んだ空や海のような色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 三原色 (Zipf 2.33)']::text[], '830f321e-9b60-438b-aad8-359bdfb0dd5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51886, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桃色", "is_correct": false, "explanation": "桃色は親しみや優しさを表す色で、信頼を連想させる色とは言いにくい。"}, {"text": "黄色", "is_correct": false, "explanation": "黄色は注意や明るさを連想させる色で、信頼の答えではない。"}, {"text": "青", "is_correct": true, "explanation": "信頼を連想させる色は青。空欄に入るのはこの語。"}, {"text": "黒", "is_correct": false, "explanation": "黒は威厳や重さを連想させる色で、信頼の答えとしては誤り。"}], "explanations": {"桃色": "桃色は親しみや優しさを表す色で、信頼を連想させる色とは言いにくい。", "黄色": "黄色は注意や明るさを連想させる色で、信頼の答えではない。", "青": "信頼を連想させる色は青。空欄に入るのはこの語。", "黒": "黒は威厳や重さを連想させる色で、信頼の答えとしては誤り。"}, "sentence_index": 0, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その提案は青紙のまま、来月まで保留になった。", "explanation": "〈白紙〉の〈白〉を〈青〉に替えたもの。「白紙のまま」とは言うが、〈青紙〉とは言わない。"}, {"text": "今日の試合は青星で終わった。", "explanation": "勝ち負けは〈白星〉〈黒星〉で言う。〈青〉は星の勝敗には使わないので、〈青星〉は合わない。"}, {"text": "隣に越してきた人は青の他人だが、毎朝挨拶してくれる。", "explanation": "〈赤の他人〉の〈赤〉を〈青〉に替えたもの。まったくの他人を表す決まった言い方は〈赤の他人〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51886, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "茶色", "is_correct": false, "explanation": "茶色は土や木の色で、澄んだ空と白い雲の対比には使わない。"}, {"text": "青", "is_correct": true, "explanation": "空の色として雲の白と対比させる色は青。空欄の答え。"}, {"text": "桃色", "is_correct": false, "explanation": "桃色は花や頬の色で、空を表す色としては不自然で対比が成り立たない。"}, {"text": "肌色", "is_correct": false, "explanation": "肌色は人の肌の色を指すので、空の色を描写する語としては合わない。"}], "explanations": {"茶色": "茶色は土や木の色で、澄んだ空と白い雲の対比には使わない。", "青": "空の色として雲の白と対比させる色は青。空欄の答え。", "桃色": "桃色は花や頬の色で、空を表す色としては不自然で対比が成り立たない。", "肌色": "肌色は人の肌の色を指すので、空の色を描写する語としては合わない。"}, "sentence_index": 6, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合は青熱の展開になり、観客が沸いた。", "explanation": "〈白熱〉の〈白〉を〈青〉に替えたもの。熱気を表すのは〈白熱〉で、〈青熱〉とは言わない。"}, {"text": "影で糸を引いていたのは、青幕の男だった。", "explanation": "〈黒幕〉の〈黒〉を〈青〉に替えたもの。陰で操る人は〈黒幕〉と言い、〈青幕〉とは言わない。"}, {"text": "紺屋の青袴で、いつも身なりがだらしない。", "explanation": "ことわざ〈紺屋の白袴〉の〈白〉を〈青〉に替えたもの。決まった言い方は〈白袴〉で、〈青袴〉とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51886, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "川の水面は、澄んだ青に映していた。", "corrected_sentence": "川の水面は、澄んだ青を映していた。", "error_description": "「映す」の対象は「を」で示す。「青に」は誤りで、正しくは「青を映していた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51886, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は青くシャツを着ていた。", "corrected_sentence": "彼は青いシャツを着ていた。", "error_description": "名詞「シャツ」を修飾する形容詞は連体形「青い」が必要。「青く」は連用形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6eb6c740-f214-43dc-8e1c-c719d42eb9e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
