INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51887, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "すぐに、たいへんなことをしなければならないこと。", "primary_collocate": null, "pronunciation": "きんきゅう", "ipa": "kʲiŋkʲɯː", "syllable_count": 4, "sentences": [{"text": "緊急の用事ができたので、会議を先に出ます。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の用事[ようじ]ができたので、会議[かいぎ]を先[さき]に出[で]ます。", "sentence_source": "generated"}, {"text": "社長から緊急だと言われ、すぐに会社へ戻った。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "社長[しゃちょう]から緊急[きんきゅう]だと言[い]われ、すぐに会社[かいしゃ]へ戻[もど]った。", "sentence_source": "generated"}, {"text": "これは緊急の仕事なので、今日中に終わらせてください。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "これは緊急[きんきゅう]の仕事[しごと]なので、今日中[きょうじゅう]に終[お]わらせてください。", "sentence_source": "generated"}, {"text": "緊急に必要な書類を、急いでコピーした。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]に必要[ひつよう]な書類[しょるい]を、急[いそ]いでコピーした。", "sentence_source": "generated"}, {"text": "緊急ではないから、明日の朝に相談しましょう。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]ではないから、明日[あした]の朝[あさ]に相談[そうだん]しましょう。", "sentence_source": "generated"}, {"text": "緊急のときは、この番号に電話してください。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]のときは、この番号[ばんごう]に電話[でんわ]してください。", "sentence_source": "generated"}, {"text": "弟から緊急のメッセージが届き、びっくりした。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "弟[おとうと]から緊急[きんきゅう]のメッセージが届[とど]き、びっくりした。", "sentence_source": "generated"}, {"text": "緊急の用だと言うので、食事の途中で席を立った。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の用[よう]だと言[い]うので、食事[しょくじ]の途中[とちゅう]で席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "先生は緊急の話があると言って、私たちを集めた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "先生[せんせい]は緊急[きんきゅう]の話[はなし]があると言[い]って、私[わたし]たちを集[あつ]めた。", "sentence_source": "generated"}, {"text": "緊急の手続きがあり、朝から役所へ行った。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の手続[てつづ]きがあり、朝[あさ]から役所[やくしょ]へ行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊急だ", "label": "断定形"}, {"form": "緊急の", "label": "連体形"}, {"form": "緊急に", "label": "連用形"}, {"form": "緊急ではない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "すぐに大事なことをしなければならない用事や仕事の性質", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51887, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "「すぐに対処が必要な」の意味で、用事の性質を表すので文に合う。"}, {"text": "不吉", "is_correct": false, "explanation": "縁起が悪い様子を表す。「不吉の用事」とは言えず、用事の性質としては入らない。"}, {"text": "静穏", "is_correct": false, "explanation": "物音や動きがない様子を表す。「静穏の用事」は成り立たず、空所に入らない。"}, {"text": "鮮明", "is_correct": false, "explanation": "輪郭や色がはっきりしている様子を表す。用事の形容には合わない。"}], "explanations": {"緊急": "「すぐに対処が必要な」の意味で、用事の性質を表すので文に合う。", "不吉": "縁起が悪い様子を表す。「不吉の用事」とは言えず、用事の性質としては入らない。", "静穏": "物音や動きがない様子を表す。「静穏の用事」は成り立たず、空所に入らない。", "鮮明": "輪郭や色がはっきりしている様子を表す。用事の形容には合わない。"}, "sentence_index": 0, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "試合の前に、緊急な気持ちになった。", "explanation": "ここは〈緊張〉の意味。緊急は差し迫って対処が必要な事態に使い、気持ちの張りつめた状態には使わない。"}, {"text": "窓の外では緊急な雨が降りだした。", "explanation": "ここは〈急〉の意味（急な雨）。緊急は対処が必要な事態を指すので、雨が突然降るさまは表せない。"}, {"text": "彼女から贈られた緊急な思い出を、今も大切にしている。", "explanation": "ここは〈かけがえのない〉の意味（かけがえのない思い出）。緊急は差し迫った対応の必要性を表すので、思い出の尊さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51887, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "「すぐに対処が必要な」の意味で、メッセージの性質として文に合う。"}, {"text": "厳か", "is_correct": false, "explanation": "格式ばって重々しい様子を表す。「厳かのメッセージ」とは言えず、空所に入らない。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく楽しげな様子を表す。メッセージの性質の形容としては入らない。"}, {"text": "純粋", "is_correct": false, "explanation": "混じりけのない様子を表す。「純粋のメッセージ」は不自然で、文に合わない。"}], "explanations": {"緊急": "「すぐに対処が必要な」の意味で、メッセージの性質として文に合う。", "厳か": "格式ばって重々しい様子を表す。「厳かのメッセージ」とは言えず、空所に入らない。", "陽気": "明るく楽しげな様子を表す。メッセージの性質の形容としては入らない。", "純粋": "混じりけのない様子を表す。「純粋のメッセージ」は不自然で、文に合わない。"}, "sentence_index": 6, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は緊急な態度で、客に丁寧に接した。", "explanation": "ここは〈誠実〉の意味（誠実な態度）。緊急は差し迫った状況を表すので、人の態度の誠実さは表せない。"}, {"text": "彼女は緊急な才能に恵まれている。", "explanation": "ここは〈豊か〉の意味（豊かな才能）。緊急は差し迫った事態を指すので、才能の多さには合わない。"}, {"text": "海は緊急に静まり返っていた。", "explanation": "ここは〈穏やか〉の意味。緊急は差し迫った状態を表し、海が穏やかに静まる様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51887, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "緊急を知らせが入ったので、会議を抜けます。", "corrected_sentence": "緊急の知らせが入ったので、会議を抜けます。", "error_description": "「緊急」に続く助詞が誤り。名詞「知らせ」を修飾するには「の」を使い、「を」は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "文中の「緊急だと」の「緊急だ」の語幹にあたり、断定の「だ」の前に来る形。"}, {"text": "緊急の", "is_correct": false, "explanation": "連体形。名詞の前に付く形で、「だと言われ」の位置には入らない。"}, {"text": "緊急に", "is_correct": false, "explanation": "連用形。動詞や形容詞を修飾する形で、「だと言われ」の文脈に合わない。"}, {"text": "緊急ではない", "is_correct": false, "explanation": "否定形。肯定の「だ」を「ではない」にすると、文の意味が逆になる。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 1, "explanations": {"緊急": "文中の「緊急だと」の「緊急だ」の語幹にあたり、断定の「だ」の前に来る形。", "緊急の": "連体形。名詞の前に付く形で、「だと言われ」の位置には入らない。", "緊急に": "連用形。動詞や形容詞を修飾する形で、「だと言われ」の文脈に合わない。", "緊急ではない": "否定形。肯定の「だ」を「ではない」にすると、文の意味が逆になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51887, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊急く連絡が来たので、すぐに出かけた。", "corrected_sentence": "緊急の連絡が来たので、すぐに出かけた。", "error_description": "「緊急」の語尾が誤り。名詞「連絡」を修飾する形は「緊急の」で、「緊急く」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "緊急", "is_correct": true, "explanation": "語幹の形で、「の」や「だ」などが付く前の基本の形。"}, {"text": "緊急だ", "is_correct": false, "explanation": "断定形。名詞「用」を直接修飾できず、「用」の前に置くと文が成り立たない。"}, {"text": "緊急で", "is_correct": false, "explanation": "中止形。「で」で文をつなぐ形で、名詞「用」を修飾できない。"}, {"text": "緊急ではなかった", "is_correct": false, "explanation": "否定の過去形。「用」を修飾すると意味が逆になり、「だと言うので」の理由が成り立たない。"}], "correct_form": "緊急", "base_form": "緊急", "form_label": "語幹", "sentence_index": 7, "explanations": {"緊急": "語幹の形で、「の」や「だ」などが付く前の基本の形。", "緊急だ": "断定形。名詞「用」を直接修飾できず、「用」の前に置くと文が成り立たない。", "緊急で": "中止形。「で」で文をつなぐ形で、名詞「用」を修飾できない。", "緊急ではなかった": "否定の過去形。「用」を修飾すると意味が逆になり、「だと言うので」の理由が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
