INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51888, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が差し迫っていて、すぐに対処しなければならない状態。また、そのような事態。", "primary_collocate": null, "pronunciation": "きんきゅう", "ipa": "kʲiŋkʲɯː", "syllable_count": 4, "sentences": [{"text": "市は緊急の会議を開き、対策を話し合った。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "市[し]は緊急[きんきゅう]の会議[かいぎ]を開[ひら]き、対策[たいさく]を話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "緊急に処理すべき課題が、まだ山のように残っている。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]に処理[しょり]すべき課題[かだい]が、まだ山[やま]のように残[のこ]っている。", "sentence_source": "generated"}, {"text": "この問題は緊急を要するため、今週中に決定したい。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "この問題[もんだい]は緊急[きんきゅう]を要[よう]するため、今週中[こんしゅうちゅう]に決定[けってい]したい。", "sentence_source": "generated"}, {"text": "緊急の課題として、人手不足の解消が挙げられた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の課題[かだい]として、人手不足[ひとでぶそく]の解消[かいしょう]が挙[あ]げられた。", "sentence_source": "generated"}, {"text": "台風の接近で、緊急の対策が求められている。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "台風[たいふう]の接近[せっきん]で、緊急[きんきゅう]の対策[たいさく]が求[もと]められている。", "sentence_source": "generated"}, {"text": "政府は緊急に支援金を出すと発表した。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "政府[せいふ]は緊急[きんきゅう]に支援金[しえんきん]を出[だ]すと発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "現地では緊急の事態が続き、報告が次々に届いた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "現地[げんち]では緊急[きんきゅう]の事態[じたい]が続[つづ]き、報告[ほうこく]が次々[つぎつぎ]に届[とど]いた。", "sentence_source": "generated"}, {"text": "報告書には、緊急かつ重要な点が三つ書かれていた。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]には、緊急[きんきゅう]かつ重要[じゅうよう]な点[てん]が三[みっ]つ書[か]かれていた。", "sentence_source": "generated"}, {"text": "状況は緊急で、一日の遅れも許されない。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "状況[じょうきょう]は緊急[きんきゅう]で、一日[いちにち]の遅[おく]れも許[ゆる]されない。", "sentence_source": "generated"}, {"text": "緊急の場合に備えて、非常用の食料を用意しておく。", "target_word": "緊急", "complexity_tier": "T3", "furigana": "緊急[きんきゅう]の場合[ばあい]に備[そな]えて、非常用[ひじょうよう]の食料[しょくりょう]を用意[ようい]しておく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "緊急", "label": "基本形"}, {"form": "緊急の", "label": "連体形"}, {"form": "緊急に", "label": "連用形"}, {"form": "緊急を要する", "label": "慣用表現"}], "register": "formal", "sense_fingerprint": "物事が差し迫り、すぐ対処が必要な状態や事態（公的・報道的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51888, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "差し迫って対処が必要な会議であることを表し、文に合う。"}, {"text": "静穏", "is_correct": false, "explanation": "物音がない様子を表す。「静穏の会議」は成り立たず、空所に入らない。"}, {"text": "鮮明", "is_correct": false, "explanation": "輪郭がはっきりした様子を表す。会議の形容には合わない。"}, {"text": "不吉", "is_correct": false, "explanation": "縁起が悪い様子を表す。「不吉の会議」は文脈に合わない。"}], "explanations": {"緊急": "差し迫って対処が必要な会議であることを表し、文に合う。", "静穏": "物音がない様子を表す。「静穏の会議」は成り立たず、空所に入らない。", "鮮明": "輪郭がはっきりした様子を表す。会議の形容には合わない。", "不吉": "縁起が悪い様子を表す。「不吉の会議」は文脈に合わない。"}, "sentence_index": 0, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議室には緊急な空気が流れた。", "explanation": "ここは〈緊迫〉の意味（緊迫した空気）。緊急は対処が必要な事態を表し、張りつめた雰囲気の描写には使わない。"}, {"text": "最後まで緊急な試合が続いた。", "explanation": "ここは〈白熱〉の意味（白熱した試合）。緊急は差し迫った事態への対処を表し、熱戦の盛り上がりには使わない。"}, {"text": "期限までまだ緊急がある。", "explanation": "ここは〈猶予〉の意味。緊急は差し迫った事態を表し、期限までの余裕は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51888, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "緊急", "is_correct": true, "explanation": "「差し迫った」事態の性質を表し、文に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "明るく楽しげな様子を表す。「陽気の事態」は成り立たない。"}, {"text": "厳か", "is_correct": false, "explanation": "格式ばった重々しい様子を表す。事態の形容には合わない。"}, {"text": "純粋", "is_correct": false, "explanation": "混じりけのない様子を表す。「純粋の事態」は文脈に合わない。"}], "explanations": {"緊急": "「差し迫った」事態の性質を表し、文に合う。", "陽気": "明るく楽しげな様子を表す。「陽気の事態」は成り立たない。", "厳か": "格式ばった重々しい様子を表す。事態の形容には合わない。", "純粋": "混じりけのない様子を表す。「純粋の事態」は文脈に合わない。"}, "sentence_index": 6, "correct_answer": "緊急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この緊急は、多くの人に愛される名作だ。", "explanation": "ここは〈作品〉の意味。緊急は差し迫った事態を指し、芸術の成果物には使わない。"}, {"text": "この食事は緊急が豊富で、体にいい。", "explanation": "ここは〈栄養〉の意味（栄養が豊富）。緊急は差し迫った事態を表し、体に必要な成分は表さない。"}, {"text": "庭に緊急が漂っている。", "explanation": "ここは〈香り〉の意味。緊急は差し迫った事態を表し、匂いは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51888, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は緊急を対策会議を開き、今夜の対応を決めた。", "corrected_sentence": "市は緊急の対策会議を開き、今夜の対応を決めた。", "error_description": "「緊急」の直後に「を」を続けるのは誤り。名詞「対策会議」を修飾するには「の」を使う。（「緊急を要する」は慣用句なので例外。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51888, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "緊急が対策が求められ、人手が集まった。", "corrected_sentence": "緊急の対策が求められ、人手が集まった。", "error_description": "「緊急」に続く「が」が誤り。名詞「対策」を修飾するには「の」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
