INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51889, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "じょうずに、うまく。", "primary_collocate": null, "pronunciation": "たくみ", "ipa": "takɯmi", "syllable_count": 3, "sentences": [{"text": "猫は狭い隙間を巧みにすり抜けていった。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "猫[ねこ]は狭[せま]い隙間[すきま]を巧[たく]みにすり抜[ぬ]けていった。", "sentence_source": "generated"}, {"text": "彼は船を巧みに操って、激しい波を乗り越えた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼[かれ]は船[ふね]を巧[たく]みに操[あやつ]って、激[はげ]しい波[なみ]を乗[の]り越[こ]えた。", "sentence_source": "generated"}, {"text": "母は限られた食材を巧みに使い、豪華な夕食を作った。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "母[はは]は限[かぎ]られた食材[しょくざい]を巧[たく]みに使[つか]い、豪華[ごうか]な夕食[ゆうしょく]を作[つく]った。", "sentence_source": "generated"}, {"text": "彼女はピアノの音色を巧みに変えて、悲しい場面を表した。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はピアノの音色[ねいろ]を巧[たく]みに変[か]えて、悲[かな]しい場面[ばめん]を表[あらわ]した。", "sentence_source": "generated"}, {"text": "政治家は難しい質問を巧みにはぐらかした。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "政治家[せいじか]は難[むずか]しい質問[しつもん]を巧[たく]みにはぐらかした。", "sentence_source": "generated"}, {"text": "子どもたちは先生の目を巧みに避けて、教室を抜け出した。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "子[こ]どもたちは先生[せんせい]の目[め]を巧[たく]みに避[さ]けて、教室[きょうしつ]を抜[ぬ]け出[だ]した。", "sentence_source": "generated"}, {"text": "彼は外国語を巧みに話すので、通訳を任されている。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼[かれ]は外国語[がいこくご]を巧[たく]みに話[はな]すので、通訳[つうやく]を任[まか]されている。", "sentence_source": "generated"}, {"text": "彼女は色を巧みに組み合わせて、明るい部屋にした。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は色[いろ]を巧[たく]みに組[く]み合[あ]わせて、明[あか]るい部屋[へや]にした。", "sentence_source": "generated"}, {"text": "運転手は混んだ道を巧みに走り、時間通りに着いた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "運転手[うんてんしゅ]は混[こ]んだ道[みち]を巧[たく]みに走[はし]り、時間[じかん]通[どお]りに着[つ]いた。", "sentence_source": "generated"}, {"text": "画家は光と影を巧みに描き分けている。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "画家[がか]は光[ひかり]と影[かげ]を巧[たく]みに描[か]き分[わ]けている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巧みだ", "label": "終止形"}, {"form": "巧みな", "label": "連体形"}, {"form": "巧みに", "label": "連用形"}, {"form": "巧みで", "label": "中止形"}], "register": "文章語・やや改まった表現", "sense_fingerprint": "じょうずに、うまく(連用形「巧みに」で動作を修飾する用法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51889, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧み", "is_correct": true, "explanation": "「狭い隙間をすり抜ける」の仕方を、無理なく上手に行う様子として表せるのは「巧み」だけ。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈」は丈夫で壊れにくい状態を表すので、すり抜ける動作の仕方として合わない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔」は汚れがない状態を表すので、動作の様子としては成り立たない。"}, {"text": "几帳面", "is_correct": false, "explanation": "「几帳面」は物事を細かく整える性格を表すので、すり抜ける動作には合わない。"}], "explanations": {"巧み": "「狭い隙間をすり抜ける」の仕方を、無理なく上手に行う様子として表せるのは「巧み」だけ。", "頑丈": "「頑丈」は丈夫で壊れにくい状態を表すので、すり抜ける動作の仕方として合わない。", "清潔": "「清潔」は汚れがない状態を表すので、動作の様子としては成り立たない。", "几帳面": "「几帳面」は物事を細かく整える性格を表すので、すり抜ける動作には合わない。"}, "sentence_index": 0, "correct_answer": "巧み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は巧みに足を滑らせて、転んでしまった。", "explanation": "ここは〈不運〉の意味。巧みは技術や工夫で行う様子なので、転ぶ失敗には合わない。"}, {"text": "宝くじが巧みに当たった。", "explanation": "ここは〈偶然〉の意味。巧みは人が腕や工夫で行う様子を表すので、くじの当たりには使わない。"}, {"text": "彼は巧みに皿を割ってしまった。", "explanation": "ここは〈不注意〉の意味。巧みは上手にやり遂げることを表すので、失敗の描写には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51889, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧み", "is_correct": true, "explanation": "「外国語を巧みに話す」は、上手に話せることを表し、通訳を任される理由として自然に入る。"}, {"text": "身勝手", "is_correct": false, "explanation": "「身勝手」は自分本位の態度を表すので、話し方を表せず空所に入らない。"}, {"text": "窮屈", "is_correct": false, "explanation": "「窮屈」は狭くて動きにくい様子を表すので、話し方には使えない。"}, {"text": "乱雑", "is_correct": false, "explanation": "「乱雑」は散らかった様子を表すので、外国語の話し方には合わない。"}], "explanations": {"巧み": "「外国語を巧みに話す」は、上手に話せることを表し、通訳を任される理由として自然に入る。", "身勝手": "「身勝手」は自分本位の態度を表すので、話し方を表せず空所に入らない。", "窮屈": "「窮屈」は狭くて動きにくい様子を表すので、話し方には使えない。", "乱雑": "「乱雑」は散らかった様子を表すので、外国語の話し方には合わない。"}, "sentence_index": 6, "correct_answer": "巧み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は巧みに眠りこけて、会議に遅れた。", "explanation": "ここは〈寝坊〉の意味。巧みは技術や工夫のうまさを表すので、眠りこける失敗には合わない。"}, {"text": "彼は巧みに絵の具を床にこぼした。", "explanation": "ここは〈不注意〉の意味。巧みは技術や工夫のうまさを表すので、絵の具をこぼす失敗には合わない。"}, {"text": "彼は巧みに慌てふためいた。", "explanation": "ここは〈慌てふためく〉の意味。取り乱す様子で、巧みは技術や工夫で行う様子を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51889, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "男の子は人混みを巧みで抜けていった。", "corrected_sentence": "男の子は人混みを巧みに抜けていった。", "error_description": "「巧みで」は中止形で、動詞「抜ける」を修飾できない。連用形「巧みに」が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "巧みに", "is_correct": true, "explanation": "連用形。動詞「操って」を修飾する形。"}, {"text": "巧みだ", "is_correct": false, "explanation": "終止形で、「船を〜操って」と動詞を修飾できない。"}, {"text": "巧みな", "is_correct": false, "explanation": "連体形で名詞を修飾する形。動詞「操る」の前には置けない。"}, {"text": "巧みで", "is_correct": false, "explanation": "中止形で、「船を巧みで操って」は動詞を修飾できない。"}], "correct_form": "巧みに", "base_form": "巧みだ", "form_label": "連用形", "sentence_index": 1, "explanations": {"巧みに": "連用形。動詞「操って」を修飾する形。", "巧みだ": "終止形で、「船を〜操って」と動詞を修飾できない。", "巧みな": "連体形で名詞を修飾する形。動詞「操る」の前には置けない。", "巧みで": "中止形で、「船を巧みで操って」は動詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51889, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "画家は絵の具を巧みな混ぜ、柔らかい色を作った。", "corrected_sentence": "画家は絵の具を巧みに混ぜ、柔らかい色を作った。", "error_description": "連体形「巧みな」は名詞を修飾する形で、動詞「混ぜる」は修飾できない。連用形「巧みに」が必要。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "巧みに", "is_correct": true, "explanation": "連用形。動詞「組み合わせて」を修飾する形。"}, {"text": "巧みである", "is_correct": false, "explanation": "断定の形で、「組み合わせて」という動詞を修飾できない。"}, {"text": "巧みだった", "is_correct": false, "explanation": "過去の断定の形で、動詞の前に置いて修飾することはできない。"}, {"text": "巧みだろう", "is_correct": false, "explanation": "推量の形で、「組み合わせて」を修飾する位置には入らない。"}], "correct_form": "巧みに", "base_form": "巧みだ", "form_label": "連用形", "sentence_index": 7, "explanations": {"巧みに": "連用形。動詞「組み合わせて」を修飾する形。", "巧みである": "断定の形で、「組み合わせて」という動詞を修飾できない。", "巧みだった": "過去の断定の形で、動詞の前に置いて修飾することはできない。", "巧みだろう": "推量の形で、「組み合わせて」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
