INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51890, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事を技術や工夫を使って、うまく行うさま。", "primary_collocate": null, "pronunciation": "たくみ", "ipa": "takɯmi", "syllable_count": 3, "sentences": [{"text": "企業はブランディングにおいて、色彩理論を巧みに利用している。", "target_word": "巧み", "complexity_tier": "T4", "furigana": "企業[きぎょう]はブランディングにおいて、色彩[しきさい]理論[りろん]を巧[たく]みに利用[りよう]している。", "sentence_source": "mined"}, {"text": "彼は言葉を巧みに使って、客の心をつかんだ。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼[かれ]は言葉[ことば]を巧[たく]みに使[つか]って、客[きゃく]の心[こころ]をつかんだ。", "sentence_source": "generated"}, {"text": "職人は巧みな手さばきで、あっという間に魚をさばいた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "職人[しょくにん]は巧[たく]みな手[て]さばきで、あっという間[ま]に魚[さかな]をさばいた。", "sentence_source": "generated"}, {"text": "彼女は巧みな話術で、会議の空気を和らげた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は巧[たく]みな話術[わじゅつ]で、会議[かいぎ]の空気[くうき]を和[やわ]らげた。", "sentence_source": "generated"}, {"text": "彼は相手の動きを読み、巧みにボールをかわした。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼[かれ]は相手[あいて]の動[うご]きを読[よ]み、巧[たく]みにボールをかわした。", "sentence_source": "generated"}, {"text": "この作家は人物の心の動きを巧みに描いている。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "この作家[さっか]は人物[じんぶつ]の心[こころ]の動[うご]きを巧[たく]みに描[えが]いている。", "sentence_source": "generated"}, {"text": "巧みな演出のおかげで、この映画は最後まで飽きずに見られた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "巧[たく]みな演出[えんしゅつ]のおかげで、この映画[えいが]は最後[さいご]まで飽[あ]きずに見[み]られた。", "sentence_source": "generated"}, {"text": "店長はお客さんの不満を巧みにかわして、その場をおさめた。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "店長[てんちょう]はお客[きゃく]さんの不満[ふまん]を巧[たく]みにかわして、その場[ば]をおさめた。", "sentence_source": "generated"}, {"text": "巧みな交渉によって、会社は有利な条件で契約を結ぶことができた。", "target_word": "巧み", "complexity_tier": "T4", "furigana": "巧[たく]みな交渉[こうしょう]によって、会社[かいしゃ]は有利[ゆうり]な条件[じょうけん]で契約[けいやく]を結[むす]ぶことができた。", "sentence_source": "generated"}, {"text": "彼女は糸を巧みに操り、人形を生きているように動かした。", "target_word": "巧み", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は糸[いと]を巧[たく]みに操[あやつ]り、人形[にんぎょう]を生[い]きているように動[うご]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巧みだ", "label": "終止形"}, {"form": "巧みな", "label": "連体形"}, {"form": "巧みに", "label": "連用形"}, {"form": "巧みで", "label": "中止形"}], "register": "文章語・やや改まった表現", "sense_fingerprint": "技術や工夫を使って物事をうまく行う様子(巧みに・巧みな)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51890, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧み", "is_correct": true, "explanation": "「色彩理論を〜に利用する」の空所には、技術や工夫で物事をうまく行う様子を表す「巧み」だけが入る。"}, {"text": "頑丈", "is_correct": false, "explanation": "「頑丈」は丈夫で壊れにくい状態を表すので、利用の仕方の上手さを表す文脈には合わない。"}, {"text": "上機嫌", "is_correct": false, "explanation": "「上機嫌に利用している」は気分を表す語で、理論の利用の仕方としては不自然。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気」は明るく快活な雰囲気を表すので、「陽気に利用している」は意味が通らない。"}], "explanations": {"巧み": "「色彩理論を〜に利用する」の空所には、技術や工夫で物事をうまく行う様子を表す「巧み」だけが入る。", "頑丈": "「頑丈」は丈夫で壊れにくい状態を表すので、利用の仕方の上手さを表す文脈には合わない。", "上機嫌": "「上機嫌に利用している」は気分を表す語で、理論の利用の仕方としては不自然。", "陽気": "「陽気」は明るく快活な雰囲気を表すので、「陽気に利用している」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "巧み"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の巧みな寝顔は、家族を笑わせた。", "explanation": "ここは〈かわいらしさ〉の意味。巧みは技術や工夫のうまさを表すので、寝顔の形容には合わない。"}, {"text": "彼は巧みに大きなくしゃみをして、会議を中断させた。", "explanation": "ここは〈派手さ〉の意味。巧みは技術や工夫のうまさを表すので、くしゃみの大きさには合わない。"}, {"text": "雨が巧みにやんだ。", "explanation": "ここは〈偶然〉の意味。巧みは人が技術や工夫で行う様子に使うので、天候の変化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51890, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧み", "is_correct": true, "explanation": "「巧みな演出」は技術や工夫の見事さを表し、映画の出来を評価する文脈で空所に入る。"}, {"text": "身勝手", "is_correct": false, "explanation": "「身勝手」は自分本位の態度を表すので、演出には使えない。"}, {"text": "清潔", "is_correct": false, "explanation": "「清潔」は汚れがない状態を表すので、演出の出来を表す文脈には合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "「退屈な演出のおかげで飽きずに見られた」は文意が逆になり合わない。"}], "explanations": {"巧み": "「巧みな演出」は技術や工夫の見事さを表し、映画の出来を評価する文脈で空所に入る。", "身勝手": "「身勝手」は自分本位の態度を表すので、演出には使えない。", "清潔": "「清潔」は汚れがない状態を表すので、演出の出来を表す文脈には合わない。", "退屈": "「退屈な演出のおかげで飽きずに見られた」は文意が逆になり合わない。"}, "sentence_index": 6, "correct_answer": "巧み"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は巧みに財布を落として、友人に笑われた。", "explanation": "ここは〈不注意〉の意味。巧みは技術や工夫のうまさを表すので、財布を落とす失敗には合わない。"}, {"text": "彼女は巧みに風邪をひいて、旅行を断念した。", "explanation": "ここは〈不運〉の意味。巧みは技術や工夫で行う様子なので、風邪をひくことには合わない。"}, {"text": "彼は巧みに電車に乗り遅れた。", "explanation": "ここは〈慌てる〉の意味。慌てた結果の失敗を表す文で、巧みは成功させる技術や工夫の様子なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51890, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "職人は道具を巧みで使い、細かな細工を仕上げた。", "corrected_sentence": "職人は道具を巧みに使い、細かな細工を仕上げた。", "error_description": "「巧みで」は中止形で、動詞「使う」を修飾できない。動詞を修飾する連用形「巧みに」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "巧みに", "is_correct": true, "explanation": "連用形。動詞「使って」を修飾する形。"}, {"text": "巧みだ", "is_correct": false, "explanation": "終止形で、「言葉を〜使って」と動詞を修飾できない。"}, {"text": "巧みな", "is_correct": false, "explanation": "連体形で名詞を修飾する形。動詞「使う」の前には置けない。"}, {"text": "巧みで", "is_correct": false, "explanation": "中止形で、「言葉を巧みで使って」は動詞を修飾できない。"}], "correct_form": "巧みに", "base_form": "巧みだ", "form_label": "連用形", "sentence_index": 1, "explanations": {"巧みに": "連用形。動詞「使って」を修飾する形。", "巧みだ": "終止形で、「言葉を〜使って」と動詞を修飾できない。", "巧みな": "連体形で名詞を修飾する形。動詞「使う」の前には置けない。", "巧みで": "中止形で、「言葉を巧みで使って」は動詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51890, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は糸を巧みを操り、人形を生きているように見せた。", "corrected_sentence": "彼女は糸を巧みに操り、人形を生きているように見せた。", "error_description": "「巧み」に格助詞「を」を付けている。副詞の「巧みに」は助詞を続けず、動詞「操る」を直接修飾する。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "巧みに", "is_correct": true, "explanation": "連用形。動詞「かわして」を修飾する形。"}, {"text": "巧みである", "is_correct": false, "explanation": "断定の形で、「かわして」という動詞を修飾できない。"}, {"text": "巧みだった", "is_correct": false, "explanation": "過去の断定の形で、動詞の前に置いて修飾することはできない。"}, {"text": "巧みだろう", "is_correct": false, "explanation": "推量の形で、「かわして」を修飾する位置には入らない。"}], "correct_form": "巧みに", "base_form": "巧みだ", "form_label": "連用形", "sentence_index": 7, "explanations": {"巧みに": "連用形。動詞「かわして」を修飾する形。", "巧みである": "断定の形で、「かわして」という動詞を修飾できない。", "巧みだった": "過去の断定の形で、動詞の前に置いて修飾することはできない。", "巧みだろう": "推量の形で、「かわして」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「正義感を植え付けてくれる」の形で、植え付ける対象を示す目的語になる。"}, {"text": "と", "is_correct": false, "explanation": "「正義感と植え付けてくれる」は並列の形で、続く動詞の対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「正義感へ植え付けてくれる」は方向の「へ」で、動詞の目的語を示せず非文になる。"}, {"text": "の", "is_correct": false, "explanation": "「正義感の植え付けてくれる」は名詞を修飾する形にならず、動詞の目的語として合わない。"}], "correct_answer": "を", "explanations": {"を": "「正義感を植え付けてくれる」の形で、植え付ける対象を示す目的語になる。", "と": "「正義感と植え付けてくれる」は並列の形で、続く動詞の対象として成り立たない。", "へ": "「正義感へ植え付けてくれる」は方向の「へ」で、動詞の目的語を示せず非文になる。", "の": "「正義感の植え付けてくれる」は名詞を修飾する形にならず、動詞の目的語として合わない。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "の": "所有・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "心にしっかりと入れること。", "primary_collocate": null, "pronunciation": "うえつける", "ipa": "ɯetsɯkeɾɯ", "syllable_count": 5, "sentences": [{"text": "厳しい訓練は、兵士に規律を植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "厳[きび]しい訓練[くんれん]は、兵士[へいし]に規律[きりつ]を植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "この本は、子どもの心に正義感を植え付けてくれる。", "target_word": "植え付けて", "complexity_tier": "T3", "furigana": "この本[ほん]は、子[こ]どもの心[こころ]に正義感[せいぎかん]を植[う]え付[つ]けてくれる。", "sentence_source": "generated"}, {"text": "父は私に、嘘をつかない心を植え付けようとした。", "target_word": "植え付けよう", "complexity_tier": "T3", "furigana": "父[ちち]は私[わたし]に、嘘[うそ]をつかない心[こころ]を植[う]え付[つ]けようとした。", "sentence_source": "generated"}, {"text": "事故の映像が、運転手たちに安全への意識を植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "事故[じこ]の映像[えいぞう]が、運転手[うんてんしゅ]たちに安全[あんぜん]への意識[いしき]を植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "彼女は新入社員に、会社の理念を植え付ける役目を任された。", "target_word": "植え付ける", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は新入[しんにゅう]社員[しゃいん]に、会社[かいしゃ]の理念[りねん]を植[う]え付[つ]ける役目[やくめ]を任[まか]された。", "sentence_source": "generated"}, {"text": "失敗の経験が、彼の心に慎重さを植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "失敗[しっぱい]の経験[けいけん]が、彼[かれ]の心[こころ]に慎重[しんちょう]さを植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "繰り返しの練習で、正しいフォームを頭に植え付ける。", "target_word": "植え付ける", "complexity_tier": "T3", "furigana": "繰[く]り返[かえ]しの練習[れんしゅう]で、正[ただ]しいフォームを頭[あたま]に植[う]え付[つ]ける。", "sentence_source": "generated"}, {"text": "祖母の昔話は、私に優しさを植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "祖母[そぼ]の昔話[むかしばなし]は、私[わたし]に優[やさ]しさを植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "親の言葉は、子どもに考え方の土台を植え付ける。", "target_word": "植え付ける", "complexity_tier": "T3", "furigana": "親[おや]の言葉[ことば]は、子[こ]どもに考[かんが]え方[かた]の土台[どだい]を植[う]え付[つ]ける。", "sentence_source": "generated"}, {"text": "学校は生徒に、助け合う心を植え付けようとしている。", "target_word": "植え付けよう", "complexity_tier": "T3", "furigana": "学校[がっこう]は生徒[せいと]に、助[たす]け合[あ]う心[こころ]を植[う]え付[つ]けようとしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植え付ける", "label": "辞書形"}, {"form": "植え付けない", "label": "否定形"}, {"form": "植え付けます", "label": "丁寧形"}, {"form": "植え付けた", "label": "夕形"}, {"form": "植え付けて", "label": "テ形"}, {"form": "植え付けよう", "label": "意向形"}, {"form": "植え付けられる", "label": "受身形"}], "register": "やや改まった書き言葉", "sense_fingerprint": "考え・習慣・感情などを心や頭にしっかり入れて定着させる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植え付けた", "is_correct": true, "explanation": "夕形で文を過去の出来事として終えられ、「厳しい訓練は規律を植え付けた」と自然に続く。"}, {"text": "植え付けよう", "is_correct": false, "explanation": "意向形で文を終えると勧誘の文になり、訓練の結果を述べる文にならない。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形では文が終わらず、「規律を植え付けて。」は文として成り立たない。"}, {"text": "植え付けつつ", "is_correct": false, "explanation": "連用形で文を終えられず、「規律を植え付けつつ。」は文として成り立たない。"}], "explanations": {"植え付けた": "夕形で文を過去の出来事として終えられ、「厳しい訓練は規律を植え付けた」と自然に続く。", "植え付けよう": "意向形で文を終えると勧誘の文になり、訓練の結果を述べる文にならない。", "植え付けて": "テ形では文が終わらず、「規律を植え付けて。」は文として成り立たない。", "植え付けつつ": "連用形で文を終えられず、「規律を植え付けつつ。」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "植え付けた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は冷蔵庫に缶ジュースを植え付けた。", "explanation": "ここは〈冷やす〉の意味。冷蔵庫に物を入れる場面で、植え付けるは心にしっかり入れる意味なので合わない。"}, {"text": "彼は地図に町の名前を植え付けた。", "explanation": "ここは〈記入〉の意味。地図に文字を書き込む場面で、心にしっかり入れる意味ではないので合わない。"}, {"text": "彼は箱に大事な書類を植え付けた。", "explanation": "ここは〈しまう〉の意味。物を収納する場面で、植え付けるは心の中に入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植え付ける", "is_correct": true, "explanation": "辞書形で文を終えられ、「練習で正しいフォームを頭に植え付ける」と自然に言える。"}, {"text": "植え付ければ", "is_correct": false, "explanation": "ば形は後ろに続く文が必要で、「頭に植え付ければ。」は文として成り立たない。"}, {"text": "植え付けながら", "is_correct": false, "explanation": "〜ながらは文を終えられず、文として成り立たない。"}, {"text": "植え付けたら", "is_correct": false, "explanation": "たら形は後ろに続く文が必要で、「頭に植え付けたら。」は文として成り立たない。"}], "explanations": {"植え付ける": "辞書形で文を終えられ、「練習で正しいフォームを頭に植え付ける」と自然に言える。", "植え付ければ": "ば形は後ろに続く文が必要で、「頭に植え付ければ。」は文として成り立たない。", "植え付けながら": "〜ながらは文を終えられず、文として成り立たない。", "植え付けたら": "たら形は後ろに続く文が必要で、「頭に植え付けたら。」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "植え付ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は木の幹に恋人の名前を植え付けた。", "explanation": "ここは〈刻む〉の意味。木の幹に文字を彫る場面で、心にしっかり入れる意味ではない。"}, {"text": "店員はカップに熱いお茶を植え付けた。", "explanation": "ここは〈注ぐ〉の意味。液体を器に入れる場面で、心にしっかり入れる意味とは違う。"}, {"text": "彼女は壁にポスターを植え付けた。", "explanation": "ここは〈貼る〉の意味。物を平面に留める場面で、植え付けるは心に入れる意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は私に、正直さを植え付けようした。", "corrected_sentence": "祖父は私に、正直さを植え付けようとした。", "error_description": "「〜ようとする」の「と」が抜けている。意図を表す「〜ようとした」の形が必要。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植え付けて", "is_correct": true, "explanation": "テ形で、後ろの「くれる」に続けて補助動詞の形を作る。"}, {"text": "植え付けない", "is_correct": false, "explanation": "否定形になると、「植え付けないてくれる」の形になり、文として成り立たない。"}, {"text": "植え付けます", "is_correct": false, "explanation": "丁寧形は「くれる」に直接続かず、文の形が崩れる。"}, {"text": "植え付けた", "is_correct": false, "explanation": "夕形は「くれる」に続かず、「植え付けたてくれる」は非文になる。"}], "correct_form": "植え付けて", "base_form": "植え付ける", "form_label": "テ形", "sentence_index": 1, "explanations": {"植え付けて": "テ形で、後ろの「くれる」に続けて補助動詞の形を作る。", "植え付けない": "否定形になると、「植え付けないてくれる」の形になり、文として成り立たない。", "植え付けます": "丁寧形は「くれる」に直接続かず、文の形が崩れる。", "植え付けた": "夕形は「くれる」に続かず、「植え付けたてくれる」は非文になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51891, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼い頃の経験が、私に慎重さを植え付けるた。", "corrected_sentence": "幼い頃の経験が、私に慎重さを植え付けた。", "error_description": "「植え付けるた」は動詞の終止形「る」が過去の助動詞「た」の前に残っている誤り。過去形は「植え付けた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植え付けた", "is_correct": true, "explanation": "夕形で、過去に行われた出来事として文を終えられる。"}, {"text": "植え付けながら", "is_correct": false, "explanation": "〜ながらは文を終えられず、「優しさを植え付けながら。」は文として成り立たない。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形で文を終えられず、「優しさを植え付けて。」は文として成り立たない。"}, {"text": "植え付けつつ", "is_correct": false, "explanation": "連用形で文を終えられず、文として成り立たない。"}], "correct_form": "植え付けた", "base_form": "植え付ける", "form_label": "夕形", "sentence_index": 7, "explanations": {"植え付けた": "夕形で、過去に行われた出来事として文を終えられる。", "植え付けながら": "〜ながらは文を終えられず、「優しさを植え付けながら。」は文として成り立たない。", "植え付けて": "テ形で文を終えられず、「優しさを植え付けて。」は文として成り立たない。", "植え付けつつ": "連用形で文を終えられず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「考えている」の内容を引用する「と」。「植え付けたいと考えている」で正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」を置くと「植え付けたいが」が主語を立てる形になり、「考えている」の内容として続かない。"}, {"text": "を", "is_correct": false, "explanation": "「植え付けたいを考えている」は、希望の内容を目的語として取る形にならない。"}, {"text": "に", "is_correct": false, "explanation": "「植え付けたいに考えている」は、相手や場所を示す「に」で、考える内容を示せない。"}], "correct_answer": "と", "explanations": {"と": "「考えている」の内容を引用する「と」。「植え付けたいと考えている」で正しい。", "が": "「が」を置くと「植え付けたいが」が主語を立てる形になり、「考えている」の内容として続かない。", "を": "「植え付けたいを考えている」は、希望の内容を目的語として取る形にならない。", "に": "「植え付けたいに考えている」は、相手や場所を示す「に」で、考える内容を示せない。"}, "error_tags": {"が": "主語・逆接", "を": "目的語", "に": "相手・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
