INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物を土に植えるように、考えや気持ちを人の心に強く残すこと。", "primary_collocate": null, "pronunciation": "うえつける", "ipa": "ɯetsɯkeɾɯ", "syllable_count": 5, "sentences": [{"text": "企業はこれらの色彩が持つ記号的意味を深く理解し、自社のアイデンティティを消費者の心に効果的に植え付けようとしている。", "target_word": "植え付けよう", "complexity_tier": "T4", "furigana": "企業[きぎょう]はこれらの色彩[しきさい]が持[も]つ記号的[きごうてき]意味[いみ]を深[ふか]く理解[りかい]し、自社[じしゃ]のアイデンティティを消費者[しょうひしゃ]の心[こころ]に効果的[こうかてき]に植[う]え付[つ]けようとしている。", "sentence_source": "mined"}, {"text": "親は子どもに、約束を守る大切さを植え付けたいと考えている。", "target_word": "植え付けたい", "complexity_tier": "T3", "furigana": "親[おや]は子[こ]どもに、約束[やくそく]を守[まも]る大切[たいせつ]さを植[う]え付[つ]けたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "長年の宣伝が、消費者に「安い店」という印象を植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "長年[ながねん]の宣伝[せんでん]が、消費者[しょうひしゃ]に「安[やす]い店[みせ]」という印象[いんしょう]を植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "先生は生徒に、自分で考える習慣を植え付けようと工夫している。", "target_word": "植え付けよう", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]に、自分[じぶん]で考[かんが]える習慣[しゅうかん]を植[う]え付[つ]けようと工夫[くふう]している。", "sentence_source": "generated"}, {"text": "戦争の記憶は、人々の心に深い恐怖を植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "戦争[せんそう]の記憶[きおく]は、人々[ひとびと]の心[こころ]に深[ふか]い恐怖[きょうふ]を植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "彼の冷たい態度が、私に人への不信感を植え付けてしまった。", "target_word": "植え付けて", "complexity_tier": "T3", "furigana": "彼[かれ]の冷[つめ]たい態度[たいど]が、私[わたし]に人[ひと]への不信感[ふしんかん]を植[う]え付[つ]けてしまった。", "sentence_source": "generated"}, {"text": "幼いころに植え付けられた偏見は、なかなか消えない。", "target_word": "植え付けられた", "complexity_tier": "T3", "furigana": "幼[おさな]いころに植[う]え付[つ]けられた偏見[へんけん]は、なかなか消[き]えない。", "sentence_source": "generated"}, {"text": "監督は選手たちに、勝つことへの強い自信を植え付けた。", "target_word": "植え付けた", "complexity_tier": "T3", "furigana": "監督[かんとく]は選手[せんしゅ]たちに、勝[か]つことへの強[つよ]い自信[じしん]を植[う]え付[つ]けた。", "sentence_source": "generated"}, {"text": "広告は、商品への憧れを見る人の頭に植え付けるように作られている。", "target_word": "植え付ける", "complexity_tier": "T4", "furigana": "広告[こうこく]は、商品[しょうひん]への憧[あこが]れを見[み]る人[ひと]の頭[あたま]に植[う]え付[つ]けるように作[つく]られている。", "sentence_source": "generated"}, {"text": "祖父は孫に、自然を大切にする気持ちを植え付けてくれた。", "target_word": "植え付けて", "complexity_tier": "T3", "furigana": "祖父[そふ]は孫[まご]に、自然[しぜん]を大切[たいせつ]にする気持[きも]ちを植[う]え付[つ]けてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "植え付ける", "label": "辞書形"}, {"form": "植え付けない", "label": "否定形"}, {"form": "植え付けます", "label": "丁寧形"}, {"form": "植え付けた", "label": "夕形"}, {"form": "植え付けて", "label": "テ形"}, {"form": "植え付けよう", "label": "意向形"}, {"form": "植え付けられる", "label": "受身形"}], "register": "やや改まった書き言葉", "sense_fingerprint": "考えや気持ち、印象を人の心に強く残す(比喩的用法)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植え付けよう", "is_correct": true, "explanation": "「〜ようとしている」の形で、意図して働きかけている様子を表す。"}, {"text": "植え付けない", "is_correct": false, "explanation": "否定形は「としている」に続かず、「植え付けないとしている」は文として成り立たない。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形は「としている」に続かず、「植え付けてとしている」は文として成り立たない。"}, {"text": "植え付けながら", "is_correct": false, "explanation": "〜ながらは「としている」に続かず、文として成り立たない。"}], "explanations": {"植え付けよう": "「〜ようとしている」の形で、意図して働きかけている様子を表す。", "植え付けない": "否定形は「としている」に続かず、「植え付けないとしている」は文として成り立たない。", "植え付けて": "テ形は「としている」に続かず、「植え付けてとしている」は文として成り立たない。", "植え付けながら": "〜ながらは「としている」に続かず、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "植え付けよう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は孫に、古い着物を植え付けた。", "explanation": "ここは〈贈る〉の意味。着物は物であり、心に強く残す対象ではないので合わない。"}, {"text": "医師は患者のカルテに病名を植え付けた。", "explanation": "ここは〈記入〉の意味。カルテに文字を書き込む場面で、心に強く残す意味ではないので合わない。"}, {"text": "学長は卒業生に学位を植え付けた。", "explanation": "ここは〈授与〉の意味。学位は授けるものであり、心に強く残す対象にはならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植え付けられた", "is_correct": true, "explanation": "受身の過去形で、後ろの「偏見」を修飾する連体形として自然に入る。"}, {"text": "植え付けよう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、「幼いころに植え付けよう偏見」は成り立たない。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形は名詞を修飾できず、「植え付けて偏見」は成り立たない。"}, {"text": "植え付けます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「植え付けます偏見」は成り立たない。"}], "explanations": {"植え付けられた": "受身の過去形で、後ろの「偏見」を修飾する連体形として自然に入る。", "植え付けよう": "意向形は名詞を修飾できず、「幼いころに植え付けよう偏見」は成り立たない。", "植え付けて": "テ形は名詞を修飾できず、「植え付けて偏見」は成り立たない。", "植え付けます": "丁寧形は名詞を修飾できず、「植え付けます偏見」は成り立たない。"}, "sentence_index": 6, "correct_answer": "植え付けられた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は孫に小遣いを植え付けた。", "explanation": "ここは〈贈る〉の意味。小遣いは物であり、心に強く残す意味の文脈には合わない。"}, {"text": "彼は昔の約束を植え付けている。", "explanation": "ここは〈記憶〉の意味。自分が覚えている状態を表す語で、植え付けるは外から心に残す動作なので合わない。"}, {"text": "彼女は机の上に写真を植え付けた。", "explanation": "ここは〈飾る〉の意味。物を置いて見せる場面で、植え付けるは人の心に強く残す動作なので使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は生徒に、自分で考える習慣を植え付けてとしている。", "corrected_sentence": "先生は生徒に、自分で考える習慣を植え付けようとしている。", "error_description": "「〜ようとしている」には意向形「植え付けよう」が必要。テ形「植え付けて」は「としている」に続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "植え付けたい", "is_correct": true, "explanation": "希望形で、「〜たいと考えている」の形に続く。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形で、「〜たいと考えている」の希望の内容にはならない。"}, {"text": "植え付けなくて", "is_correct": false, "explanation": "テ形は「と考えている」の内容として続かず、文として成り立たない。"}, {"text": "植え付けたくて", "is_correct": false, "explanation": "テ形は「と考えている」の内容として続かず、文として成り立たない。"}], "correct_form": "植え付けたい", "base_form": "植え付ける", "form_label": "希望形", "sentence_index": 1, "explanations": {"植え付けたい": "希望形で、「〜たいと考えている」の形に続く。", "植え付けて": "テ形で、「〜たいと考えている」の希望の内容にはならない。", "植え付けなくて": "テ形は「と考えている」の内容として続かず、文として成り立たない。", "植え付けたくて": "テ形は「と考えている」の内容として続かず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51892, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は娘に、家事の大切さを植え付けくれた。", "corrected_sentence": "母は娘に、家事の大切さを植え付けてくれた。", "error_description": "「植え付けてくれた」のテ形の「て」が抜けている。「くれた」は「て」を伴って補助動詞として続く。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "植え付けた", "is_correct": true, "explanation": "夕形で、すでに行われた完了の出来事を述べる。"}, {"text": "植え付けながら", "is_correct": false, "explanation": "〜ながらは文を終えられず、「自信を植え付けながら。」は文として成り立たない。"}, {"text": "植え付けて", "is_correct": false, "explanation": "テ形で文を終えられず、文として成り立たない。"}, {"text": "植え付けつつ", "is_correct": false, "explanation": "連用形で文を終えられず、文として成り立たない。"}], "correct_form": "植え付けた", "base_form": "植え付ける", "form_label": "夕形", "sentence_index": 7, "explanations": {"植え付けた": "夕形で、すでに行われた完了の出来事を述べる。", "植え付けながら": "〜ながらは文を終えられず、「自信を植え付けながら。」は文として成り立たない。", "植え付けて": "テ形で文を終えられず、文として成り立たない。", "植え付けつつ": "連用形で文を終えられず、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
