INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51893, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "じぶんの かいしゃ", "primary_collocate": null, "pronunciation": "じしゃ", "ipa": "dʑiɕa", "syllable_count": 2, "sentences": [{"text": "私は自社の製品を友だちに紹介した。", "target_word": "自社", "complexity_tier": "T2", "furigana": "私[わたし]は自社[じしゃ]の製品[せいひん]を友[とも]だちに紹介[しょうかい]した。", "sentence_source": "generated"}, {"text": "自社のホームページを新しく作り直した。", "target_word": "自社", "complexity_tier": "T2", "furigana": "自社[じしゃ]のホームページを新[あたら]しく作[つく]り直[なお]した。", "sentence_source": "generated"}, {"text": "山田さんは自社の車で取引先へ向かった。", "target_word": "自社", "complexity_tier": "T3", "furigana": "山田[やまだ]さんは自社[じしゃ]の車[くるま]で取引先[とりひきさき]へ向[む]かった。", "sentence_source": "generated"}, {"text": "他社より、自社のほうが給料が高いそうだ。", "target_word": "自社", "complexity_tier": "T3", "furigana": "他社[たしゃ]より、自社[じしゃ]のほうが給料[きゅうりょう]が高[たか]いそうだ。", "sentence_source": "generated"}, {"text": "彼は自社の悪口を言わない人だ。", "target_word": "自社", "complexity_tier": "T2", "furigana": "彼[かれ]は自社[じしゃ]の悪口[わるぐち]を言[い]わない人[ひと]だ。", "sentence_source": "generated"}, {"text": "自社の場所が分かりにくいので、地図を送った。", "target_word": "自社", "complexity_tier": "T3", "furigana": "自社[じしゃ]の場所[ばしょ]が分[わ]かりにくいので、地図[ちず]を送[おく]った。", "sentence_source": "generated"}, {"text": "部長は自社の社員を大切にしている。", "target_word": "自社", "complexity_tier": "T3", "furigana": "部長[ぶちょう]は自社[じしゃ]の社員[しゃいん]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "会社の見学で、自社の工場を案内してもらった。", "target_word": "自社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の見学[けんがく]で、自社[じしゃ]の工場[こうじょう]を案内[あんない]してもらった。", "sentence_source": "generated"}, {"text": "自社の名前が新聞に出て、みんな喜んだ。", "target_word": "自社", "complexity_tier": "T2", "furigana": "自社[じしゃ]の名前[なまえ]が新聞[しんぶん]に出[で]て、みんな喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "社長が自社の将来について話した。", "target_word": "自社", "complexity_tier": "T3", "furigana": "社長[しゃちょう]が自社[じしゃ]の将来[しょうらい]について話[はな]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自社", "label": "基本形"}, {"form": "自社の", "label": "連体修飾形"}, {"form": "自社で", "label": "場所・手段の形"}], "register": "ビジネス・やや改まった表現", "sense_fingerprint": "自分の会社(他社に対する自分の側の会社)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51893, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自社", "is_correct": true, "explanation": "自分の会社を表す。「自社の製品」は、話し手の会社の製品を指すので文に合う。"}, {"text": "価格", "is_correct": false, "explanation": "値段の意味。「価格の製品」とは言えず、紹介する対象として合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩の意味。「散歩の製品」は意味を成さず、文に入らない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける行為の意味。「配達の製品」は成り立たず、文に合わない。"}], "explanations": {"自社": "自分の会社を表す。「自社の製品」は、話し手の会社の製品を指すので文に合う。", "価格": "値段の意味。「価格の製品」とは言えず、紹介する対象として合わない。", "散歩": "散歩の意味。「散歩の製品」は意味を成さず、文に入らない。", "配達": "品物を届ける行為の意味。「配達の製品」は成り立たず、文に合わない。"}, "sentence_index": 0, "correct_answer": "自社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "休みの日は自社でのんびり昼寝をする。", "explanation": "ここは〈自宅〉の意味。自社は会社を指すので、昼寝をする家の意味では使えない。"}, {"text": "部員たちは自社練習を続けた。", "explanation": "ここは〈自主〉の意味。自主練習は自分から進んで行う練習で、会社の意味の自社とは別の語。"}, {"text": "ライバルの自社に先を越された。", "explanation": "ここは〈他社〉の意味。自社は話し手側の会社なので、ライバル社を指すには他社を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51893, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自社", "is_correct": true, "explanation": "自分の会社を表す。「自社の社員」は、話し手の会社で働く人を指すので文に合う。"}, {"text": "色彩", "is_correct": false, "explanation": "色の種類や色合いの意味。「色彩の社員」は成り立たず、文に入らない。"}, {"text": "季節", "is_correct": false, "explanation": "季節の意味。「季節の社員」は人を修飾できず、文に入らない。"}, {"text": "経費", "is_correct": false, "explanation": "会社の費用の意味。「経費の社員」は人を指せず、ここには入らない。"}], "explanations": {"自社": "自分の会社を表す。「自社の社員」は、話し手の会社で働く人を指すので文に合う。", "色彩": "色の種類や色合いの意味。「色彩の社員」は成り立たず、文に入らない。", "季節": "季節の意味。「季節の社員」は人を修飾できず、文に入らない。", "経費": "会社の費用の意味。「経費の社員」は人を指せず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "自社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "自社の顔色が悪いので、心配になった。", "explanation": "ここは〈友人〉の意味。自社は会社を指す語で、人の顔色には使えない。"}, {"text": "うちの犬は自社の散歩が好きだ。", "explanation": "ここは〈うち〉の意味。飼い犬は会社とは関係がないので、自社ではなく『うちの』と言う。"}, {"text": "祖母は自社の孫の成長を喜んでいる。", "explanation": "ここは〈家族〉の意味。自社は会社の意味で、家族の孫を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51893, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は自社に企画の仕事をしている。", "corrected_sentence": "兄は自社で企画の仕事をしている。", "error_description": "「で」が「に」になっている。『仕事をする』は場所や手段を『で』で示す。『に』では勤務の場所として不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51893, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は自社へ長く経理を担当した。", "corrected_sentence": "彼女は自社で長く経理を担当した。", "error_description": "「で」が「へ」になっている。『担当する』は場所を『で』で示す。『へ』は向かう先を表すので、勤務の場所としては不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
