INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自社の責任」の形で、自社が責任の所在であることを示す。"}, {"text": "を", "is_correct": false, "explanation": "「自社を責任」は目的語の形で、責任と続かない。"}, {"text": "で", "is_correct": false, "explanation": "「自社で責任」は場所や手段を示すが、名詞句として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「自社へ責任」は方向を示すが、責任を修飾する形にならない。"}], "correct_answer": "の", "explanations": {"の": "「自社の責任」の形で、自社が責任の所在であることを示す。", "を": "「自社を責任」は目的語の形で、責任と続かない。", "で": "「自社で責任」は場所や手段を示すが、名詞句として成り立たない。", "へ": "「自社へ責任」は方向を示すが、責任を修飾する形にならない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分が働いている会社や、自分が経営している会社", "primary_collocate": null, "pronunciation": "じしゃ", "ipa": "dʑiɕa", "syllable_count": 2, "sentences": [{"text": "企業はこれらの色彩が持つ記号的意味を深く理解し、自社のアイデンティティを消費者の心に効果的に植え付けようとしている。", "target_word": "自社", "complexity_tier": "T4", "furigana": "企業[きぎょう]はこれらの色彩[しきさい]が持[も]つ記号的[きごうてき]意味[いみ]を深[ふか]く理解[りかい]し、自社[じしゃ]のアイデンティティを消費者[しょうひしゃ]の心[こころ]に効果的[こうかてき]に植[う]え付[つ]けようとしている。", "sentence_source": "mined"}, {"text": "営業部は自社の強みを、わかりやすく客に説明した。", "target_word": "自社", "complexity_tier": "T3", "furigana": "営業部[えいぎょうぶ]は自社[じしゃ]の強[つよ]みを、わかりやすく客[きゃく]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "彼は他社の製品と比べて、自社の商品の良さを訴えた。", "target_word": "自社", "complexity_tier": "T3", "furigana": "彼[かれ]は他社[たしゃ]の製品[せいひん]と比[くら]べて、自社[じしゃ]の商品[しょうひん]の良[よ]さを訴[うった]えた。", "sentence_source": "generated"}, {"text": "自社で働く社員の満足度を上げることが、社長の目標だ。", "target_word": "自社", "complexity_tier": "T4", "furigana": "自社[じしゃ]で働[はたら]く社員[しゃいん]の満足度[まんぞくど]を上[あ]げることが、社長[しゃちょう]の目標[もくひょう]だ。", "sentence_source": "generated"}, {"text": "競合が増えたので、自社の価格を見直すことになった。", "target_word": "自社", "complexity_tier": "T3", "furigana": "競合[きょうごう]が増[ふ]えたので、自社[じしゃ]の価格[かかく]を見直[みなお]すことになった。", "sentence_source": "generated"}, {"text": "展示会では、各社が自社の新製品を並べて競い合った。", "target_word": "自社", "complexity_tier": "T3", "furigana": "展示会[てんじかい]では、各社[かくしゃ]が自社[じしゃ]の新製品[しんせいひん]を並[なら]べて競[きそ]い合[あ]った。", "sentence_source": "generated"}, {"text": "彼は自社のサービスに自信を持っている。", "target_word": "自社", "complexity_tier": "T3", "furigana": "彼[かれ]は自社[じしゃ]のサービスに自信[じしん]を持[も]っている。", "sentence_source": "generated"}, {"text": "取引先に迷惑をかけないよう、自社の責任で問題を解決した。", "target_word": "自社", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]に迷惑[めいわく]をかけないよう、自社[じしゃ]の責任[せきにん]で問題[もんだい]を解決[かいけつ]した。", "sentence_source": "generated"}, {"text": "自社の評判を守るために、広報担当は丁寧に謝罪した。", "target_word": "自社", "complexity_tier": "T4", "furigana": "自社[じしゃ]の評判[ひょうばん]を守[まも]るために、広報[こうほう]担当[たんとう]は丁寧[ていねい]に謝罪[しゃざい]した。", "sentence_source": "generated"}, {"text": "他社の動きを調べると同時に、自社の課題も洗い出した。", "target_word": "自社", "complexity_tier": "T4", "furigana": "他社[たしゃ]の動[うご]きを調[しら]べると同時[どうじ]に、自社[じしゃ]の課題[かだい]も洗[あら]い出[だ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自社", "label": "基本形"}, {"form": "自社の", "label": "連体修飾形"}, {"form": "自社で", "label": "場所・手段の形"}], "register": "ビジネス・やや改まった表現", "sense_fingerprint": "自分の勤め先や経営する会社(他社と対比して使う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ce53bb-6d6d-4084-9e59-dd625884db11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自社", "is_correct": true, "explanation": "自分の会社を表す。「自社のアイデンティティ」は企業自身の独自性を指し、文の意味に合う。"}, {"text": "価格", "is_correct": false, "explanation": "商品の値段の意味。「価格のアイデンティティ」は成り立たず、ここには入らない。"}, {"text": "効果", "is_correct": false, "explanation": "ききめや結果の意味。「効果のアイデンティティ」は成り立たず、所有の対象として合わない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける行為の意味。「配達のアイデンティティ」は成り立たず、文の流れに合わない。"}], "explanations": {"自社": "自分の会社を表す。「自社のアイデンティティ」は企業自身の独自性を指し、文の意味に合う。", "価格": "商品の値段の意味。「価格のアイデンティティ」は成り立たず、ここには入らない。", "効果": "ききめや結果の意味。「効果のアイデンティティ」は成り立たず、所有の対象として合わない。", "配達": "品物を届ける行為の意味。「配達のアイデンティティ」は成り立たず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "自社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は自社でゆっくり寝て過ごした。", "explanation": "ここは〈自宅〉の意味。自社は『自分の会社』の意味なので、寝て過ごす場所の家には使えない。"}, {"text": "ライバルの自社が新製品を出して、業界が騒がしい。", "explanation": "ここは〈他社〉の意味。自社は話し手側の会社を指すので、相手方やライバル社には使えない。"}, {"text": "選手たちは自社練習を続けて、大会に備えた。", "explanation": "ここは〈自主〉の意味。自主練習は自分から進んで行う練習で、会社とは関係がないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自社", "is_correct": true, "explanation": "自分の会社を表す。「自社のサービス」は、話し手の会社が提供するサービスを指す。"}, {"text": "体重", "is_correct": false, "explanation": "体重の意味。「体重のサービス」は意味を成さず、文に入らない。"}, {"text": "色彩", "is_correct": false, "explanation": "色の種類や色合いの意味。サービスを修飾すると意味が通らない。"}, {"text": "湿気", "is_correct": false, "explanation": "湿り気の意味。「湿気のサービス」は意味を成さず、文に入らない。"}], "explanations": {"自社": "自分の会社を表す。「自社のサービス」は、話し手の会社が提供するサービスを指す。", "体重": "体重の意味。「体重のサービス」は意味を成さず、文に入らない。", "色彩": "色の種類や色合いの意味。サービスを修飾すると意味が通らない。", "湿気": "湿り気の意味。「湿気のサービス」は意味を成さず、文に入らない。"}, "sentence_index": 6, "correct_answer": "自社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "自社の体調が悪いので、今日は学校を休んだ。", "explanation": "ここは〈自分〉の意味。自社は会社を指す語で、人の体調には使えない。"}, {"text": "自社の新製品を拝見しました。", "explanation": "ここは〈御社〉の意味。拝見は相手のものを見る謙譲語で、相手の会社には自社ではなく御社を使う。"}, {"text": "祖父は自社の孫を溺愛している。", "explanation": "ここは〈家族〉の意味。自社は会社のことで、家族の孫を指すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先輩は自社を新しい機械を紹介してくれた。", "corrected_sentence": "先輩は自社の新しい機械を紹介してくれた。", "error_description": "「自社の」の「の」が「を」になっている。『を』が二つ並び、自社が紹介の目的語になってしまう。正しくは『自社の』で、自社は機械の所属先を示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51894, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は自社へ資金を調達した。", "corrected_sentence": "叔父は自社から資金を調達した。", "error_description": "「から」が「へ」になっている。『調達する』は出どころを『から』で示す。『へ』は向かう先を表すので、資金の出どころとして不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd56d1e9e-e8a3-45e6-b2cb-98ab0d373661') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「影」は「織り成す」の主語（組み合わさるもの）なので、〈が〉で示す。"}, {"text": "に", "is_correct": false, "explanation": "〈影に織り成す〉は相手や場所を示す〈に〉では主語を作れず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、〈影へ織り成す〉は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較の基準を示すので、〈影より織り成す〉は文として成立しない。"}], "correct_answer": "が", "explanations": {"が": "「影」は「織り成す」の主語（組み合わさるもの）なので、〈が〉で示す。", "に": "〈影に織り成す〉は相手や場所を示す〈に〉では主語を作れず、不自然。", "へ": "〈へ〉は方向を示すので、〈影へ織り成す〉は意味が通らない。", "より": "〈より〉は比較の基準を示すので、〈影より織り成す〉は文として成立しない。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「民族音楽」は「織り成して」の目的語（組み合わせる対象）なので、〈を〉で示す。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞どうしをつなぐので、「民族音楽の織り成して」は動詞の目的語を示せず、文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は位置・相手を示すので、組み合わせる対象を示せず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、「民族音楽へ織り成して」は組み合わせる対象を示せず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「民族音楽」は「織り成して」の目的語（組み合わせる対象）なので、〈を〉で示す。", "の": "〈の〉は名詞どうしをつなぐので、「民族音楽の織り成して」は動詞の目的語を示せず、文として成り立たない。", "に": "〈に〉は位置・相手を示すので、組み合わせる対象を示せず、不自然。", "へ": "〈へ〉は方向を示すので、「民族音楽へ織り成して」は組み合わせる対象を示せず、不自然。"}, "error_tags": {"の": "修飾・連体", "に": "位置・相手", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "いくつかのものを組み合わせて、一つのまとまりを作ること。", "primary_collocate": null, "pronunciation": "おりなす", "ipa": "orinasɯ", "syllable_count": 4, "sentences": [{"text": "赤や黄色の葉が織り成す秋の景色は、とても美しい。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "赤[あか]や黄色[きいろ]の葉[は]が織[お]り成[な]す秋[あき]の景色[けしき]は、とても美[うつく]しい。", "sentence_source": "generated"}, {"text": "光と影が織り成す模様を、ずっと眺めていた。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "光[ひかり]と影[かげ]が織[お]り成[な]す模様[もよう]を、ずっと眺[なが]めていた。", "sentence_source": "generated"}, {"text": "この映画は、三つの家族の話を織り成して、一つの大きな物語にしている。", "target_word": "織り成して", "complexity_tier": "T3", "furigana": "この映画[えいが]は、三[みっ]つの家族[かぞく]の話[はなし]を織[お]り成[な]して、一[ひと]つの大[おお]きな物語[ものがたり]にしている。", "sentence_source": "generated"}, {"text": "楽器の音が織り成す響きに、会場は静まり返った。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "楽器[がっき]の音[おと]が織[お]り成[な]す響[ひび]きに、会場[かいじょう]は静[しず]まり返[かえ]った。", "sentence_source": "generated"}, {"text": "山と海が織り成す風景を見に、多くの観光客が訪れる。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "山[やま]と海[うみ]が織[お]り成[な]す風景[ふうけい]を見[み]に、多[おお]くの観光客[かんこうきゃく]が訪[おとず]れる。", "sentence_source": "generated"}, {"text": "笑いと涙が織り成す物語に、観客は引き込まれた。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "笑[わら]いと涙[なみだ]が織[お]り成[な]す物語[ものがたり]に、観客[かんきゃく]は引[ひ]き込[こ]まれた。", "sentence_source": "generated"}, {"text": "季節ごとの花が織り成す色の変化を、庭で楽しんでいる。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "季節[きせつ]ごとの花[はな]が織[お]り成[な]す色[いろ]の変化[へんか]を、庭[にわ]で楽[たの]しんでいる。", "sentence_source": "generated"}, {"text": "作曲家は、さまざまな民族音楽を織り成して、新しい曲を作った。", "target_word": "織り成して", "complexity_tier": "T3", "furigana": "作曲家[さっきょくか]は、さまざまな民族音楽[みんぞくおんがく]を織[お]り成[な]して、新[あたら]しい曲[きょく]を作[つく]った。", "sentence_source": "generated"}, {"text": "人々の思いが織り成す町の歴史を、本にまとめたい。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "人々[ひとびと]の思[おも]いが織[お]り成[な]す町[まち]の歴史[れきし]を、本[ほん]にまとめたい。", "sentence_source": "generated"}, {"text": "雲と夕日が織り成した空の色は、写真では伝えきれない。", "target_word": "織り成した", "complexity_tier": "T3", "furigana": "雲[くも]と夕日[ゆうひ]が織[お]り成[な]した空[そら]の色[いろ]は、写真[しゃしん]では伝[つた]えきれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "織り成す", "label": "辞書形"}, {"form": "織り成し", "label": "連用形"}, {"form": "織り成して", "label": "て形"}, {"form": "織り成した", "label": "過去形"}, {"form": "織り成さない", "label": "否定形"}, {"form": "織り成せば", "label": "仮定形"}], "register": "literary", "sense_fingerprint": "複数のものが組み合わさって景色・模様・物語などのまとまりを作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "織り成す", "is_correct": true, "explanation": "複数の葉が組み合わさって景色を作る意味で、「秋の景色」と合う。"}, {"text": "逃げる", "is_correct": false, "explanation": "「葉が逃げる景色」は主語と動詞が合わず、意味が通らない。"}, {"text": "寝る", "is_correct": false, "explanation": "「葉が寝る景色」は不自然で、景色を作る意味とも合わない。"}, {"text": "割る", "is_correct": false, "explanation": "「葉が割る景色」は目的語がなく、意味が通らない。"}], "explanations": {"織り成す": "複数の葉が組み合わさって景色を作る意味で、「秋の景色」と合う。", "逃げる": "「葉が逃げる景色」は主語と動詞が合わず、意味が通らない。", "寝る": "「葉が寝る景色」は不自然で、景色を作る意味とも合わない。", "割る": "「葉が割る景色」は目的語がなく、意味が通らない。"}, "sentence_index": 0, "correct_answer": "織り成す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は毛糸で冬用の帽子を織り成した。", "explanation": "ここは〈編む〉の意味。織り成すは模様や景色のように複数の要素がまとまって一つの姿になる場合に使い、手で帽子を編む動作には使わない。"}, {"text": "嵐が村の景色を織り成して、すべて壊してしまった。", "explanation": "織り成すは〈作り出す〉意味で、〈壊す〉の意味はない。ここでは〈壊す〉を使う。"}, {"text": "彼は友達の悪口を織り成して、先生に話した。", "explanation": "織り成すは〈まとまりを作る〉意味。悪口には〈言う〉を使うので、織り成すは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "織り成す", "is_correct": true, "explanation": "複数の花が組み合わさって色の変化を作る意味で、「色の変化」と合う。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "「花が叫ぶ色の変化」は不自然で、意味が通らない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「花が運ぶ色の変化」は目的語と動詞が合わず、意味が通らない。"}, {"text": "眺める", "is_correct": false, "explanation": "「花が眺める色の変化」は、花が見る主体にならないので意味が通らない。"}], "explanations": {"織り成す": "複数の花が組み合わさって色の変化を作る意味で、「色の変化」と合う。", "叫ぶ": "「花が叫ぶ色の変化」は不自然で、意味が通らない。", "運ぶ": "「花が運ぶ色の変化」は目的語と動詞が合わず、意味が通らない。", "眺める": "「花が眺める色の変化」は、花が見る主体にならないので意味が通らない。"}, "sentence_index": 6, "correct_answer": "織り成す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "映画は三時間を織り成していて、少し長かった。", "explanation": "織り成すは〈組み合わせて一つにする〉意味。時間の長さには使わず、〈長さ〉の意味でも使わない。"}, {"text": "警察は犯人を織り成して、事件を解決した。", "explanation": "織り成すは〈まとまりを作る〉意味。人を捕まえる意味では使わないので、合わない。"}, {"text": "彼女は足を織り成して、ゆっくり歩いた。", "explanation": "ここは〈足を組む〉の意味。織り成すは複数の要素がまとまって一つの模様や景色を作る場合に使い、体の一部を組む動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕焼けと雲に織り成す空は、いつ見ても美しい。", "corrected_sentence": "夕焼けと雲が織り成す空は、いつ見ても美しい。", "error_description": "助詞の誤り。誤: 雲に織り成す／正: 雲が織り成す。「織り成す」の主語（組み合わさるもの）は〈が〉で示す。〈に〉は方向や相手を示すので主語にならない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "織り成す", "is_correct": true, "explanation": "連体形（辞書形と同じ形）。「模様」を直接修飾するので、この形になる。"}, {"text": "織り成し", "is_correct": false, "explanation": "連用形。名詞を直接修飾できないので、「模様」の前には置けない。"}, {"text": "織り成して", "is_correct": false, "explanation": "て形。名詞「模様」に直接つながらないので、この位置では使えない。"}, {"text": "織り成せば", "is_correct": false, "explanation": "仮定形。条件を表すので、名詞「模様」を修飾できない。"}], "correct_form": "織り成す", "base_form": "織り成す", "form_label": "連体形", "sentence_index": 1, "explanations": {"織り成す": "連体形（辞書形と同じ形）。「模様」を直接修飾するので、この形になる。", "織り成し": "連用形。名詞を直接修飾できないので、「模様」の前には置けない。", "織り成して": "て形。名詞「模様」に直接つながらないので、この位置では使えない。", "織り成せば": "仮定形。条件を表すので、名詞「模様」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51895, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雲と夕日が織り成して空は、言葉では伝えられない。", "corrected_sentence": "雲と夕日が織り成した空は、言葉では伝えられない。", "error_description": "活用の誤り。誤: 織り成して空／正: 織り成した空。名詞「空」を修飾するので、〈た〉で終わる連体形が必要。〈て〉は名詞に直接続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "織り成して", "is_correct": true, "explanation": "て形。後ろの「新しい曲を作った」へ続け、動作を並べる役割。"}, {"text": "織り成せ", "is_correct": false, "explanation": "命令形。文の途中では使えず、「作った」へ続けられない。"}, {"text": "織り成した", "is_correct": false, "explanation": "過去形。「作った」と並ぶと過去が二つになり、「て」で続ける形にならない。"}, {"text": "織り成せば", "is_correct": false, "explanation": "仮定形。条件を表すので、「新しい曲を作った」という文と合わない。"}], "correct_form": "織り成して", "base_form": "織り成す", "form_label": "て形", "sentence_index": 7, "explanations": {"織り成して": "て形。後ろの「新しい曲を作った」へ続け、動作を並べる役割。", "織り成せ": "命令形。文の途中では使えず、「作った」へ続けられない。", "織り成した": "過去形。「作った」と並ぶと過去が二つになり、「て」で続ける形にならない。", "織り成せば": "仮定形。条件を表すので、「新しい曲を作った」という文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「別れ」は「織り成した」の主語（組み合わさるもの）なので、〈が〉で示す。"}, {"text": "に", "is_correct": false, "explanation": "〈別れに織り成した〉は相手や場所を示す〈に〉では主語にならず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、〈別れへ織り成した〉は成立しない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示すので、〈別れより織り成した〉は文として不自然。"}], "correct_answer": "が", "explanations": {"が": "「別れ」は「織り成した」の主語（組み合わさるもの）なので、〈が〉で示す。", "に": "〈別れに織り成した〉は相手や場所を示す〈に〉では主語にならず、不自然。", "へ": "〈へ〉は方向を示すので、〈別れへ織り成した〉は成立しない。", "より": "〈より〉は比較を示すので、〈別れより織り成した〉は文として不自然。"}, "error_tags": {"に": "位置・相手", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「異なる文化」は「織り成す」の主語（組み合わさるもの）なので、〈が〉で示す。"}, {"text": "や", "is_correct": false, "explanation": "〈や〉は名詞を並列に並べる助詞なので、「異なる文化や織り成す」では主語にならず、不自然。"}, {"text": "か", "is_correct": false, "explanation": "〈か〉は選択や疑問を示すので、「異なる文化か織り成す」は主語を示せず、不自然。"}, {"text": "ほど", "is_correct": false, "explanation": "〈ほど〉は程度を示すので、「異なる文化ほど織り成す」は主語を作れず、文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「異なる文化」は「織り成す」の主語（組み合わさるもの）なので、〈が〉で示す。", "や": "〈や〉は名詞を並列に並べる助詞なので、「異なる文化や織り成す」では主語にならず、不自然。", "か": "〈か〉は選択や疑問を示すので、「異なる文化か織り成す」は主語を示せず、不自然。", "ほど": "〈ほど〉は程度を示すので、「異なる文化ほど織り成す」は主語を作れず、文として成り立たない。"}, "error_tags": {"や": "列挙", "か": "選択・疑問", "ほど": "程度"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "複数の要素や事柄を組み合わせて、一つのまとまりのあるものを作り出すこと。", "primary_collocate": null, "pronunciation": "おりなす", "ipa": "orinasɯ", "syllable_count": 4, "sentences": [{"text": "川と森が織り成す静かな風景が、この村の自慢だ。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "川[かわ]と森[もり]が織[お]り成[な]す静[しず]かな風景[ふうけい]が、この村[むら]の自慢[じまん]だ。", "sentence_source": "generated"}, {"text": "長い年月の中で、人々の出会いと別れが織り成した物語がある。", "target_word": "織り成した", "complexity_tier": "T3", "furigana": "長[なが]い年月[としつき]の中[なか]で、人々[ひとびと]の出会[であ]いと別[わか]れが織[お]り成[な]した物語[ものがたり]がある。", "sentence_source": "generated"}, {"text": "色とりどりの花火が夜空に織り成す光の模様に、歓声が上がった。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "色[いろ]とりどりの花火[はなび]が夜空[よぞら]に織[お]り成[な]す光[ひかり]の模様[もよう]に、歓声[かんせい]が上[あ]がった。", "sentence_source": "generated"}, {"text": "彼女の詩は、悲しみと希望を織り成して、読む人の心に響く。", "target_word": "織り成して", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の詩[し]は、悲[かな]しみと希望[きぼう]を織[お]り成[な]して、読[よ]む人[ひと]の心[こころ]に響[ひび]く。", "sentence_source": "generated"}, {"text": "古い建物と新しいビルが織り成す町並みが、この都市の魅力だ。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "古[ふる]い建物[たてもの]と新[あたら]しいビルが織[お]り成[な]す町並[まちな]みが、この都市[とし]の魅力[みりょく]だ。", "sentence_source": "generated"}, {"text": "声と楽器が織り成すハーモニーを、ホールで聴いた。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "声[こえ]と楽器[がっき]が織[お]り成[な]すハーモニーを、ホールで聴[き]いた。", "sentence_source": "generated"}, {"text": "この小説は、いくつもの出来事を織り成して、大きな一つの話にしている。", "target_word": "織り成して", "complexity_tier": "T3", "furigana": "この小説[しょうせつ]は、いくつもの出来事[できごと]を織[お]り成[な]して、大[おお]きな一[ひと]つの話[はなし]にしている。", "sentence_source": "generated"}, {"text": "異なる文化が織り成す食べ物の世界は、とても豊かだ。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "異[こと]なる文化[ぶんか]が織[お]り成[な]す食[た]べ物[もの]の世界[せかい]は、とても豊[ゆた]かだ。", "sentence_source": "generated"}, {"text": "雨と霧が織り成す幻想的な景色の中を、ゆっくり歩いた。", "target_word": "織り成す", "complexity_tier": "T3", "furigana": "雨[あめ]と霧[きり]が織[お]り成[な]す幻想的[げんそうてき]な景色[けしき]の中[なか]を、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "監督はさまざまな場面を織り成して、一本の長い映画を作り上げた。", "target_word": "織り成して", "complexity_tier": "T3", "furigana": "監督[かんとく]はさまざまな場面[ばめん]を織[お]り成[な]して、一本[いっぽん]の長[なが]い映画[えいが]を作[つく]り上[あ]げた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "織り成す", "label": "辞書形"}, {"form": "織り成し", "label": "連用形"}, {"form": "織り成して", "label": "て形"}, {"form": "織り成した", "label": "過去形"}, {"form": "織り成さない", "label": "否定形"}, {"form": "織り成せば", "label": "仮定形"}], "register": "literary", "sense_fingerprint": "複数の要素を組み合わせ、まとまりのある全体を作り出す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71e68b13-de29-4e18-b8c1-858f5a03d21e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "織り成す", "is_correct": true, "explanation": "川と森が組み合わさって景色を作る意味で、「静かな風景」と合う。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "「川と森が叫ぶ風景」は意味が通らず、景色を作る意味とも合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "「川と森が運ぶ風景」は動詞と主語が合わず、意味が通らない。"}, {"text": "割る", "is_correct": false, "explanation": "「川と森が割る風景」は目的語がなく、意味が通らない。"}], "explanations": {"織り成す": "川と森が組み合わさって景色を作る意味で、「静かな風景」と合う。", "叫ぶ": "「川と森が叫ぶ風景」は意味が通らず、景色を作る意味とも合わない。", "運ぶ": "「川と森が運ぶ風景」は動詞と主語が合わず、意味が通らない。", "割る": "「川と森が割る風景」は目的語がなく、意味が通らない。"}, "sentence_index": 0, "correct_answer": "織り成す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部屋の掃除を織り成して、一時間で終えた。", "explanation": "掃除は〈片づける〉ものなので、組み合わせて一つにする織り成すは合わない。"}, {"text": "この店は売り上げを織り成して、閉店時間を決めた。", "explanation": "売り上げは〈伸ばす〉や〈上げる〉の対象で、組み合わせる意味の織り成すは使わない。"}, {"text": "彼は薬を織り成して、熱を下げた。", "explanation": "薬は〈飲む〉ものなので、織り成すとは結びつかず、ここでは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "織り成して", "is_correct": true, "explanation": "て形。「出来事を〜して、話にしている」と、いくつもの出来事を組み合わせる流れに合う。"}, {"text": "逃げて", "is_correct": false, "explanation": "「出来事を逃げて」は〈逃げる〉が目的語を取れず、文として成り立たない。"}, {"text": "寝て", "is_correct": false, "explanation": "「出来事を寝て」は〈寝る〉が目的語を取れず、意味が通らない。"}, {"text": "光って", "is_correct": false, "explanation": "「出来事を光って」は〈光る〉が目的語を取れず、文として成り立たない。"}], "explanations": {"織り成して": "て形。「出来事を〜して、話にしている」と、いくつもの出来事を組み合わせる流れに合う。", "逃げて": "「出来事を逃げて」は〈逃げる〉が目的語を取れず、文として成り立たない。", "寝て": "「出来事を寝て」は〈寝る〉が目的語を取れず、意味が通らない。", "光って": "「出来事を光って」は〈光る〉が目的語を取れず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "織り成して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人は固く手を織り成した。", "explanation": "ここは〈結ぶ〉の意味。織り成すは複数の要素が組み合わさって一つの姿になる場合に使い、手を結び合わせる動作には使わない。"}, {"text": "台風が村の景色を織り成して、すべて流してしまった。", "explanation": "織り成すは〈作り出す〉意味で、〈流す〉の意味はない。ここでは〈流す〉を使う。"}, {"text": "彼は友達の悪口を織り成して、笑いながら話した。", "explanation": "織り成すは〈まとまりを作る〉意味。悪口は〈言う〉を使うので、織り成すは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谷と川が織り成して景色を、毎朝写真に撮っている。", "corrected_sentence": "谷と川が織り成す景色を、毎朝写真に撮っている。", "error_description": "活用の誤り。誤: 織り成して景色／正: 織り成す景色。名詞「景色」を修飾するので、辞書形と同じ連体形が必要。〈て〉は名詞に直接続かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "織り成した", "is_correct": true, "explanation": "過去の連体形。「物語」を修飾し、すでに作られた話という意味になる。"}, {"text": "織り成し", "is_correct": false, "explanation": "連用形。名詞「物語」を直接修飾できないので、この位置では使えない。"}, {"text": "織り成して", "is_correct": false, "explanation": "て形。名詞「物語」に直接つながらないので、ここでは使えない。"}, {"text": "織り成せば", "is_correct": false, "explanation": "仮定形。条件を表すので、名詞「物語」を修飾できない。"}], "correct_form": "織り成した", "base_form": "織り成す", "form_label": "連体形（過去）", "sentence_index": 1, "explanations": {"織り成した": "過去の連体形。「物語」を修飾し、すでに作られた話という意味になる。", "織り成し": "連用形。名詞「物語」を直接修飾できないので、この位置では使えない。", "織り成して": "て形。名詞「物語」に直接つながらないので、ここでは使えない。", "織り成せば": "仮定形。条件を表すので、名詞「物語」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51896, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "森と湖に織り成す景色を、毎朝写真に撮っている。", "corrected_sentence": "森と湖が織り成す景色を、毎朝写真に撮っている。", "error_description": "助詞の誤り。誤: 森と湖に織り成す／正: 森と湖が織り成す。「織り成す」の主語は〈が〉で示す。〈に〉では主語にならない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "織り成す", "is_correct": true, "explanation": "連体形（辞書形と同じ形）。「食べ物の世界」を直接修飾するので、この形になる。"}, {"text": "織り成し", "is_correct": false, "explanation": "連用形。名詞「世界」を直接修飾できないので、「食べ物の世界」の前には置けない。"}, {"text": "織り成せ", "is_correct": false, "explanation": "命令形。名詞「世界」を修飾できないので、この位置では使えない。"}, {"text": "織り成そう", "is_correct": false, "explanation": "意向形。名詞「世界」を直接修飾できないので、「食べ物の世界」の前には置けない。"}], "correct_form": "織り成す", "base_form": "織り成す", "form_label": "連体形", "sentence_index": 7, "explanations": {"織り成す": "連体形（辞書形と同じ形）。「食べ物の世界」を直接修飾するので、この形になる。", "織り成し": "連用形。名詞「世界」を直接修飾できないので、「食べ物の世界」の前には置けない。", "織り成せ": "命令形。名詞「世界」を修飾できないので、この位置では使えない。", "織り成そう": "意向形。名詞「世界」を直接修飾できないので、「食べ物の世界」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3356f2b-98b3-4f73-b02d-e8910fc47c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51897, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「会う」の相手を表す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「会う」の相手に「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、会う相手には使えない。"}, {"text": "の", "is_correct": false, "explanation": "「の」では文が終われず、述語につながらない。"}], "correct_answer": "に", "explanations": {"に": "「会う」の相手を表す「に」が合う。", "を": "「会う」の相手に「を」は使えない。", "で": "「で」は場所や手段を表し、会う相手には使えない。", "の": "「の」では文が終われず、述語につながらない。"}, "error_tags": {"を": "object_marker", "で": "location_means", "の": "possessive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51897, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "教わる相手・出どころを表す「から」が合う。"}, {"text": "を", "is_correct": false, "explanation": "すでに「作り方を」があり、相手に「を」は使えない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表し、教わる相手には使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は向かう方向を表し、教わる相手・出どころには使えない。"}], "correct_answer": "から", "explanations": {"から": "教わる相手・出どころを表す「から」が合う。", "を": "すでに「作り方を」があり、相手に「を」は使えない。", "で": "「で」は場所や手段を表し、教わる相手には使えない。", "へ": "「へ」は向かう方向を表し、教わる相手・出どころには使えない。"}, "error_tags": {"を": "object_marker", "で": "location_means", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51897, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "作品や物を作った人。", "primary_collocate": null, "pronunciation": "さくしゃ", "ipa": "sakɯɕa", "syllable_count": 3, "sentences": [{"text": "作者はだれですか。", "target_word": "作者", "complexity_tier": "T2", "furigana": "作者[さくしゃ]はだれですか。", "sentence_source": "generated"}, {"text": "この皿の作者に会った。", "target_word": "作者", "complexity_tier": "T2", "furigana": "この皿[さら]の作者[さくしゃ]に会[あ]った。", "sentence_source": "generated"}, {"text": "作者の名前が箱に書いてある。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]の名前[なまえ]が箱[はこ]に書[か]いてある。", "sentence_source": "generated"}, {"text": "この椅子は作者が一つずつ作った。", "target_word": "作者", "complexity_tier": "T3", "furigana": "この椅子[いす]は作者[さくしゃ]が一[ひと]つずつ作[つく]った。", "sentence_source": "generated"}, {"text": "作者を知らない絵が展示されている。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]を知[し]らない絵[え]が展示[てんじ]されている。", "sentence_source": "generated"}, {"text": "作者によって、色の使い方が違う。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]によって、色[いろ]の使[つか]い方[かた]が違[ちが]う。", "sentence_source": "generated"}, {"text": "作者に直接ほめられて、うれしかった。", "target_word": "作者", "complexity_tier": "T4", "furigana": "作者[さくしゃ]に直接[ちょくせつ]ほめられて、うれしかった。", "sentence_source": "generated"}, {"text": "作者から、作り方を教わった。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]から、作[つく]り方[かた]を教[おそ]わった。", "sentence_source": "generated"}, {"text": "作者が使った道具は、今も残っている。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]が使[つか]った道具[どうぐ]は、今[いま]も残[のこ]っている。", "sentence_source": "generated"}, {"text": "展覧会では、作者が自分で作品を説明した。", "target_word": "作者", "complexity_tier": "T4", "furigana": "展覧会[てんらんかい]では、作者[さくしゃ]が自分[じぶん]で作品[さくひん]を説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原作者", "label": "派生"}, {"form": "作者名", "label": "派生"}, {"form": "作者本人", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 作品や物を作った人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
