INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51898, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "小説や絵、音楽などを作った人のこと。", "primary_collocate": null, "pronunciation": "さくしゃ", "ipa": "sakɯɕa", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "作者", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "この小説の作者は有名です。", "target_word": "作者", "complexity_tier": "T2", "furigana": "この小説[しょうせつ]の作者[さくしゃ]は有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "作者に手紙を書いた。", "target_word": "作者", "complexity_tier": "T2", "furigana": "作者[さくしゃ]に手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "絵の作者がわからない。", "target_word": "作者", "complexity_tier": "T3", "furigana": "絵[え]の作者[さくしゃ]がわからない。", "sentence_source": "generated"}, {"text": "作者は、この物語を十年かけて書いた。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]は、この物語[ものがたり]を十年[じゅうねん]かけて書[か]いた。", "sentence_source": "generated"}, {"text": "作者の考えを読み取りたい。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]の考[かんが]えを読[よ]み取[と]りたい。", "sentence_source": "generated"}, {"text": "その歌の作者に会ってみたい。", "target_word": "作者", "complexity_tier": "T3", "furigana": "その歌[うた]の作者[さくしゃ]に会[あ]ってみたい。", "sentence_source": "generated"}, {"text": "作者が亡くなってから、人気が出た。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]が亡[な]くなってから、人気[にんき]が出[で]た。", "sentence_source": "generated"}, {"text": "作者によると、主人公にはモデルがいるそうだ。", "target_word": "作者", "complexity_tier": "T4", "furigana": "作者[さくしゃ]によると、主人公[しゅじんこう]にはモデルがいるそうだ。", "sentence_source": "generated"}, {"text": "作者として、読者の声はうれしい。", "target_word": "作者", "complexity_tier": "T3", "furigana": "作者[さくしゃ]として、読者[どくしゃ]の声[こえ]はうれしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "原作者", "label": "派生"}, {"form": "作者名", "label": "派生"}, {"form": "作者たち", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 小説や絵や音楽を作った人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
