INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51899, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「数字が矛盾する」と主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「矛盾する」は目的語をとらないので不自然。"}, {"text": "から", "is_correct": false, "explanation": "「数字から矛盾しています」は主語を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は主語の位置に合わない。"}], "correct_answer": "が", "explanations": {"が": "「数字が矛盾する」と主語を示す。", "を": "「矛盾する」は目的語をとらないので不自然。", "から": "「数字から矛盾しています」は主語を示せず、文が成り立たない。", "へ": "方向を表す「へ」は主語の位置に合わない。"}, "error_tags": {"を": "object_marker", "から": "wrong_case", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一致", "is_correct": true, "explanation": "合わない「矛盾」に対して、合うことを表す反対語。"}, {"text": "対立", "is_correct": false, "explanation": "反対ではなく、意見がぶつかる近い意味の語。"}, {"text": "混乱", "is_correct": false, "explanation": "乱れることで、「矛盾」の反対語ではない。"}, {"text": "誤解", "is_correct": false, "explanation": "思い違いのことで、「矛盾」の反対語ではない。"}], "correct_answer": "一致", "explanations": {"一致": "合わない「矛盾」に対して、合うことを表す反対語。", "対立": "反対ではなく、意見がぶつかる近い意味の語。", "混乱": "乱れることで、「矛盾」の反対語ではない。", "誤解": "思い違いのことで、「矛盾」の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
