INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51899, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのことが合わないこと。", "primary_collocate": null, "pronunciation": "むじゅん", "ipa": "mɯdʑɯɴ", "syllable_count": 3, "sentences": [{"text": "話に矛盾がある。", "target_word": "矛盾", "complexity_tier": "T1", "furigana": "話[はなし]に矛盾[むじゅん]がある。", "sentence_source": "generated"}, {"text": "二つの数字が矛盾しています。", "target_word": "矛盾しています", "complexity_tier": "T2", "furigana": "二[ふた]つの数字[すうじ]が矛盾[むじゅん]しています。", "sentence_source": "generated"}, {"text": "彼の言葉は行動と矛盾する。", "target_word": "矛盾する", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]は行動[こうどう]と矛盾[むじゅん]する。", "sentence_source": "generated"}, {"text": "矛盾した答えを聞いて、先生は首をかしげた。", "target_word": "矛盾した", "complexity_tier": "T4", "furigana": "矛盾[むじゅん]した答[こた]えを聞[き]いて、先生[せんせい]は首[くび]をかしげた。", "sentence_source": "generated"}, {"text": "矛盾を直してから、提出してください。", "target_word": "矛盾", "complexity_tier": "T3", "furigana": "矛盾[むじゅん]を直[なお]してから、提出[ていしゅつ]してください。", "sentence_source": "generated"}, {"text": "地図と説明が矛盾していて、道に迷った。", "target_word": "矛盾していて", "complexity_tier": "T4", "furigana": "地図[ちず]と説明[せつめい]が矛盾[むじゅん]していて、道[みち]に迷[まよ]った。", "sentence_source": "generated"}, {"text": "矛盾のない話を作るのは意外と難しい。", "target_word": "矛盾", "complexity_tier": "T4", "furigana": "矛盾[むじゅん]のない話[はなし]を作[つく]るのは意外[いがい]と難[むずか]しい。", "sentence_source": "generated"}, {"text": "記録と記憶の矛盾が、事件の鍵になった。", "target_word": "矛盾", "complexity_tier": "T4", "furigana": "記録[きろく]と記憶[きおく]の矛盾[むじゅん]が、事件[じけん]の鍵[かぎ]になった。", "sentence_source": "generated"}, {"text": "矛盾しないように、もう一度確認しよう。", "target_word": "矛盾しない", "complexity_tier": "T4", "furigana": "矛盾[むじゅん]しないように、もう一度[いちど]確認[かくにん]しよう。", "sentence_source": "generated"}, {"text": "二人の意見は、どこかで矛盾していた。", "target_word": "矛盾していた", "complexity_tier": "T4", "furigana": "二人[ふたり]の意見[いけん]は、どこかで矛盾[むじゅん]していた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矛盾する", "label": "活用"}, {"form": "矛盾した", "label": "活用"}, {"form": "矛盾点", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 二つの事が合わないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51899, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "話の中の合わない点を指す「矛盾」が意味に合う。"}, {"text": "面積", "is_correct": false, "explanation": "形は合うが、話に面積があるという意味は合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、話に景色があるという意味は合わない。"}, {"text": "電池", "is_correct": false, "explanation": "形は合うが、話に電池があるという意味は合わない。"}], "explanations": {"矛盾": "話の中の合わない点を指す「矛盾」が意味に合う。", "面積": "形は合うが、話に面積があるという意味は合わない。", "景色": "形は合うが、話に景色があるという意味は合わない。", "電池": "形は合うが、話に電池があるという意味は合わない。"}, "sentence_index": 0, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人の意見がぴったり合ったので、矛盾した。", "explanation": "「矛盾」は合わないことなのに、合った場面に使っていて意味が逆。"}, {"text": "矛盾を冷蔵庫に入れて、冷やしておいた。", "explanation": "「矛盾」は抽象的なことで、物のように冷蔵庫に入れられない。"}, {"text": "彼は毎朝矛盾を飲んでいる。", "explanation": "「矛盾」は飲み物ではないので、「飲む」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51899, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "「合わない点のない話」という意味に合う。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段のない話では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気のない話では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節のない話では意味が合わない。"}], "explanations": {"矛盾": "「合わない点のない話」という意味に合う。", "値段": "形は合うが、値段のない話では意味が合わない。", "天気": "形は合うが、天気のない話では意味が合わない。", "季節": "形は合うが、季節のない話では意味が合わない。"}, "sentence_index": 6, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の意見が同じなので、矛盾していた。", "explanation": "意見が同じなら合っているので、「矛盾」の意味と逆になる。"}, {"text": "矛盾を電車に乗せて、駅まで運んだ。", "explanation": "「矛盾」は物ではないので、電車に乗せて運べない。"}, {"text": "私は矛盾が好きで、毎日歌っている。", "explanation": "「矛盾」は歌うものではなく、「歌う」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
