INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51899, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地図と説明の矛盾に、道に迷った。", "corrected_sentence": "地図と説明の矛盾で、道に迷った。", "error_description": "原因を表す助詞は「で」で、「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51900, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「彼の話」を主題として示す「は」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「矛盾する」は目的語をとらない動詞なので、「を」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表す助詞で、「彼の話へ矛盾している」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「彼の話の矛盾している」では文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「彼の話」を主題として示す「は」が合う。", "を": "「矛盾する」は目的語をとらない動詞なので、「を」は使えない。", "へ": "「へ」は方向を表す助詞で、「彼の話へ矛盾している」は成り立たない。", "の": "「彼の話の矛盾している」では文が成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "の": "possessive"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整合", "is_correct": true, "explanation": "食い違いがなく合っていることで、「矛盾」の反対になる。"}, {"text": "対立", "is_correct": false, "explanation": "意見がぶつかることで、反対ではなく近い意味になる。"}, {"text": "食い違い", "is_correct": false, "explanation": "「矛盾」と近い意味で、反対ではない。"}, {"text": "混乱", "is_correct": false, "explanation": "乱れることで、矛盾の反対の関係ではない。"}], "correct_answer": "整合", "explanations": {"整合": "食い違いがなく合っていることで、「矛盾」の反対になる。", "対立": "意見がぶつかることで、反対ではなく近い意味になる。", "食い違い": "「矛盾」と近い意味で、反対ではない。", "混乱": "乱れることで、矛盾の反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51900, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「気づく」の対象を表す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「気づく」の対象に「を」は使えない。"}, {"text": "が", "is_correct": false, "explanation": "「矛盾が気づかない」では対象を表せず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「気づく」の対象には使えない。"}], "correct_answer": "に", "explanations": {"に": "「気づく」の対象を表す「に」が合う。", "を": "「気づく」の対象に「を」は使えない。", "が": "「矛盾が気づかない」では対象を表せず文が成り立たない。", "へ": "「へ」は方向を表し、「気づく」の対象には使えない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一貫", "is_correct": true, "explanation": "筋が通って食い違わないことで、「矛盾」の反対になる。"}, {"text": "衝突", "is_correct": false, "explanation": "ぶつかることで、矛盾に近い意味になる。"}, {"text": "誤解", "is_correct": false, "explanation": "思い違いのことで、矛盾の反対の関係ではない。"}, {"text": "複雑", "is_correct": false, "explanation": "入り組んでいることで、矛盾の反対の関係ではない。"}], "correct_answer": "一貫", "explanations": {"一貫": "筋が通って食い違わないことで、「矛盾」の反対になる。", "衝突": "ぶつかることで、矛盾に近い意味になる。", "誤解": "思い違いのことで、矛盾の反対の関係ではない。", "複雑": "入り組んでいることで、矛盾の反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51900, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の間に食い違いやつじつまの合わない点があること。", "primary_collocate": null, "pronunciation": "むじゅん", "ipa": "mɯdʑɯɴ", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "矛盾", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "彼の話は矛盾している。", "target_word": "矛盾している", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は矛盾[むじゅん]している。", "sentence_source": "generated"}, {"text": "二つの説明に矛盾がある。", "target_word": "矛盾", "complexity_tier": "T3", "furigana": "二[ふた]つの説明[せつめい]に矛盾[むじゅん]がある。", "sentence_source": "generated"}, {"text": "矛盾を見つけた。", "target_word": "矛盾", "complexity_tier": "T2", "furigana": "矛盾[むじゅん]を見[み]つけた。", "sentence_source": "generated"}, {"text": "言うこととやることが矛盾しています。", "target_word": "矛盾しています", "complexity_tier": "T3", "furigana": "言[い]うこととやることが矛盾[むじゅん]しています。", "sentence_source": "generated"}, {"text": "矛盾する意見をまとめるのは難しい。", "target_word": "矛盾する", "complexity_tier": "T3", "furigana": "矛盾[むじゅん]する意見[いけん]をまとめるのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "証言の矛盾から、うそがばれた。", "target_word": "矛盾", "complexity_tier": "T3", "furigana": "証言[しょうげん]の矛盾[むじゅん]から、うそがばれた。", "sentence_source": "generated"}, {"text": "矛盾に気づかないまま、計画を進めてしまった。", "target_word": "矛盾", "complexity_tier": "T4", "furigana": "矛盾[むじゅん]に気[き]づかないまま、計画[けいかく]を進[すす]めてしまった。", "sentence_source": "generated"}, {"text": "この規則は、別の規則と矛盾しないだろうか。", "target_word": "矛盾しない", "complexity_tier": "T4", "furigana": "この規則[きそく]は、別[べつ]の規則[きそく]と矛盾[むじゅん]しないだろうか。", "sentence_source": "generated"}, {"text": "矛盾だらけの説明では、だれも納得しない。", "target_word": "矛盾", "complexity_tier": "T4", "furigana": "矛盾[むじゅん]だらけの説明[せつめい]では、だれも納得[なっとく]しない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "矛盾する", "label": "活用"}, {"form": "矛盾した", "label": "活用"}, {"form": "矛盾点", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の食い違いやつじつまの合わなさ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51900, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "社会の中にある食い違いという、浮き彫りにする対象に合う。"}, {"text": "傘", "is_correct": false, "explanation": "形は合うが、傘を浮き彫りにするという意味にならない。"}, {"text": "湿度", "is_correct": false, "explanation": "形は合うが、社会的な文脈と並べる意味にならない。"}, {"text": "弁当", "is_correct": false, "explanation": "形は合うが、弁当を浮き彫りにするという意味にならない。"}], "explanations": {"矛盾": "社会の中にある食い違いという、浮き彫りにする対象に合う。", "傘": "形は合うが、傘を浮き彫りにするという意味にならない。", "湿度": "形は合うが、社会的な文脈と並べる意味にならない。", "弁当": "形は合うが、弁当を浮き彫りにするという意味にならない。"}, "sentence_index": 0, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "矛盾を飲んだら、体が温まった。", "explanation": "「矛盾」は食い違いを指し、飲み物の意味では使えない。"}, {"text": "矛盾を二つ買って、友達にあげた。", "explanation": "「矛盾」は食い違いであり、買ってあげる物ではない。"}, {"text": "駅の前で矛盾に乗って、家に帰った。", "explanation": "「矛盾」は乗り物ではなく、「乗る」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51900, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "矛盾", "is_correct": true, "explanation": "証言の食い違いからうそがばれた、という意味に合う。"}, {"text": "気温", "is_correct": false, "explanation": "形は合うが、気温からうそがばれるという意味にならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、砂糖からうそがばれるという意味にならない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、証言の屋根では意味が合わない。"}], "explanations": {"矛盾": "証言の食い違いからうそがばれた、という意味に合う。", "気温": "形は合うが、気温からうそがばれるという意味にならない。", "砂糖": "形は合うが、砂糖からうそがばれるという意味にならない。", "屋根": "形は合うが、証言の屋根では意味が合わない。"}, "sentence_index": 6, "correct_answer": "矛盾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "矛盾が熱いうちに、早く食べてください。", "explanation": "「矛盾」は食い違いであり、食べ物の意味では使えない。"}, {"text": "矛盾をかぶって、日差しを避けた。", "explanation": "「矛盾」は帽子のような物ではなく、かぶる対象にならない。"}, {"text": "矛盾の色は、赤くて丸い。", "explanation": "「矛盾」は抽象的な概念で、色や形を持たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
