INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51901, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "手紙やはがきを出すときに入れる、道などに置かれた郵便の箱。", "primary_collocate": null, "pronunciation": "ぽすと", "ipa": "posɯto", "syllable_count": 3, "sentences": [{"text": "ポストに手紙を入れる。", "target_word": "ポスト", "complexity_tier": "T2", "furigana": "ポストに手紙[てがみ]を入[い]れる。", "sentence_source": "generated"}, {"text": "赤いポストがあります。", "target_word": "ポスト", "complexity_tier": "T2", "furigana": "赤[あか]いポストがあります。", "sentence_source": "generated"}, {"text": "ポストはあそこです。", "target_word": "ポスト", "complexity_tier": "T2", "furigana": "ポストはあそこです。", "sentence_source": "generated"}, {"text": "学校の近くにポストがある。", "target_word": "ポスト", "complexity_tier": "T3", "furigana": "学校[がっこう]の近[ちか]くにポストがある。", "sentence_source": "generated"}, {"text": "ポストに年賀状を入れてきた。", "target_word": "ポスト", "complexity_tier": "T3", "furigana": "ポストに年賀状[ねんがじょう]を入[い]れてきた。", "sentence_source": "generated"}, {"text": "毎朝ポストの前を通って、駅へ行く。", "target_word": "ポスト", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]ポストの前[まえ]を通[とお]って、駅[えき]へ行[い]く。", "sentence_source": "generated"}, {"text": "ポストの中から古い手紙が出てきた。", "target_word": "ポスト", "complexity_tier": "T3", "furigana": "ポストの中[なか]から古[ふる]い手紙[てがみ]が出[で]てきた。", "sentence_source": "generated"}, {"text": "雨の日はポストの前で傘を閉じる。", "target_word": "ポスト", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]はポストの前[まえ]で傘[かさ]を閉[と]じる。", "sentence_source": "generated"}, {"text": "ポストが遠いので、手紙を出すのが大変だ。", "target_word": "ポスト", "complexity_tier": "T4", "furigana": "ポストが遠[とお]いので、手紙[てがみ]を出[だ]すのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "ポストへ行く途中で、友だちに会った。", "target_word": "ポスト", "complexity_tier": "T4", "furigana": "ポストへ行[い]く途中[とちゅう]で、友[とも]だちに会[あ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "郵便ポスト", "label": "派生"}, {"form": "ポスト投函", "label": "派生"}, {"form": "ポストイン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 手紙を入れる郵便の箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
