 "label": "派生"}, {"form": "ポストイン", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 郵便物を入れる箱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51902, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ポスト", "is_correct": true, "explanation": "見出し語。"}, {"text": "ホスト", "is_correct": false, "explanation": "「ぽ」が「ほ」に変わる一音違い。"}, {"text": "コスト", "is_correct": false, "explanation": "「ぽ」が「こ」に変わる一音違い。"}, {"text": "ポット", "is_correct": false, "explanation": "「す」が促音「っ」に変わる一音違い。"}], "explanations": {"ポスト": "見出し語。", "ホスト": "「ぽ」が「ほ」に変わる一音違い。", "コスト": "「ぽ」が「こ」に変わる一音違い。", "ポット": "「す」が促音「っ」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "ポスト"}, "level_3": {"options": [{"text": "ポスト", "is_correct": true, "explanation": "はがきを出すときに入れる箱として、意味に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "形は合うが、砂糖にはがきを出すという意味にならない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが、宿題にはがきを出すという意味にならない。"}, {"text": "音楽", "is_correct": false, "explanation": "形は合うが、音楽にはがきを出すという意味にならない。"}], "explanations": {"ポスト": "はがきを出すときに入れる箱として、意味に合う。", "砂糖": "形は合うが、砂糖にはがきを出すという意味にならない。", "宿題": "形は合うが、宿題にはがきを出すという意味にならない。", "音楽": "形は合うが、音楽にはがきを出すという意味にならない。"}, "sentence_index": 0, "correct_answer": "ポスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ポストをかぶって、雨の中を歩いた。", "explanation": "「ポスト」は郵便の箱で、帽子のようにかぶるものではない。"}, {"text": "ポストを洗濯機に入れて、きれいに洗った。", "explanation": "「ポスト」は道に置かれた大きな郵便の箱で、洗濯機で洗うものではない。"}, {"text": "ポストにお湯を入れて、お茶を作った。", "explanation": "「ポスト」は郵便物を入れる箱で、お湯を入れる容器ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51902, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ポスト", "is_correct": true, "explanation": "見出し語。"}, {"text": "テスト", "is_correct": false, "explanation": "「ぽ」が「て」に変わる一音違い。"}, {"text": "ラスト", "is_correct": false, "explanation": "「ぽ」が「ら」に変わる一音違い。"}, {"text": "ベスト", "is_correct": false, "explanation": "「ぽ」が「べ」に変わる一音違い。"}, {"text": "マスト", "is_correct": false, "explanation": "「ぽ」が「ま」に変わる一音違い。"}], "explanations": {"ポスト": "見出し語。", "テスト": "「ぽ」が「て」に変わる一音違い。", "ラスト": "「ぽ」が「ら」に変わる一音違い。", "ベスト": "「ぽ」が「べ」に変わる一音違い。", "マスト": "「ぽ」が「ま」に変わる一音違い。"}, "sentence_index": null, "correct_answer": "ポスト"}, "level_3": {"options": [{"text": "ポスト", "is_correct": true, "explanation": "手紙を入れる前に切手をはる、という流れに合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気に入れる前に切手をはる意味は合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "形は合うが、音楽に入れる前に切手をはる意味は合わない。"}, {"text": "テーブル", "is_correct": false, "explanation": "形は合うが、テーブルに入れる前に切手をはる意味は合わない。"}], "explanations": {"ポスト": "手紙を入れる前に切手をはる、という流れに合う。", "天気": "形は合うが、天気に入れる前に切手をはる意味は合わない。", "音楽": "形は合うが、音楽に入れる前に切手をはる意味は合わない。", "テーブル": "形は合うが、テーブルに入れる前に切手をはる意味は合わない。"}, "sentence_index": 6, "correct_answer": "ポスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ポストを食べて、お腹がいっぱいになった。", "explanation": "「ポスト」は郵便の箱で、食べ物ではない。"}, {"text": "ポストで電話をかけて、友だちと話した。", "explanation": "「ポスト」は郵便の箱で、電話をかける場所ではない。"}, {"text": "ポストが歌を歌って、みんなを笑わせた。", "explanation": "「ポスト」は箱であり、歌を歌う主語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.