INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「足跡が浮き彫りになる」で、主語を表す。"}, {"text": "を", "is_correct": false, "explanation": "「足跡を浮き彫りになっていた」は自動詞的な「なる」と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「足跡と浮き彫りになっていた」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「足跡へ浮き彫りになっていた」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「足跡が浮き彫りになる」で、主語を表す。", "を": "「足跡を浮き彫りになっていた」は自動詞的な「なる」と合わない。", "と": "「足跡と浮き彫りになっていた」は文として成り立たない。", "へ": "「足跡へ浮き彫りになっていた」は文として成り立たない。"}, "error_tags": {"を": "object", "と": "comitative", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "見えないように隠すことで、「浮き彫り」の反対。"}, {"text": "強調", "is_correct": false, "explanation": "目立たせる意味で、近い意味。"}, {"text": "明示", "is_correct": false, "explanation": "はっきり示す意味で、近い意味。"}, {"text": "可視化", "is_correct": false, "explanation": "見えるようにする意味で、近い意味。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "見えないように隠すことで、「浮き彫り」の反対。", "強調": "目立たせる意味で、近い意味。", "明示": "はっきり示す意味で、近い意味。", "可視化": "見えるようにする意味で、近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「山の形を絵にかく」で、かく対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「かく」の対象なので「が」では文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「山の形へ絵にかいた」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「山の形より絵にかいた」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「山の形を絵にかく」で、かく対象を表す。", "が": "「かく」の対象なので「が」では文として成り立たない。", "へ": "「山の形へ絵にかいた」は文として成り立たない。", "より": "「山の形より絵にかいた」は文として成り立たない。"}, "error_tags": {"が": "subject", "へ": "direction", "より": "comparison"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "埋没", "is_correct": true, "explanation": "埋もれて見えなくなることで、「浮き彫り」の反対。"}, {"text": "強調", "is_correct": false, "explanation": "目立たせる意味で、近い意味。"}, {"text": "明示", "is_correct": false, "explanation": "はっきり示す意味で、近い意味。"}, {"text": "顕在化", "is_correct": false, "explanation": "表に現れる意味で、近い意味。"}], "correct_answer": "埋没", "explanations": {"埋没": "埋もれて見えなくなることで、「浮き彫り」の反対。", "強調": "目立たせる意味で、近い意味。", "明示": "はっきり示す意味で、近い意味。", "顕在化": "表に現れる意味で、近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを、はっきりと見えるようにすること。", "primary_collocate": null, "pronunciation": "うきぼり", "ipa": "ɯkibori", "syllable_count": 4, "sentences": [{"text": "横から光を当てて、傷を浮き彫りにする。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "横[よこ]から光[ひかり]を当[あ]てて、傷[きず]を浮[う]き彫[ぼ]りにする。", "sentence_source": "generated"}, {"text": "雪の上に、足跡が浮き彫りになっていた。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]に、足跡[あしあと]が浮[う]き彫[ぼ]りになっていた。", "sentence_source": "generated"}, {"text": "朝日が山の形を浮き彫りにします。", "target_word": "浮き彫り", "complexity_tier": "T2", "furigana": "朝日[あさひ]が山[やま]の形[かたち]を浮[う]き彫[ぼ]りにします。", "sentence_source": "generated"}, {"text": "雨の夜、街の灯が道を浮き彫りにしている。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "雨[あめ]の夜[よる]、街[まち]の灯[あかり]が道[みち]を浮[う]き彫[ぼ]りにしている。", "sentence_source": "generated"}, {"text": "暗い部屋では、月明かりで彼の横顔が浮き彫りになった。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "暗[くら]い部屋[へや]では、月明[つきあ]かりで彼[かれ]の横顔[よこがお]が浮[う]き彫[ぼ]りになった。", "sentence_source": "generated"}, {"text": "影のおかげで、木の形が浮き彫りに見える。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "影[かげ]のおかげで、木[き]の形[かたち]が浮[う]き彫[ぼ]りに見[み]える。", "sentence_source": "generated"}, {"text": "夕日に浮き彫りにされた山の形が、はっきり見えた。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "夕日[ゆうひ]に浮[う]き彫[ぼ]りにされた山[やま]の形[かたち]が、はっきり見[み]えた。", "sentence_source": "generated"}, {"text": "浮き彫りになった山の形を、絵にかいた。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "浮[う]き彫[ぼ]りになった山[やま]の形[かたち]を、絵[え]にかいた。", "sentence_source": "generated"}, {"text": "特別なライトは、見えない指紋を浮き彫りにできる。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "特別[とくべつ]なライトは、見[み]えない指紋[しもん]を浮[う]き彫[ぼ]りにできる。", "sentence_source": "generated"}, {"text": "光の角度を変えれば、壁の凹凸は浮き彫りになるはずだ。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "光[ひかり]の角度[かくど]を変[か]えれば、壁[かべ]の凹凸[おうとつ]は浮[う]き彫[ぼ]りになるはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮き彫りにする", "label": "活用"}, {"form": "浮き彫りになる", "label": "活用"}, {"form": "浮き彫りにされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 何かをはっきり見えるようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮き彫り", "is_correct": true, "explanation": "「傷を浮き彫りにする」で、はっきり見えるようにする意味に合う。"}, {"text": "台無し", "is_correct": false, "explanation": "形は合うが、傷をだめにする意味になり意味が合わない。"}, {"text": "水増し", "is_correct": false, "explanation": "形は合うが、傷を増やす意味になり意味が合わない。"}, {"text": "山分け", "is_correct": false, "explanation": "形は合うが、傷を分け合う意味になり意味が合わない。"}], "explanations": {"浮き彫り": "「傷を浮き彫りにする」で、はっきり見えるようにする意味に合う。", "台無し": "形は合うが、傷をだめにする意味になり意味が合わない。", "水増し": "形は合うが、傷を増やす意味になり意味が合わない。", "山分け": "形は合うが、傷を分け合う意味になり意味が合わない。"}, "sentence_index": 0, "correct_answer": "浮き彫り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母は台所でじゃがいもを浮き彫りにしている。", "explanation": "「皮をむく」の意味で使っているが、「浮き彫りにする」にその意味はない。"}, {"text": "弟は部屋の掃除を浮き彫りにして、遊びに出かけた。", "explanation": "「後回しにする」の意味で使っているが、意味が逆になっている。"}, {"text": "冷蔵庫の中の牛乳を浮き彫りにして、冷やした。", "explanation": "「取り出す」の意味で使っているが、「浮き彫りにする」にその意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮き彫り", "is_correct": true, "explanation": "夕日で山の形がはっきり見えるようになった意味に合う。"}, {"text": "山分け", "is_correct": false, "explanation": "形は合うが、夕日が山を分け合う意味になり意味が合わない。"}, {"text": "水増し", "is_correct": false, "explanation": "形は合うが、山の形を増やす意味になり意味が合わない。"}, {"text": "横取り", "is_correct": false, "explanation": "形は合うが、山の形を奪う意味になり意味が合わない。"}], "explanations": {"浮き彫り": "夕日で山の形がはっきり見えるようになった意味に合う。", "山分け": "形は合うが、夕日が山を分け合う意味になり意味が合わない。", "水増し": "形は合うが、山の形を増やす意味になり意味が合わない。", "横取り": "形は合うが、山の形を奪う意味になり意味が合わない。"}, "sentence_index": 6, "correct_answer": "浮き彫り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明日は雨だから、傘が浮き彫りになるはずだ。", "explanation": "「必要になる」の意味で使っているが、「浮き彫り」にその意味はない。"}, {"text": "彼は走るのが速いので、すぐ浮き彫りになるはずだ。", "explanation": "「追いつく」の意味で使っているが、「浮き彫り」にその意味はない。"}, {"text": "冷たい水に入れれば、氷は浮き彫りになるはずだ。", "explanation": "「浮く」と混同しており、「浮き彫り」に水に浮く意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
