INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51903, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の上に、足跡が浮き彫りへなっていた。", "corrected_sentence": "雪の上に、足跡が浮き彫りになっていた。", "error_description": "「浮き彫りになる」と言うところを、助詞「へ」にしている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「問題を浮き彫りにする」で、対象を表す。"}, {"text": "と", "is_correct": false, "explanation": "「問題と浮き彫りにした」は文として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「問題から浮き彫りにした」は対象を表せず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「問題へ浮き彫りにした」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「問題を浮き彫りにする」で、対象を表す。", "と": "「問題と浮き彫りにした」は文として成り立たない。", "から": "「問題から浮き彫りにした」は対象を表せず不自然。", "へ": "「問題へ浮き彫りにした」は文として成り立たない。"}, "error_tags": {"と": "comitative", "から": "source", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "埋没", "is_correct": true, "explanation": "目立たず埋もれることで、「浮き彫り」の反対。"}, {"text": "強調", "is_correct": false, "explanation": "目立たせる意味で、反対ではなく近い意味。"}, {"text": "明示", "is_correct": false, "explanation": "はっきり示す意味で、近い意味。"}, {"text": "顕在化", "is_correct": false, "explanation": "表に現れる意味で、近い意味。"}], "correct_answer": "埋没", "explanations": {"埋没": "目立たず埋もれることで、「浮き彫り」の反対。", "強調": "目立たせる意味で、反対ではなく近い意味。", "明示": "はっきり示す意味で、近い意味。", "顕在化": "表に現れる意味で、近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「浮き彫りにしたと言える」で、言う内容を表す。"}, {"text": "を", "is_correct": false, "explanation": "「浮き彫りにしたを言える」は文法的に成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「浮き彫りにしたに言える」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「浮き彫りにしたの言える」は文法的に成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「浮き彫りにしたと言える」で、言う内容を表す。", "を": "「浮き彫りにしたを言える」は文法的に成り立たない。", "に": "「浮き彫りにしたに言える」は文法的に成り立たない。", "の": "「浮き彫りにしたの言える」は文法的に成り立たない。"}, "error_tags": {"を": "object", "に": "target", "の": "genitive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隠蔽", "is_correct": true, "explanation": "隠して見えなくすることで、「浮き彫り」の反対。"}, {"text": "表面化", "is_correct": false, "explanation": "表に出る意味で、近い意味。"}, {"text": "可視化", "is_correct": false, "explanation": "見えるようにする意味で、近い意味。"}, {"text": "具体化", "is_correct": false, "explanation": "はっきりした形にする意味で、近い意味。"}], "correct_answer": "隠蔽", "explanations": {"隠蔽": "隠して見えなくすることで、「浮き彫り」の反対。", "表面化": "表に出る意味で、近い意味。", "可視化": "見えるようにする意味で、近い意味。", "具体化": "はっきりした形にする意味で、近い意味。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の本質や特徴を、はっきりと目立つように示すこと。", "primary_collocate": null, "pronunciation": "うきぼり", "ipa": "ɯkibori", "syllable_count": 4, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "浮き彫り", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "調査が問題を浮き彫りにした。", "target_word": "浮き彫り", "complexity_tier": "T2", "furigana": "調査[ちょうさ]が問題[もんだい]を浮[う]き彫[ぼ]りにした。", "sentence_source": "generated"}, {"text": "この数字は格差を浮き彫りにした。", "target_word": "浮き彫り", "complexity_tier": "T2", "furigana": "この数字[すうじ]は格差[かくさ]を浮[う]き彫[ぼ]りにした。", "sentence_source": "generated"}, {"text": "事故で安全対策の甘さが浮き彫りになった。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "事故[じこ]で安全対策[あんぜんたいさく]の甘[あま]さが浮[う]き彫[ぼ]りになった。", "sentence_source": "generated"}, {"text": "彼の言葉が問題点を浮き彫りにしている。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "彼[かれ]の言葉[ことば]が問題点[もんだいてん]を浮[う]き彫[ぼ]りにしている。", "sentence_source": "generated"}, {"text": "浮き彫りにされた課題に、市は取り組む。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "浮[う]き彫[ぼ]りにされた課題[かだい]に、市[し]は取[と]り組[く]む。", "sentence_source": "generated"}, {"text": "比べると、違いがはっきり浮き彫りになる。", "target_word": "浮き彫り", "complexity_tier": "T3", "furigana": "比[くら]べると、違[ちが]いがはっきり浮[う]き彫[ぼ]りになる。", "sentence_source": "generated"}, {"text": "この調査は、現代社会の孤独を浮き彫りにしたと言える。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "この調査[ちょうさ]は、現代社会[げんだいしゃかい]の孤独[こどく]を浮[う]き彫[ぼ]りにしたと言[い]える。", "sentence_source": "generated"}, {"text": "災害は、社会の弱さを浮き彫りにすることがある。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "災害[さいがい]は、社会[しゃかい]の弱[よわ]さを浮[う]き彫[ぼ]りにすることがある。", "sentence_source": "generated"}, {"text": "作者は対比によって人物の性格を浮き彫りにする。", "target_word": "浮き彫り", "complexity_tier": "T4", "furigana": "作者[さくしゃ]は対比[たいひ]によって人物[じんぶつ]の性格[せいかく]を浮[う]き彫[ぼ]りにする。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮き彫りにする", "label": "活用"}, {"form": "浮き彫りになる", "label": "活用"}, {"form": "浮き彫りにされる", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の本質をはっきり目立たせること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮き彫り", "is_correct": true, "explanation": "「矛盾を浮き彫りにする」で、本質をはっきり示す意味に合う。"}, {"text": "水増し", "is_correct": false, "explanation": "形は合うが、矛盾を数や量を増やす意味になり意味が合わない。"}, {"text": "横取り", "is_correct": false, "explanation": "形は合うが、矛盾を人から奪う意味になり意味が合わない。"}, {"text": "山分け", "is_correct": false, "explanation": "形は合うが、矛盾を分け合う意味になり意味が合わない。"}], "explanations": {"浮き彫り": "「矛盾を浮き彫りにする」で、本質をはっきり示す意味に合う。", "水増し": "形は合うが、矛盾を数や量を増やす意味になり意味が合わない。", "横取り": "形は合うが、矛盾を人から奪う意味になり意味が合わない。", "山分け": "形は合うが、矛盾を分け合う意味になり意味が合わない。"}, "sentence_index": 0, "correct_answer": "浮き彫り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は毎朝、浮き彫りを飲んでから会社に行く。", "explanation": "「浮き彫り」は飲むものではなく、物事をはっきり示すことなので用法が違う。"}, {"text": "雨で試合が浮き彫りになった。", "explanation": "「延期」の意味で使っているが、「浮き彫り」に試合が延びる意味はない。"}, {"text": "新しい服を浮き彫りにして出かけた。", "explanation": "「着る」の意味で使っているが、「浮き彫りにする」に服を身につける意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮き彫り", "is_correct": true, "explanation": "「違いが浮き彫りになる」で、違いが際立つ意味に合う。"}, {"text": "無駄", "is_correct": false, "explanation": "形は合うが、違いが無駄になるでは意味が合わない。"}, {"text": "台無し", "is_correct": false, "explanation": "形は合うが、違いがだめになる意味になり意味が合わない。"}, {"text": "手遅れ", "is_correct": false, "explanation": "形は合うが、違いが手遅れになる意味になり意味が合わない。"}], "explanations": {"浮き彫り": "「違いが浮き彫りになる」で、違いが際立つ意味に合う。", "無駄": "形は合うが、違いが無駄になるでは意味が合わない。", "台無し": "形は合うが、違いがだめになる意味になり意味が合わない。", "手遅れ": "形は合うが、違いが手遅れになる意味になり意味が合わない。"}, "sentence_index": 6, "correct_answer": "浮き彫り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は朝七時に浮き彫りになる。", "explanation": "「開店する」の意味で使っているが、「浮き彫り」に開く意味はない。"}, {"text": "友人は私の誕生日を浮き彫りにして、プレゼントを忘れた。", "explanation": "「忘れる」の意味で使っているが、「浮き彫りにする」は際立たせる意味で逆。"}, {"text": "電車が遅れたので、会議の時間を浮き彫りにした。", "explanation": "「変更する」の意味で使っているが、「浮き彫りにする」に変更の意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社会の矛盾が浮き彫りをなった。", "corrected_sentence": "社会の矛盾が浮き彫りになった。", "error_description": "「浮き彫りになる」と言うところを「浮き彫りをなった」と助詞を誤っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51904, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の発言が組織の問題に浮き彫りにした。", "corrected_sentence": "彼の発言が組織の問題を浮き彫りにした。", "error_description": "「浮き彫りにする」の対象は「を」で示すのに、「に」を使っている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
