INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51905, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「テキストを入力する」で、動作の対象を表す。"}, {"text": "へ", "is_correct": false, "explanation": "「テキストへ入力して」は対象を表せず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「テキストが入力して」では、入力される側のテキストが動作主になり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「テキストの入力して」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「テキストを入力する」で、動作の対象を表す。", "へ": "「テキストへ入力して」は対象を表せず不自然。", "が": "「テキストが入力して」では、入力される側のテキストが動作主になり、文として成り立たない。", "の": "「テキストの入力して」は文として成り立たない。"}, "error_tags": {"へ": "direction", "が": "subject", "の": "genitive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51905, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "文字や言葉の集まり。", "primary_collocate": null, "pronunciation": "てきすと", "ipa": "tekisɯto", "syllable_count": 4, "sentences": [{"text": "このテキストは短いです。", "target_word": "テキスト", "complexity_tier": "T2", "furigana": "このテキストは短[みじか]いです。", "sentence_source": "generated"}, {"text": "テキストを読んで、答えを書く。", "target_word": "テキスト", "complexity_tier": "T2", "furigana": "テキストを読[よ]んで、答[こた]えを書[か]く。", "sentence_source": "generated"}, {"text": "長いテキストを短くまとめた。", "target_word": "テキスト", "complexity_tier": "T2", "furigana": "長[なが]いテキストを短[みじか]くまとめた。", "sentence_source": "generated"}, {"text": "画面のテキストが小さくて読めない。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "画面[がめん]のテキストが小[ちい]さくて読[よ]めない。", "sentence_source": "generated"}, {"text": "このテキストには、難しい言葉が多い。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "このテキストには、難[むずか]しい言葉[ことば]が多[おお]い。", "sentence_source": "generated"}, {"text": "同じテキストでも、人によって読み方は違う。", "target_word": "テキスト", "complexity_tier": "T4", "furigana": "同[おな]じテキストでも、人[ひと]によって読[よ]み方[かた]は違[ちが]う。", "sentence_source": "generated"}, {"text": "彼女はテキストの意味を丁寧に説明した。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はテキストの意味[いみ]を丁寧[ていねい]に説明[せつめい]した。", "sentence_source": "generated"}, {"text": "テキストを入力して、送信ボタンを押す。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "テキストを入力[にゅうりょく]して、送信[そうしん]ボタンを押[お]す。", "sentence_source": "generated"}, {"text": "写真の下に、短いテキストが付いている。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "写真[しゃしん]の下[した]に、短[みじか]いテキストが付[つ]いている。", "sentence_source": "generated"}, {"text": "このテキストは百年前に書かれたものだ。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "このテキストは百年前[ひゃくねんまえ]に書[か]かれたものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テキストファイル", "label": "派生"}, {"form": "テキストデータ", "label": "派生"}, {"form": "テキスト化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 文字や言葉が集まったもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51905, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テキスト", "is_correct": true, "explanation": "「このテキストは短い」で、文字の集まりの意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気が短いでは意味が合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物が短いでは意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、台風が短いでは意味が合わない。"}], "explanations": {"テキスト": "「このテキストは短い」で、文字の集まりの意味に合う。", "天気": "形は合うが、天気が短いでは意味が合わない。", "果物": "形は合うが、果物が短いでは意味が合わない。", "台風": "形は合うが、台風が短いでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "テキスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このテキストを塩で焼いて、昼ごはんにした。", "explanation": "「テキスト」は文字や言葉の集まりで、焼いて食べるものではない。"}, {"text": "公園のテキストで、犬が元気に走っている。", "explanation": "「テキスト」は文字の集まりで、犬が走る場所ではない。"}, {"text": "テキストが痛いので、病院に行った。", "explanation": "「テキスト」は文字の集まりで、体の部位ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51905, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テキスト", "is_correct": true, "explanation": "「テキストの意味を説明する」で、文字や言葉の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気の意味を丁寧に説明するのは文脈に合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物の意味を説明するのは意味が合わない。"}, {"text": "階段", "is_correct": false, "explanation": "形は合うが、階段の意味を説明するのは意味が合わない。"}], "explanations": {"テキスト": "「テキストの意味を説明する」で、文字や言葉の意味に合う。", "天気": "形は合うが、天気の意味を丁寧に説明するのは文脈に合わない。", "果物": "形は合うが、果物の意味を説明するのは意味が合わない。", "階段": "形は合うが、階段の意味を説明するのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "テキスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この赤いテキストは、駅の近くを走っている。", "explanation": "「テキスト」は文字の集まりで、走る乗り物ではない。"}, {"text": "彼はテキストを履いて、散歩に出た。", "explanation": "「テキスト」は履き物ではない。"}, {"text": "テキストの色がきれいで、窓の外で泳いでいた。", "explanation": "「テキスト」は文字の集まりで、泳ぐ生き物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51905, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "長いテキストに短くまとめた。", "corrected_sentence": "長いテキストを短くまとめた。", "error_description": "「まとめる」の対象は「を」で示すのに、「に」を使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
