INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51906, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「テキストで送る」で、形式・手段を表す。"}, {"text": "が", "is_correct": false, "explanation": "「テキストが送ってください」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「テキストと送ってください」は文として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「テキストに送ってください」は送る形式を表せず、不自然。"}], "correct_answer": "で", "explanations": {"で": "「テキストで送る」で、形式・手段を表す。", "が": "「テキストが送ってください」は文として成り立たない。", "と": "「テキストと送ってください」は文として不自然。", "に": "「テキストに送ってください」は送る形式を表せず、不自然。"}, "error_tags": {"が": "subject", "と": "comitative", "に": "target"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51906, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「テキストは軽い」で、主題を表す。"}, {"text": "を", "is_correct": false, "explanation": "「テキストを軽いので」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「テキストへ軽いので」は文として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「テキストに軽いので」は文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「テキストは軽い」で、主題を表す。", "を": "「テキストを軽いので」は文として成り立たない。", "へ": "「テキストへ軽いので」は文として成り立たない。", "に": "「テキストに軽いので」は文として成り立たない。"}, "error_tags": {"を": "object", "へ": "direction", "に": "target"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51906, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "書かれた文章や、コンピュータで扱う文字データ。", "primary_collocate": null, "pronunciation": "てきすと", "ipa": "tekisɯto", "syllable_count": 4, "sentences": [{"text": "建築を単なる機能の集合体ではなく、記号が織りなすテキストとして読み解く態度が、ポスト構造主義に基づく批評の核心です。", "target_word": "テキスト", "complexity_tier": "T6", "furigana": "建築[けんちく]を単[たん]なる機能[きのう]の集合体[しゅうごうたい]ではなく、記号[きごう]が織[お]りなすテキストとして読[よ]み解[と]く態度[たいど]が、ポスト構造主義[こうぞうしゅぎ]に基[もと]づく批評[ひひょう]の核心[かくしん]です。", "sentence_source": "mined"}, {"text": "画像ではなく、テキストで送ってください。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "画像[がぞう]ではなく、テキストで送[おく]ってください。", "sentence_source": "generated"}, {"text": "テキストが長すぎて、画面に入らない。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "テキストが長[なが]すぎて、画面[がめん]に入[はい]らない。", "sentence_source": "generated"}, {"text": "このアプリはテキストを自動で読み上げる。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "このアプリはテキストを自動[じどう]で読[よ]み上[あ]げる。", "sentence_source": "generated"}, {"text": "メモのテキストは、保存すると消えない。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "メモのテキストは、保存[ほぞん]すると消[き]えない。", "sentence_source": "generated"}, {"text": "文書のテキストだけを抜き出した。", "target_word": "テキスト", "complexity_tier": "T2", "furigana": "文書[ぶんしょ]のテキストだけを抜[ぬ]き出[だ]した。", "sentence_source": "generated"}, {"text": "このテキストの文字化けを直した。", "target_word": "テキスト", "complexity_tier": "T2", "furigana": "このテキストの文字化[もじば]けを直[なお]した。", "sentence_source": "generated"}, {"text": "テキストは軽いので、メールですぐ送れる。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "テキストは軽[かる]いので、メールですぐ送[おく]れる。", "sentence_source": "generated"}, {"text": "画像の中のテキストを、機械が読み取れる。", "target_word": "テキスト", "complexity_tier": "T3", "furigana": "画像[がぞう]の中[なか]のテキストを、機械[きかい]が読[よ]み取[と]れる。", "sentence_source": "generated"}, {"text": "貼り付けたテキストの形式が、元と違ってしまった。", "target_word": "テキスト", "complexity_tier": "T4", "furigana": "貼[は]り付[つ]けたテキストの形式[けいしき]が、元[もと]と違[ちが]ってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "テキストファイル", "label": "派生"}, {"form": "テキストデータ", "label": "派生"}, {"form": "テキスト化", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 書かれた文章や文字データのこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51906, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "テキスト", "is_correct": true, "explanation": "「記号が織りなすテキスト」で、文章の意味に合う。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、記号が織りなす果物では意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気として読み解くのは意味が合わない。"}, {"text": "乗り物", "is_correct": false, "explanation": "形は合うが、乗り物として読み解くのは意味が合わない。"}], "explanations": {"テキスト": "「記号が織りなすテキスト」で、文章の意味に合う。", "果物": "形は合うが、記号が織りなす果物では意味が合わない。", "天気": "形は合うが、天気として読み解くのは意味が合わない。", "乗り物": "形は合うが、乗り物として読み解くのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "テキスト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんにテキストを焼いて食べた。", "explanation": "「テキスト」は文章や文字データで、焼いて食べるものではない。"}, {"text": "テキストが降ってきたので、傘をさした。", "explanation": "「テキスト」は天気ではなく、降る物ではない。"}, {"text": "テキストに乗って、駅まで行った。", "explanation": "「テキスト」は乗り物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51906, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "テキスト", "is_correct": true, "explanation": "「テキストの文字化けを直す」で、文字データの意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気の文字化けは意味が合わない。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、果物の文字化けは意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節の文字化けは意味が合わない。"}], "explanations": {"テキスト": "「テキストの文字化けを直す」で、文字データの意味に合う。", "天気": "形は合うが、天気の文字化けは意味が合わない。", "果物": "形は合うが、果物の文字化けは意味が合わない。", "季節": "形は合うが、季節の文字化けは意味が合わない。"}, "sentence_index": 6, "correct_answer": "テキスト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "貼り付けたテキストが、庭で花を咲かせた。", "explanation": "「テキスト」は文字データで、花を咲かせる植物ではない。"}, {"text": "私は昨日、新しいテキストを着て出かけた。", "explanation": "「テキスト」は衣服ではなく、着るものではない。"}, {"text": "テキストの温度が高いので、お湯を沸かした。", "explanation": "「テキスト」は文字データで、温度を持つ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
