INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51907, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが続いているのに、とまってなくなること。", "primary_collocate": null, "pronunciation": "たえる", "ipa": "taeɾɯ", "syllable_count": 3, "sentences": [{"text": "嵐のあと、島との連絡が絶えてしまった。", "target_word": "絶えて", "complexity_tier": "T3", "furigana": "嵐[あらし]のあと、島[しま]との連絡[れんらく]が絶[た]えてしまった。", "sentence_source": "generated"}, {"text": "この店は、昼も夜もお客が絶えない。", "target_word": "絶えない", "complexity_tier": "T3", "furigana": "この店[みせ]は、昼[ひる]も夜[よる]もお客[きゃく]が絶[た]えない。", "sentence_source": "generated"}, {"text": "雪の日は、駅前の人通りが絶える。", "target_word": "絶える", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、駅前[えきまえ]の人通[ひとどお]りが絶[た]える。", "sentence_source": "generated"}, {"text": "長い間、友人からの便りが絶えていた。", "target_word": "絶えて", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、友人[ゆうじん]からの便[たよ]りが絶[た]えていた。", "sentence_source": "generated"}, {"text": "二人の間では、争いが絶えなかった。", "target_word": "絶えなかった", "complexity_tier": "T3", "furigana": "二人[ふたり]の間[あいだ]では、争[あらそ]いが絶[た]えなかった。", "sentence_source": "generated"}, {"text": "夏の渇水で、川の水が絶えた。", "target_word": "絶えた", "complexity_tier": "T3", "furigana": "夏[なつ]の渇水[かっすい]で、川[かわ]の水[みず]が絶[た]えた。", "sentence_source": "generated"}, {"text": "あの家の笑い声が絶えることはなかった。", "target_word": "絶える", "complexity_tier": "T3", "furigana": "あの家[いえ]の笑[わら]い声[ごえ]が絶[た]えることはなかった。", "sentence_source": "generated"}, {"text": "山奥の村では、水が絶えたことがない。", "target_word": "絶えた", "complexity_tier": "T3", "furigana": "山奥[やまおく]の村[むら]では、水[みず]が絶[た]えたことがない。", "sentence_source": "generated"}, {"text": "跡継ぎがいなくて、その家の血筋が絶えた。", "target_word": "絶えた", "complexity_tier": "T3", "furigana": "跡継[あとつ]ぎがいなくて、その家[いえ]の血筋[ちすじ]が絶[た]えた。", "sentence_source": "generated"}, {"text": "山の上では、携帯電話の電波が絶えることがある。", "target_word": "絶える", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]では、携帯電話[けいたいでんわ]の電波[でんぱ]が絶[た]えることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絶える", "label": "辞書形"}, {"form": "絶えた", "label": "過去形"}, {"form": "絶えない", "label": "否定形"}, {"form": "絶えて", "label": "て形"}, {"form": "絶えれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "続いていたもの（連絡・人通り・息など）がとぎれてなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51907, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絶えて", "is_correct": true, "explanation": "「絶えてしまった」の形で、続いていた連絡が途切れてなくなったことを表す。"}, {"text": "光って", "is_correct": false, "explanation": "光る動きで、連絡を主語にできず文に合わない。"}, {"text": "咲いて", "is_correct": false, "explanation": "花が開く意味で、連絡には使わない。"}, {"text": "転がって", "is_correct": false, "explanation": "物が転がる意味で、連絡の途切れを表せない。"}], "explanations": {"絶えて": "「絶えてしまった」の形で、続いていた連絡が途切れてなくなったことを表す。", "光って": "光る動きで、連絡を主語にできず文に合わない。", "咲いて": "花が開く意味で、連絡には使わない。", "転がって": "物が転がる意味で、連絡の途切れを表せない。"}, "sentence_index": 0, "correct_answer": "絶えて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厳しい寒さに絶えて、春を待った。", "explanation": "ここは〈耐える〉の意味。絶えるは続いていたものがなくなることで、苦しさを我慢する意味では使わない。"}, {"text": "机の上のコップが絶えて、テーブルがきれいになった。", "explanation": "ここは〈消える〉の意味。絶えるは続いていた流れや動きが途切れることで、物が消えることには使わない。"}, {"text": "この村では、子どもが絶えて毎年生まれている。", "explanation": "ここは〈誕生〉の意味。絶えるは続いていたものがなくなることで、新しく子どもが生じる意味は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51907, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絶える", "is_correct": true, "explanation": "「ことはなかった」の前に置き、笑い声がなくならなかったことを表す。"}, {"text": "凍る", "is_correct": false, "explanation": "寒さで固まる意味。笑い声を主語にすると合わない。"}, {"text": "焦げる", "is_correct": false, "explanation": "熱で黒くなる意味。笑い声には使わない。"}, {"text": "煮える", "is_correct": false, "explanation": "火で熱が通る意味。笑い声には使わない。"}], "explanations": {"絶える": "「ことはなかった」の前に置き、笑い声がなくならなかったことを表す。", "凍る": "寒さで固まる意味。笑い声を主語にすると合わない。", "焦げる": "熱で黒くなる意味。笑い声には使わない。", "煮える": "火で熱が通る意味。笑い声には使わない。"}, "sentence_index": 6, "correct_answer": "絶える"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山の上に、電波の塔を絶えて設置した。", "explanation": "ここは〈据え付け〉の意味。絶えるは続いていたものがなくなることで、物を取り付ける行為には使わない。"}, {"text": "新しい橋が絶えて、ついに完成した。", "explanation": "ここは〈竣工〉の意味。絶えるは続いていたものがなくなることで、工事が仕上がる意味は表さない。"}, {"text": "バスが絶えて、駅を出発した。", "explanation": "ここは〈発車〉の意味。絶えるは続いていた流れがなくなることで、乗り物が出ていく意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51907, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は、駅前の人通りが絶ている。", "corrected_sentence": "雨の日は、駅前の人通りが絶えている。", "error_description": "「絶ている」は誤り。語幹の「絶え」に「ている」を続けた「絶えている」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "絶えない", "is_correct": true, "explanation": "否定の「ない」で、お客が途切れないことを表す形。"}, {"text": "絶えて", "is_correct": false, "explanation": "て形で、後ろに続けて使う形。否定の述語としては成り立たない。"}, {"text": "絶えさせ", "is_correct": false, "explanation": "使役の語幹で、文末には置けない。否定形の「絶えない」が入る。"}, {"text": "絶えれば", "is_correct": false, "explanation": "仮定形で、「〜ば」の条件を表す形。ここでは条件節が必要ない。"}], "correct_form": "絶えない", "base_form": "絶える", "form_label": "否定形", "sentence_index": 1, "explanations": {"絶えない": "否定の「ない」で、お客が途切れないことを表す形。", "絶えて": "て形で、後ろに続けて使う形。否定の述語としては成り立たない。", "絶えさせ": "使役の語幹で、文末には置けない。否定形の「絶えない」が入る。", "絶えれば": "仮定形で、「〜ば」の条件を表す形。ここでは条件節が必要ない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51907, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の道では、人影を絶える。", "corrected_sentence": "夜の道では、人影が絶える。", "error_description": "「人影を絶える」は誤り。「絶える」は自動詞なので、主語の「人影」を「が」で示した「人影が絶える」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "絶えた", "is_correct": true, "explanation": "過去の「た」で、水が途切れなかったという経験を述べる「絶えたことがない」の形。"}, {"text": "絶えず", "is_correct": false, "explanation": "副詞の「絶えず」で、「ことがない」の前には動詞の形として続かず、文が成り立たない。"}, {"text": "絶えよう", "is_correct": false, "explanation": "意志形で、「ことがない」には続かない。経験を表す文に合わない。"}, {"text": "絶えます", "is_correct": false, "explanation": "丁寧な現在形で、過去の経験を表す文に合わない。"}], "correct_form": "絶えた", "base_form": "絶える", "form_label": "過去形", "sentence_index": 7, "explanations": {"絶えた": "過去の「た」で、水が途切れなかったという経験を述べる「絶えたことがない」の形。", "絶えず": "副詞の「絶えず」で、「ことがない」の前には動詞の形として続かず、文が成り立たない。", "絶えよう": "意志形で、「ことがない」には続かない。経験を表す文に合わない。", "絶えます": "丁寧な現在形で、過去の経験を表す文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51909, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「更新の手続き」で、更新に関する手続きを表す。"}, {"text": "を", "is_correct": false, "explanation": "「更新を手続きは」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「更新で手続きは」は意味が通らない。"}, {"text": "が", "is_correct": false, "explanation": "「更新が手続きは」は助詞が重なり、文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「更新の手続き」で、更新に関する手続きを表す。", "を": "「更新を手続きは」は文として成り立たない。", "で": "「更新で手続きは」は意味が通らない。", "が": "「更新が手続きは」は助詞が重なり、文として成り立たない。"}, "error_tags": {"を": "object", "で": "means", "が": "subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "維持", "is_correct": true, "explanation": "新しく変える更新に対し、そのまま保つ維持は反対の関係。"}, {"text": "変更", "is_correct": false, "explanation": "変えることで、更新に近く反対ではない。"}, {"text": "追加", "is_correct": false, "explanation": "足すことで、更新の反対ではない。"}, {"text": "作成", "is_correct": false, "explanation": "新しく作ることで、更新の反対ではない。"}], "correct_answer": "維持", "explanations": {"維持": "新しく変える更新に対し、そのまま保つ維持は反対の関係。", "変更": "変えることで、更新に近く反対ではない。", "追加": "足すことで、更新の反対ではない。", "作成": "新しく作ることで、更新の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51909, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「更新した地図を見た」で、見る対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「地図に、みんなで見た」は対象の示し方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「地図と、みんなで見た」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「地図の、みんなで見た」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「更新した地図を見た」で、見る対象を表す。", "に": "「地図に、みんなで見た」は対象の示し方として不自然。", "と": "「地図と、みんなで見た」は文として成り立たない。", "の": "「地図の、みんなで見た」は文として成り立たない。"}, "error_tags": {"に": "location", "と": "comitative", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "据え置き", "is_correct": true, "explanation": "新しく変える更新に対し、そのままにする据え置きは反対の関係。"}, {"text": "改善", "is_correct": false, "explanation": "よりよく変えることで、更新に近く反対ではない。"}, {"text": "交換", "is_correct": false, "explanation": "取りかえることで、更新に近く反対ではない。"}, {"text": "削除", "is_correct": false, "explanation": "消すことで、更新の反対ではない。"}], "correct_answer": "据え置き", "explanations": {"据え置き": "新しく変える更新に対し、そのままにする据え置きは反対の関係。", "改善": "よりよく変えることで、更新に近く反対ではない。", "交換": "取りかえることで、更新に近く反対ではない。", "削除": "消すことで、更新の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
