INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51910, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "古い情報や状態を新しいものに変えること。", "primary_collocate": null, "pronunciation": "こうしん", "ipa": "koːɕiɴ", "syllable_count": 4, "sentences": [{"text": "結果として、建築は静的な物体ではなく、見る者によって絶えず意味が更新される開かれた場として再定義されるのです。", "target_word": "更新", "complexity_tier": "T6", "furigana": "結果[けっか]として、建築[けんちく]は静的[せいてき]な物体[ぶったい]ではなく、見[み]る者[もの]によって絶[た]えず意味[いみ]が更新[こうしん]される開[ひら]かれた場[ば]として再定義[さいていぎ]されるのです。", "sentence_source": "mined"}, {"text": "ホームページを毎日更新している。", "target_word": "更新", "complexity_tier": "T3", "furigana": "ホームページを毎日[まいにち]更新[こうしん]している。", "sentence_source": "generated"}, {"text": "免許の更新に行ってきた。", "target_word": "更新", "complexity_tier": "T2", "furigana": "免許[めんきょ]の更新[こうしん]に行[い]ってきた。", "sentence_source": "generated"}, {"text": "ソフトを更新すると、動きが速くなった。", "target_word": "更新", "complexity_tier": "T3", "furigana": "ソフトを更新[こうしん]すると、動[うご]きが速[はや]くなった。", "sentence_source": "generated"}, {"text": "古いデータを新しい情報に更新する。", "target_word": "更新", "complexity_tier": "T3", "furigana": "古[ふる]いデータを新[あたら]しい情報[じょうほう]に更新[こうしん]する。", "sentence_source": "generated"}, {"text": "パスワードを更新してください。", "target_word": "更新", "complexity_tier": "T2", "furigana": "パスワードを更新[こうしん]してください。", "sentence_source": "generated"}, {"text": "更新された記事は、上に表示される。", "target_word": "更新", "complexity_tier": "T3", "furigana": "更新[こうしん]された記事[きじ]は、上[うえ]に表示[ひょうじ]される。", "sentence_source": "generated"}, {"text": "ブログの更新が止まって、一年になる。", "target_word": "更新", "complexity_tier": "T3", "furigana": "ブログの更新[こうしん]が止[と]まって、一年[いちねん]になる。", "sentence_source": "generated"}, {"text": "契約の更新を忘れると、サービスが使えなくなる。", "target_word": "更新", "complexity_tier": "T4", "furigana": "契約[けいやく]の更新[こうしん]を忘[わす]れると、サービスが使[つか]えなくなる。", "sentence_source": "generated"}, {"text": "記録を更新した選手が、笑顔で手を振った。", "target_word": "更新", "complexity_tier": "T4", "furigana": "記録[きろく]を更新[こうしん]した選手[せんしゅ]が、笑顔[えがお]で手[て]を振[ふ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "更新する", "label": "活用"}, {"form": "更新される", "label": "活用"}, {"form": "更新日", "label": "派生"}, {"form": "自動更新", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 古い情報や状態を新しく変えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47a9a169-f8ce-40f2-ac03-946696cdfb23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51910, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "更新", "is_correct": true, "explanation": "見出し語そのもの（こうしん）。"}, {"text": "通信", "is_correct": false, "explanation": "つうしん。1拍目の「こ」が「つ」に変わる。"}, {"text": "方針", "is_correct": false, "explanation": "ほうしん。1拍目の「こ」が「ほ」に変わる。"}, {"text": "降参", "is_correct": false, "explanation": "こうさん。3拍目の「し」が「さ」に変わる。"}, {"text": "公式", "is_correct": false, "explanation": "こうしき。4拍目の「ん」が「き」に変わる。"}], "explanations": {"更新": "見出し語そのもの（こうしん）。", "通信": "つうしん。1拍目の「こ」が「つ」に変わる。", "方針": "ほうしん。1拍目の「こ」が「ほ」に変わる。", "降参": "こうさん。3拍目の「し」が「さ」に変わる。", "公式": "こうしき。4拍目の「ん」が「き」に変わる。"}, "sentence_index": null, "correct_answer": "更新"}, "level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "「意味が更新される」で意味が合う。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、意味が散歩されるのは意味が合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、意味が出発されるのは意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、意味が卒業されるのは意味が合わない。"}], "explanations": {"更新": "「意味が更新される」で意味が合う。", "散歩": "形は合うが、意味が散歩されるのは意味が合わない。", "出発": "形は合うが、意味が出発されるのは意味が合わない。", "卒業": "形は合うが、意味が卒業されるのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、公園で更新してから会社へ行く。", "explanation": "更新は古いものを新しくすることで、運動や散歩の意味では使えない。"}, {"text": "このスープは更新が強くて、とても辛い。", "explanation": "更新は味の強さを表さず、味の説明に使えない。"}, {"text": "弟は更新を食べて、元気になった。", "explanation": "更新は動作・手続きの名前で、食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings =