INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51910, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "更新", "is_correct": true, "explanation": "見出し語そのもの（こうしん）。"}, {"text": "盲信", "is_correct": false, "explanation": "もうしん。1拍目の「こ」が「も」に変わる。"}, {"text": "降臨", "is_correct": false, "explanation": "こうりん。3拍目の「し」が「り」に変わる。"}, {"text": "公民", "is_correct": false, "explanation": "こうみん。3拍目の「し」が「み」に変わる。"}, {"text": "光線", "is_correct": false, "explanation": "こうせん。3拍目の「し」が「せ」に変わる。"}], "explanations": {"更新": "見出し語そのもの（こうしん）。", "盲信": "もうしん。1拍目の「こ」が「も」に変わる。", "降臨": "こうりん。3拍目の「し」が「り」に変わる。", "公民": "こうみん。3拍目の「し」が「み」に変わる。", "光線": "こうせん。3拍目の「し」が「せ」に変わる。"}, "sentence_index": null, "correct_answer": "更新"}, "level_3": {"options": [{"text": "更新", "is_correct": true, "explanation": "「更新された記事」で意味が合う。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、卒業された記事は意味が合わない。"}, {"text": "散歩", "is_correct": false, "explanation": "形は合うが、散歩された記事は意味が合わない。"}, {"text": "出発", "is_correct": false, "explanation": "形は合うが、出発された記事は意味が合わない。"}], "explanations": {"更新": "「更新された記事」で意味が合う。", "卒業": "形は合うが、卒業された記事は意味が合わない。", "散歩": "形は合うが、散歩された記事は意味が合わない。", "出発": "形は合うが、出発された記事は意味が合わない。"}, "sentence_index": 6, "correct_answer": "更新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冷蔵庫の中の牛乳が更新して、飲めなくなった。", "explanation": "更新は新しくする意味で、牛乳が傷む意味では使えない。"}, {"text": "雨の日は、傘を更新して歩くのが好きだ。", "explanation": "更新は傘を差す動作を表さず、意味が合わない。"}, {"text": "子どもが更新して、大きな声で笑った。", "explanation": "更新は人の笑う動作を表さず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2197b1bc-1dbc-4d2e-8a3d-935419e745a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.vali