INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51911, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "行く時刻を表すので「に」です。"}, {"text": "を", "is_correct": false, "explanation": "「午後を買い物へ行く」は文法的に誤りです。"}, {"text": "が", "is_correct": false, "explanation": "「午後が買い物へ行く」は主語が合わず誤りです。"}, {"text": "と", "is_correct": false, "explanation": "「午後と買い物へ行く」は意味が通りません。"}], "correct_answer": "に", "explanations": {"に": "行く時刻を表すので「に」です。", "を": "「午後を買い物へ行く」は文法的に誤りです。", "が": "「午後が買い物へ行く」は主語が合わず誤りです。", "と": "「午後と買い物へ行く」は意味が通りません。"}, "error_tags": {"を": "object", "が": "subject", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "午前", "is_correct": true, "explanation": "昼ごはんの前の時間で、午後の反対です。"}, {"text": "夕方", "is_correct": false, "explanation": "午後の一部で、反対ではありません。"}, {"text": "今日", "is_correct": false, "explanation": "日を表す語で、午後の反対ではありません。"}, {"text": "日曜日", "is_correct": false, "explanation": "曜日を表す語で、午後の反対ではありません。"}], "correct_answer": "午前", "explanations": {"午前": "昼ごはんの前の時間で、午後の反対です。", "夕方": "午後の一部で、反対ではありません。", "今日": "日を表す語で、午後の反対ではありません。", "日曜日": "曜日を表す語で、午後の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
