INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51911, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お昼ごはんを食べたあとの時間のことです。", "primary_collocate": null, "pronunciation": "ごご", "ipa": "ɡoɡo", "syllable_count": 2, "sentences": [{"text": "午後は休みだ。", "target_word": "午後", "complexity_tier": "T1", "furigana": "午後[ごご]は休[やす]みだ。", "sentence_source": "generated"}, {"text": "午後に買い物へ行く。", "target_word": "午後", "complexity_tier": "T1", "furigana": "午後[ごご]に買い物[かいもの]へ行[い]く。", "sentence_source": "generated"}, {"text": "午後、母と公園に行きました。", "target_word": "午後", "complexity_tier": "T2", "furigana": "午後[ごご]、母[はは]と公園[こうえん]に行[い]きました。", "sentence_source": "generated"}, {"text": "昼ごはんの後の午後は、少し眠い。", "target_word": "午後", "complexity_tier": "T3", "furigana": "昼[ひる]ごはんの後[あと]の午後[ごご]は、少[すこ]し眠[ねむ]い。", "sentence_source": "generated"}, {"text": "今日の午後は暑かったです。", "target_word": "午後", "complexity_tier": "T2", "furigana": "今日[きょう]の午後[ごご]は暑[あつ]かったです。", "sentence_source": "generated"}, {"text": "午後から雨がふりました。", "target_word": "午後", "complexity_tier": "T2", "furigana": "午後[ごご]から雨[あめ]がふりました。", "sentence_source": "generated"}, {"text": "午後になると、子どもたちが帰ってくる。", "target_word": "午後", "complexity_tier": "T3", "furigana": "午後[ごご]になると、子[こ]どもたちが帰[かえ]ってくる。", "sentence_source": "generated"}, {"text": "午後の時間に、宿題をします。", "target_word": "午後", "complexity_tier": "T2", "furigana": "午後[ごご]の時間[じかん]に、宿題[しゅくだい]をします。", "sentence_source": "generated"}, {"text": "午後までに、手紙を書いてしまった。", "target_word": "午後", "complexity_tier": "T3", "furigana": "午後[ごご]までに、手紙[てがみ]を書[か]いてしまった。", "sentence_source": "generated"}, {"text": "日曜日の午後、友だちと映画を見た。", "target_word": "午後", "complexity_tier": "T3", "furigana": "日曜日[にちようび]の午後[ごご]、友[とも]だちと映画[えいが]を見[み]た。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 昼ごはんのあとの時間", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
