INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51912, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "正午から夕方までの時間帯。午前の後の時間。", "primary_collocate": null, "pronunciation": "ごご", "ipa": "ɡoɡo", "syllable_count": 2, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り口で一人の少年が手作りのレモネードを販売していた。", "target_word": "午後", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り口[ぐち]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "generated"}, {"text": "午後は雨だ。", "target_word": "午後", "complexity_tier": "T1", "furigana": "午後[ごご]は雨[あめ]だ。", "sentence_source": "generated"}, {"text": "午後に友達と会います。", "target_word": "午後", "complexity_tier": "T2", "furigana": "午後[ごご]に友達[ともだち]と会[あ]います。", "sentence_source": "generated"}, {"text": "午後、公園で本を読んだ。", "target_word": "午後", "complexity_tier": "T2", "furigana": "午後[ごご]、公園[こうえん]で本[ほん]を読[よ]んだ。", "sentence_source": "generated"}, {"text": "明日の午後、病院へ行く予定だ。", "target_word": "午後", "complexity_tier": "T3", "furigana": "明日[あした]の午後[ごご]、病院[びょういん]へ行[い]く予定[よてい]だ。", "sentence_source": "generated"}, {"text": "午後から天気が悪くなるそうだ。", "target_word": "午後", "complexity_tier": "T3", "furigana": "午後[ごご]から天気[てんき]が悪[わる]くなるそうだ。", "sentence_source": "generated"}, {"text": "午後の授業は眠くなりやすい。", "target_word": "午後", "complexity_tier": "T3", "furigana": "午後[ごご]の授業[じゅぎょう]は眠[ねむ]くなりやすい。", "sentence_source": "generated"}, {"text": "毎日、午後になると、猫が窓のそばで寝る。", "target_word": "午後", "complexity_tier": "T3", "furigana": "毎日[まいにち]、午後[ごご]になると、猫[ねこ]が窓[まど]のそばで寝[ね]る。", "sentence_source": "generated"}, {"text": "午後までに報告書を出さなければならない。", "target_word": "午後", "complexity_tier": "T4", "furigana": "午後[ごご]までに報告書[ほうこくしょ]を出[だ]さなければならない。", "sentence_source": "generated"}, {"text": "午前より午後のほうが店は混んでいる。", "target_word": "午後", "complexity_tier": "T3", "furigana": "午前[ごぜん]より午後[ごご]のほうが店[みせ]は混[こ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 正午から夕方までの時間帯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e809459e-112d-418e-b65d-24a3fcd1f3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51912, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "午後", "is_correct": true, "explanation": "見出し語の「ごご」です。"}, {"text": "此処", "is_correct": false, "explanation": "「ここ」で、最初のごがこに変わっています。"}, {"text": "胡麻", "is_correct": false, "explanation": "「ごま」で、最後のごがまに変わっています。"}, {"text": "ごみ", "is_correct": false, "explanation": "「ごみ」で、最後のごがみに変わっています。"}, {"text": "頃", "is_correct": false, "explanation": "「ごろ」で、最後のごがろに変わっています。"}], "explanations": {"午後": "見出し語の「ごご」です。", "此処": "「ここ」で、最初のごがこに変わっています。", "胡麻": "「ごま」で、最後のごがまに変わっています。", "ごみ": "「ごみ」で、最後のごがみに変わっています。", "頃": "「ごろ」で、最後のごがろに変わっています。"}, "sentence_index": null, "correct_answer": "午後"}, "level_3": {"options": [{"text": "午後", "is_correct": true, "explanation": "夏の暑い時間帯を表し、文意に合います。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが、辞書は時間ではなく意味が合わない。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜は時間ではなく意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図は時間ではなく意味が合わない。"}], "explanations": {"午後": "夏の暑い時間帯を表し、文意に合います。", "辞書": "形は合うが、辞書は時間ではなく意味が合わない。", "野菜": "形は合うが、野菜は時間ではなく意味が合わない。", "地図": "形は合うが、地図は時間ではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "午後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "午後を机の上に置いた。", "explanation": "午後は時間帯なので、物のように置けません。"}, {"text": "午後の色は赤くて丸い。", "explanation": "午後は時間帯で、形や色を持つ物ではありません。"}, {"text": "午後に乗って駅へ行った。", "explanation": "午後は乗り物ではないので「乗る」とは使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '861d1c7d-3753-4885-8f4d-62b03829a50d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
