INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51913, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "気温（きおん）が高（たか）いことです。", "primary_collocate": null, "pronunciation": "あつい", "ipa": "atsɯi", "syllable_count": 3, "sentences": [{"text": "夏は暑い。", "target_word": "暑い", "complexity_tier": "T1", "furigana": "夏[なつ]は暑[あつ]い。", "sentence_source": "generated"}, {"text": "今日は暑くない。", "target_word": "暑く", "complexity_tier": "T1", "furigana": "今日[きょう]は暑[あつ]くない。", "sentence_source": "generated"}, {"text": "外はとても暑いですね。", "target_word": "暑い", "complexity_tier": "T2", "furigana": "外[そと]はとても暑[あつ]いですね。", "sentence_source": "generated"}, {"text": "昨日は暑かったです。", "target_word": "暑かった", "complexity_tier": "T2", "furigana": "昨日[きのう]は暑[あつ]かったです。", "sentence_source": "generated"}, {"text": "暑い部屋で勉強しています。", "target_word": "暑い", "complexity_tier": "T3", "furigana": "暑[あつ]い部屋[へや]で勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "夜になっても暑くて、よく眠れない。", "target_word": "暑くて", "complexity_tier": "T3", "furigana": "夜[よる]になっても暑[あつ]くて、よく眠[ねむ]れない。", "sentence_source": "generated"}, {"text": "こんなに暑いと、アイスが食べたくなる。", "target_word": "暑い", "complexity_tier": "T4", "furigana": "こんなに暑[あつ]いと、アイスが食[た]べたくなる。", "sentence_source": "generated"}, {"text": "暑ければ、上着を脱いでもいいですよ。", "target_word": "暑ければ", "complexity_tier": "T4", "furigana": "暑[あつ]ければ、上着[うわぎ]を脱[ぬ]いでもいいですよ。", "sentence_source": "generated"}, {"text": "暑さのせいで、犬も元気がありません。", "target_word": "暑さ", "complexity_tier": "T3", "furigana": "暑[あつ]さのせいで、犬[いぬ]も元気[げんき]がありません。", "sentence_source": "generated"}, {"text": "今年の夏は去年より暑い気がします。", "target_word": "暑い", "complexity_tier": "T3", "furigana": "今年[ことし]の夏[なつ]は去年[きょねん]より暑[あつ]い気[き]がします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暑かった", "label": "活用"}, {"form": "暑くない", "label": "活用"}, {"form": "暑さ", "label": "派生"}, {"form": "暑がる", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 気温が高くて熱く感じること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51913, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暑い", "is_correct": true, "explanation": "見出し語「あつい」そのもの。"}, {"text": "甘い", "is_correct": false, "explanation": "「あまい」。つがまに変わる。"}, {"text": "浅い", "is_correct": false, "explanation": "「あさい」。つがさに変わる。"}, {"text": "赤い", "is_correct": false, "explanation": "「あかい」。つがかに変わる。"}], "explanations": {"暑い": "見出し語「あつい」そのもの。", "甘い": "「あまい」。つがまに変わる。", "浅い": "「あさい」。つがさに変わる。", "赤い": "「あかい」。つがかに変わる。"}, "sentence_index": null, "correct_answer": "暑い"}, "level_3": {"options": [{"text": "暑い", "is_correct": true, "explanation": "夏の気温が高いことを表す。"}, {"text": "甘い", "is_correct": false, "explanation": "形は合うが、「夏は甘い」では意味が合わない。"}, {"text": "重い", "is_correct": false, "explanation": "形は合うが、「夏は重い」では意味が合わない。"}, {"text": "狭い", "is_correct": false, "explanation": "形は合うが、「夏は狭い」では意味が合わない。"}], "explanations": {"暑い": "夏の気温が高いことを表す。", "甘い": "形は合うが、「夏は甘い」では意味が合わない。", "重い": "形は合うが、「夏は重い」では意味が合わない。", "狭い": "形は合うが、「夏は狭い」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "暑い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お風呂のお湯が暑かったので、水を足した。", "explanation": "お湯の温度は「熱い」。「暑い」は気温なので誤り。"}, {"text": "試合は最後まで暑い戦いになった。", "explanation": "白熱した戦いは「熱い」。「暑い」は気温の高さなので誤り。"}, {"text": "雪の朝は暑くて、手袋をした。", "explanation": "雪の朝に手袋をする場面で「暑い」は意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51913, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "暑い", "is_correct": true, "explanation": "見出し語「あつい」そのもの。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」。つがおに変わる。"}, {"text": "荒い", "is_correct": false, "explanation": "「あらい」。つがらに変わる。"}, {"text": "値", "is_correct": false, "explanation": "「あたい」。つがたに変わる。"}], "explanations": {"暑い": "見出し語「あつい」そのもの。", "青い": "「あおい」。つがおに変わる。", "荒い": "「あらい」。つがらに変わる。", "値": "「あたい」。つがたに変わる。"}, "sentence_index": null, "correct_answer": "暑い"}, "level_3": {"options": [{"text": "暑い", "is_correct": true, "explanation": "暑いとアイスが食べたくなる、という自然な流れ。"}, {"text": "重い", "is_correct": false, "explanation": "形は合うが、「重いとアイスが食べたくなる」は意味が合わない。"}, {"text": "狭い", "is_correct": false, "explanation": "形は合うが、「狭いとアイスが食べたくなる」は意味が合わない。"}, {"text": "痛い", "is_correct": false, "explanation": "形は合うが、「痛いとアイスが食べたくなる」は意味が合わない。"}], "explanations": {"暑い": "暑いとアイスが食べたくなる、という自然な流れ。", "重い": "形は合うが、「重いとアイスが食べたくなる」は意味が合わない。", "狭い": "形は合うが、「狭いとアイスが食べたくなる」は意味が合わない。", "痛い": "形は合うが、「痛いとアイスが食べたくなる」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "暑い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この鉄板は暑いから、触らないでね。", "explanation": "鉄板など物の温度は「熱い」。「暑い」は気温なので誤り。"}, {"text": "彼は暑い心を持った教師だ。", "explanation": "情熱的な心は「熱い」。「暑い」は気温の高さなので誤り。"}, {"text": "冬の夜は暑いので、ストーブをつけた。", "explanation": "冬の夜にストーブをつける場面で「暑い」は意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
