INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51914, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "気温が高く、暑さを感じるさま。夏の天候などに用いる。", "primary_collocate": null, "pronunciation": "あつい", "ipa": "atsɯi", "syllable_count": 3, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り口で一人の少年が手作りのレモネードを販売していた。", "target_word": "暑さ", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り口[ぐち]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "generated"}, {"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "暑さ", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "今日はとても暑いです。", "target_word": "暑い", "complexity_tier": "T2", "furigana": "今日[きょう]はとても暑[あつ]いです。", "sentence_source": "generated"}, {"text": "暑い日は水をたくさん飲む。", "target_word": "暑い", "complexity_tier": "T2", "furigana": "暑[あつ]い日[ひ]は水[みず]をたくさん飲[の]む。", "sentence_source": "generated"}, {"text": "昨日は暑かったので、早く寝た。", "target_word": "暑かった", "complexity_tier": "T3", "furigana": "昨日[きのう]は暑[あつ]かったので、早[はや]く寝[ね]た。", "sentence_source": "generated"}, {"text": "夏の東京は暑くて、外に出たくない。", "target_word": "暑くて", "complexity_tier": "T3", "furigana": "夏[なつ]の東京[とうきょう]は暑[あつ]くて、外[そと]に出[で]たくない。", "sentence_source": "generated"}, {"text": "暑くなる前に、散歩に行こう。", "target_word": "暑く", "complexity_tier": "T3", "furigana": "暑[あつ]くなる前[まえ]に、散歩[さんぽ]に行[い]こう。", "sentence_source": "generated"}, {"text": "部屋が暑すぎて、窓を開けました。", "target_word": "暑すぎて", "complexity_tier": "T3", "furigana": "部屋[へや]が暑[あつ]すぎて、窓[まど]を開[あ]けました。", "sentence_source": "generated"}, {"text": "暑ければエアコンをつけてもいいですよ。", "target_word": "暑ければ", "complexity_tier": "T4", "furigana": "暑[あつ]ければエアコンをつけてもいいですよ。", "sentence_source": "generated"}, {"text": "暑い中、子どもたちは一日中外で遊んだ。", "target_word": "暑い", "complexity_tier": "T4", "furigana": "暑[あつ]い中[なか]、子[こ]どもたちは一日中[いちにちじゅう]外[そと]で遊[あそ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "暑かった", "label": "活用"}, {"form": "暑くない", "label": "活用"}, {"form": "暑さ", "label": "派生"}, {"form": "暑がる", "label": "派生"}], "register": "plain", "sense_fingerprint": "形容詞 | 夏の気温が高く不快に感じる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 中外 (Zipf 2.44)']::text[], '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51914, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暑い", "is_correct": true, "explanation": "見出し語「あつい」そのもの。"}, {"text": "甘い", "is_correct": false, "explanation": "「あまい」。つがまに変わる。"}, {"text": "浅い", "is_correct": false, "explanation": "「あさい」。つがさに変わる。"}, {"text": "赤い", "is_correct": false, "explanation": "「あかい」。つがかに変わる。"}], "explanations": {"暑い": "見出し語「あつい」そのもの。", "甘い": "「あまい」。つがまに変わる。", "浅い": "「あさい」。つがさに変わる。", "赤い": "「あかい」。つがかに変わる。"}, "sentence_index": null, "correct_answer": "暑い"}, "level_3": {"options": [{"text": "暑さ", "is_correct": true, "explanation": "夏の午後に続く記録的な気温の高さを表す。"}, {"text": "甘さ", "is_correct": false, "explanation": "形は合うが、「記録的な甘さが続く夏の午後」では意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、「記録的な重さが続く」は意味が合わない。"}, {"text": "広さ", "is_correct": false, "explanation": "形は合うが、「記録的な広さが続く」は意味が合わない。"}], "explanations": {"暑さ": "夏の午後に続く記録的な気温の高さを表す。", "甘さ": "形は合うが、「記録的な甘さが続く夏の午後」では意味が合わない。", "重さ": "形は合うが、「記録的な重さが続く」は意味が合わない。", "広さ": "形は合うが、「記録的な広さが続く」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "暑さ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑いお茶を飲むと体が温まる。", "explanation": "飲み物などの温度が高いことは「熱い」を使う。「暑い」は気温に使うので誤り。"}, {"text": "会議で暑い議論が交わされた。", "explanation": "議論が白熱するのは「熱い」。「暑い」は気温の高さなので誤り。"}, {"text": "雪が降った冬の朝は、とても暑い日だった。", "explanation": "雪の降る冬の朝に「暑い」は意味が合わない。暑いのは夏などの高い気温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51914, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "暑い", "is_correct": true, "explanation": "見出し語「あつい」そのもの。"}, {"text": "青い", "is_correct": false, "explanation": "「あおい」。つがおに変わる。"}, {"text": "荒い", "is_correct": false, "explanation": "「あらい」。つがらに変わる。"}, {"text": "値", "is_correct": false, "explanation": "「あたい」。つがたに変わる。"}], "explanations": {"暑い": "見出し語「あつい」そのもの。", "青い": "「あおい」。つがおに変わる。", "荒い": "「あらい」。つがらに変わる。", "値": "「あたい」。つがたに変わる。"}, "sentence_index": null, "correct_answer": "暑い"}, "level_3": {"options": [{"text": "暑く", "is_correct": true, "explanation": "「暑くなる前に」で、気温が上がる前の意味になる。"}, {"text": "甘く", "is_correct": false, "explanation": "形は合うが、散歩の前に「甘くなる」は意味が合わない。"}, {"text": "重く", "is_correct": false, "explanation": "形は合うが、散歩の前に「重くなる」は意味が合わない。"}, {"text": "狭く", "is_correct": false, "explanation": "形は合うが、散歩の前に「狭くなる」は意味が合わない。"}], "explanations": {"暑く": "「暑くなる前に」で、気温が上がる前の意味になる。", "甘く": "形は合うが、散歩の前に「甘くなる」は意味が合わない。", "重く": "形は合うが、散歩の前に「重くなる」は意味が合わない。", "狭く": "形は合うが、散歩の前に「狭くなる」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "暑く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑い鍋にうどんを入れて煮込んだ。", "explanation": "鍋など物の温度は「熱い」。「暑い」は気温なので誤り。"}, {"text": "二人は暑い友情で結ばれていた。", "explanation": "情熱的な友情は「熱い」。「暑い」は気温の高さなので誤り。"}, {"text": "雪が積もった暑い朝、コートを着て出かけた。", "explanation": "雪とコートの場面に「暑い」は意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51914, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日は暑いかったので、早く寝た。", "corrected_sentence": "昨日は暑かったので、早く寝た。", "error_description": "「暑い」の過去形は「暑かった」。「暑いかった」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "暑さ", "is_correct": true, "explanation": "「暑さに疲れた」と名詞形になり、助詞「に」につながる。"}, {"text": "暑く", "is_correct": false, "explanation": "連用形は「に」の前に置けない。"}, {"text": "暑かった", "is_correct": false, "explanation": "過去形は「に疲れた人々」の形に合わない。"}, {"text": "暑ければ", "is_correct": false, "explanation": "仮定形は助詞「に」につながらない。"}], "correct_form": "暑さ", "base_form": "暑い", "form_label": "派生（名詞形）", "sentence_index": 1, "explanations": {"暑さ": "「暑さに疲れた」と名詞形になり、助詞「に」につながる。", "暑く": "連用形は「に」の前に置けない。", "暑かった": "過去形は「に疲れた人々」の形に合わない。", "暑ければ": "仮定形は助詞「に」につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51914, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今日はとても暑さです。", "corrected_sentence": "今日はとても暑いです。", "error_description": "「とても」が修飾するのは形容詞「暑い」。名詞形「暑さ」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "暑すぎて", "is_correct": true, "explanation": "「暑すぎて」と理由を述べ、「窓を開けました」につながる。"}, {"text": "暑さ", "is_correct": false, "explanation": "名詞形では「窓を開けました」への原因表現にならない。"}, {"text": "暑ければ", "is_correct": false, "explanation": "仮定形では過去の事実「開けました」と合わない。"}, {"text": "暑がる", "is_correct": false, "explanation": "「暑がる」は人の様子を表す動詞で、部屋の描写に合わない。"}], "correct_form": "暑すぎて", "base_form": "暑い", "form_label": "活用（すぎる＋て形）", "sentence_index": 7, "explanations": {"暑すぎて": "「暑すぎて」と理由を述べ、「窓を開けました」につながる。", "暑さ": "名詞形では「窓を開けました」への原因表現にならない。", "暑ければ": "仮定形では過去の事実「開けました」と合わない。", "暑がる": "「暑がる」は人の様子を表す動詞で、部屋の描写に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「手作りの」で、手作りを名詞として後ろの「マフラー」を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「手作りを」は後ろの「マフラー」とつながらず、文の目的語にならない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や相手を示す。「手作りに」は不自然で、修飾の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「手作りへマフラー」は方向として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「手作りの」で、手作りを名詞として後ろの「マフラー」を修飾する「の」。", "を": "「手作りを」は後ろの「マフラー」とつながらず、文の目的語にならない。", "に": "「に」は時点や相手を示す。「手作りに」は不自然で、修飾の関係が成り立たない。", "へ": "「へ」は方向を示す。「手作りへマフラー」は方向として成り立たない。"}, "error_tags": {"を": "目的", "に": "時点・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「手作りのほう」で、手作りを名詞として後ろの「ほう」を修飾する「の」。"}, {"text": "が", "is_correct": false, "explanation": "「手作りがほうが」は主語の形になり、「ほうが」の前に入らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すが、「手作りでほうが」は「ほうが」とつながらない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並べる相手を示すが、「手作りとほうが」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「手作りのほう」で、手作りを名詞として後ろの「ほう」を修飾する「の」。", "が": "「手作りがほうが」は主語の形になり、「ほうが」の前に入らない。", "で": "「で」は手段を示すが、「手作りでほうが」は「ほうが」とつながらない。", "と": "「と」は並べる相手を示すが、「手作りとほうが」では文が成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "相手・並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分で作ったもの。", "primary_collocate": null, "pronunciation": "てづくり", "ipa": "tedzɯkɯɾi", "syllable_count": 4, "sentences": [{"text": "母の手作りのケーキは、お店の味より好きだ。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "母[はは]の手作[てづく]りのケーキは、お店[みせ]の味[あじ]より好[す]きだ。", "sentence_source": "generated"}, {"text": "誕生日に、手作りのマフラーをもらった。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "誕生日[たんじょうび]に、手作[てづく]りのマフラーをもらった。", "sentence_source": "generated"}, {"text": "このジャムは全部手作りで、保存料は入っていない。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "このジャムは全部[ぜんぶ]手作[てづく]りで、保存料[ほぞんりょう]は入[はい]っていない。", "sentence_source": "generated"}, {"text": "手作りの人形は、一つずつ顔が少し違う。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "手作[てづく]りの人形[にんぎょう]は、一[ひと]つずつ顔[かお]が少[すこ]し違[ちが]う。", "sentence_source": "generated"}, {"text": "手作りだから、形はあまりきれいではないよ。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "手作[てづく]りだから、形[かたち]はあまりきれいではないよ。", "sentence_source": "generated"}, {"text": "妹は手作りのカードに、短い手紙を書いた。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "妹[いもうと]は手作[てづく]りのカードに、短[みじか]い手紙[てがみ]を書[か]いた。", "sentence_source": "generated"}, {"text": "市場では、手作りのパンが毎朝売られている。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "市場[いちば]では、手作[てづく]りのパンが毎朝[まいあさ]売[う]られている。", "sentence_source": "generated"}, {"text": "買ったものより、手作りのほうが心がこもる。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "買[か]ったものより、手作[てづく]りのほうが心[こころ]がこもる。", "sentence_source": "generated"}, {"text": "彼は手作りの本棚を、自慢げに見せてくれた。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "彼[かれ]は手作[てづく]りの本棚[ほんだな]を、自慢[じまん]げに見[み]せてくれた。", "sentence_source": "generated"}, {"text": "手作りの弁当を持って、公園へ遊びに行った。", "target_word": "手作り", "complexity_tier": "T3", "furigana": "手作[てづく]りの弁当[べんとう]を持[も]って、公園[こうえん]へ遊[あそ]びに行[い]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手作り", "label": "基本形"}, {"form": "手作りの", "label": "連体形"}, {"form": "手作りだ", "label": "断定形"}, {"form": "手作りで", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "店で買ったものではなく、自分の手で作ったもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手作り", "is_correct": true, "explanation": "「母の手作りのケーキ」で、ケーキを作った人を示す修飾語になる。"}, {"text": "手紙", "is_correct": false, "explanation": "書いた文章の意味。ケーキを修飾する文にならない。"}, {"text": "写真", "is_correct": false, "explanation": "写した画像の意味。ケーキを修飾する文に合わない。"}, {"text": "花束", "is_correct": false, "explanation": "花をまとめた束の意味。ケーキを修飾する意味にならない。"}], "explanations": {"手作り": "「母の手作りのケーキ」で、ケーキを作った人を示す修飾語になる。", "手紙": "書いた文章の意味。ケーキを修飾する文にならない。", "写真": "写した画像の意味。ケーキを修飾する文に合わない。", "花束": "花をまとめた束の意味。ケーキを修飾する意味にならない。"}, "sentence_index": 0, "correct_answer": "手作り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "機械が一度に千個のケーキを作ったが、どれも手作りだ。", "explanation": "ここは〈機械製〉の意味。手作りは自分の手で作ったものを指し、機械が作った品には使わない。"}, {"text": "店で買ったこのマフラーは既製品だが、手作りだ。", "explanation": "ここは〈市販品〉の意味。手作りは自分で作ったものを指し、店で売られている品物には使わない。"}, {"text": "機械が自動で組み立てた部品は、どれも手作りの製品だ。", "explanation": "ここは〈工場製〉の意味。機械で組み立てた部品は手作りとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手作り", "is_correct": true, "explanation": "「市場では手作りのパン」で、パンを作った方法を示す修飾語になる。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う小さな紙の意味。パンを修飾できない。"}, {"text": "地図", "is_correct": false, "explanation": "場所を示す図の意味。パンを修飾する文に合わない。"}, {"text": "傘", "is_correct": false, "explanation": "雨具の意味。パンを修飾する文に合わない。"}], "explanations": {"手作り": "「市場では手作りのパン」で、パンを作った方法を示す修飾語になる。", "切手": "郵便に使う小さな紙の意味。パンを修飾できない。", "地図": "場所を示す図の意味。パンを修飾する文に合わない。", "傘": "雨具の意味。パンを修飾する文に合わない。"}, "sentence_index": 6, "correct_answer": "手作り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "業者に頼んで、お弁当を手作りで作らせた。", "explanation": "ここは〈外注〉の意味。手作りは本人が作ることで、人に頼んだ作業には使わない。"}, {"text": "店で売っている既製のケーキは、どれも手作りだ。", "explanation": "ここは〈市販品〉の意味。手作りは自分で作ったものを指し、店で売られている既製品には使わない。"}, {"text": "自動機械が作った野菜は、どれも手作りの品だ。", "explanation": "ここは〈自動化〉の意味。機械が作ったものは手作りとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達は手作るのクッキーを焼いた。", "corrected_sentence": "友達は手作りのクッキーを焼いた。", "error_description": "「手作る」は動詞で、名詞の「手作り」を後ろの「の」で修飾する形にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51915, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近所の店では、手作りがパンが毎朝売られている。", "corrected_sentence": "近所の店では、手作りのパンが毎朝売られている。", "error_description": "「手作りが」は誤り。手作りは後ろの「パン」を修飾する「の」で続ける必要がある。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51917, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題として「少年」を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「少年をパンを食べました」は目的語が重なり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「少年へパンを食べました」は食べる主体が示されず誤り。"}, {"text": "で", "is_correct": false, "explanation": "「少年でパンを食べました」は文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "主題として「少年」を示す助詞。", "を": "「少年をパンを食べました」は目的語が重なり不自然。", "へ": "「少年へパンを食べました」は食べる主体が示されず誤り。", "で": "「少年でパンを食べました」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "で": "location_means"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51917, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "声をかける相手を示す助詞。"}, {"text": "を", "is_correct": false, "explanation": "「少年を、女性が声をかけた」は「声を」と重なり誤り。"}, {"text": "の", "is_correct": false, "explanation": "「少年の、女性が声をかけた」は声をかける相手が示されず誤り。"}, {"text": "で", "is_correct": false, "explanation": "「少年で」は場所・手段を表し、声をかける相手にならない。"}], "correct_answer": "に", "explanations": {"に": "声をかける相手を示す助詞。", "を": "「少年を、女性が声をかけた」は「声を」と重なり誤り。", "の": "「少年の、女性が声をかけた」は声をかける相手が示されず誤り。", "で": "「少年で」は場所・手段を表し、声をかける相手にならない。"}, "error_tags": {"を": "object_marker", "の": "possessive", "で": "location_means"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51917, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "男の子のことです。", "primary_collocate": null, "pronunciation": "しょうねん", "ipa": "ɕoːneɴ", "syllable_count": 4, "sentences": [{"text": "少年が走る。", "target_word": "少年", "complexity_tier": "T1", "furigana": "少年[しょうねん]が走[はし]る。", "sentence_source": "generated"}, {"text": "あの少年は十歳だ。", "target_word": "少年", "complexity_tier": "T1", "furigana": "あの少年[しょうねん]は十歳[じゅっさい]だ。", "sentence_source": "generated"}, {"text": "少年はパンを食べました。", "target_word": "少年", "complexity_tier": "T2", "furigana": "少年[しょうねん]はパンを食[た]べました。", "sentence_source": "generated"}, {"text": "公園に少年が三人います。", "target_word": "少年", "complexity_tier": "T2", "furigana": "公園[こうえん]に少年[しょうねん]が三人[さんにん]います。", "sentence_source": "generated"}, {"text": "少年にりんごをあげました。", "target_word": "少年", "complexity_tier": "T2", "furigana": "少年[しょうねん]にりんごをあげました。", "sentence_source": "generated"}, {"text": "少年の帽子が風で飛んでしまった。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]の帽子[ぼうし]が風[かぜ]で飛[と]んでしまった。", "sentence_source": "generated"}, {"text": "その少年は毎朝、新聞を配っている。", "target_word": "少年", "complexity_tier": "T3", "furigana": "その少年[しょうねん]は毎朝[まいあさ]、新聞[しんぶん]を配[くば]っている。", "sentence_source": "generated"}, {"text": "泣いている少年に、女性が声をかけた。", "target_word": "少年", "complexity_tier": "T3", "furigana": "泣[な]いている少年[しょうねん]に、女性[じょせい]が声[こえ]をかけた。", "sentence_source": "generated"}, {"text": "少年と犬はいつも一緒に学校へ行く。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]と犬[いぬ]はいつも一緒[いっしょ]に学校[がっこう]へ行[い]く。", "sentence_source": "generated"}, {"text": "少年だったころ、私は海の近くに住んでいた。", "target_word": "少年", "complexity_tier": "T4", "furigana": "少年[しょうねん]だったころ、私[わたし]は海[うみ]の近[ちか]くに住[す]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "少年たち", "label": "派生"}, {"form": "少年期", "label": "派生"}, {"form": "少年時代", "label": "派生"}, {"form": "少年院", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 年の若い男の子のこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51917, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少年", "is_correct": true, "explanation": "見出し語「しょうねん」そのもの。"}, {"text": "商店", "is_correct": false, "explanation": "「しょうてん」。ねがてに変わる。"}, {"text": "情念", "is_correct": false, "explanation": "「じょうねん」。しょが清濁だけ変わる。"}, {"text": "正面", "is_correct": false, "explanation": "「しょうめん」。ねがめに変わる。"}], "explanations": {"少年": "見出し語「しょうねん」そのもの。", "商店": "「しょうてん」。ねがてに変わる。", "情念": "「じょうねん」。しょが清濁だけ変わる。", "正面": "「しょうめん」。ねがめに変わる。"}, "sentence_index": null, "correct_answer": "少年"}, "level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "走る主体として男の子が自然に入る。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机が走ることはなく意味が合わない。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが、空が走ることはなく意味が合わない。"}, {"text": "本", "is_correct": false, "explanation": "形は合うが、本が走ることはなく意味が合わない。"}], "explanations": {"少年": "走る主体として男の子が自然に入る。", "机": "形は合うが、机が走ることはなく意味が合わない。", "空": "形は合うが、空が走ることはなく意味が合わない。", "本": "形は合うが、本が走ることはなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園に五十歳の少年がいます。", "explanation": "「少年」は年の若い男の子。五十歳には使えない。"}, {"text": "公園で遊んでいる少年は、私の娘です。", "explanation": "「少年」は男の子を指す。娘には使えない。"}, {"text": "公園にいる少年は、去年生まれた子犬です。", "explanation": "「少年」は人間の男の子。子犬には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
