INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51918, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "年齢が若い男性の子ども。特に、小学生から中学生くらいの男の子を指す。", "primary_collocate": null, "pronunciation": "しょうねん", "ipa": "ɕoːneɴ", "syllable_count": 4, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り口で一人の少年が手作りのレモネードを販売していた。", "target_word": "少年", "complexity_tier": "T6", "furigana": "記録的[きろくてき]な暑[あつ]さが続[つづ]く夏[なつ]の午後[ごご]、公園[こうえん]の入[い]り口[ぐち]で一人[ひとり]の少年[しょうねん]が手作[てづく]りのレモネードを販売[はんばい]していた。", "sentence_source": "generated"}, {"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "少年", "complexity_tier": "T6", "furigana": "冷[つめ]たくて甘[あま]いレモネードは、暑[あつ]さに疲[つか]れた人々[ひとびと]の喉[のど]を潤[うるお]し、少年[しょうねん]の努力[どりょく]は小[ちい]さな売上[うりあげ]となって確実[かくじつ]に実[み]を結[むす]んでいった。", "sentence_source": "mined"}, {"text": "少年は本を読んでいる。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]は本[ほん]を読[よ]んでいる。", "sentence_source": "generated"}, {"text": "あの少年は私の弟です。", "target_word": "少年", "complexity_tier": "T2", "furigana": "あの少年[しょうねん]は私[わたし]の弟[おとうと]です。", "sentence_source": "generated"}, {"text": "少年が犬と走っています。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]が犬[いぬ]と走[はし]っています。", "sentence_source": "generated"}, {"text": "少年の夢は宇宙飛行士になることだ。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]の夢[ゆめ]は宇宙飛行士[うちゅうひこうし]になることだ。", "sentence_source": "generated"}, {"text": "町の人々は少年に道を聞いた。", "target_word": "少年", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]は少年[しょうねん]に道[みち]を聞[き]いた。", "sentence_source": "generated"}, {"text": "少年を助けた警察官が表彰された。", "target_word": "少年", "complexity_tier": "T4", "furigana": "少年[しょうねん]を助[たす]けた警察官[けいさつかん]が表彰[ひょうしょう]された。", "sentence_source": "generated"}, {"text": "少年たちは川で魚を捕まえて遊んだ。", "target_word": "少年", "complexity_tier": "T3", "furigana": "少年[しょうねん]たちは川[かわ]で魚[さかな]を捕[つか]まえて遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "昔、少年だった彼は、今では有名な画家だ。", "target_word": "少年", "complexity_tier": "T4", "furigana": "昔[むかし]、少年[しょうねん]だった彼[かれ]は、今[いま]では有名[ゆうめい]な画家[がか]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "少年たち", "label": "派生"}, {"form": "少年期", "label": "派生"}, {"form": "少年時代", "label": "派生"}, {"form": "少年院", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 小中学生くらいの若い男の子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
