INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51918, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少年", "is_correct": true, "explanation": "見出し語「しょうねん」そのもの。"}, {"text": "商戦", "is_correct": false, "explanation": "「しょうせん」。ねがせに変わる。"}, {"text": "抄本", "is_correct": false, "explanation": "「しょうほん」。ねがほに変わる。"}, {"text": "荘園", "is_correct": false, "explanation": "「しょうえん」。ねがえに変わる。"}], "explanations": {"少年": "見出し語「しょうねん」そのもの。", "商戦": "「しょうせん」。ねがせに変わる。", "抄本": "「しょうほん」。ねがほに変わる。", "荘園": "「しょうえん」。ねがえに変わる。"}, "sentence_index": null, "correct_answer": "少年"}, "level_3": {"options": [{"text": "少年", "is_correct": true, "explanation": "町の人々が道を尋ねる相手として自然。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、地図に道を聞くことはなく意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、時計に道を聞くことはなく意味が合わない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、屋根に道を聞くことはなく意味が合わない。"}], "explanations": {"少年": "町の人々が道を尋ねる相手として自然。", "地図": "形は合うが、地図に道を聞くことはなく意味が合わない。", "時計": "形は合うが、時計に道を聞くことはなく意味が合わない。", "屋根": "形は合うが、屋根に道を聞くことはなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "少年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昔、少年だった彼女は、今では有名な画家だ。", "explanation": "「少年」は男の子。女性である「彼女」の過去には使えない。"}, {"text": "彼は三十年間、会社で少年として働いている。", "explanation": "「少年」は若い男の子。三十年働く大人には使えない。"}, {"text": "昔、少年だった犬は、今では大きくなった。", "explanation": "「少年」は人間の男の子。犬には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
