INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51918, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "少年たちを川で魚を捕まえて遊んだ。", "corrected_sentence": "少年たちは川で魚を捕まえて遊んだ。", "error_description": "遊んだ主体は「少年たちは」で表す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
