INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「拭わないと」で条件を示し、拭かないと風邪をひくという意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「拭わないに」とは接続せず、文が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「拭わないへ」と続けられず、方向を示せない。"}, {"text": "を", "is_correct": false, "explanation": "「拭わないを」は目的語を示す形にならず、文が成立しない。"}], "correct_answer": "と", "explanations": {"と": "「拭わないと」で条件を示し、拭かないと風邪をひくという意味になる。", "に": "「拭わないに」とは接続せず、文が成立しない。", "へ": "「拭わないへ」と続けられず、方向を示せない。", "を": "「拭わないを」は目的語を示す形にならず、文が成立しない。"}, "error_tags": {"に": "接続不可", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や布で、体についた水や汗を取ること。", "primary_collocate": null, "pronunciation": "ぬぐう", "ipa": "nɯɡɯɯ", "syllable_count": 3, "sentences": [{"text": "走ったあと、タオルで顔の汗を拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "走[はし]ったあと、タオルで顔[かお]の汗[あせ]を拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "手についた水を、ハンカチで拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "手[て]についた水[みず]を、ハンカチで拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "お風呂から出て、体の水をしっかり拭う。", "target_word": "拭う", "complexity_tier": "T2", "furigana": "お風呂[ふろ]から出[で]て、体[からだ]の水[みず]をしっかり拭[ぬぐ]う。", "sentence_source": "generated"}, {"text": "子どもの濡れた髪をタオルで拭ってあげた。", "target_word": "拭って", "complexity_tier": "T3", "furigana": "子[こ]どもの濡[ぬ]れた髪[かみ]をタオルで拭[ぬぐ]ってあげた。", "sentence_source": "generated"}, {"text": "暑くて、ハンカチで何度も額の汗を拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "暑[あつ]くて、ハンカチで何度[なんど]も額[ひたい]の汗[あせ]を拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "雨にぬれたので、駅で腕の水滴を拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれたので、駅[えき]で腕[うで]の水滴[すいてき]を拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "プールから上がって、肩の水滴を手で拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "プールから上[あ]がって、肩[かた]の水滴[すいてき]を手[て]で拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "泳いだあとは、すぐに体を拭わないと風邪をひく。", "target_word": "拭わない", "complexity_tier": "T3", "furigana": "泳[およ]いだあとは、すぐに体[からだ]を拭[ぬぐ]わないと風邪[かぜ]をひく。", "sentence_source": "generated"}, {"text": "汗で濡れた背中を、母がタオルで拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "汗[あせ]で濡[ぬ]れた背中[せなか]を、母[はは]がタオルで拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "試合のあと、選手は首の汗を拭って水を飲んだ。", "target_word": "拭って", "complexity_tier": "T3", "furigana": "試合[しあい]のあと、選手[せんしゅ]は首[くび]の汗[あせ]を拭[ぬぐ]って水[みず]を飲[の]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拭わない", "label": "未然形+ない"}, {"form": "拭います", "label": "連用形+ます"}, {"form": "拭った", "label": "過去形"}, {"form": "拭って", "label": "て形"}, {"form": "拭える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "体についた汗・涙・水を手や布で取る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拭った", "is_correct": true, "explanation": "過去の動作を表す終止形で、「走ったあと」に続く文として自然。"}, {"text": "拭って", "is_correct": false, "explanation": "て形のため文末に置けず、ここでは文が完結しない。"}, {"text": "拭い", "is_correct": false, "explanation": "連用形だけでは文を言い切れず、文末として不完全。"}, {"text": "拭わ", "is_correct": false, "explanation": "未然形の語幹のみで、「ない」「う」などを伴わないと文が成立しない。"}], "explanations": {"拭った": "過去の動作を表す終止形で、「走ったあと」に続く文として自然。", "拭って": "て形のため文末に置けず、ここでは文が完結しない。", "拭い": "連用形だけでは文を言い切れず、文末として不完全。", "拭わ": "未然形の語幹のみで、「ない」「う」などを伴わないと文が成立しない。"}, "sentence_index": 0, "correct_answer": "拭った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの濡れた髪を、シャンプーで拭ってあげた。", "explanation": "ここは〈洗う〉の意味。拭うは布などで水分や汚れをこすり取る動作で、シャンプーで髪を洗う行為には使わない。"}, {"text": "子どもの濡れた髪を、ドライヤーで拭ってあげた。", "explanation": "ここは〈乾かす〉の意味。拭うは布でこすって水分を取る動作で、熱風で乾かす意味では使わない。"}, {"text": "子どもの濡れた髪を、櫛で拭ってあげた。", "explanation": "ここは〈梳かす〉の意味。拭うは水分や汚れを取る動作で、櫛で髪を整える意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拭った", "is_correct": true, "explanation": "過去の動作を表し、プールから上がった後の肩の水滴を手で取ったという文脈に合う。"}, {"text": "拭えて", "is_correct": false, "explanation": "可能形のて形で、文を言い切れず不完全。"}, {"text": "拭います", "is_correct": false, "explanation": "丁寧形で、過去の出来事を述べる文脈と合わない。"}, {"text": "拭えず", "is_correct": false, "explanation": "可能形の否定で「拭けず」の意味になり、取ったという文脈と反対になる。"}], "explanations": {"拭った": "過去の動作を表し、プールから上がった後の肩の水滴を手で取ったという文脈に合う。", "拭えて": "可能形のて形で、文を言い切れず不完全。", "拭います": "丁寧形で、過去の出来事を述べる文脈と合わない。", "拭えず": "可能形の否定で「拭けず」の意味になり、取ったという文脈と反対になる。"}, "sentence_index": 6, "correct_answer": "拭った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合のあと、選手はシャワーで首の汗を拭って水を飲んだ。", "explanation": "ここは〈流す〉の意味。拭うは布などでこすり取る動作で、シャワーで洗い流す意味では使わない。"}, {"text": "試合のあと、選手はやかんでお湯を拭って水を飲んだ。", "explanation": "ここは〈沸かす〉の意味。拭うは温度を上げる意味では使わず、お湯を沸かす場面には合わない。"}, {"text": "試合のあと、選手はコップに水を拭って飲んだ。", "explanation": "ここは〈注ぐ〉の意味。拭うは水分を取る動作で、容器に水を入れる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "泣いていた子の涙を指で拭うた。", "corrected_sentence": "泣いていた子の涙を指で拭った。", "error_description": "「拭うた」は誤った活用形。過去形は促音便を使い「拭った」と言う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拭った", "is_correct": true, "explanation": "過去形で、手についた水を取った出来事を表す文に合う。"}, {"text": "拭うた", "is_correct": false, "explanation": "誤った活用形。過去形は促音便で「拭った」と言う。"}, {"text": "拭って", "is_correct": false, "explanation": "て形のため、文の述語として完結しない。"}, {"text": "拭わ", "is_correct": false, "explanation": "未然形の語幹のみで、文末として成立しない。"}], "correct_form": "拭った", "base_form": "拭う", "form_label": "過去形", "sentence_index": 1, "explanations": {"拭った": "過去形で、手についた水を取った出来事を表す文に合う。", "拭うた": "誤った活用形。過去形は促音便で「拭った」と言う。", "拭って": "て形のため、文の述語として完結しない。", "拭わ": "未然形の語幹のみで、文末として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51919, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "顔の水滴が拭うと、視界がはっきりした。", "corrected_sentence": "顔の水滴を拭うと、視界がはっきりした。", "error_description": "「顔の水滴が拭う」は誤り。拭うの目的語は「を」で示すので、「顔の水滴を拭う」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拭わない", "is_correct": true, "explanation": "未然形＋ない。「拭わないと」の条件として、拭かないと風邪をひくという文脈に合う。"}, {"text": "拭います", "is_correct": false, "explanation": "丁寧形で、「ないと」の条件に続かない。"}, {"text": "拭おう", "is_correct": false, "explanation": "意志形で、「ないと」の条件に続かず文が成立しない。"}, {"text": "拭えず", "is_correct": false, "explanation": "可能形の否定連用形で、「ないと」の条件に続かず文が成立しない。"}], "correct_form": "拭わない", "base_form": "拭う", "form_label": "未然形+ない", "sentence_index": 7, "explanations": {"拭わない": "未然形＋ない。「拭わないと」の条件として、拭かないと風邪をひくという文脈に合う。", "拭います": "丁寧形で、「ないと」の条件に続かない。", "拭おう": "意志形で、「ないと」の条件に続かず文が成立しない。", "拭えず": "可能形の否定連用形で、「ないと」の条件に続かず文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
