INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「拭ってから」で動作の後を示し、拭いた後に家に入る順序を表す。"}, {"text": "が", "is_correct": false, "explanation": "「拭ってが」とは続けられず、主語も示せない。"}, {"text": "に", "is_correct": false, "explanation": "「拭ってに」とは続かず、場所や時間の意味にならない。"}, {"text": "で", "is_correct": false, "explanation": "「拭ってで」とは続けられず、手段の意味にならない。"}], "correct_answer": "から", "explanations": {"から": "「拭ってから」で動作の後を示し、拭いた後に家に入る順序を表す。", "が": "「拭ってが」とは続けられず、主語も示せない。", "に": "「拭ってに」とは続かず、場所や時間の意味にならない。", "で": "「拭ってで」とは続けられず、手段の意味にならない。"}, "error_tags": {"が": "主語", "に": "着点", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "表面についた水分や汚れを、布や手などでこすって取り除くこと。", "primary_collocate": null, "pronunciation": "ぬぐう", "ipa": "nɯɡɯɯ", "syllable_count": 3, "sentences": [{"text": "テーブルにこぼれた牛乳を布巾で拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "テーブルにこぼれた牛乳[ぎゅうにゅう]を布巾[ふきん]で拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "窓ガラスの汚れを雑巾で拭う。", "target_word": "拭う", "complexity_tier": "T2", "furigana": "窓[まど]ガラスの汚[よご]れを雑巾[ぞうきん]で拭[ぬぐ]う。", "sentence_source": "generated"}, {"text": "濡れた床をすぐに拭わないと、滑って危ない。", "target_word": "拭わない", "complexity_tier": "T3", "furigana": "濡[ぬ]れた床[ゆか]をすぐに拭[ぬぐ]わないと、滑[すべ]って危[あぶ]ない。", "sentence_source": "generated"}, {"text": "彼は眼鏡のくもりをハンカチで拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "彼[かれ]は眼鏡[めがね]のくもりをハンカチで拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "掃除の最後に、棚のほこりを拭って終わりにした。", "target_word": "拭って", "complexity_tier": "T3", "furigana": "掃除[そうじ]の最後[さいご]に、棚[たな]のほこりを拭[ぬぐ]って終[お]わりにした。", "sentence_source": "generated"}, {"text": "ペンキがついた壁を、湿った布で拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "ペンキがついた壁[かべ]を、湿[しめ]った布[ぬの]で拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "鏡についた水滴を拭うと、顔がはっきり映った。", "target_word": "拭う", "complexity_tier": "T3", "furigana": "鏡[かがみ]についた水滴[すいてき]を拭[ぬぐ]うと、顔[かお]がはっきり映[うつ]った。", "sentence_source": "generated"}, {"text": "靴の泥を玄関で拭ってから、家に入った。", "target_word": "拭って", "complexity_tier": "T3", "furigana": "靴[くつ]の泥[どろ]を玄関[げんかん]で拭[ぬぐ]ってから、家[いえ]に入[はい]った。", "sentence_source": "generated"}, {"text": "食事のあと、テーブルの上をふきんで拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "食事[しょくじ]のあと、テーブルの上[うえ]をふきんで拭[ぬぐ]った。", "sentence_source": "generated"}, {"text": "スマホの画面の指紋を、柔らかい布で拭った。", "target_word": "拭った", "complexity_tier": "T3", "furigana": "スマホの画面[がめん]の指紋[しもん]を、柔[やわ]らかい布[ぬの]で拭[ぬぐ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "拭わない", "label": "未然形+ない"}, {"form": "拭います", "label": "連用形+ます"}, {"form": "拭った", "label": "過去形"}, {"form": "拭って", "label": "て形"}, {"form": "拭える", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "物の表面の水分や汚れを布でこすって取り除く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拭った", "is_correct": true, "explanation": "過去形で、こぼれた牛乳を布巾で拭き取った出来事に合う。"}, {"text": "拭って", "is_correct": false, "explanation": "て形のため、文を言い切れず不完全。"}, {"text": "拭い", "is_correct": false, "explanation": "連用形で、文末として不完全。"}, {"text": "拭わ", "is_correct": false, "explanation": "未然形の語幹だけでは文が成立しない。"}], "explanations": {"拭った": "過去形で、こぼれた牛乳を布巾で拭き取った出来事に合う。", "拭って": "て形のため、文を言い切れず不完全。", "拭い": "連用形で、文末として不完全。", "拭わ": "未然形の語幹だけでは文が成立しない。"}, "sentence_index": 0, "correct_answer": "拭った"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は失敗の汚名を、チームの勝利で拭った。", "explanation": "ここは〈汚名をそそぐ〉の意味。この文は評判を取り戻す比喩で、布で表面の汚れを取る今回の意味には当てはまらない。"}, {"text": "彼はコップに水を、ハンカチで拭った。", "explanation": "ここは〈注ぐ〉の意味。拭うは水分を取る動作で、容器に水を入れる意味では使わない。"}, {"text": "彼は眼鏡の枠を、小刀で拭った。", "explanation": "ここは〈削る〉の意味。拭うは表面の汚れを布などでこすり取る動作で、小刀で枠を削る意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拭う", "is_correct": true, "explanation": "基本形で、「拭うと」の条件として鏡の水滴を拭く文脈に自然につながる。"}, {"text": "拭えて", "is_correct": false, "explanation": "可能形のて形で、条件の文として続かない。"}, {"text": "拭います", "is_correct": false, "explanation": "丁寧形で、「拭うと」の条件に続かない。"}, {"text": "拭わず", "is_correct": false, "explanation": "中止形で、「と」に続く条件の形にならず文が成立しない。"}], "explanations": {"拭う": "基本形で、「拭うと」の条件として鏡の水滴を拭く文脈に自然につながる。", "拭えて": "可能形のて形で、条件の文として続かない。", "拭います": "丁寧形で、「拭うと」の条件に続かない。", "拭わず": "中止形で、「と」に続く条件の形にならず文が成立しない。"}, "sentence_index": 6, "correct_answer": "拭う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スマホの画面の傷を、柔らかい布で拭った。", "explanation": "ここは〈削り取る〉の意味。拭うは表面の汚れを布でこすり取る動作で、傷そのものを削る意味では使わない。"}, {"text": "スマホの画面の火を、柔らかい布で拭った。", "explanation": "ここは〈消す〉の意味。拭うは汚れを取る動作で、火を消す意味では使わない。"}, {"text": "スマホの画面の音を、柔らかい布で拭った。", "explanation": "ここは〈止める〉の意味。拭うは物の表面から汚れを取る動作で、音を止める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "床にこぼれた水を雑巾で拭うた。", "corrected_sentence": "床にこぼれた水を雑巾で拭った。", "error_description": "「拭うた」は誤った活用形。過去形は促音便を使い「拭った」と言う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "拭わない", "is_correct": true, "explanation": "未然形＋ない。「拭わないと」の条件として、拭かないと滑って危ないという文脈に合う。"}, {"text": "拭い", "is_correct": false, "explanation": "連用形で、「ないと」に続かず文が成立しない。"}, {"text": "拭った", "is_correct": false, "explanation": "過去形で、「ないと」に続かず文が成立しない。"}, {"text": "拭って", "is_correct": false, "explanation": "て形で、「ないと」に続かず文が成立しない。"}], "correct_form": "拭わない", "base_form": "拭う", "form_label": "未然形+ない", "sentence_index": 1, "explanations": {"拭わない": "未然形＋ない。「拭わないと」の条件として、拭かないと滑って危ないという文脈に合う。", "拭い": "連用形で、「ないと」に続かず文が成立しない。", "拭った": "過去形で、「ないと」に続かず文が成立しない。", "拭って": "て形で、「ないと」に続かず文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51920, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓の結露が拭うと、景色がよく見えた。", "corrected_sentence": "窓の結露を拭うと、景色がよく見えた。", "error_description": "「窓の結露が拭う」は誤り。拭うの目的語は「を」で示すので、「窓の結露を拭う」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "拭って", "is_correct": true, "explanation": "て形で、「拭ってから」と動作の順序を表し、泥を拭いてから家に入る文脈に合う。"}, {"text": "拭い", "is_correct": false, "explanation": "連用形で、「から」に続かず文が成立しない。"}, {"text": "拭わず", "is_correct": false, "explanation": "中止形で、「から」に続かず文が成立しない。"}, {"text": "拭わ", "is_correct": false, "explanation": "未然形の語幹のみで、「から」に続かず文が成立しない。"}], "correct_form": "拭って", "base_form": "拭う", "form_label": "て形", "sentence_index": 7, "explanations": {"拭って": "て形で、「拭ってから」と動作の順序を表し、泥を拭いてから家に入る文脈に合う。", "拭い": "連用形で、「から」に続かず文が成立しない。", "拭わず": "中止形で、「から」に続かず文が成立しない。", "拭わ": "未然形の語幹のみで、「から」に続かず文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51921, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「夏に」は時を表す。"}, {"text": "で", "is_correct": false, "explanation": "「夏で」は時を表せず、成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「夏を海で稼いだ」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「夏へ」は成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「夏に」は時を表す。", "で": "「夏で」は時を表せず、成り立たない。", "を": "「夏を海で稼いだ」は文として成り立たない。", "へ": "「へ」は方向を表し、「夏へ」は成り立たない。"}, "error_tags": {"で": "place_vs_time", "を": "object_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "使う", "is_correct": true, "explanation": "お金を得る「稼ぐ」に対し、お金を出す「使う」が反対の意味になる。"}, {"text": "売る", "is_correct": false, "explanation": "「売る」は稼ぐ手段で、反対の意味ではない。"}, {"text": "働く", "is_correct": false, "explanation": "「働く」は稼ぐ手段で、反対の意味ではない。"}, {"text": "貯める", "is_correct": false, "explanation": "「貯める」はお金をためることで、反対の意味ではない。"}], "correct_answer": "使う", "explanations": {"使う": "お金を得る「稼ぐ」に対し、お金を出す「使う」が反対の意味になる。", "売る": "「売る」は稼ぐ手段で、反対の意味ではない。", "働く": "「働く」は稼ぐ手段で、反対の意味ではない。", "貯める": "「貯める」はお金をためることで、反対の意味ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51921, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「商品を売って」で、売る対象を表す。"}, {"text": "に", "is_correct": false, "explanation": "「商品に売って」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「商品へ売って」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「彼女は商品が売って」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「商品を売って」で、売る対象を表す。", "に": "「商品に売って」は文法的に成り立たない。", "へ": "「へ」は方向を表し、「商品へ売って」は成り立たない。", "が": "「彼女は商品が売って」は文法的に成り立たない。"}, "error_tags": {"に": "goal_vs_object", "へ": "direction", "が": "subject_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪費する", "is_correct": true, "explanation": "お金を得る「稼ぐ」に対し、お金をむだに使う「浪費する」が反対の意味になる。"}, {"text": "儲ける", "is_correct": false, "explanation": "「儲ける」は類義語で、反対の意味ではない。"}, {"text": "得る", "is_correct": false, "explanation": "「得る」は類義的で、反対の意味ではない。"}, {"text": "働く", "is_correct": false, "explanation": "「働く」は稼ぐ手段で、反対の意味ではない。"}], "correct_answer": "浪費する", "explanations": {"浪費する": "お金を得る「稼ぐ」に対し、お金をむだに使う「浪費する」が反対の意味になる。", "儲ける": "「儲ける」は類義語で、反対の意味ではない。", "得る": "「得る」は類義的で、反対の意味ではない。", "働く": "「働く」は稼ぐ手段で、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51921, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "お金をもらうために、仕事をしたり、何かを売ったりする。", "primary_collocate": null, "pronunciation": "かせぐ", "ipa": "kaseɡɯ", "syllable_count": 3, "sentences": [{"text": "父は店で稼ぐ。", "target_word": "稼ぐ", "complexity_tier": "T1", "furigana": "父[ちち]は店[みせ]で稼[かせ]ぐ。", "sentence_source": "generated"}, {"text": "彼は夏に海で稼いだ。", "target_word": "稼いだ", "complexity_tier": "T1", "furigana": "彼[かれ]は夏[なつ]に海[うみ]で稼[かせ]いだ。", "sentence_source": "generated"}, {"text": "私は店で働いて稼ぎます。", "target_word": "稼ぎます", "complexity_tier": "T2", "furigana": "私[わたし]は店[みせ]で働[はたら]いて稼[かせ]ぎます。", "sentence_source": "generated"}, {"text": "野菜を売って稼いでいます。", "target_word": "稼いでいます", "complexity_tier": "T3", "furigana": "野菜[やさい]を売[う]って稼[かせ]いでいます。", "sentence_source": "generated"}, {"text": "休みの日に、絵を売って稼ぐ人もいる。", "target_word": "稼ぐ", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に、絵[え]を売[う]って稼[かせ]ぐ人[ひと]もいる。", "sentence_source": "generated"}, {"text": "稼いだお金を貯金しました。", "target_word": "稼いだ", "complexity_tier": "T2", "furigana": "稼[かせ]いだお金[かね]を貯金[ちょきん]しました。", "sentence_source": "generated"}, {"text": "もっと稼ぐために、新しい仕事を始めた。", "target_word": "稼ぐ", "complexity_tier": "T3", "furigana": "もっと稼[かせ]ぐために、新[あたら]しい仕事[しごと]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "彼女はネットで商品を売って、月に十万円稼ぐ。", "target_word": "稼ぐ", "complexity_tier": "T4", "furigana": "彼女[かのじょ]はネットで商品[しょうひん]を売[う]って、月[つき]に十万円[じゅうまんえん]稼[かせ]ぐ。", "sentence_source": "generated"}, {"text": "稼げなければ、生活するのが難しくなる。", "target_word": "稼げなければ", "complexity_tier": "T4", "furigana": "稼[かせ]げなければ、生活[せいかつ]するのが難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "弟は新聞を配って、小遣いを稼いでいる。", "target_word": "稼いでいる", "complexity_tier": "T3", "furigana": "弟[おとうと]は新聞[しんぶん]を配[くば]って、小遣[こづか]いを稼[かせ]いでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "稼いだ", "label": "活用"}, {"form": "稼げる", "label": "活用"}, {"form": "稼がせる", "label": "活用"}, {"form": "稼ぎ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 仕事や販売でお金を手に入れる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51921, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稼ぐ", "is_correct": true, "explanation": "「父は店で稼ぐ」で、店で働いてお金を得る意味になる。"}, {"text": "咲く", "is_correct": false, "explanation": "形は合うが、人である父が「咲く」ことはなく、意味が合わない。"}, {"text": "降る", "is_correct": false, "explanation": "形は合うが、「降る」のは雨や雪で、父が店で降ることはない。"}, {"text": "沸く", "is_correct": false, "explanation": "形は合うが、「沸く」のはお湯などで、父には使えない。"}], "explanations": {"稼ぐ": "「父は店で稼ぐ」で、店で働いてお金を得る意味になる。", "咲く": "形は合うが、人である父が「咲く」ことはなく、意味が合わない。", "降る": "形は合うが、「降る」のは雨や雪で、父が店で降ることはない。", "沸く": "形は合うが、「沸く」のはお湯などで、父には使えない。"}, "sentence_index": 0, "correct_answer": "稼ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友だちの家で宿題を稼いでいます。", "explanation": "「稼ぐ」の目的語はお金で、宿題には使えない。"}, {"text": "山に登って、きれいな景色を稼いでいます。", "explanation": "「稼ぐ」は景色を見る意味には使えない。"}, {"text": "毎日走って、足の力を稼いでいます。", "explanation": "「稼ぐ」は力をつける意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51921, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稼ぐ", "is_correct": true, "explanation": "「もっと稼ぐために」で、新しい仕事を始める目的として意味が通る。"}, {"text": "転ぶ", "is_correct": false, "explanation": "形は合うが、「もっと転ぶために仕事を始めた」は意味が通らない。"}, {"text": "濡れる", "is_correct": false, "explanation": "形は合うが、新しい仕事を始める目的として意味が通らない。"}, {"text": "怒る", "is_correct": false, "explanation": "形は合うが、新しい仕事を始める目的として意味が合わない。"}], "explanations": {"稼ぐ": "「もっと稼ぐために」で、新しい仕事を始める目的として意味が通る。", "転ぶ": "形は合うが、「もっと転ぶために仕事を始めた」は意味が通らない。", "濡れる": "形は合うが、新しい仕事を始める目的として意味が通らない。", "怒る": "形は合うが、新しい仕事を始める目的として意味が合わない。"}, "sentence_index": 6, "correct_answer": "稼ぐ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "弟は新聞を配って、元気を稼いでいる。", "explanation": "「稼ぐ」の目的語はお金で、元気には使えない。"}, {"text": "妹は図書館で、本を稼いでいる。", "explanation": "「稼ぐ」は本を読んだり借りたりする意味には使えない。"}, {"text": "弟は新聞を稼いで、毎朝家に持って帰る。", "explanation": "「稼ぐ」は新聞をもらう意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
