INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「一年で」は期間の範囲を表す。"}, {"text": "を", "is_correct": false, "explanation": "「一年を一億円も」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「一年と一億円も稼いだ」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「一年へ」は成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「一年で」は期間の範囲を表す。", "を": "「一年を一億円も」は文として成り立たない。", "と": "「一年と一億円も稼いだ」は意味が通らない。", "へ": "「へ」は方向を表し、「一年へ」は成り立たない。"}, "error_tags": {"を": "object_marker", "と": "companion", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "費やす", "is_correct": true, "explanation": "お金を得る「稼ぐ」に対し、お金を使ってなくす「費やす」が反対の意味になる。"}, {"text": "儲ける", "is_correct": false, "explanation": "「儲ける」は類義語で、反対の意味ではない。"}, {"text": "働く", "is_correct": false, "explanation": "「働く」は稼ぐ手段で、反対の意味ではない。"}, {"text": "得る", "is_correct": false, "explanation": "「得る」は類義的で、反対の意味ではない。"}], "correct_answer": "費やす", "explanations": {"費やす": "お金を得る「稼ぐ」に対し、お金を使ってなくす「費やす」が反対の意味になる。", "儲ける": "「儲ける」は類義語で、反対の意味ではない。", "働く": "「働く」は稼ぐ手段で、反対の意味ではない。", "得る": "「得る」は類義的で、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "努力や仕事をして、お金や利益を得る。", "primary_collocate": null, "pronunciation": "かせぐ", "ipa": "kaseɡɯ", "syllable_count": 3, "sentences": [{"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "稼ぐ", "complexity_tier": "T6", "furigana": "この販売[はんばい]活動[かつどう]は、単[たん]にお金[かね]を稼[かせ]ぐためだけでなく、自分[じぶん]で計画[けいかく]を立[た]てて実行[じっこう]するという貴重[きちょう]な経験[けいけん]を積[つ]むことが目的[もくてき]だった。", "sentence_source": "mined"}, {"text": "彼はよく稼ぐ。", "target_word": "稼ぐ", "complexity_tier": "T1", "furigana": "彼[かれ]はよく稼[かせ]ぐ。", "sentence_source": "generated"}, {"text": "兄は工場で働いて稼いでいます。", "target_word": "稼いで", "complexity_tier": "T3", "furigana": "兄[あに]は工場[こうじょう]で働[はたら]いて稼[かせ]いでいます。", "sentence_source": "generated"}, {"text": "学生のとき、アルバイトで学費を稼いだ。", "target_word": "稼いだ", "complexity_tier": "T3", "furigana": "学生[がくせい]のとき、アルバイトで学費[がくひ]を稼[かせ]いだ。", "sentence_source": "generated"}, {"text": "たくさん稼ぎたいなら、まず資格を取るべきだ。", "target_word": "稼ぎたい", "complexity_tier": "T4", "furigana": "たくさん稼[かせ]ぎたいなら、まず資格[しかく]を取[と]るべきだ。", "sentence_source": "generated"}, {"text": "稼げる仕事を探しています。", "target_word": "稼げる", "complexity_tier": "T3", "furigana": "稼[かせ]げる仕事[しごと]を探[さが]しています。", "sentence_source": "generated"}, {"text": "母は一日八時間働いて、家族のために稼いでいる。", "target_word": "稼いでいる", "complexity_tier": "T4", "furigana": "母[はは]は一日[いちにち]八時間[はちじかん]働[はたら]いて、家族[かぞく]のために稼[かせ]いでいる。", "sentence_source": "generated"}, {"text": "彼女は一年で一億円も稼いだそうだ。", "target_word": "稼いだ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は一年[いちねん]で一億円[いちおくえん]も稼[かせ]いだそうだ。", "sentence_source": "generated"}, {"text": "稼いだお金で、両親に旅行をプレゼントした。", "target_word": "稼いだ", "complexity_tier": "T3", "furigana": "稼[かせ]いだお金[かね]で、両親[りょうしん]に旅行[りょこう]をプレゼントした。", "sentence_source": "generated"}, {"text": "子どもに稼がせるのは、よくないと思う。", "target_word": "稼がせる", "complexity_tier": "T4", "furigana": "子[こ]どもに稼[かせ]がせるのは、よくないと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "稼いだ", "label": "活用"}, {"form": "稼げる", "label": "活用"}, {"form": "稼がせる", "label": "活用"}, {"form": "稼ぎ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 働いてお金や利益を得る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稼ぐ", "is_correct": true, "explanation": "「お金を稼ぐ」で、働いてお金を得る意味になり、文脈に合う。"}, {"text": "捨てる", "is_correct": false, "explanation": "形は合うが、「お金を捨てるためだけでなく」では販売活動の目的として意味が合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが、お金を洗うことは販売活動の目的として意味が合わない。"}, {"text": "忘れる", "is_correct": false, "explanation": "形は合うが、「お金を忘れるためだけでなく」では販売活動の目的として意味が通らない。"}], "explanations": {"稼ぐ": "「お金を稼ぐ」で、働いてお金を得る意味になり、文脈に合う。", "捨てる": "形は合うが、「お金を捨てるためだけでなく」では販売活動の目的として意味が合わない。", "洗う": "形は合うが、お金を洗うことは販売活動の目的として意味が合わない。", "忘れる": "形は合うが、「お金を忘れるためだけでなく」では販売活動の目的として意味が通らない。"}, "sentence_index": 0, "correct_answer": "稼ぐ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅の前で財布を稼いでしまった。", "explanation": "「稼ぐ」は働いてお金を得る意味で、財布をなくす意味には使えない。"}, {"text": "友だちから本を稼いで読んだ。", "explanation": "「稼ぐ」は借りる意味ではなく、本を目的語にして「借りる」の意味には使えない。"}, {"text": "風邪をひいて、高い熱を稼いだ。", "explanation": "「稼ぐ」の目的語はお金や利益で、熱のような症状には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稼いでいる", "is_correct": true, "explanation": "「家族のために稼いでいる」で、働いてお金を得ている意味になる。"}, {"text": "忘れている", "is_correct": false, "explanation": "形は合うが、「家族のために忘れている」は前の「働いて」と意味がつながらない。"}, {"text": "壊している", "is_correct": false, "explanation": "形は合うが、一日八時間働く理由として意味が合わない。"}, {"text": "迷っている", "is_correct": false, "explanation": "形は合うが、「家族のために迷っている」は働く文脈に意味が合わない。"}], "explanations": {"稼いでいる": "「家族のために稼いでいる」で、働いてお金を得ている意味になる。", "忘れている": "形は合うが、「家族のために忘れている」は前の「働いて」と意味がつながらない。", "壊している": "形は合うが、一日八時間働く理由として意味が合わない。", "迷っている": "形は合うが、「家族のために迷っている」は働く文脈に意味が合わない。"}, "sentence_index": 6, "correct_answer": "稼いでいる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は生徒に漢字を稼がせた。", "explanation": "「稼がせる」は人にお金を得させる意味で、漢字を覚えさせる意味には使えない。"}, {"text": "母は犬に水を稼がせた。", "explanation": "「稼がせる」の目的語はお金や利益で、水には使えない。"}, {"text": "社長は風邪を社員に稼がせた。", "explanation": "「稼がせる」は風邪のような病気をうつす意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は毎日働いて、たくさんの汗を稼いでいる。", "corrected_sentence": "彼は毎日働いて、たくさんのお金を稼いでいる。", "error_description": "「稼ぐ」の目的語に「汗」は使えない。働いて得るものは「お金」である。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "稼ぐ", "is_correct": true, "explanation": "文末で「彼はよく稼ぐ」と言う辞書形で、文が自然に終わる。"}, {"text": "稼げば", "is_correct": false, "explanation": "仮定形は文末で言い切れず、この位置では文が成立しない。"}, {"text": "稼いで", "is_correct": false, "explanation": "て形は文を途中で止める形で、文末では成立しない。"}, {"text": "稼ぎ", "is_correct": false, "explanation": "名詞形の「稼ぎ」では述語にならず、文が終わらない。"}], "correct_form": "稼ぐ", "base_form": "稼ぐ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"稼ぐ": "文末で「彼はよく稼ぐ」と言う辞書形で、文が自然に終わる。", "稼げば": "仮定形は文末で言い切れず、この位置では文が成立しない。", "稼いで": "て形は文を途中で止める形で、文末では成立しない。", "稼ぎ": "名詞形の「稼ぎ」では述語にならず、文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51922, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は会社で働いて、お金へ稼いでいる。", "corrected_sentence": "姉は会社で働いて、お金を稼いでいる。", "error_description": "「稼ぐ」の対象を表す助詞は「を」で、「へ」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "稼いだ", "is_correct": true, "explanation": "「稼いだそうだ」で、過去に稼いだという伝聞を表す。"}, {"text": "稼いだら", "is_correct": false, "explanation": "条件形「稼いだら」に「そうだ」は続かず、文が成立しない。"}, {"text": "稼げば", "is_correct": false, "explanation": "仮定形に「そうだ」は続かず、文が成立しない。"}, {"text": "稼ごう", "is_correct": false, "explanation": "意志形に「そうだ」は続かず、文が成立しない。"}], "correct_form": "稼いだ", "base_form": "稼ぐ", "form_label": "た形", "sentence_index": 7, "explanations": {"稼いだ": "「稼いだそうだ」で、過去に稼いだという伝聞を表す。", "稼いだら": "条件形「稼いだら」に「そうだ」は続かず、文が成立しない。", "稼げば": "仮定形に「そうだ」は続かず、文が成立しない。", "稼ごう": "意志形に「そうだ」は続かず、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51923, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「道が狭い」の主格の「が」。"}, {"text": "を", "is_correct": false, "explanation": "「道を狭くて」は非文。"}, {"text": "に", "is_correct": false, "explanation": "「道に狭くて」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「道へ狭くて」は非文。"}], "correct_answer": "が", "explanations": {"が": "「道が狭い」の主格の「が」。", "を": "「道を狭くて」は非文。", "に": "「道に狭くて」は非文。", "へ": "「道へ狭くて」は非文。"}, "error_tags": {"を": "object_marker", "に": "target_location", "へ": "direction"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "閉鎖", "is_correct": true, "explanation": "道を閉じて通れなくすることで、通行の反対。"}, {"text": "往来", "is_correct": false, "explanation": "行き来することで、通行に近い意味。"}, {"text": "通過", "is_correct": false, "explanation": "通り過ぎることで、通行に近い意味。"}, {"text": "開通", "is_correct": false, "explanation": "道が通じることで、反対ではない。"}], "correct_answer": "閉鎖", "explanations": {"閉鎖": "道を閉じて通れなくすることで、通行の反対。", "往来": "行き来することで、通行に近い意味。", "通過": "通り過ぎることで、通行に近い意味。", "開通": "道が通じることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51923, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「この道の通行」と通行の対象を修飾する「の」。"}, {"text": "を", "is_correct": false, "explanation": "「通行が制限される」の文で「この道を」とは言えず、非文。"}, {"text": "に", "is_correct": false, "explanation": "「この道に通行が制限される」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「この道へ通行が」は非文。"}], "correct_answer": "の", "explanations": {"の": "「この道の通行」と通行の対象を修飾する「の」。", "を": "「通行が制限される」の文で「この道を」とは言えず、非文。", "に": "「この道に通行が制限される」は非文。", "へ": "「この道へ通行が」は非文。"}, "error_tags": {"を": "object_marker", "に": "target_location", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遮断", "is_correct": true, "explanation": "通れなくすることで、通行の反対。"}, {"text": "通勤", "is_correct": false, "explanation": "勤め先へ通うことで、反対ではない。"}, {"text": "歩行", "is_correct": false, "explanation": "歩くことで、反対ではない。"}, {"text": "運行", "is_correct": false, "explanation": "車などが決まった道を動くことで、反対ではない。"}], "correct_answer": "遮断", "explanations": {"遮断": "通れなくすることで、通行の反対。", "通勤": "勤め先へ通うことで、反対ではない。", "歩行": "歩くことで、反対ではない。", "運行": "車などが決まった道を動くことで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51923, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が道を通ること", "primary_collocate": null, "pronunciation": "つうこう", "ipa": "tsɯːkoː", "syllable_count": 4, "sentences": [{"text": "ここは通行できる。", "target_word": "通行", "complexity_tier": "T1", "furigana": "ここは通行[つうこう]できる。", "sentence_source": "generated"}, {"text": "通行を許可する。", "target_word": "通行", "complexity_tier": "T1", "furigana": "通行[つうこう]を許可[きょか]する。", "sentence_source": "generated"}, {"text": "道が狭くて通行しにくいです。", "target_word": "通行", "complexity_tier": "T2", "furigana": "道[みち]が狭[せま]くて通行[つうこう]しにくいです。", "sentence_source": "generated"}, {"text": "夜は通行する人が少ないです。", "target_word": "通行", "complexity_tier": "T2", "furigana": "夜[よる]は通行[つうこう]する人[ひと]が少[すく]ないです。", "sentence_source": "generated"}, {"text": "この橋の通行は無料です。", "target_word": "通行", "complexity_tier": "T2", "furigana": "この橋[はし]の通行[つうこう]は無料[むりょう]です。", "sentence_source": "generated"}, {"text": "雨の日は、車の通行に気をつけましょう。", "target_word": "通行", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、車[くるま]の通行[つうこう]に気[き]をつけましょう。", "sentence_source": "generated"}, {"text": "通行の邪魔になるので、荷物をどけてください。", "target_word": "通行", "complexity_tier": "T3", "furigana": "通行[つうこう]の邪魔[じゃま]になるので、荷物[にもつ]をどけてください。", "sentence_source": "generated"}, {"text": "祭りの間は、この道の通行が制限される。", "target_word": "通行", "complexity_tier": "T4", "furigana": "祭[まつ]りの間[あいだ]は、この道[みち]の通行[つうこう]が制限[せいげん]される。", "sentence_source": "generated"}, {"text": "山道は通行が危険だと言われている。", "target_word": "通行", "complexity_tier": "T4", "furigana": "山道[やまみち]は通行[つうこう]が危険[きけん]だと言[い]われている。", "sentence_source": "generated"}, {"text": "川が増水したため、通行できなくなった。", "target_word": "通行", "complexity_tier": "T3", "furigana": "川[かわ]が増水[ぞうすい]したため、通行[つうこう]できなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通行する", "label": "活用"}, {"form": "通行人", "label": "派生"}, {"form": "通行止め", "label": "派生"}, {"form": "通行料", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人や車が道を通ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
