INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「通行が多い」で、多いものを表す主格の「が」。"}, {"text": "を", "is_correct": false, "explanation": "「人の通行を多く」は述語と合わず非文。"}, {"text": "で", "is_correct": false, "explanation": "「人の通行で多く」は非文。"}, {"text": "へ", "is_correct": false, "explanation": "「人の通行へ多く」は非文。"}], "correct_answer": "が", "explanations": {"が": "「通行が多い」で、多いものを表す主格の「が」。", "を": "「人の通行を多く」は述語と合わず非文。", "で": "「人の通行で多く」は非文。", "へ": "「人の通行へ多く」は非文。"}, "error_tags": {"を": "object_marker", "で": "location_means", "へ": "direction"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遮断", "is_correct": true, "explanation": "通れなくすることで、通行の反対。"}, {"text": "往来", "is_correct": false, "explanation": "行き来することで、通行に近い意味。"}, {"text": "通過", "is_correct": false, "explanation": "通り過ぎることで、通行に近い意味。"}, {"text": "開通", "is_correct": false, "explanation": "道が通じることで、反対ではない。"}], "correct_answer": "遮断", "explanations": {"遮断": "通れなくすることで、通行の反対。", "往来": "行き来することで、通行に近い意味。", "通過": "通り過ぎることで、通行に近い意味。", "開通": "道が通じることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
