INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "道路や場所を通り過ぎること。また、その交通や人の流れ。", "primary_collocate": null, "pronunciation": "つうこう", "ipa": "tsɯːkoː", "syllable_count": 4, "sentences": [{"text": "駅前の道路は朝になると人の通行が多く、自転車は降りて押さなければならない。", "target_word": "通行", "complexity_tier": "T5", "furigana": "駅前[えきまえ]の道路[どうろ]は朝[あさ]になると人[ひと]の通行[つうこう]が多[おお]く、自転車[じてんしゃ]は降[お]りて押[お]さなければならない。", "sentence_source": "generated"}, {"text": "ここは通行できません。", "target_word": "通行", "complexity_tier": "T2", "furigana": "ここは通行[つうこう]できません。", "sentence_source": "generated"}, {"text": "この道は車の通行が多い。", "target_word": "通行", "complexity_tier": "T2", "furigana": "この道[みち]は車[くるま]の通行[つうこう]が多[おお]い。", "sentence_source": "generated"}, {"text": "夜は通行する人が少ない。", "target_word": "通行", "complexity_tier": "T2", "furigana": "夜[よる]は通行[つうこう]する人[ひと]が少[すく]ない。", "sentence_source": "generated"}, {"text": "工事のため、通行が禁止されています。", "target_word": "通行", "complexity_tier": "T3", "furigana": "工事[こうじ]のため、通行[つうこう]が禁止[きんし]されています。", "sentence_source": "generated"}, {"text": "雪で道が狭くなり、通行が難しくなった。", "target_word": "通行", "complexity_tier": "T3", "furigana": "雪[ゆき]で道[みち]が狭[せま]くなり、通行[つうこう]が難[むずか]しくなった。", "sentence_source": "generated"}, {"text": "歩行者の通行を妨げないでください。", "target_word": "通行", "complexity_tier": "T3", "furigana": "歩行者[ほこうしゃ]の通行[つうこう]を妨[さまた]げないでください。", "sentence_source": "generated"}, {"text": "橋は一般車両の通行が許可されている。", "target_word": "通行", "complexity_tier": "T4", "furigana": "橋[はし]は一般車両[いっぱんしゃりょう]の通行[つうこう]が許可[きょか]されている。", "sentence_source": "generated"}, {"text": "通行を許可するには、事前の申請が必要です。", "target_word": "通行", "complexity_tier": "T4", "furigana": "通行[つうこう]を許可[きょか]するには、事前[じぜん]の申請[しんせい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "この狭い道を通行するときは、注意してください。", "target_word": "通行", "complexity_tier": "T4", "furigana": "この狭[せま]い道[みち]を通行[つうこう]するときは、注意[ちゅうい]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通行する", "label": "活用"}, {"form": "通行人", "label": "派生"}, {"form": "通行止め", "label": "派生"}, {"form": "通行料", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 道や場所を通ること、またその交通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6ab7e1-b183-4ad7-bb07-3e9856366fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通行", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "通告", "is_correct": false, "explanation": "「つうこく」で最後の一拍が異なる。"}, {"text": "痛恨", "is_correct": false, "explanation": "「つうこん」で最後の一拍が異なる。"}, {"text": "登校", "is_correct": false, "explanation": "「とうこう」で最初の一拍が異なる。"}], "explanations": {"通行": "見出し語そのもの。", "通告": "「つうこく」で最後の一拍が異なる。", "痛恨": "「つうこん」で最後の一拍が異なる。", "登校": "「とうこう」で最初の一拍が異なる。"}, "sentence_index": null, "correct_answer": "通行"}, "level_3": {"options": [{"text": "通行", "is_correct": true, "explanation": "朝に道路を通る人が多いという意味で、文意に合う。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、朝の道路で人の結婚が多いとは言えない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、道路の様子を表す語として意味が合わない。"}, {"text": "入院", "is_correct": false, "explanation": "形は合うが、道路で人の入院が多いとは言えない。"}], "explanations": {"通行": "朝に道路を通る人が多いという意味で、文意に合う。", "結婚": "形は合うが、朝の道路で人の結婚が多いとは言えない。", "卒業": "形は合うが、道路の様子を表す語として意味が合わない。", "入院": "形は合うが、道路で人の入院が多いとは言えない。"}, "sentence_index": 0, "correct_answer": "通行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この小説は通行がとても面白かった。", "explanation": "「通行」は道を通ることで、物語の内容を表さない。"}, {"text": "彼は通行を食べて元気になった。", "explanation": "「通行」は食べ物ではないので「食べる」とは結びつかない。"}, {"text": "鉛筆の通行が切れたので買いに行く。", "explanation": "「通行」は物の在庫や量を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通行", "is_correct": true, "explanation": "見出し語そのもの。"}, {"text": "風光", "is_correct": false, "explanation": "「ふうこう」で最初の一拍が異なる。"}, {"text": "崇高", "is_correct": false, "explanation": "「すうこう」で最初の一拍が異なる。"}, {"text": "有効", "is_correct": false, "explanation": "「ゆうこう」で最初の一拍が異なる。"}], "explanations": {"通行": "見出し語そのもの。", "風光": "「ふうこう」で最初の一拍が異なる。", "崇高": "「すうこう」で最初の一拍が異なる。", "有効": "「ゆうこう」で最初の一拍が異なる。"}, "sentence_index": null, "correct_answer": "通行"}, "level_3": {"options": [{"text": "通行", "is_correct": true, "explanation": "歩行者の通り道を妨げないという意味に合う。"}, {"text": "営業", "is_correct": false, "explanation": "形は合うが意味が合わない。歩行者の営業は不自然。"}, {"text": "収穫", "is_correct": false, "explanation": "形は合うが意味が合わない。歩行者が収穫するとは言えない。"}, {"text": "販売", "is_correct": false, "explanation": "形は合うが意味が合わない。歩行者の販売は不自然。"}], "explanations": {"通行": "歩行者の通り道を妨げないという意味に合う。", "営業": "形は合うが意味が合わない。歩行者の営業は不自然。", "収穫": "形は合うが意味が合わない。歩行者が収穫するとは言えない。", "販売": "形は合うが意味が合わない。歩行者の販売は不自然。"}, "sentence_index": 6, "correct_answer": "通行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は通行で熱が出て学校を休んだ。", "explanation": "「通行」は病気や熱の原因を表す語ではない。"}, {"text": "彼女は通行を歌うのが上手だ。", "explanation": "「通行」は歌えるものではない。"}, {"text": "冷蔵庫の通行が切れたので買いに行く。", "explanation": "「通行」は物の在庫を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雪のため、この道路を通行が禁止された。", "corrected_sentence": "大雪のため、この道路は通行が禁止された。", "error_description": "「通行が禁止された」の主題は「を」ではなく「は」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51924, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この橋に通行する車は多い。", "corrected_sentence": "この橋を通行する車は多い。", "error_description": "通る場所は「に」ではなく「を」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35199de4-2e5f-4578-a7ff-254ee2598ebe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「予定を立てた」の「を」で、立てる行為の対象を示す目的語。"}, {"text": "が", "is_correct": false, "explanation": "「予定が立てた」だと予定が立てる主体になり、対象を示せないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段・場所を示すので、「勉強の予定で立てた」は対象を表せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すので、「勉強の予定に立てた」では目的語にならない。"}], "correct_answer": "を", "explanations": {"を": "「予定を立てた」の「を」で、立てる行為の対象を示す目的語。", "が": "「予定が立てた」だと予定が立てる主体になり、対象を示せないので合わない。", "で": "「で」は手段・場所を示すので、「勉強の予定で立てた」は対象を表せず不自然。", "に": "「に」は場所や相手を示すので、「勉強の予定に立てた」では目的語にならない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "に": "場所・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「献立を立てる」の「を」で、立てる行為の対象を示す目的語。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「献立と立てる」では対象を表せず不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すので、「献立から立てる」は対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「献立へ立てる」は対象を表せず合わない。"}], "correct_answer": "を", "explanations": {"を": "「献立を立てる」の「を」で、立てる行為の対象を示す目的語。", "と": "「と」は並列や共同を示すので、「献立と立てる」では対象を表せず不自然。", "から": "「から」は起点を示すので、「献立から立てる」は対象を表せない。", "へ": "「へ」は方向を示すので、「献立へ立てる」は対象を表せず合わない。"}, "error_tags": {"と": "並列・共同", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分で何かを決めて、それをやるために準備をすること。", "primary_collocate": null, "pronunciation": "たてる", "ipa": "tateɾɯ", "syllable_count": 3, "sentences": [{"text": "夏休みの旅行の計画を立てる。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの旅行[りょこう]の計画[けいかく]を立[た]てる。", "sentence_source": "generated"}, {"text": "試験の前に、勉強の予定を立てた。", "target_word": "立てた", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]に、勉強[べんきょう]の予定[よてい]を立[た]てた。", "sentence_source": "generated"}, {"text": "今年は毎日運動するという目標を立てた。", "target_word": "立てた", "complexity_tier": "T3", "furigana": "今年[ことし]は毎日[まいにち]運動[うんどう]するという目標[もくひょう]を立[た]てた。", "sentence_source": "generated"}, {"text": "先にスケジュールを立てておけば、慌てずに済む。", "target_word": "立てて", "complexity_tier": "T3", "furigana": "先[さき]にスケジュールを立[た]てておけば、慌[あわ]てずに済[す]む。", "sentence_source": "generated"}, {"text": "彼は将来のために、貯金の計画を立てている。", "target_word": "立てて", "complexity_tier": "T3", "furigana": "彼[かれ]は将来[しょうらい]のために、貯金[ちょきん]の計画[けいかく]を立[た]てている。", "sentence_source": "generated"}, {"text": "週末の予定を立てる前に、天気を調べた。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]の予定[よてい]を立[た]てる前[まえ]に、天気[てんき]を調[しら]べた。", "sentence_source": "generated"}, {"text": "長い旅行では、無理のない計画を立てることが大切だ。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "長[なが]い旅行[りょこう]では、無理[むり]のない計画[けいかく]を立[た]てることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "母は、家族の食事の献立を立てるのが上手だ。", "target_word": "立てる", "complexity_tier": "T3", "furigana": "母[はは]は、家族[かぞく]の食事[しょくじ]の献立[こんだて]を立[た]てるのが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "チームで話し合って、新しい作戦を立てた。", "target_word": "立てた", "complexity_tier": "T3", "furigana": "チームで話[はな]し合[あ]って、新[あたら]しい作戦[さくせん]を立[た]てた。", "sentence_source": "generated"}, {"text": "目標を立てても、続けなければ意味がない。", "target_word": "立てて", "complexity_tier": "T3", "furigana": "目標[もくひょう]を立[た]てても、続[つづ]けなければ意味[いみ]がない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "立てる", "label": "辞書形"}, {"form": "立てた", "label": "過去形"}, {"form": "立てて", "label": "て形"}, {"form": "立てない", "label": "否定形"}, {"form": "立てれば", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "計画・予定・目標などを自分で考えて決めること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8f1722b-8f6a-484b-8e04-67ac74b730cc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立てる", "is_correct": true, "explanation": "計画を作る意味で、夏休みの旅行の計画に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "「食べる」は口に入れる意味で、計画とは合わない。"}, {"text": "洗う", "is_correct": false, "explanation": "「洗う」は汚れを落とす意味で、計画には使えない。"}, {"text": "払う", "is_correct": false, "explanation": "「払う」は代金や埃を取り除く意味で、計画には使えない。"}], "explanations": {"立てる": "計画を作る意味で、夏休みの旅行の計画に合う。", "食べる": "「食べる」は口に入れる意味で、計画とは合わない。", "洗う": "「洗う」は汚れを落とす意味で、計画には使えない。", "払う": "「払う」は代金や埃を取り除く意味で、計画には使えない。"}, "sentence_index": 0, "correct_answer": "立てる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の天気を立てた。", "explanation": "ここは〈予想する〉の意味。立てるは計画や予定を作ることで、天気を予想する場合には使わない。"}, {"text": "行き先はまだ立てていない。", "explanation": "ここは〈決める〉の意味。立てるは計画や予定を作ることで、行き先を決める場面では使わない。"}, {"text": "母は毎日、料理を立てている。", "explanation": "ここは〈作る〉の意味。料理は作るもので、立てるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立てる", "is_correct": true, "explanation": "計画を作る意味で、無理のない計画を立てることが大切だという文に合う。"}, {"text": "掘る", "is_correct": false, "explanation": "「掘る」は地面などを削り取る意味で、計画には使えない。"}, {"text": "吹く", "is_correct": false, "explanation": "「吹く」は風や息を出す意味で、計画には使えない。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る」は寝る意味で、計画の対象にはならない。"}], "explanations": {"立てる": "計画を作る意味で、無理のない計画を立てることが大切だという文に合う。", "掘る": "「掘る」は地面などを削り取る意味で、計画には使えない。", "吹く": "「吹く」は風や息を出す意味で、計画には使えない。", "眠る": "「眠る」は寝る意味で、計画の対象にはならない。"}, "sentence_index": 6, "correct_answer": "立てる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しいアイデアを立てた。", "explanation": "ここは〈考える〉の意味。立てるは計画や予定を作る意味で、アイデアには使わない。"}, {"text": "申請書を立てて、提出した。", "explanation": "ここは〈作成する〉の意味。立てるは計画などを決める意味で、書類を作る場合には使わない。"}, {"text": "テストで高い点を立てた。", "explanation": "ここは〈取る〉の意味。立てるは計画や予定を作る意味で、点数を得る場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先に計画を立てるば、慌てずに済む。", "corrected_sentence": "先に計画を立てれば、慌てずに済む。", "error_description": "「立てる」の仮定形は「立てれば」。「立てるば」は誤った形で、正しくは「立てれば」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "立てた", "is_correct": true, "explanation": "過去形で、試験の前に予定を立てたという過去の出来事に合う。"}, {"text": "立てて", "is_correct": false, "explanation": "て形で、文末に置くと文が途中で切れてしまう。"}, {"text": "立てれば", "is_correct": false, "explanation": "仮定形で、「〜れば」で続く文が必要になり、ここでは文が成り立たない。"}, {"text": "立て", "is_correct": false, "explanation": "命令形になり、過去の出来事を述べる文に合わない。"}], "correct_form": "立てた", "base_form": "立てる", "form_label": "過去形", "sentence_index": 1, "explanations": {"立てた": "過去形で、試験の前に予定を立てたという過去の出来事に合う。", "立てて": "て形で、文末に置くと文が途中で切れてしまう。", "立てれば": "仮定形で、「〜れば」で続く文が必要になり、ここでは文が成り立たない。", "立て": "命令形になり、過去の出来事を述べる文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51925, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は旅行の計画に立てるのに慣れている。", "corrected_sentence": "彼は旅行の計画を立てるのに慣れている。", "error_description": "「立てる」は目的語に「を」をとる。「計画に」は誤りで、正しくは「計画を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "立てる", "is_correct": true, "explanation": "辞書形で、「〜のが上手だ」と名詞化して続けられる。"}, {"text": "立てず", "is_correct": false, "explanation": "否定の連用形で、「〜のが上手だ」とは続かない。"}, {"text": "立てろ", "is_correct": false, "explanation": "命令形で、命令の文になり、「〜のが上手だ」と続けられない。"}, {"text": "立てよう", "is_correct": false, "explanation": "意向形で、「〜のが」に続けられず、文が成り立たない。"}], "correct_form": "立てる", "base_form": "立てる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"立てる": "辞書形で、「〜のが上手だ」と名詞化して続けられる。", "立てず": "否定の連用形で、「〜のが上手だ」とは続かない。", "立てろ": "命令形で、命令の文になり、「〜のが上手だ」と続けられない。", "立てよう": "意向形で、「〜のが」に続けられず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90ec2dfb-e78f-4e1a-ad62-d6ea71303c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
