INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51927, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "レモネードを主題として示す助詞で自然につながる。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}, {"text": "を", "is_correct": false, "explanation": "「甘くない」は目的語を取らないので、「レモネードを」では文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「レモネードの、あまり甘くなくて」は述語につながらない。"}], "correct_answer": "は", "explanations": {"は": "レモネードを主題として示す助詞で自然につながる。", "へ": "方向を表す助詞で、ここでは使えない。", "を": "「甘くない」は目的語を取らないので、「レモネードを」では文が成り立たない。", "の": "「レモネードの、あまり甘くなくて」は述語につながらない。"}, "error_tags": {"へ": "direction", "を": "object", "の": "possessive"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51927, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "レモンの味がする、甘い飲み物です。", "primary_collocate": null, "pronunciation": "れもねーど", "ipa": "ɾemoneːdo", "syllable_count": 5, "sentences": [{"text": "レモネードをください。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "レモネードをください。", "sentence_source": "generated"}, {"text": "レモネードは甘いです。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "レモネードはあまいです。", "sentence_source": "generated"}, {"text": "私はレモネードが好きです。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "わたしはレモネードがすきです。", "sentence_source": "generated"}, {"text": "レモネードを飲みました。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "レモネードをのみました。", "sentence_source": "generated"}, {"text": "夏になると、レモネードをよく飲む。", "target_word": "レモネード", "complexity_tier": "T4", "furigana": "なつになると、レモネードをよくのむ。", "sentence_source": "generated"}, {"text": "レモネードの中にレモンが入っている。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "レモネードのなかにレモンがはいっている。", "sentence_source": "generated"}, {"text": "兄はレモネードを飲みながら本を読んでいた。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "あにはレモネードをのみながらほんをよんでいた。", "sentence_source": "generated"}, {"text": "このレモネードはあまり甘くなくて、さっぱりしている。", "target_word": "レモネード", "complexity_tier": "T4", "furigana": "このレモネードはあまりあまくなくて、さっぱりしている。", "sentence_source": "generated"}, {"text": "レモネードを作るために、レモンを買ってきた。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "レモネードをつくるために、レモンをかってきた。", "sentence_source": "generated"}, {"text": "レモネードの方がジュースより甘くないと思う。", "target_word": "レモネード", "complexity_tier": "T4", "furigana": "レモネードのほうがジュースよりあまくないとおもう。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | レモン味の甘い冷たい飲み物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51927, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レモネード", "is_correct": true, "explanation": "注文する飲み物として意味が合う。"}, {"text": "空", "is_correct": false, "explanation": "形は合うが、「ください」と頼める物ではなく意味が合わない。"}, {"text": "電車", "is_correct": false, "explanation": "形は合うが、飲み物を頼む場面で意味が合わない。"}, {"text": "駅", "is_correct": false, "explanation": "形は合うが、「ください」と頼む物として意味が合わない。"}], "explanations": {"レモネード": "注文する飲み物として意味が合う。", "空": "形は合うが、「ください」と頼める物ではなく意味が合わない。", "電車": "形は合うが、飲み物を頼む場面で意味が合わない。", "駅": "形は合うが、「ください」と頼む物として意味が合わない。"}, "sentence_index": 0, "correct_answer": "レモネード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レモネードに乗って学校へ行きました。", "explanation": "レモネードは乗り物ではないので「乗る」は使えない。"}, {"text": "レモネードは熱い鉄でできた硬い道具です。", "explanation": "飲み物であるレモネードを道具の意味で使っている。"}, {"text": "レモネードで手紙を書きました。", "explanation": "レモネードは筆記用具として使う物ではなく、用法が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51927, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レモネード", "is_correct": true, "explanation": "飲みながら本を読む対象として意味が合う。"}, {"text": "石", "is_correct": false, "explanation": "形は合うが、石は飲む物ではなく意味が合わない。"}, {"text": "靴", "is_correct": false, "explanation": "形は合うが、靴は飲む物ではなく意味が合わない。"}, {"text": "電話", "is_correct": false, "explanation": "形は合うが、電話は飲む物ではなく意味が合わない。"}], "explanations": {"レモネード": "飲みながら本を読む対象として意味が合う。", "石": "形は合うが、石は飲む物ではなく意味が合わない。", "靴": "形は合うが、靴は飲む物ではなく意味が合わない。", "電話": "形は合うが、電話は飲む物ではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "レモネード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レモネードは毎朝六時に起きて散歩をする。", "explanation": "レモネードは飲み物なので、人のように起きて散歩はしない。"}, {"text": "レモネードを何度も折りたたんでかばんに入れた。", "explanation": "液体の飲み物は折りたためないので、使い方が合わない。"}, {"text": "このレモネードは五人の兄弟で、みんな背が高い。", "explanation": "レモネードを人間の兄弟の意味で使っており、誤りである。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51927, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、レモネードを着ました。", "corrected_sentence": "昨日、レモネードを飲みました。", "error_description": "レモネードは飲み物なので、動詞は「着る」ではなく「飲む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
