INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「飲みたい」の対象を表す助詞として自然である。"}, {"text": "に", "is_correct": false, "explanation": "「レモネードに飲みたい」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}, {"text": "で", "is_correct": false, "explanation": "「レモネードで飲みたい」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「飲みたい」の対象を表す助詞として自然である。", "に": "「レモネードに飲みたい」は文として成り立たない。", "へ": "方向を表す助詞で、ここでは使えない。", "で": "「レモネードで飲みたい」は意味が通らない。"}, "error_tags": {"に": "target_or_location", "へ": "direction", "で": "means_or_place"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "レモン果汁と砂糖などを混ぜて作った清涼飲料水。", "primary_collocate": null, "pronunciation": "れもねーど", "ipa": "ɾemoneːdo", "syllable_count": 5, "sentences": [{"text": "記録的な暑さが続く夏の午後、公園の入り方で一人の少年が手作りのレモネードを販売していた。", "target_word": "レモネード", "complexity_tier": "T6", "furigana": "きろくてきなあつさがつづくなつのごご、こうえんのいりかたでひとりのしょうねんがてづくりのレモネードをはんばいしていた。", "sentence_source": "mined"}, {"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "レモネード", "complexity_tier": "T6", "furigana": "つめたくてあまいレモネードは、あつさにつかれたひとびとののどをうるおし、しょうねんのどりょくはちいさなうりあげとなってかくじつにみをむすんでいった。", "sentence_source": "mined"}, {"text": "レモネードを一杯ください。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "レモネードをいっぱいください。", "sentence_source": "generated"}, {"text": "このレモネードはとても甘いです。", "target_word": "レモネード", "complexity_tier": "T2", "furigana": "このレモネードはとてもあまいです。", "sentence_source": "generated"}, {"text": "母が作ったレモネードを冷蔵庫で冷やしている。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "ははがつくったレモネードをれいぞうこでひやしている。", "sentence_source": "generated"}, {"text": "レモネードが好きな友達と、カフェに行きました。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "レモネードがすきなともだちと、カフェにいきました。", "sentence_source": "generated"}, {"text": "レモネードとコーヒーのどちらにしますか。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "レモネードとコーヒーのどちらにしますか。", "sentence_source": "generated"}, {"text": "暑い日は、冷たいレモネードが飲みたくなる。", "target_word": "レモネード", "complexity_tier": "T3", "furigana": "あついひは、つめたいレモネードがのみたくなる。", "sentence_source": "generated"}, {"text": "レモネードに氷を入れると、すぐに冷たくなる。", "target_word": "レモネード", "complexity_tier": "T4", "furigana": "レモネードにこおりをいれると、すぐにつめたくなる。", "sentence_source": "generated"}, {"text": "子どもたちにレモネードを売らせてみたら、全部売れた。", "target_word": "レモネード", "complexity_tier": "T4", "furigana": "こどもたちにレモネードをうらせてみたら、ぜんぶうれた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 果汁と砂糖で作る冷たい飲み物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "レモネード", "is_correct": true, "explanation": "手作りして販売する飲み物として意味が合う。"}, {"text": "暑さ", "is_correct": false, "explanation": "形は合うが、暑さは手作りして販売するものではなく意味が合わない。"}, {"text": "午後", "is_correct": false, "explanation": "形は合うが、時間帯を手作りして販売することはなく意味が合わない。"}, {"text": "公園", "is_correct": false, "explanation": "形は合うが、少年が手作りして販売する物としては意味が合わない。"}], "explanations": {"レモネード": "手作りして販売する飲み物として意味が合う。", "暑さ": "形は合うが、暑さは手作りして販売するものではなく意味が合わない。", "午後": "形は合うが、時間帯を手作りして販売することはなく意味が合わない。", "公園": "形は合うが、少年が手作りして販売する物としては意味が合わない。"}, "sentence_index": 0, "correct_answer": "レモネード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "レモネードに乗って駅まで行きました。", "explanation": "レモネードは飲み物で、乗り物ではないので「乗る」と使えない。"}, {"text": "レモネードは熱い鉄でできた硬い道具です。", "explanation": "レモネードを道具の意味で使っており、飲み物の意味から外れている。"}, {"text": "寒い朝、レモネードを着て出かけた。", "explanation": "レモネードは衣服ではないので「着る」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "レモネード", "is_correct": true, "explanation": "コーヒーと並べて選ぶ飲み物として意味が合う。"}, {"text": "椅子", "is_correct": false, "explanation": "形は合うが、コーヒーと並べて「どちらにしますか」と選ぶ物として意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、飲み物の選択として意味が合わない。"}, {"text": "教室", "is_correct": false, "explanation": "形は合うが、コーヒーと並べる選択肢として意味が合わない。"}], "explanations": {"レモネード": "コーヒーと並べて選ぶ飲み物として意味が合う。", "椅子": "形は合うが、コーヒーと並べて「どちらにしますか」と選ぶ物として意味が合わない。", "時計": "形は合うが、飲み物の選択として意味が合わない。", "教室": "形は合うが、コーヒーと並べる選択肢として意味が合わない。"}, "sentence_index": 6, "correct_answer": "レモネード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "レモネードは毎朝六時に起きて散歩をする。", "explanation": "レモネードは飲み物なので、人のように起きて散歩はしない。"}, {"text": "レモネードを何度も折りたたんで、かばんに入れた。", "explanation": "液体の飲み物は折りたためないので、使い方が合わない。"}, {"text": "このレモネードは五人の兄弟で、みんな背が高い。", "explanation": "レモネードを人間の兄弟の意味で使っており、誤りである。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑かったので、レモネードを食べた。", "corrected_sentence": "暑かったので、レモネードを飲んだ。", "error_description": "レモネードは飲み物なので「食べる」ではなく「飲む」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51928, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑い日は、冷たいレモネードを歩きたくなる。", "corrected_sentence": "暑い日は、冷たいレモネードを飲みたくなる。", "error_description": "レモネードに対する動詞が「歩く」になっている。正しくは「飲む」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "潤すの対象を表す助詞で自然である。"}, {"text": "に", "is_correct": false, "explanation": "「土に潤した」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「土で潤した」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "潤すの対象を表す助詞で自然である。", "に": "「土に潤した」は文として成り立たない。", "で": "「土で潤した」は意味が通らない。", "へ": "方向を表す助詞で、ここでは使えない。"}, "error_tags": {"に": "target_or_location", "で": "means_or_place", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾かす", "is_correct": true, "explanation": "水分を取り除く意味で、潤すの反対にあたる。"}, {"text": "濡らす", "is_correct": false, "explanation": "水分をつける意味で、反対ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "水で汚れを落とす意味で、反対ではない。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を下げる意味で、反対ではない。"}], "correct_answer": "乾かす", "explanations": {"乾かす": "水分を取り除く意味で、潤すの反対にあたる。", "濡らす": "水分をつける意味で、反対ではない。", "洗う": "水で汚れを落とす意味で、反対ではない。", "冷やす": "温度を下げる意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "潤すの対象を表す助詞で自然である。"}, {"text": "に", "is_correct": false, "explanation": "「大地に潤す」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "他動詞の対象に「が」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "潤すの対象を表す助詞で自然である。", "に": "「大地に潤す」は文として成り立たない。", "が": "他動詞の対象に「が」は使えない。", "へ": "方向を表す助詞で、ここでは使えない。"}, "error_tags": {"に": "target_or_location", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "枯らす", "is_correct": true, "explanation": "水分を失わせる意味で、潤すの反対にあたる。"}, {"text": "注ぐ", "is_correct": false, "explanation": "液体を入れる意味で、反対ではない。"}, {"text": "育てる", "is_correct": false, "explanation": "成長させる意味で、反対ではない。"}, {"text": "洗う", "is_correct": false, "explanation": "水で汚れを落とす意味で、反対ではない。"}], "correct_answer": "枯らす", "explanations": {"枯らす": "水分を失わせる意味で、潤すの反対にあたる。", "注ぐ": "液体を入れる意味で、反対ではない。", "育てる": "成長させる意味で、反対ではない。", "洗う": "水で汚れを落とす意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水やしめりけをあたえて、かわいたものをしっとりさせること。", "primary_collocate": null, "pronunciation": "うるおす", "ipa": "ɯɾɯosɯ", "syllable_count": 4, "sentences": [{"text": "水で喉を潤す。", "target_word": "潤す", "complexity_tier": "T1", "furigana": "みずでのどをうるおす。", "sentence_source": "generated"}, {"text": "雨が土を潤した。", "target_word": "潤した", "complexity_tier": "T1", "furigana": "あめがつちをうるおした。", "sentence_source": "generated"}, {"text": "リップクリームで唇を潤します。", "target_word": "潤します", "complexity_tier": "T2", "furigana": "リップクリームでくちびるをうるおします。", "sentence_source": "generated"}, {"text": "お茶を飲んで、喉を潤しました。", "target_word": "潤しました", "complexity_tier": "T2", "furigana": "おちゃをのんで、のどをうるおしました。", "sentence_source": "generated"}, {"text": "花に水をやって土を潤している。", "target_word": "潤している", "complexity_tier": "T3", "furigana": "はなにみずをやってつちをうるおしている。", "sentence_source": "generated"}, {"text": "化粧水で肌を潤してから、クリームをつけます。", "target_word": "潤して", "complexity_tier": "T3", "furigana": "けしょうすいではだをうるおしてから、クリームをつけます。", "sentence_source": "generated"}, {"text": "乾いた喉を潤すために、冷たい水を買った。", "target_word": "潤す", "complexity_tier": "T3", "furigana": "かわいたのどをうるおすために、つめたいみずをかった。", "sentence_source": "generated"}, {"text": "雨が降れば、乾いた大地を潤すだろう。", "target_word": "潤す", "complexity_tier": "T4", "furigana": "あめがふれば、かわいただいちをうるおすだろう。", "sentence_source": "generated"}, {"text": "雨に潤された畑は、緑がきれいだった。", "target_word": "潤された", "complexity_tier": "T4", "furigana": "あめにうるおされたはたけは、みどりがきれいだった。", "sentence_source": "generated"}, {"text": "冷たい水は喉を潤してくれる。", "target_word": "潤してくれる", "complexity_tier": "T3", "furigana": "つめたいみずはのどをうるおしてくれる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潤い", "label": "派生"}, {"form": "潤して", "label": "活用"}, {"form": "潤した", "label": "活用"}, {"form": "潤される", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 水分を与えて乾いた物をしっとりさせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潤す", "is_correct": true, "explanation": "水で喉に水分を与える意味で合う。"}, {"text": "壊す", "is_correct": false, "explanation": "形は合うが、水で喉を壊すのは意味が合わない。"}, {"text": "隠す", "is_correct": false, "explanation": "形は合うが、水で喉を隠すのは意味が合わない。"}, {"text": "折る", "is_correct": false, "explanation": "形は合うが、喉を折るのは意味が合わない。"}], "explanations": {"潤す": "水で喉に水分を与える意味で合う。", "壊す": "形は合うが、水で喉を壊すのは意味が合わない。", "隠す": "形は合うが、水で喉を隠すのは意味が合わない。", "折る": "形は合うが、喉を折るのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "潤す"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドライヤーで濡れた髪を潤しました。", "explanation": "ドライヤーは乾かす道具で、水分を与える潤すとは意味が合わない。"}, {"text": "歩いて、遠くの駅を潤しました。", "explanation": "駅は水分を与える対象ではなく、潤すの使い方が合わない。"}, {"text": "友達の宿題を潤して、先生に出した。", "explanation": "宿題には水分を与えられず、潤すの用法が誤りである。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潤す", "is_correct": true, "explanation": "乾いた喉に水分を与える意味で合う。"}, {"text": "壊す", "is_correct": false, "explanation": "形は合うが、水を買う目的として喉を壊すのは意味が合わない。"}, {"text": "数える", "is_correct": false, "explanation": "形は合うが、喉を数えるのは意味が合わない。"}, {"text": "隠す", "is_correct": false, "explanation": "形は合うが、水を買って喉を隠すのは意味が合わない。"}], "explanations": {"潤す": "乾いた喉に水分を与える意味で合う。", "壊す": "形は合うが、水を買う目的として喉を壊すのは意味が合わない。", "数える": "形は合うが、喉を数えるのは意味が合わない。", "隠す": "形は合うが、水を買って喉を隠すのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "潤す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この辞書は難しい言葉を潤してくれる。", "explanation": "言葉には水分を与えられず、潤すの用法が合わない。"}, {"text": "毎朝、犬が公園を潤して走っている。", "explanation": "走る行為と潤すは結びつかず、使い方が誤りである。"}, {"text": "このはさみは紙を潤してくれる。", "explanation": "はさみは物を切る道具で水分を与えないので、潤すの使い方が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨が土に潤した。", "corrected_sentence": "雨が土を潤した。", "error_description": "潤すの対象を表す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潤した", "is_correct": true, "explanation": "雨が土を潤した、という過去の文で自然である。"}, {"text": "潤い", "is_correct": false, "explanation": "名詞形なので、文末で述語にならない。"}, {"text": "潤して", "is_correct": false, "explanation": "て形なので、文末に置くと文が終わらない。"}, {"text": "潤される", "is_correct": false, "explanation": "受身形なので「土を」と合わず、意味が合わない。"}], "correct_form": "潤した", "base_form": "潤す", "form_label": "た形", "sentence_index": 1, "explanations": {"潤した": "雨が土を潤した、という過去の文で自然である。", "潤い": "名詞形なので、文末で述語にならない。", "潤して": "て形なので、文末に置くと文が終わらない。", "潤される": "受身形なので「土を」と合わず、意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51929, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷たい水は喉が潤してくれる。", "corrected_sentence": "冷たい水は喉を潤してくれる。", "error_description": "潤すの対象を表す助詞は「が」ではなく「を」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潤す", "is_correct": true, "explanation": "「だろう」に続く終止形で自然である。"}, {"text": "潤い", "is_correct": false, "explanation": "名詞形なので「だろう」に続けられない。"}, {"text": "潤して", "is_correct": false, "explanation": "て形なので「だろう」に続けられない。"}, {"text": "潤される", "is_correct": false, "explanation": "受身形なので「大地を」と合わず、意味が合わない。"}], "correct_form": "潤す", "base_form": "潤す", "form_label": "終止形", "sentence_index": 7, "explanations": {"潤す": "「だろう」に続く終止形で自然である。", "潤い": "名詞形なので「だろう」に続けられない。", "潤して": "て形なので「だろう」に続けられない。", "潤される": "受身形なので「大地を」と合わず、意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51930, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "潤すの対象を表す助詞で自然である。"}, {"text": "に", "is_correct": false, "explanation": "「喉に潤す」は文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "他動詞の対象に「が」は使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}], "correct_answer": "を", "explanations": {"を": "潤すの対象を表す助詞で自然である。", "に": "「喉に潤す」は文として成り立たない。", "が": "他動詞の対象に「が」は使えない。", "へ": "方向を表す助詞で、ここでは使えない。"}, "error_tags": {"に": "target_or_location", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "乾かす", "is_correct": true, "explanation": "水分を与える潤すの反対で、水分を取り除く意味。"}, {"text": "洗う", "is_correct": false, "explanation": "水を使う行為で、反対の意味ではない。"}, {"text": "満たす", "is_correct": false, "explanation": "いっぱいにする意味で、反対ではない。"}, {"text": "冷やす", "is_correct": false, "explanation": "温度を下げる意味で、反対ではない。"}], "correct_answer": "乾かす", "explanations": {"乾かす": "水分を与える潤すの反対で、水分を取り除く意味。", "洗う": "水を使う行為で、反対の意味ではない。", "満たす": "いっぱいにする意味で、反対ではない。", "冷やす": "温度を下げる意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51930, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "潤すの対象を表す助詞で自然である。"}, {"text": "に", "is_correct": false, "explanation": "「経済に潤した」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、ここでは使えない。"}, {"text": "と", "is_correct": false, "explanation": "「経済と潤した」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "潤すの対象を表す助詞で自然である。", "に": "「経済に潤した」は文として成り立たない。", "へ": "方向を表す助詞で、ここでは使えない。", "と": "「経済と潤した」は意味が通らない。"}, "error_tags": {"に": "target_or_location", "へ": "direction", "と": "companion"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "枯らす", "is_correct": true, "explanation": "水分や豊かさを奪う意味で、潤すの反対にあたる。"}, {"text": "育てる", "is_correct": false, "explanation": "成長させる意味で、反対ではない。"}, {"text": "注ぐ", "is_correct": false, "explanation": "液体を入れる意味で、反対ではない。"}, {"text": "豊かにする", "is_correct": false, "explanation": "潤すに近い意味で、反対ではない。"}], "correct_answer": "枯らす", "explanations": {"枯らす": "水分や豊かさを奪う意味で、潤すの反対にあたる。", "育てる": "成長させる意味で、反対ではない。", "注ぐ": "液体を入れる意味で、反対ではない。", "豊かにする": "潤すに近い意味で、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51930, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "水分を与えて乾燥を和らげる。また、心や生活に豊かさやゆとりをもたらす。", "primary_collocate": null, "pronunciation": "うるおす", "ipa": "ɯɾɯosɯ", "syllable_count": 4, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "潤し", "complexity_tier": "T6", "furigana": "つめたくてあまいレモネードは、あつさにつかれたひとびとののどをうるおし、しょうねんのどりょくはちいさなうりあげとなってかくじつにみをむすんでいった。", "sentence_source": "mined"}, {"text": "お茶で喉を潤す。", "target_word": "潤す", "complexity_tier": "T1", "furigana": "おちゃでのどをうるおす。", "sentence_source": "generated"}, {"text": "水を飲んで、渇いた体を潤しました。", "target_word": "潤しました", "complexity_tier": "T2", "furigana": "みずをのんで、かわいたからだをうるおしました。", "sentence_source": "generated"}, {"text": "雨が畑の土を潤している。", "target_word": "潤している", "complexity_tier": "T3", "furigana": "あめがはたけのつちをうるおしている。", "sentence_source": "generated"}, {"text": "音楽は私たちの心を潤してくれる。", "target_word": "潤してくれる", "complexity_tier": "T3", "furigana": "おんがくはわたしたちのこころをうるおしてくれる。", "sentence_source": "generated"}, {"text": "クリームで肌を潤さないと、すぐ乾燥する。", "target_word": "潤さない", "complexity_tier": "T4", "furigana": "クリームではだをうるおさないと、すぐかんそうする。", "sentence_source": "generated"}, {"text": "この映画は、疲れた心を潤す力がある。", "target_word": "潤す", "complexity_tier": "T3", "furigana": "このえいがは、つかれたこころをうるおすちからがある。", "sentence_source": "generated"}, {"text": "新しい工場は町の経済を潤した。", "target_word": "潤した", "complexity_tier": "T3", "furigana": "あたらしいこうじょうはまちのけいざいをうるおした。", "sentence_source": "generated"}, {"text": "喉を潤したい人のために、水を用意した。", "target_word": "潤したい", "complexity_tier": "T3", "furigana": "のどをうるおしたいひとのために、みずをよういした。", "sentence_source": "generated"}, {"text": "観光客の増加が、地元の商店を潤すだろう。", "target_word": "潤す", "complexity_tier": "T3", "furigana": "かんこうきゃくのぞうかが、じもとのしょうてんをうるおすだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潤い", "label": "派生"}, {"form": "潤して", "label": "活用"}, {"form": "潤した", "label": "活用"}, {"form": "潤さない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 水分や豊かさを与えて満たす", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51930, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潤し", "is_correct": true, "explanation": "冷たいレモネードが喉に水分を与える意味で合う。"}, {"text": "傷つけ", "is_correct": false, "explanation": "形は合うが、冷たく甘い飲み物が喉を傷つけるのは意味が合わない。"}, {"text": "塞ぎ", "is_correct": false, "explanation": "形は合うが、レモネードが喉を塞ぐのは意味が合わない。"}, {"text": "削り", "is_correct": false, "explanation": "形は合うが、飲み物が喉を削るのは意味が合わない。"}], "explanations": {"潤し": "冷たいレモネードが喉に水分を与える意味で合う。", "傷つけ": "形は合うが、冷たく甘い飲み物が喉を傷つけるのは意味が合わない。", "塞ぎ": "形は合うが、レモネードが喉を塞ぐのは意味が合わない。", "削り": "形は合うが、飲み物が喉を削るのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "潤し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "砂漠の乾いた砂を、炎が潤している。", "explanation": "炎は水分を与えず乾かすので、潤すの使い方が合わない。"}, {"text": "毎日、掃除機で床を潤している。", "explanation": "掃除機は水分を与えないので、潤すと結びつかない。"}, {"text": "ドライヤーで濡れた髪を潤して、完全に乾かした。", "explanation": "ドライヤーで乾かす行為に潤すを使うのは誤りである。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51930, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潤す", "is_correct": true, "explanation": "映画が疲れた心に豊かさを与える意味で合う。"}, {"text": "干す", "is_correct": false, "explanation": "形は合うが、心を干すという言い方はなく意味が合わない。"}, {"text": "数える", "is_correct": false, "explanation": "形は合うが、心を数えるのは意味が合わない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "形は合うが、心を運ぶという意味はここに合わない。"}], "explanations": {"潤す": "映画が疲れた心に豊かさを与える意味で合う。", "干す": "形は合うが、心を干すという言い方はなく意味が合わない。", "数える": "形は合うが、心を数えるのは意味が合わない。", "運ぶ": "形は合うが、心を運ぶという意味はここに合わない。"}, "sentence_index": 6, "correct_answer": "潤す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日の運動が、机の足を潤している。", "explanation": "机の足には潤す対象としての水分も豊かさもなく、誤りである。"}, {"text": "彼は歌いながら重い荷物を潤して運んだ。", "explanation": "荷物を運ぶ行為に潤すは使えない。"}, {"text": "雪が積もって、道路の車を潤してしまった。", "explanation": "雪が車を潤すという意味は成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
