INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「仕事で疲れる」で原因を表す。"}, {"text": "を", "is_correct": false, "explanation": "「疲れる」は自動詞なので「を」は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では原因を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「仕事と疲れた」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「仕事で疲れる」で原因を表す。", "を": "「疲れる」は自動詞なので「を」は取れない。", "へ": "方向を表す「へ」では原因を示せない。", "と": "「仕事と疲れた」では意味が通らない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "companion"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "元気になる", "is_correct": true, "explanation": "力がなくなる「疲れる」と反対に、力が戻る状態を表す。"}, {"text": "眠る", "is_correct": false, "explanation": "疲れの結果の行動で、反対ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "疲れとは関係がなく、反対ではない。"}, {"text": "歩く", "is_correct": false, "explanation": "動作で、疲れの反対ではない。"}], "correct_answer": "元気になる", "explanations": {"元気になる": "力がなくなる「疲れる」と反対に、力が戻る状態を表す。", "眠る": "疲れの結果の行動で、反対ではない。", "笑う": "疲れとは関係がなく、反対ではない。", "歩く": "動作で、疲れの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
