INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "体や心の力がなくなって、休みたくなること。", "primary_collocate": null, "pronunciation": "つかれる", "ipa": "tsɯkaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "私は疲れました。", "target_word": "疲れました", "complexity_tier": "T1", "furigana": "わたしはつかれました。", "sentence_source": "generated"}, {"text": "今日は仕事で疲れた。", "target_word": "疲れた", "complexity_tier": "T1", "furigana": "きょうはしごとでつかれた。", "sentence_source": "generated"}, {"text": "走ったので、とても疲れています。", "target_word": "疲れています", "complexity_tier": "T2", "furigana": "はしったので、とてもつかれています。", "sentence_source": "generated"}, {"text": "疲れると、すぐ眠くなります。", "target_word": "疲れる", "complexity_tier": "T4", "furigana": "つかれると、すぐねむくなります。", "sentence_source": "generated"}, {"text": "疲れた時は、ゆっくりお風呂に入る。", "target_word": "疲れた", "complexity_tier": "T3", "furigana": "つかれたときは、ゆっくりおふろにはいる。", "sentence_source": "generated"}, {"text": "勉強しすぎて、頭が疲れてしまった。", "target_word": "疲れて", "complexity_tier": "T3", "furigana": "べんきょうしすぎて、あたまがつかれてしまった。", "sentence_source": "generated"}, {"text": "あまり疲れない運動を始めたい。", "target_word": "疲れない", "complexity_tier": "T3", "furigana": "あまりつかれないうんどうをはじめたい。", "sentence_source": "generated"}, {"text": "疲れているなら、早く帰って休んだほうがいい。", "target_word": "疲れている", "complexity_tier": "T4", "furigana": "つかれているなら、はやくかえってやすんだほうがいい。", "sentence_source": "generated"}, {"text": "疲れて何も食べたくない。", "target_word": "疲れて", "complexity_tier": "T3", "furigana": "つかれてなにもたべたくない。", "sentence_source": "generated"}, {"text": "疲れる仕事の後は、休みが必要だ。", "target_word": "疲れる", "complexity_tier": "T3", "furigana": "つかれるしごとのあとは、やすみがひつようだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲れ", "label": "派生"}, {"form": "疲れて", "label": "活用"}, {"form": "疲れた", "label": "活用"}, {"form": "疲れない", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 力がなくなって休みたくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疲れる", "is_correct": true, "explanation": "見出し語そのもの。「つかれる」。"}, {"text": "仕える", "is_correct": false, "explanation": "「つかえる」。「れ」が「え」に変わる1拍違い。"}, {"text": "浮かれる", "is_correct": false, "explanation": "「うかれる」。「つ」が「う」に変わる1拍違い。"}, {"text": "捕まる", "is_correct": false, "explanation": "「つかまる」。「れ」が「ま」に変わる1拍違い。"}], "explanations": {"疲れる": "見出し語そのもの。「つかれる」。", "仕える": "「つかえる」。「れ」が「え」に変わる1拍違い。", "浮かれる": "「うかれる」。「つ」が「う」に変わる1拍違い。", "捕まる": "「つかまる」。「れ」が「ま」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "疲れる"}, "level_3": {"options": [{"text": "疲れました", "is_correct": true, "explanation": "「私」の状態を丁寧に述べる自然な形。"}, {"text": "割れました", "is_correct": false, "explanation": "形は合うが、人には使えず意味が合わない。"}, {"text": "咲きました", "is_correct": false, "explanation": "形は合うが、「私は」の述語として意味が合わない。"}, {"text": "溶けました", "is_correct": false, "explanation": "形は合うが、人の状態として意味が合わない。"}], "explanations": {"疲れました": "「私」の状態を丁寧に述べる自然な形。", "割れました": "形は合うが、人には使えず意味が合わない。", "咲きました": "形は合うが、「私は」の述語として意味が合わない。", "溶けました": "形は合うが、人の状態として意味が合わない。"}, "sentence_index": 0, "correct_answer": "疲れました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石が疲れると、すぐ割れます。", "explanation": "「疲れる」は人や生き物に使い、石には使えない。"}, {"text": "友達を疲れると、すぐ眠くなります。", "explanation": "「疲れる」は自動詞なので「を」で対象を取れない。"}, {"text": "疲れると、すぐ元気になります。", "explanation": "「疲れる」は力がなくなることで、元気になる結果とは意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "疲れる", "is_correct": true, "explanation": "見出し語そのもの。「つかれる」。"}, {"text": "いかれる", "is_correct": false, "explanation": "「いかれる」。「つ」が「い」に変わる1拍違い。"}, {"text": "束ねる", "is_correct": false, "explanation": "「つかねる」。「れ」が「ね」に変わる1拍違い。"}, {"text": "潰れる", "is_correct": false, "explanation": "「つぶれる」。「か」が「ぶ」に変わる1拍違い。"}], "explanations": {"疲れる": "見出し語そのもの。「つかれる」。", "いかれる": "「いかれる」。「つ」が「い」に変わる1拍違い。", "束ねる": "「つかねる」。「れ」が「ね」に変わる1拍違い。", "潰れる": "「つぶれる」。「か」が「ぶ」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "疲れる"}, "level_3": {"options": [{"text": "疲れない", "is_correct": true, "explanation": "「あまり〜ない」で、疲れにくい運動を表し自然。"}, {"text": "咲かない", "is_correct": false, "explanation": "形は合うが、運動を修飾する意味が合わない。"}, {"text": "割れない", "is_correct": false, "explanation": "形は合うが、運動の性質として意味が合わない。"}, {"text": "溶けない", "is_correct": false, "explanation": "形は合うが、運動を修飾する意味が合わない。"}], "explanations": {"疲れない": "「あまり〜ない」で、疲れにくい運動を表し自然。", "咲かない": "形は合うが、運動を修飾する意味が合わない。", "割れない": "形は合うが、運動の性質として意味が合わない。", "溶けない": "形は合うが、運動を修飾する意味が合わない。"}, "sentence_index": 6, "correct_answer": "疲れない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "疲れる机は、掃除が必要だ。", "explanation": "「疲れる」は人や生き物に使い、机には使えない。"}, {"text": "仕事を疲れるので、休みが必要だ。", "explanation": "「疲れる」は自動詞なので「仕事を」とは言えない。"}, {"text": "楽で元気が出る仕事は、疲れる。", "explanation": "「疲れる」は力がなくなることで、元気が出る内容とは意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走りすぎて、足を疲れました。", "corrected_sentence": "走りすぎて、足が疲れました。", "error_description": "「疲れる」は自動詞なので、「足を」ではなく「足が」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "疲れた", "is_correct": true, "explanation": "文末で過去の状態を表すた形。"}, {"text": "疲れて", "is_correct": false, "explanation": "て形は文を終えられない。"}, {"text": "疲れ", "is_correct": false, "explanation": "名詞形では述語にならず文が成立しない。"}, {"text": "疲れれば", "is_correct": false, "explanation": "仮定形は文末に置けない。"}], "correct_form": "疲れた", "base_form": "疲れる", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"疲れた": "文末で過去の状態を表すた形。", "疲れて": "て形は文を終えられない。", "疲れ": "名詞形では述語にならず文が成立しない。", "疲れれば": "仮定形は文末に置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51931, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "忙しい日が続いて、姉を疲れている。", "corrected_sentence": "忙しい日が続いて、姉は疲れている。", "error_description": "「疲れる」の主語は「姉は」で、「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "疲れている", "is_correct": true, "explanation": "「なら」に続き、疲れた状態が続くことを表す。"}, {"text": "疲れて", "is_correct": false, "explanation": "て形は「なら」に直接続かない。"}, {"text": "疲れ", "is_correct": false, "explanation": "名詞形では「なら」に続かず、文意が成立しない。"}, {"text": "疲れれば", "is_correct": false, "explanation": "仮定形に「なら」は続けられない。"}], "correct_form": "疲れている", "base_form": "疲れる", "form_label": "ている形", "sentence_index": 7, "explanations": {"疲れている": "「なら」に続き、疲れた状態が続くことを表す。", "疲れて": "て形は「なら」に直接続かない。", "疲れ": "名詞形では「なら」に続かず、文意が成立しない。", "疲れれば": "仮定形に「なら」は続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「暑さに疲れる」で原因・対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「疲れる」は自動詞なので「を」は取れない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では原因を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「暑さが疲れた人々」は成立しない。"}], "correct_answer": "に", "explanations": {"に": "「暑さに疲れる」で原因・対象を表す。", "を": "「疲れる」は自動詞なので「を」は取れない。", "へ": "方向を表す「へ」では原因を示せない。", "が": "「暑さが疲れた人々」は成立しない。"}, "error_tags": {"を": "自動詞に目的語", "へ": "方向", "が": "主語"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "元気になる", "is_correct": true, "explanation": "力がなくなる「疲れる」と反対に、力が戻る状態を表す。"}, {"text": "眠る", "is_correct": false, "explanation": "反対ではなく、疲れの結果として起こる行動。"}, {"text": "笑う", "is_correct": false, "explanation": "疲れとは関係がなく、反対の意味でもない。"}, {"text": "怒る", "is_correct": false, "explanation": "感情の動きで、疲れの反対ではない。"}], "correct_answer": "元気になる", "explanations": {"元気になる": "力がなくなる「疲れる」と反対に、力が戻る状態を表す。", "眠る": "反対ではなく、疲れの結果として起こる行動。", "笑う": "疲れとは関係がなく、反対の意味でもない。", "怒る": "感情の動きで、疲れの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「疲れた人々の喉」で所有を表す。"}, {"text": "を", "is_correct": false, "explanation": "「人々を喉を潤し」では「を」が重なり不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「人々へ喉を」では名詞をつなげない。"}, {"text": "から", "is_correct": false, "explanation": "「人々から喉を潤し」では意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「疲れた人々の喉」で所有を表す。", "を": "「人々を喉を潤し」では「を」が重なり不自然。", "へ": "「人々へ喉を」では名詞をつなげない。", "から": "「人々から喉を潤し」では意味が通らない。"}, "error_tags": {"を": "目的語の重複", "へ": "方向", "から": "起点"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回復する", "is_correct": true, "explanation": "疲れた状態から力が戻ることで、「疲れる」の反対。"}, {"text": "困る", "is_correct": false, "explanation": "別の状態を表し、反対ではない。"}, {"text": "驚く", "is_correct": false, "explanation": "感情の動きで、疲れの反対ではない。"}, {"text": "悩む", "is_correct": false, "explanation": "気持ちの状態で、反対の意味ではない。"}], "correct_answer": "回復する", "explanations": {"回復する": "疲れた状態から力が戻ることで、「疲れる」の反対。", "困る": "別の状態を表し、反対ではない。", "驚く": "感情の動きで、疲れの反対ではない。", "悩む": "気持ちの状態で、反対の意味ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "体力や気力がなくなり、休みたい状態になること。", "primary_collocate": null, "pronunciation": "つかれる", "ipa": "tsɯkaɾeɾɯ", "syllable_count": 4, "sentences": [{"text": "冷たくて甘いレモネードは、暑さに疲れた人々の喉を潤し、少年の努力は小さな売上となって確実に実を結んでいった。", "target_word": "疲れた", "complexity_tier": "T6", "furigana": "つめたくてあまいレモネードは、あつさにつかれたひとびとののどをうるおし、しょうねんのどりょくはちいさなうりあげとなってかくじつにみをむすんでいった。", "sentence_source": "mined"}, {"text": "今日はとても疲れた。", "target_word": "疲れた", "complexity_tier": "T1", "furigana": "きょうはとてもつかれた。", "sentence_source": "generated"}, {"text": "毎日の仕事で疲れています。", "target_word": "疲れています", "complexity_tier": "T2", "furigana": "まいにちのしごとでつかれています。", "sentence_source": "generated"}, {"text": "疲れたら、少し休んでください。", "target_word": "疲れたら", "complexity_tier": "T4", "furigana": "つかれたら、すこしやすんでください。", "sentence_source": "generated"}, {"text": "長い時間歩いて、足が疲れた。", "target_word": "疲れた", "complexity_tier": "T3", "furigana": "ながいじかんあるいて、あしがつかれた。", "sentence_source": "generated"}, {"text": "疲れた顔をしているけど、大丈夫？", "target_word": "疲れた", "complexity_tier": "T3", "furigana": "つかれたかおをしているけど、だいじょうぶ？", "sentence_source": "generated"}, {"text": "彼は疲れているのに、まだ働いている。", "target_word": "疲れている", "complexity_tier": "T3", "furigana": "かれはつかれているのに、まだはたらいている。", "sentence_source": "generated"}, {"text": "子どもを疲れさせないように、早めに帰った。", "target_word": "疲れさせない", "complexity_tier": "T4", "furigana": "こどもをつかれさせないように、はやめにかえった。", "sentence_source": "generated"}, {"text": "疲れが取れないので、今日は早く寝ます。", "target_word": "疲れ", "complexity_tier": "T3", "furigana": "つかれがとれないので、きょうははやくねます。", "sentence_source": "generated"}, {"text": "会議が長すぎて、みんな疲れてしまった。", "target_word": "疲れて", "complexity_tier": "T3", "furigana": "かいぎがながすぎて、みんなつかれてしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲れ", "label": "派生"}, {"form": "疲れて", "label": "活用"}, {"form": "疲れた", "label": "活用"}, {"form": "疲れない", "label": "活用"}, {"form": "疲れさせる", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 体や気力が弱って休みたくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疲れる", "is_correct": true, "explanation": "見出し語そのもの。「つかれる」。"}, {"text": "使える", "is_correct": false, "explanation": "「つかえる」。「れ」が「え」に変わる1拍違い。"}, {"text": "捕まる", "is_correct": false, "explanation": "「つかまる」。「れ」が「ま」に変わる1拍違い。"}, {"text": "仕える", "is_correct": false, "explanation": "「つかえる」。「れ」が「え」に変わる1拍違い。"}], "explanations": {"疲れる": "見出し語そのもの。「つかれる」。", "使える": "「つかえる」。「れ」が「え」に変わる1拍違い。", "捕まる": "「つかまる」。「れ」が「ま」に変わる1拍違い。", "仕える": "「つかえる」。「れ」が「え」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "疲れる"}, "level_3": {"options": [{"text": "疲れた", "is_correct": true, "explanation": "暑さで体力を失った人々を表し、文脈に合う。"}, {"text": "咲いた", "is_correct": false, "explanation": "形は合うが、人々を修飾する意味が合わない。"}, {"text": "沈んだ", "is_correct": false, "explanation": "形は合うが、暑さの中で喉を潤す人々の描写として意味が合わない。"}, {"text": "割れた", "is_correct": false, "explanation": "形は合うが、人には使えず意味が合わない。"}], "explanations": {"疲れた": "暑さで体力を失った人々を表し、文脈に合う。", "咲いた": "形は合うが、人々を修飾する意味が合わない。", "沈んだ": "形は合うが、暑さの中で喉を潤す人々の描写として意味が合わない。", "割れた": "形は合うが、人には使えず意味が合わない。"}, "sentence_index": 0, "correct_answer": "疲れた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "空が疲れたので、雨が降りました。", "explanation": "「疲れる」は人や動物の体や気力について言い、空のようなものには使えない。"}, {"text": "宿題を疲れたので、少し休みます。", "explanation": "「疲れる」は自動詞で、「を」で対象を取る使い方はできない。"}, {"text": "ぐっすり眠ったので、とても疲れた気分です。", "explanation": "「疲れる」は力がなくなった状態で、十分に眠った結果とは意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "疲れる", "is_correct": true, "explanation": "見出し語そのもの。「つかれる」。"}, {"text": "掴める", "is_correct": false, "explanation": "「つかめる」。「れ」が「め」に変わる1拍違い。"}, {"text": "束ねる", "is_correct": false, "explanation": "「つかねる」。「れ」が「ね」に変わる1拍違い。"}, {"text": "掴まる", "is_correct": false, "explanation": "「つかまる」。「れ」が「ま」に変わる1拍違い。"}, {"text": "潰れる", "is_correct": false, "explanation": "「つぶれる」。「か」が「ぶ」に変わる1拍違い。"}], "explanations": {"疲れる": "見出し語そのもの。「つかれる」。", "掴める": "「つかめる」。「れ」が「め」に変わる1拍違い。", "束ねる": "「つかねる」。「れ」が「ね」に変わる1拍違い。", "掴まる": "「つかまる」。「れ」が「ま」に変わる1拍違い。", "潰れる": "「つぶれる」。「か」が「ぶ」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "疲れる"}, "level_3": {"options": [{"text": "疲れている", "is_correct": true, "explanation": "疲れた状態が続いていることを表し、「のに」と自然につながる。"}, {"text": "咲いている", "is_correct": false, "explanation": "形は合うが、彼の状態としては意味が合わない。"}, {"text": "割れている", "is_correct": false, "explanation": "形は合うが、人には使えず意味が合わない。"}, {"text": "溶けている", "is_correct": false, "explanation": "形は合うが、「まだ働いている」の逆接として意味が合わない。"}], "explanations": {"疲れている": "疲れた状態が続いていることを表し、「のに」と自然につながる。", "咲いている": "形は合うが、彼の状態としては意味が合わない。", "割れている": "形は合うが、人には使えず意味が合わない。", "溶けている": "形は合うが、「まだ働いている」の逆接として意味が合わない。"}, "sentence_index": 6, "correct_answer": "疲れている"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今日は元気いっぱいで、体がとても疲れている。", "explanation": "「疲れる」は力がなくなった状態で、元気いっぱいとは意味が矛盾する。"}, {"text": "この問題は難しくて、答えが疲れた。", "explanation": "「疲れる」は人や生き物に使い、答えのような抽象物には使えない。"}, {"text": "試験の結果を疲れて、みんな喜んだ。", "explanation": "「疲れる」は自動詞で、「結果を」と対象を取る使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "歩きすぎて、膝を疲れました。", "corrected_sentence": "歩きすぎて、膝が疲れました。", "error_description": "「疲れる」は自動詞なので、「膝を」ではなく「膝が」とする。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "疲れた", "is_correct": true, "explanation": "文末で過去の状態を表すた形。"}, {"text": "疲れて", "is_correct": false, "explanation": "て形は文を終えられず、ここでは合わない。"}, {"text": "疲れ", "is_correct": false, "explanation": "名詞形では「今日はとても〜。」の文が成立しない。"}, {"text": "疲れれば", "is_correct": false, "explanation": "仮定形は文末に置けず、ここでは合わない。"}], "correct_form": "疲れた", "base_form": "疲れる", "form_label": "過去形（た形）", "sentence_index": 1, "explanations": {"疲れた": "文末で過去の状態を表すた形。", "疲れて": "て形は文を終えられず、ここでは合わない。", "疲れ": "名詞形では「今日はとても〜。」の文が成立しない。", "疲れれば": "仮定形は文末に置けず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51932, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遠足で歩きすぎて、子どもたちをとても疲れています。", "corrected_sentence": "遠足で歩きすぎて、子どもたちはとても疲れています。", "error_description": "「疲れる」の主語は「子どもたちは」で、「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "疲れさせない", "is_correct": true, "explanation": "「子どもを」を受ける使役の否定形で意味が通る。"}, {"text": "疲れない", "is_correct": false, "explanation": "自動詞なので「子どもを」を取れない。"}, {"text": "疲れた", "is_correct": false, "explanation": "「ように」の前で「子どもを」を取れず合わない。"}, {"text": "疲れて", "is_correct": false, "explanation": "て形は「ように」に続かない。"}], "correct_form": "疲れさせない", "base_form": "疲れる", "form_label": "使役否定形", "sentence_index": 7, "explanations": {"疲れさせない": "「子どもを」を受ける使役の否定形で意味が通る。", "疲れない": "自動詞なので「子どもを」を取れない。", "疲れた": "「ように」の前で「子どもを」を取れず合わない。", "疲れて": "て形は「ように」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
