INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "書くの目的語として、売り上げを記録するという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「売り上げが書いている」は主語になり、記録の対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「売り上げへ書いている」は方向の意味になり、記録の対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「売り上げの毎晩ノートに」と続かず、書くの目的語を示せず文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "書くの目的語として、売り上げを記録するという意味になる。", "が": "「売り上げが書いている」は主語になり、記録の対象を示せない。", "へ": "「売り上げへ書いている」は方向の意味になり、記録の対象にならない。", "の": "「売り上げの毎晩ノートに」と続かず、書くの目的語を示せず文が成立しない。"}, "error_tags": {"が": "主語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お店がものを売って得たお金。", "primary_collocate": null, "pronunciation": "うりあげ", "ipa": "ɯɾiaɡe", "syllable_count": 4, "sentences": [{"text": "今日の店の売り上げは、三万円だった。", "target_word": "売り上げ", "complexity_tier": "T2", "furigana": "今日[きょう]の店[みせ]の売[う]り上[あ]げは、三万円[さんまんえん]だった。", "sentence_source": "generated"}, {"text": "雨の日は、お客さんが少なくて売り上げが下がる。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は、お客[きゃく]さんが少[すく]なくて売[う]り上[あ]げが下[さ]がる。", "sentence_source": "generated"}, {"text": "売り上げを数えてから、店のシャッターを閉めた。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げを数[かぞ]えてから、店[みせ]のシャッターを閉[し]めた。", "sentence_source": "generated"}, {"text": "パンの売り上げが、先月より増えた。", "target_word": "売り上げ", "complexity_tier": "T2", "furigana": "パンの売[う]り上[あ]げが、先月[せんげつ]より増[ふ]えた。", "sentence_source": "generated"}, {"text": "この店は、夏にアイスの売り上げが一番高い。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "この店[みせ]は、夏[なつ]にアイスの売[う]り上[あ]げが一番[いちばん]高[たか]い。", "sentence_source": "generated"}, {"text": "文化祭で焼きそばを売り、売り上げを学校に寄付した。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "文化祭[ぶんかさい]で焼[や]きそばを売[う]り、売[う]り上[あ]げを学校[がっこう]に寄付[きふ]した。", "sentence_source": "generated"}, {"text": "売り上げが少ないので、店長は新しい商品を考えた。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "売[う]り上[あ]げが少[すく]ないので、店長[てんちょう]は新[あたら]しい商品[しょうひん]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "一日の売り上げを、毎晩ノートに書いている。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "一日[いちにち]の売[う]り上[あ]げを、毎晩[まいばん]ノートに書[か]いている。", "sentence_source": "generated"}, {"text": "セールの日は、普段の二倍の売り上げになった。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "セールの日[ひ]は、普段[ふだん]の二倍[にばい]の売[う]り上[あ]げになった。", "sentence_source": "generated"}, {"text": "兄の店は売り上げがよく、毎日いそがしい。", "target_word": "売り上げ", "complexity_tier": "T2", "furigana": "兄[あに]の店[みせ]は売[う]り上[あ]げがよく、毎日[まいにち]いそがしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売り上げ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お店がものを売って得たお金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売り上げ", "is_correct": true, "explanation": "お店で売って得たお金の意味で、三万円という金額の主語として合う。"}, {"text": "売り場", "is_correct": false, "explanation": "店内の売るスペースの意味で、金額を述べる文の主語にならない。"}, {"text": "売り子", "is_correct": false, "explanation": "商品を売る人の意味で、金額を述べる文には合わない。"}, {"text": "品揃え", "is_correct": false, "explanation": "売る商品の種類の意味で、三万円という金額とは合わない。"}], "explanations": {"売り上げ": "お店で売って得たお金の意味で、三万円という金額の主語として合う。", "売り場": "店内の売るスペースの意味で、金額を述べる文の主語にならない。", "売り子": "商品を売る人の意味で、金額を述べる文には合わない。", "品揃え": "売る商品の種類の意味で、三万円という金額とは合わない。"}, "sentence_index": 0, "correct_answer": "売り上げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パンの売り上げを、店のかごに並べた。", "explanation": "ここは〈商品〉の意味。売り上げは販売で得たお金で、並べるものではない。"}, {"text": "パンの売り上げを、朝早くこねた。", "explanation": "ここは〈生地〉の意味。売り上げはお店でものを売って得たお金で、こねる材料ではない。"}, {"text": "パンの売り上げを、業者に注文した。", "explanation": "ここは〈注文〉の意味。売り上げはお店が得たお金で、業者に頼んで買うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売り上げ", "is_correct": true, "explanation": "少ないという状態の主語で、売り上げの減少を述べる文脈に合う。"}, {"text": "店構え", "is_correct": false, "explanation": "店の外観の意味で、少ないという状態の主語にならない。"}, {"text": "陳列", "is_correct": false, "explanation": "商品の並べ方の意味で、少ないという状態の主語にならない。"}, {"text": "開店時間", "is_correct": false, "explanation": "営業する時間の意味で、少ないという状態とは合わない。"}], "explanations": {"売り上げ": "少ないという状態の主語で、売り上げの減少を述べる文脈に合う。", "店構え": "店の外観の意味で、少ないという状態の主語にならない。", "陳列": "商品の並べ方の意味で、少ないという状態の主語にならない。", "開店時間": "営業する時間の意味で、少ないという状態とは合わない。"}, "sentence_index": 6, "correct_answer": "売り上げ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "兄の店は売り上げを返していて、毎日いそがしい。", "explanation": "ここは〈借金〉の意味。売り上げは店が得た収入で、借りた金のように返す対象ではない。"}, {"text": "兄の店は売り上げを仕入れて、毎日いそがしい。", "explanation": "ここは〈仕入れ〉の意味。売り上げは販売で得たお金で、仕入れるものではない。"}, {"text": "兄の店は売り上げを雇って、毎日いそがしい。", "explanation": "ここは〈従業員〉の意味。売り上げはお店が得た金額で、人のように雇うものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今月の店の売り上げを、五万円だった。", "corrected_sentence": "今月の店の売り上げは、五万円だった。", "error_description": "「を」は誤り。売り上げを主題として示すには「は」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51933, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月の売り上げに少ないので、店長は新しい商品を考えた。", "corrected_sentence": "先月の売り上げが少ないので、店長は新しい商品を考えた。", "error_description": "「売り上げに少ない」は誤り。「少ない」の主語は「が」で示す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51934, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「売り上げが大きく増えた」で、増えるという自動詞の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「売り上げを増えた」は成立せず、増えるは目的語を取らない自動詞。"}, {"text": "に", "is_correct": false, "explanation": "「売り上げに増えた」は着点の形で、主語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「売り上げの大きく増えた」と続かず、増えるの主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「売り上げが大きく増えた」で、増えるという自動詞の主語を示す。", "を": "「売り上げを増えた」は成立せず、増えるは目的語を取らない自動詞。", "に": "「売り上げに増えた」は着点の形で、主語を示せない。", "の": "「売り上げの大きく増えた」と続かず、増えるの主語を示せない。"}, "error_tags": {"を": "目的語", "に": "着点", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
