INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51934, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "商品やサービスを販売して得た収入の総額。", "primary_collocate": null, "pronunciation": "うりあげ", "ipa": "ɯɾiaɡe", "syllable_count": 4, "sentences": [{"text": "今年度の売り上げは、前の年より一割伸びた。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "今年度[こんねんど]の売[う]り上[あ]げは、前[まえ]の年[とし]より一割[いちわり]伸[の]びた。", "sentence_source": "generated"}, {"text": "新製品の発売で、会社の売り上げが大きく増えた。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "新製品[しんせいひん]の発売[はつばい]で、会社[かいしゃ]の売[う]り上[あ]げが大[おお]きく増[ふ]えた。", "sentence_source": "generated"}, {"text": "売り上げが目標に届かず、会議で対策を話し合った。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "売[う]り上[あ]げが目標[もくひょう]に届[とど]かず、会議[かいぎ]で対策[たいさく]を話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "この会社の売り上げの半分は、海外からのものだ。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "この会社[かいしゃ]の売[う]り上[あ]げの半分[はんぶん]は、海外[かいがい]からのものだ。", "sentence_source": "generated"}, {"text": "景気が悪くなり、四月から売り上げが落ちている。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなり、四月[しがつ]から売[う]り上[あ]げが落[お]ちている。", "sentence_source": "generated"}, {"text": "オンライン講座の売り上げが、店舗を上回った。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "オンライン講座[こうざ]の売[う]り上[あ]げが、店舗[てんぽ]を上回[うわまわ]った。", "sentence_source": "generated"}, {"text": "売り上げの総額から経費を引くと、利益が出る。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "売[う]り上[あ]げの総額[そうがく]から経費[けいひ]を引[ひ]くと、利益[りえき]が出[で]る。", "sentence_source": "generated"}, {"text": "広告を増やしたところ、売り上げが急に上がった。", "target_word": "売り上げ", "complexity_tier": "T3", "furigana": "広告[こうこく]を増[ふ]やしたところ、売[う]り上[あ]げが急[きゅう]に上[あ]がった。", "sentence_source": "generated"}, {"text": "来期の売り上げを予想して、計画を作る。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "来期[らいき]の売[う]り上[あ]げを予想[よそう]して、計画[けいかく]を作[つく]る。", "sentence_source": "generated"}, {"text": "サービス料金を変えても、売り上げはほとんど変わらなかった。", "target_word": "売り上げ", "complexity_tier": "T4", "furigana": "サービス料金[りょうきん]を変[か]えても、売[う]り上[あ]げはほとんど変[か]わらなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "売り上げ", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "会社が商品やサービスの販売で得た収入の合計", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79798bf0-106f-4811-a25f-bd391834976a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51934, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "売り上げ", "is_correct": true, "explanation": "会社が販売で得た収入の合計で、前の年より一割伸びたという文脈に合う。"}, {"text": "売り場", "is_correct": false, "explanation": "売るスペースの意味で、一割伸びたという数量の主語にならない。"}, {"text": "売り子", "is_correct": false, "explanation": "販売する人の意味で、伸びたという文の主語にならない。"}, {"text": "品揃え", "is_correct": false, "explanation": "商品の種類の意味で、一割伸びたという数量とは合わない。"}], "explanations": {"売り上げ": "会社が販売で得た収入の合計で、前の年より一割伸びたという文脈に合う。", "売り場": "売るスペースの意味で、一割伸びたという数量の主語にならない。", "売り子": "販売する人の意味で、伸びたという文の主語にならない。", "品揃え": "商品の種類の意味で、一割伸びたという数量とは合わない。"}, "sentence_index": 0, "correct_answer": "売り上げ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社の売り上げの半分は、海外で働いている。", "explanation": "ここは〈社員〉の意味。売り上げは収入の額で、人として働くものではない。"}, {"text": "この会社の売り上げの半分は、海外へ輸出された。", "explanation": "ここは〈製品〉の意味。売り上げはお金の額で、輸出される品物ではない。"}, {"text": "この会社の売り上げの半分は、海外に建てられた。", "explanation": "ここは〈工場〉の意味。売り上げは収入の額で、建てられるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51934, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "売り上げ", "is_correct": true, "explanation": "会社の販売収入で、総額から経費を引く計算の対象として合う。"}, {"text": "来客数", "is_correct": false, "explanation": "客の人数の意味で、総額という金額と合わない。"}, {"text": "製造数", "is_correct": false, "explanation": "作る個数の意味で、経費を引く計算の対象にならない。"}, {"text": "社員数", "is_correct": false, "explanation": "人数の意味で、総額から引く対象ではない。"}], "explanations": {"売り上げ": "会社の販売収入で、総額から経費を引く計算の対象として合う。", "来客数": "客の人数の意味で、総額という金額と合わない。", "製造数": "作る個数の意味で、経費を引く計算の対象にならない。", "社員数": "人数の意味で、総額から引く対象ではない。"}, "sentence_index": 6, "correct_answer": "売り上げ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "サービス料金を変えても、売り上げをほとんど利用しなかった。", "explanation": "ここは〈利用者〉の意味。売り上げは会社の収入で、利用する対象ではない。"}, {"text": "サービス料金を変えても、売り上げをほとんど結ばなかった。", "explanation": "ここは〈契約〉の意味。売り上げは収入の額で、契約のように結ぶものではない。"}, {"text": "サービス料金を変えても、売り上げをほとんど払わなかった。", "explanation": "ここは〈税金〉の意味。売り上げは受け取る収入で、払う税金ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76f2f94a-1780-4e93-9115-fac5a1ee8c81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
