INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51935, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "したいことを、本当にすること。", "primary_collocate": null, "pronunciation": "じっこう", "ipa": "dʑikkoː", "syllable_count": 4, "sentences": [{"text": "明日から実行します。", "target_word": "実行", "complexity_tier": "T2", "furigana": "あしたからじっこうします。", "sentence_source": "generated"}, {"text": "やりたいことを実行したい。", "target_word": "実行", "complexity_tier": "T2", "furigana": "やりたいことをじっこうしたい。", "sentence_source": "generated"}, {"text": "計画の実行はいつですか。", "target_word": "実行", "complexity_tier": "T2", "furigana": "けいかくのじっこうはいつですか。", "sentence_source": "generated"}, {"text": "彼はすぐに実行する人だ。", "target_word": "実行", "complexity_tier": "T3", "furigana": "かれはすぐにじっこうするひとだ。", "sentence_source": "generated"}, {"text": "言ったことは必ず実行します。", "target_word": "実行", "complexity_tier": "T2", "furigana": "いったことはかならずじっこうします。", "sentence_source": "generated"}, {"text": "実行するのは簡単ではない。", "target_word": "実行", "complexity_tier": "T3", "furigana": "じっこうするのはかんたんではない。", "sentence_source": "generated"}, {"text": "勉強の計画を立てて、実行した。", "target_word": "実行", "complexity_tier": "T3", "furigana": "べんきょうのけいかくをたてて、じっこうした。", "sentence_source": "generated"}, {"text": "みんなで話し合って、実行に移した。", "target_word": "実行", "complexity_tier": "T3", "furigana": "みんなではなしあって、じっこうにうつした。", "sentence_source": "generated"}, {"text": "実行しなければ、何も変わらない。", "target_word": "実行", "complexity_tier": "T4", "furigana": "じっこうしなければ、なにもかわらない。", "sentence_source": "generated"}, {"text": "まだ実行していないことが多い。", "target_word": "実行", "complexity_tier": "T3", "furigana": "まだじっこうしていないことがおおい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実行する", "label": "活用"}, {"form": "実行して", "label": "活用"}, {"form": "実行中", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | したいことを本当にすること", "collocate_grounding": {"status": "no