INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51935, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "実行", "is_correct": true, "explanation": "見出し語そのもの。「じっこう」。"}, {"text": "失効", "is_correct": false, "explanation": "「しっこう」。「じ」が「し」に変わる清濁の1拍違い。"}, {"text": "発行", "is_correct": false, "explanation": "「はっこう」。「じ」が「は」に変わる1拍違い。"}, {"text": "結構", "is_correct": false, "explanation": "「けっこう」。「じ」が「け」に変わる1拍違い。"}, {"text": "昵懇", "is_correct": false, "explanation": "「じっこん」。長音「う」が撥音「ん」に変わる1拍違い。"}], "explanations": {"実行": "見出し語そのもの。「じっこう」。", "失効": "「しっこう」。「じ」が「し」に変わる清濁の1拍違い。", "発行": "「はっこう」。「じ」が「は」に変わる1拍違い。", "結構": "「けっこう」。「じ」が「け」に変わる1拍違い。", "昵懇": "「じっこん」。長音「う」が撥音「ん」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "実行"}, "level_3": {"options": [{"text": "実行", "is_correct": true, "explanation": "明日からやりたいことを始める意味に合う。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、「明日から」に続く意味が合わない。"}, {"text": "消滅", "is_correct": false, "explanation": "形は合うが、意志を表す文脈に意味が合わない。"}, {"text": "退化", "is_correct": false, "explanation": "形は合うが、「明日から〜します」の意志と意味が合わない。"}], "explanations": {"実行": "明日からやりたいことを始める意味に合う。", "故障": "形は合うが、「明日から」に続く意味が合わない。", "消滅": "形は合うが、意志を表す文脈に意味が合わない。", "退化": "形は合うが、「明日から〜します」の意志と意味が合わない。"}, "sentence_index": 0, "correct_answer": "実行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は考えるだけで、すぐに実行する人だ。", "explanation": "「実行」は本当にすることで、考えるだけの人には当てはまらない。"}, {"text": "彼は実行の中で泳いでいる人だ。", "explanation": "「実行」は行為を表し、泳ぐ場所のようには使えない。"}, {"text": "彼の実行は昨日の雨だ。", "explanation": "「実行」は行うことで、雨のような現象を指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.vali