INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51936, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "考えたり計画したりしたことを、実際に行うこと。", "primary_collocate": null, "pronunciation": "じっこう", "ipa": "dʑikkoː", "syllable_count": 4, "sentences": [{"text": "この販売活動は、単にお金を稼ぐためだけでなく、自分で計画を立てて実行するという貴重な経験を積むことが目的だった。", "target_word": "実行", "complexity_tier": "T6", "furigana": "このはんばいかつどうは、たんにおかねをかせぐためだけでなく、じぶんでけいかくをたててじっこうするというきちょうなけいけんをつむことがもくてきだった。", "sentence_source": "mined"}, {"text": "計画を実行する。", "target_word": "実行", "complexity_tier": "T1", "furigana": "けいかくをじっこうする。", "sentence_source": "generated"}, {"text": "すぐに実行しましょう。", "target_word": "実行", "complexity_tier": "T2", "furigana": "すぐにじっこうしましょう。", "sentence_source": "generated"}, {"text": "実行する前に、よく考えてください。", "target_word": "実行", "complexity_tier": "T3", "furigana": "じっこうするまえに、よくかんがえてください。", "sentence_source": "generated"}, {"text": "言うだけでなく、実行することが大切だ。", "target_word": "実行", "complexity_tier": "T3", "furigana": "いうだけでなく、じっこうすることがたいせつだ。", "sentence_source": "generated"}, {"text": "その計画は、まだ実行されていない。", "target_word": "実行", "complexity_tier": "T4", "furigana": "そのけいかくは、まだじっこうされていない。", "sentence_source": "generated"}, {"text": "実行が難しい計画は、見直したほうがいい。", "target_word": "実行", "complexity_tier": "T4", "furigana": "じっこうがむずかしいけいかくは、みなおしたほうがいい。", "sentence_source": "generated"}, {"text": "先生は、生徒に計画を実行させた。", "target_word": "実行", "complexity_tier": "T4", "furigana": "せんせいは、せいとにけいかくをじっこうさせた。", "sentence_source": "generated"}, {"text": "考えたことを実行に移すまで、一週間かかった。", "target_word": "実行", "complexity_tier": "T4", "furigana": "かんがえたことをじっこうにうつすまで、いっしゅうかんかかった。", "sentence_source": "generated"}, {"text": "実行すれば、きっと結果が出るはずだ。", "target_word": "実行", "complexity_tier": "T4", "furigana": "じっこうすれば、きっとけっかがでるはずだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "実行する", "label": "活用"}, {"form": "実行して", "label": "活用"}, {"form": "実行中", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 計画したことを実際に行うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '530831ed-fe17-4cbf-8f61-bfe726a891b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51936, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "実行", "is_correct": true, "explanation": "見出し語そのもの。「じっこう」。"}, {"text": "失効", "is_correct": false, "explanation": "「しっこう」。「じ」が「し」に変わる清濁の1拍違い。"}, {"text": "発行", "is_correct": false, "explanation": "「はっこう」。「じ」が「は」に変わる1拍違い。"}, {"text": "結構", "is_correct": false, "explanation": "「けっこう」。「じ」が「け」に変わる1拍違い。"}, {"text": "昵懇", "is_correct": false, "explanation": "「じっこん」。長音「う」が撥音「ん」に変わる1拍違い。"}], "explanations": {"実行": "見出し語そのもの。「じっこう」。", "失効": "「しっこう」。「じ」が「し」に変わる清濁の1拍違い。", "発行": "「はっこう」。「じ」が「は」に変わる1拍違い。", "結構": "「けっこう」。「じ」が「け」に変わる1拍違い。", "昵懇": "「じっこん」。長音「う」が撥音「ん」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "実行"}, "level_3": {"options": [{"text": "実行", "is_correct": true, "explanation": "計画を立てて実際に行う経験という意味に合う。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、自分で立てた計画に続く意味が合わない。"}, {"text": "発生", "is_correct": false, "explanation": "形は合うが、「経験を積む」という文脈に意味が合わない。"}, {"text": "消滅", "is_correct": false, "explanation": "形は合うが、計画を立てる流れに意味が合わない。"}], "explanations": {"実行": "計画を立てて実際に行う経験という意味に合う。", "故障": "形は合うが、自分で立てた計画に続く意味が合わない。", "発生": "形は合うが、「経験を積む」という文脈に意味が合わない。", "消滅": "形は合うが、計画を立てる流れに意味が合わない。"}, "sentence_index": 0, "correct_answer": "実行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "実行は赤くて、とても甘いです。", "explanation": "「実行」は行うことを表す名詞で、味や色を持つ物としては使えない。"}, {"text": "昨日の天気を実行しました。", "explanation": "「実行」は計画などを行うことで、天気のような対象には使えない。"}, {"text": "実行を食べる前に、手を洗ってください。", "explanation": "「実行」は行為を表し、食べ物のように「食べる」対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51936, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "実行", "is_correct": true, "explanation": "見出し語そのもの。「じっこう」。"}, {"text": "続行", "is_correct": false, "explanation": "「ぞっこう」。「じ」が「ぞ」に変わる清濁の1拍違い。"}, {"text": "絶好", "is_correct": false, "explanation": "「ぜっこう」。促音の前の「じ」が「ぜ」に変わる1拍違い。"}, {"text": "勃興", "is_correct": false, "explanation": "「ぼっこう」。「じ」が「ぼ」に変わる1拍違い。"}], "explanations": {"実行": "見出し語そのもの。「じっこう」。", "続行": "「ぞっこう」。「じ」が「ぞ」に変わる清濁の1拍違い。", "絶好": "「ぜっこう」。促音の前の「じ」が「ぜ」に変わる1拍違い。", "勃興": "「ぼっこう」。「じ」が「ぼ」に変わる1拍違い。"}, "sentence_index": null, "correct_answer": "実行"}, "level_3": {"options": [{"text": "実行", "is_correct": true, "explanation": "計画を行うことが難しいという意味に合う。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、計画に対して意味が合わない。"}, {"text": "消滅", "is_correct": false, "explanation": "形は合うが、「難しい計画」を修飾する意味が合わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "形は合うが、計画に関する意味が合わない。"}], "explanations": {"実行": "計画を行うことが難しいという意味に合う。", "故障": "形は合うが、計画に対して意味が合わない。", "消滅": "形は合うが、「難しい計画」を修飾する意味が合わない。", "睡眠": "形は合うが、計画に関する意味が合わない。"}, "sentence_index": 6, "correct_answer": "実行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "何もしないで、計画を全部実行した。", "explanation": "「実行」は実際に行うことなので、「何もしないで」とは矛盾する。"}, {"text": "山が実行したので、景色がいい。", "explanation": "「実行」は意思をもって行うことで、山のような物の主語にはならない。"}, {"text": "実行を飲めば、きっと元気になる。", "explanation": "「実行」は行為を表し、飲む対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51936, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会議で決めた内容を実行がしました。", "corrected_sentence": "会議で決めた内容を実行しました。", "error_description": "「実行する」は一語の動詞なので、「実行がしました」の「が」は不要。「実行しました」とする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51936, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "決めたことを実行を移すのは勇気がいる。", "corrected_sentence": "決めたことを実行に移すのは勇気がいる。", "error_description": "「実行に移す」が正しい形で、「実行を移す」とは言わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb16708b-b95b-48c7-a0fa-86ef1023e037') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好き」の対象を表す「が」が自然。"}, {"text": "の", "is_correct": false, "explanation": "「アクセサリーの好き」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「好き」の対象には使えない。"}, {"text": "から", "is_correct": false, "explanation": "「アクセサリーから好き」は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「好き」の対象を表す「が」が自然。", "の": "「アクセサリーの好き」では文が成り立たない。", "へ": "「へ」は方向を表し、「好き」の対象には使えない。", "から": "「アクセサリーから好き」は意味が通らない。"}, "error_tags": {"の": "possessive", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「つける」の対象を表す「を」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「アクセサリーがつけすぎる」は他動詞に合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、つける対象には使えない。"}, {"text": "から", "is_correct": false, "explanation": "「アクセサリーからつけすぎる」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「つける」の対象を表す「を」が正しい。", "が": "「アクセサリーがつけすぎる」は他動詞に合わず不自然。", "へ": "「へ」は方向を表し、つける対象には使えない。", "から": "「アクセサリーからつけすぎる」は意味が通らない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "から": "source"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "からだにつけるかざりのことです。", "primary_collocate": null, "pronunciation": "あくせさりー", "ipa": "akusesaɾiː", "syllable_count": 6, "sentences": [{"text": "アクセサリーをつける。", "target_word": "アクセサリー", "complexity_tier": "T1", "furigana": "アクセサリーをつける。", "sentence_source": "generated"}, {"text": "妹はアクセサリーが好き。", "target_word": "アクセサリー", "complexity_tier": "T1", "furigana": "妹[いもうと]はアクセサリーが好[す]き。", "sentence_source": "generated"}, {"text": "アクセサリーは引き出しにあります。", "target_word": "アクセサリー", "complexity_tier": "T2", "furigana": "アクセサリーは引[ひ]き出[だ]しにあります。", "sentence_source": "generated"}, {"text": "私は指輪というアクセサリーを持っています。", "target_word": "アクセサリー", "complexity_tier": "T2", "furigana": "私[わたし]は指輪[ゆびわ]というアクセサリーを持[も]っています。", "sentence_source": "generated"}, {"text": "旅行にはアクセサリーを持っていかない。", "target_word": "アクセサリー", "complexity_tier": "T3", "furigana": "旅行[りょこう]にはアクセサリーを持[も]っていかない。", "sentence_source": "generated"}, {"text": "アクセサリーを外してから、手を洗った。", "target_word": "アクセサリー", "complexity_tier": "T3", "furigana": "アクセサリーを外[はず]してから、手[て]を洗[あら]った。", "sentence_source": "generated"}, {"text": "この店ではアクセサリーが売られている。", "target_word": "アクセサリー", "complexity_tier": "T4", "furigana": "この店[みせ]ではアクセサリーが売[う]られている。", "sentence_source": "generated"}, {"text": "アクセサリーをつけすぎると、重くて肩がこってしまう。", "target_word": "アクセサリー", "complexity_tier": "T4", "furigana": "アクセサリーをつけすぎると、重[おも]くて肩[かた]がこってしまう。", "sentence_source": "generated"}, {"text": "学校ではアクセサリーをつけてはいけないと言われた。", "target_word": "アクセサリー", "complexity_tier": "T4", "furigana": "学校[がっこう]ではアクセサリーをつけてはいけないと言[い]われた。", "sentence_source": "generated"}, {"text": "海で拾った貝殻を使って、自分だけのアクセサリーを作ってみたいと思っている。", "target_word": "アクセサリー", "complexity_tier": "T5", "furigana": "海[うみ]で拾[ひろ]った貝殻[かいがら]を使[つか]って、自分[じぶん]だけのアクセサリーを作[つく]ってみたいと思[おも]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手作りアクセサリー", "label": "派生"}, {"form": "アクセサリーケース", "label": "派生"}, {"form": "アクセサリー売り場", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 体につけるかざりの品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクセサリー", "is_correct": true, "explanation": "体にかざりとして「つける」ものなので意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気を「つける」ことはできず意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震を「つける」ことはできず意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節を「つける」とは言わず意味が合わない。"}], "explanations": {"アクセサリー": "体にかざりとして「つける」ものなので意味が合う。", "天気": "形は合うが、天気を「つける」ことはできず意味が合わない。", "地震": "形は合うが、地震を「つける」ことはできず意味が合わない。", "季節": "形は合うが、季節を「つける」とは言わず意味が合わない。"}, "sentence_index": 0, "correct_answer": "アクセサリー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は指輪というアクセサリーを食べています。", "explanation": "アクセサリーは身につけるもので、食べ物ではない。"}, {"text": "私は指輪というアクセサリーを読んでいます。", "explanation": "アクセサリーは読む対象ではなく、「読む」と結びつかない。"}, {"text": "私は指輪というアクセサリーに乗っています。", "explanation": "アクセサリーは乗り物ではないので「乗る」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクセサリー", "is_correct": true, "explanation": "店で売られる身につける飾りなので意味が合う。"}, {"text": "雷", "is_correct": false, "explanation": "形は合うが、雷は店で売られるものではなく意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、台風は売られるものではなく意味が合わない。"}, {"text": "朝日", "is_correct": false, "explanation": "形は合うが、朝日は売られるものではなく意味が合わない。"}], "explanations": {"アクセサリー": "店で売られる身につける飾りなので意味が合う。", "雷": "形は合うが、雷は店で売られるものではなく意味が合わない。", "台風": "形は合うが、台風は売られるものではなく意味が合わない。", "朝日": "形は合うが、朝日は売られるものではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "アクセサリー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海でアクセサリーを泳いでみたいと思っている。", "explanation": "アクセサリーは泳ぐ対象ではなく、「泳ぐ」と結びつかない。"}, {"text": "自分だけのアクセサリーを飲んでみたいと思っている。", "explanation": "アクセサリーは飲み物ではないので「飲む」は使えない。"}, {"text": "貝殻を使って、自分だけのアクセサリーを歌ってみたいと思っている。", "explanation": "アクセサリーは歌う対象ではなく、「歌う」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉はアクセサリーを着て出かけた。", "corrected_sentence": "姉はアクセサリーをつけて出かけた。", "error_description": "「着る」は服に使う動詞。アクセサリーには「つける」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51937, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前にアクセサリーを開けて、引き出しにしまった。", "corrected_sentence": "寝る前にアクセサリーを外して、引き出しにしまった。", "error_description": "身につけたアクセサリーには「開ける」ではなく「外す」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「収入につなげる」で、つなげる先を表す「に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「収入がつなげたい」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「収入のつなげたい」は動詞に続けられず不自然。"}, {"text": "を", "is_correct": false, "explanation": "すでに「アクセサリーを」があり、「収入を」と重ねられない。"}], "correct_answer": "に", "explanations": {"に": "「収入につなげる」で、つなげる先を表す「に」が正しい。", "が": "「収入がつなげたい」は文法的に成り立たない。", "の": "「収入のつなげたい」は動詞に続けられず不自然。", "を": "すでに「アクセサリーを」があり、「収入を」と重ねられない。"}, "error_tags": {"が": "subject_marker", "の": "possessive", "を": "object_marker"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "譲ってくれた人を表す「祖母から」が自然。"}, {"text": "を", "is_correct": false, "explanation": "「祖母を譲られた」は受身文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「祖母で譲られた」は、譲ってくれた人を表せず成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「祖母と譲られた」は受身の相手として不自然。"}], "correct_answer": "から", "explanations": {"から": "譲ってくれた人を表す「祖母から」が自然。", "を": "「祖母を譲られた」は受身文として成り立たない。", "で": "「祖母で譲られた」は、譲ってくれた人を表せず成り立たない。", "と": "「祖母と譲られた」は受身の相手として不自然。"}, "error_tags": {"を": "object_marker", "で": "instrument", "と": "comitative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "服や体につけて、おしゃれを楽しむための小さな品物。", "primary_collocate": null, "pronunciation": "あくせさりー", "ipa": "akusesaɾiː", "syllable_count": 6, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "アクセサリー", "complexity_tier": "T6", "furigana": "趣味[しゅみ]で手作[てづく]りしたアクセサリーを収入[しゅうにゅう]につなげたいなら、オンラインビジネスの構築[こうちく]が有効[ゆうこう]です。", "sentence_source": "mined"}, {"text": "このアクセサリーは新しい。", "target_word": "アクセサリー", "complexity_tier": "T1", "furigana": "このアクセサリーは新[あたら]しい。", "sentence_source": "generated"}, {"text": "母はアクセサリーを毎日つけます。", "target_word": "アクセサリー", "complexity_tier": "T2", "furigana": "母[はは]はアクセサリーを毎日[まいにち]つけます。", "sentence_source": "generated"}, {"text": "駅の前でアクセサリーを買いました。", "target_word": "アクセサリー", "complexity_tier": "T2", "furigana": "駅[えき]の前[まえ]でアクセサリーを買[か]いました。", "sentence_source": "generated"}, {"text": "友達にもらったアクセサリーをつけて出かけた。", "target_word": "アクセサリー", "complexity_tier": "T3", "furigana": "友達[ともだち]にもらったアクセサリーをつけて出[で]かけた。", "sentence_source": "generated"}, {"text": "アクセサリーを入れる箱を探している。", "target_word": "アクセサリー", "complexity_tier": "T3", "furigana": "アクセサリーを入[い]れる箱[はこ]を探[さが]している。", "sentence_source": "generated"}, {"text": "彼女は服に合うアクセサリーを選んでいる。", "target_word": "アクセサリー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は服[ふく]に合[あ]うアクセサリーを選[えら]んでいる。", "sentence_source": "generated"}, {"text": "祖母から譲られたアクセサリーは、今も大切にしている。", "target_word": "アクセサリー", "complexity_tier": "T4", "furigana": "祖母[そぼ]から譲[ゆず]られたアクセサリーは、今[いま]も大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "安いアクセサリーでも、組み合わせ次第でおしゃれに見える。", "target_word": "アクセサリー", "complexity_tier": "T4", "furigana": "安[やす]いアクセサリーでも、組[く]み合[あ]わせ次第[しだい]でおしゃれに見[み]える。", "sentence_source": "generated"}, {"text": "高価なアクセサリーを身につけて歩くと、盗まれないか心配になってしまう。", "target_word": "アクセサリー", "complexity_tier": "T5", "furigana": "高価[こうか]なアクセサリーを身[み]につけて歩[ある]くと、盗[ぬす]まれないか心配[しんぱい]になってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "手作りアクセサリー", "label": "派生"}, {"form": "アクセサリーケース", "label": "派生"}, {"form": "アクセサリー売り場", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 身につける小さな飾りの品物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アクセサリー", "is_correct": true, "explanation": "手作りして収入につなげられる品物なので、意味が合う。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、景色は手作りして収入につなげるものではなく意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気は手作りできないので意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震は手作りできないので意味が合わない。"}], "explanations": {"アクセサリー": "手作りして収入につなげられる品物なので、意味が合う。", "景色": "形は合うが、景色は手作りして収入につなげるものではなく意味が合わない。", "天気": "形は合うが、天気は手作りできないので意味が合わない。", "地震": "形は合うが、地震は手作りできないので意味が合わない。"}, "sentence_index": 0, "correct_answer": "アクセサリー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅の前でアクセサリーを食べました。", "explanation": "アクセサリーは身につける飾りで、食べ物ではないので「食べる」とは使えない。"}, {"text": "駅の前でアクセサリーを読みました。", "explanation": "アクセサリーは本ではないので「読む」の対象にならない。"}, {"text": "アクセサリーに乗って駅まで行きました。", "explanation": "アクセサリーは小さな飾りで乗り物ではないので、「乗る」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アクセサリー", "is_correct": true, "explanation": "服に合わせて選ぶ身につける品物なので意味が合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、服に合う地震は選べないので意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、服に合う台風を選ぶことはできず意味が合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "形は合うが、夕焼けは服に合わせて選ぶものではなく意味が合わない。"}], "explanations": {"アクセサリー": "服に合わせて選ぶ身につける品物なので意味が合う。", "地震": "形は合うが、服に合う地震は選べないので意味が合わない。", "台風": "形は合うが、服に合う台風を選ぶことはできず意味が合わない。", "夕焼け": "形は合うが、夕焼けは服に合わせて選ぶものではなく意味が合わない。"}, "sentence_index": 6, "correct_answer": "アクセサリー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんにアクセサリーを食べました。", "explanation": "アクセサリーは食べ物ではないので「食べる」は使えない。"}, {"text": "アクセサリーを運転して、遠くの町まで行った。", "explanation": "運転できるのは乗り物で、アクセサリーは対象にならない。"}, {"text": "寒い日はアクセサリーを沸かして飲みます。", "explanation": "アクセサリーは飲み物ではなく、「沸かす」「飲む」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は誕生日にアクセサリーを飲みました。", "corrected_sentence": "妹は誕生日にアクセサリーをもらいました。", "error_description": "「アクセサリーを飲む」は不自然。品物を受け取る意味の「もらう」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51938, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は毎朝アクセサリーを履いて出かける。", "corrected_sentence": "彼女は毎朝アクセサリーをつけて出かける。", "error_description": "「履く」は靴などに使う動詞。アクセサリーには「つける」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51939, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「収入が多い」で、主語を表す「が」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「収入へ多い」は方向を表す語で意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「収入から多い」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「収入と多い」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「収入が多い」で、主語を表す「が」が正しい。", "へ": "「収入へ多い」は方向を表す語で意味が通らない。", "から": "「収入から多い」は文として成り立たない。", "と": "「収入と多い」は文として成り立たない。"}, "error_tags": {"へ": "direction", "から": "source", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支出", "is_correct": true, "explanation": "お金をもらう収入に対し、お金を出す支出は反対の意味。"}, {"text": "給料", "is_correct": false, "explanation": "給料は収入の一種で、反対ではない。"}, {"text": "貯金", "is_correct": false, "explanation": "貯金はためたお金のことで、収入の反対ではない。"}, {"text": "所得", "is_correct": false, "explanation": "所得は収入に近い意味で、反対ではない。"}], "correct_answer": "支出", "explanations": {"支出": "お金をもらう収入に対し、お金を出す支出は反対の意味。", "給料": "給料は収入の一種で、反対ではない。", "貯金": "貯金はためたお金のことで、収入の反対ではない。", "所得": "所得は収入に近い意味で、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
