, "label": "派生"}, {"form": "副収入", "label": "派生"}, {"form": "収入額", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 仕事をして受け取るお金", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
