INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51940, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事や活動をして得るお金や利益のこと。", "primary_collocate": null, "pronunciation": "しゅうにゅう", "ipa": "ɕɯːɲɯː", "syllable_count": 4, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "収入", "complexity_tier": "T6", "furigana": "趣味[しゅみ]で手作[てづく]りしたアクセサリーを収入[しゅうにゅう]につなげたいなら、オンラインビジネスの構築[こうちく]が有効[ゆうこう]です。", "sentence_source": "mined"}, {"text": "今月は収入が多い。", "target_word": "収入", "complexity_tier": "T1", "furigana": "今月[こんげつ]は収入[しゅうにゅう]が多[おお]い。", "sentence_source": "generated"}, {"text": "収入が少ないので、節約しています。", "target_word": "収入", "complexity_tier": "T2", "furigana": "収入[しゅうにゅう]が少[すく]ないので、節約[せつやく]しています。", "sentence_source": "generated"}, {"text": "父の収入で家族が暮らしています。", "target_word": "収入", "complexity_tier": "T2", "furigana": "父[ちち]の収入[しゅうにゅう]で家族[かぞく]が暮[く]らしています。", "sentence_source": "generated"}, {"text": "アルバイトを始めて、収入が増えた。", "target_word": "収入", "complexity_tier": "T3", "furigana": "アルバイトを始[はじ]めて、収入[しゅうにゅう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "収入の一部を毎月貯金している。", "target_word": "収入", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]の一部[いちぶ]を毎月[まいつき]貯金[ちょきん]している。", "sentence_source": "generated"}, {"text": "収入と支出を記録して、ノートにまとめた。", "target_word": "収入", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]と支出[ししゅつ]を記録[きろく]して、ノートにまとめた。", "sentence_source": "generated"}, {"text": "収入が安定すれば、新しい家を買うつもりだ。", "target_word": "収入", "complexity_tier": "T4", "furigana": "収入[しゅうにゅう]が安定[あんてい]すれば、新[あたら]しい家[いえ]を買[か]うつもりだ。", "sentence_source": "generated"}, {"text": "仕事を変えたせいで、収入が半分に減ってしまった。", "target_word": "収入", "complexity_tier": "T4", "furigana": "仕事[しごと]を変[か]えたせいで、収入[しゅうにゅう]が半分[はんぶん]に減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "副業で得た収入については、きちんと申告しなければならない。", "target_word": "収入", "complexity_tier": "T5", "furigana": "副業[ふくぎょう]で得[え]た収入[しゅうにゅう]については、きちんと申告[しんこく]しなければならない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "収入源", "label": "派生"}, {"form": "副収入", "label": "派生"}, {"form": "収入額", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 仕事などで得るお金や利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51940, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "収入", "is_correct": true, "explanation": "しゅうにゅう。見出し語そのもの。"}, {"text": "収容", "is_correct": false, "explanation": "しゅうよう。「にゅ」が「よ」に変わる別の語。"}, {"text": "集中", "is_correct": false, "explanation": "しゅうちゅう。「にゅ」が「ちゅ」に変わる別の語。"}, {"text": "吸入", "is_correct": false, "explanation": "きゅうにゅう。「しゅ」が「きゅ」に変わる別の語。"}, {"text": "収納", "is_correct": false, "explanation": "しゅうのう。「にゅ」が「の」に変わる別の語。"}], "explanations": {"収入": "しゅうにゅう。見出し語そのもの。", "収容": "しゅうよう。「にゅ」が「よ」に変わる別の語。", "集中": "しゅうちゅう。「にゅ」が「ちゅ」に変わる別の語。", "吸入": "きゅうにゅう。「しゅ」が「きゅ」に変わる別の語。", "収納": "しゅうのう。「にゅ」が「の」に変わる別の語。"}, "sentence_index": null, "correct_answer": "収入"}, "level_3": {"options": [{"text": "収入", "is_correct": true, "explanation": "手作りの品を売ってお金を得ることにつなげるので意味が合う。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、景色につなげるのでは意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震につなげたいという意味は不自然。"}, {"text": "空気", "is_correct": false, "explanation": "形は合うが、空気につなげるのでは意味が合わない。"}], "explanations": {"収入": "手作りの品を売ってお金を得ることにつなげるので意味が合う。", "景色": "形は合うが、景色につなげるのでは意味が合わない。", "地震": "形は合うが、地震につなげたいという意味は不自然。", "空気": "形は合うが、空気につなげるのでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "収入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父は毎朝、収入を着て会社へ行きます。", "explanation": "収入はお金のことで、「着る」ものではない。"}, {"text": "家の前の収入で家族が遊んでいます。", "explanation": "収入は場所ではないので、遊ぶ場所として使えない。"}, {"text": "父の収入を飲んで家族が暮らしています。", "explanation": "収入は飲み物ではないので「飲む」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51940, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "収入", "is_correct": true, "explanation": "しゅうにゅう。見出し語そのもの。"}, {"text": "注入", "is_correct": false, "explanation": "ちゅうにゅう。「しゅ」が「ちゅ」に変わる別の語。"}, {"text": "収集", "is_correct": false, "explanation": "しゅうしゅう。「にゅ」が「しゅ」に変わる別の語。"}, {"text": "週休", "is_correct": false, "explanation": "しゅうきゅう。「にゅ」が「きゅ」に変わる別の語。"}], "explanations": {"収入": "しゅうにゅう。見出し語そのもの。", "注入": "ちゅうにゅう。「しゅ」が「ちゅ」に変わる別の語。", "収集": "しゅうしゅう。「にゅ」が「しゅ」に変わる別の語。", "週休": "しゅうきゅう。「にゅ」が「きゅ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "収入"}, "level_3": {"options": [{"text": "収入", "is_correct": true, "explanation": "支出と対になる、入ってくるお金なので意味が合う。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、地震と支出を並べて記録するのは意味が合わない。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが、台風と支出を並べて記録するのは意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、景色と支出を並べて記録するのは意味が合わない。"}], "explanations": {"収入": "支出と対になる、入ってくるお金なので意味が合う。", "地震": "形は合うが、地震と支出を並べて記録するのは意味が合わない。", "台風": "形は合うが、台風と支出を並べて記録するのは意味が合わない。", "景色": "形は合うが、景色と支出を並べて記録するのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "収入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "副業で得た収入を食べて、きちんと申告しなければならない。", "explanation": "収入はお金のことで、「食べる」ものではない。"}, {"text": "副業で走った収入については、きちんと申告しなければならない。", "explanation": "収入は走るものではなく、「走る」と結びつかない。"}, {"text": "収入に座って、きちんと申告しなければならない。", "explanation": "収入は座る場所ではないので「座る」は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51940, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仕事を変えて、収入が降りた。", "corrected_sentence": "仕事を変えて、収入が下がった。", "error_description": "収入が少なくなるときは「降りる」ではなく「下がる」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
