INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51941, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ただの趣味」で、名詞「ただ」が趣味を修飾する。"}, {"text": "を", "is_correct": false, "explanation": "「ただを趣味だ」では文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「ただが趣味だ」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「ただへ趣味だ」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「ただの趣味」で、名詞「ただ」が趣味を修飾する。", "を": "「ただを趣味だ」では文が成り立たない。", "が": "「ただが趣味だ」では文が成り立たない。", "へ": "「ただへ趣味だ」では文が成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本業", "is_correct": true, "explanation": "遊びのような趣味に対し、本気で取り組む本業が対義的。"}, {"text": "遊び", "is_correct": false, "explanation": "遊びは趣味に近い意味で、対義語ではない。"}, {"text": "道楽", "is_correct": false, "explanation": "道楽は好きなことに熱中することで、類義語に近い。"}, {"text": "好物", "is_correct": false, "explanation": "好物は好きな食べ物で、対義語ではない。"}], "correct_answer": "本業", "explanations": {"本業": "遊びのような趣味に対し、本気で取り組む本業が対義的。", "遊び": "遊びは趣味に近い意味で、対義語ではない。", "道楽": "道楽は好きなことに熱中することで、類義語に近い。", "好物": "好物は好きな食べ物で、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51941, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「趣味で集めた」で、動機・目的を表す。"}, {"text": "に", "is_correct": false, "explanation": "「趣味に集めた切手」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「趣味へ集めた」は方向の助詞で不自然。"}, {"text": "と", "is_correct": false, "explanation": "「趣味と集めた切手」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「趣味で集めた」で、動機・目的を表す。", "に": "「趣味に集めた切手」では意味が通らない。", "へ": "「趣味へ集めた」は方向の助詞で不自然。", "と": "「趣味と集めた切手」では意味が通らない。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仕事", "is_correct": true, "explanation": "遊びのように行う趣味に対し、義務として行う仕事が対義的。"}, {"text": "娯楽", "is_correct": false, "explanation": "娯楽は楽しみの活動で、類義語に近い。"}, {"text": "嗜好", "is_correct": false, "explanation": "嗜好は好みのことで、趣味に近く対義語ではない。"}, {"text": "余興", "is_correct": false, "explanation": "余興は楽しみのための出し物で、対義語ではない。"}], "correct_answer": "仕事", "explanations": {"仕事": "遊びのように行う趣味に対し、義務として行う仕事が対義的。", "娯楽": "娯楽は楽しみの活動で、類義語に近い。", "嗜好": "嗜好は好みのことで、趣味に近く対義語ではない。", "余興": "余興は楽しみのための出し物で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51941, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の好きなことで、遊びのようにすること。", "primary_collocate": null, "pronunciation": "しゅみ", "ipa": "ɕɯmi", "syllable_count": 2, "sentences": [{"text": "趣味で絵をかく。", "target_word": "趣味", "complexity_tier": "T1", "furigana": "趣味[しゅみ]で絵[え]をかく。", "sentence_source": "generated"}, {"text": "これはただの趣味だ。", "target_word": "趣味", "complexity_tier": "T1", "furigana": "これはただの趣味[しゅみ]だ。", "sentence_source": "generated"}, {"text": "趣味でピアノをひいています。", "target_word": "趣味", "complexity_tier": "T2", "furigana": "趣味[しゅみ]でピアノをひいています。", "sentence_source": "generated"}, {"text": "山登りが趣味になりました。", "target_word": "趣味", "complexity_tier": "T2", "furigana": "山登[やまのぼ]りが趣味[しゅみ]になりました。", "sentence_source": "generated"}, {"text": "趣味でパンを焼いて、近所の人に配った。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "趣味[しゅみ]でパンを焼[や]いて、近所[きんじょ]の人[ひと]に配[くば]った。", "sentence_source": "generated"}, {"text": "父は釣りを趣味にしている。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "父[ちち]は釣[つ]りを趣味[しゅみ]にしている。", "sentence_source": "generated"}, {"text": "趣味が同じなので、彼女とよく話す。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "趣味[しゅみ]が同[おな]じなので、彼女[かのじょ]とよく話[はな]す。", "sentence_source": "generated"}, {"text": "趣味で集めた切手が、気がつけば千枚を超えていた。", "target_word": "趣味", "complexity_tier": "T4", "furigana": "趣味[しゅみ]で集[あつ]めた切手[きって]が、気[き]がつけば千枚[せんまい]を超[こ]えていた。", "sentence_source": "generated"}, {"text": "趣味だからこそ、時間を忘れて夢中になれる。", "target_word": "趣味", "complexity_tier": "T4", "furigana": "趣味[しゅみ]だからこそ、時間[じかん]を忘[わす]れて夢中[むちゅう]になれる。", "sentence_source": "generated"}, {"text": "最初は趣味のつもりで始めたが、今では本格的に習うようになった。", "target_word": "趣味", "complexity_tier": "T5", "furigana": "最初[さいしょ]は趣味[しゅみ]のつもりで始[はじ]めたが、今[いま]では本格的[ほんかくてき]に習[なら]うようになった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "趣味嗜好", "label": "派生"}, {"form": "趣味人", "label": "派生"}, {"form": "趣味的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 好きで遊びのようにすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51941, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「しゅみ」と読む、聞こえた語そのもの。"}, {"text": "趣旨", "is_correct": false, "explanation": "「しゅし」で、最後の音が「み」ではなく「し」。"}, {"text": "手記", "is_correct": false, "explanation": "「しゅき」で、最後の音が「み」ではなく「き」。"}, {"text": "首位", "is_correct": false, "explanation": "「しゅい」で、最後の音が「み」ではなく「い」。"}, {"text": "酒気", "is_correct": false, "explanation": "「しゅき」で、最後の音が「み」ではなく「き」。"}], "explanations": {"趣味": "「しゅみ」と読む、聞こえた語そのもの。", "趣旨": "「しゅし」で、最後の音が「み」ではなく「し」。", "手記": "「しゅき」で、最後の音が「み」ではなく「き」。", "首位": "「しゅい」で、最後の音が「み」ではなく「い」。", "酒気": "「しゅき」で、最後の音が「み」ではなく「き」。"}, "sentence_index": null, "correct_answer": "趣味"}, "level_3": {"options": [{"text": "趣味", "is_correct": true, "explanation": "好きで遊びのようにする活動を表し、「趣味で絵をかく」が自然。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「天気で絵をかく」では意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。「季節で絵をかく」は理由にならない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。「値段で絵をかく」では意味が通らない。"}], "explanations": {"趣味": "好きで遊びのようにする活動を表し、「趣味で絵をかく」が自然。", "天気": "形は合うが意味が合わない。「天気で絵をかく」では意味が通らない。", "季節": "形は合うが意味が合わない。「季節で絵をかく」は理由にならない。", "値段": "形は合うが意味が合わない。「値段で絵をかく」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "趣味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は毎日、趣味を洗っている。", "explanation": "「趣味」は活動の分野で、物ではないので「洗う」ことはできない。"}, {"text": "趣味が痛いので病院へ行った。", "explanation": "「趣味」は体の部位ではなく、「痛い」の主語にならない。"}, {"text": "趣味は右に曲がると駅がある。", "explanation": "「趣味」は場所ではないので、道案内の主題にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51941, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「しゅみ」と読む、聞こえた語そのもの。"}, {"text": "紙", "is_correct": false, "explanation": "「かみ」で、最初の音が「しゅ」ではなく「か」。"}, {"text": "墨", "is_correct": false, "explanation": "「すみ」で、最初の音が「しゅ」ではなく「す」。"}, {"text": "染み", "is_correct": false, "explanation": "「しみ」で、最初の音が「しゅ」ではなく「し」。"}, {"text": "主義", "is_correct": false, "explanation": "「しゅぎ」で、最後の音が「み」ではなく「ぎ」。"}], "explanations": {"趣味": "「しゅみ」と読む、聞こえた語そのもの。", "紙": "「かみ」で、最初の音が「しゅ」ではなく「か」。", "墨": "「すみ」で、最初の音が「しゅ」ではなく「す」。", "染み": "「しみ」で、最初の音が「しゅ」ではなく「し」。", "主義": "「しゅぎ」で、最後の音が「み」ではなく「ぎ」。"}, "sentence_index": null, "correct_answer": "趣味"}, "level_3": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「趣味が同じ」で、楽しみのためにする活動が共通していることを表す。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気が同じことは彼女とよく話す理由にならない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。「季節が同じなので」では話す理由として意味が通らない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが意味が合わない。「地震が同じ」とは言わない。"}], "explanations": {"趣味": "「趣味が同じ」で、楽しみのためにする活動が共通していることを表す。", "天気": "形は合うが意味が合わない。天気が同じことは彼女とよく話す理由にならない。", "季節": "形は合うが意味が合わない。「季節が同じなので」では話す理由として意味が通らない。", "地震": "形は合うが意味が合わない。「地震が同じ」とは言わない。"}, "sentence_index": 6, "correct_answer": "趣味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "趣味が泣いているので、そっとしておいた。", "explanation": "「趣味」は人や動物ではないので「泣く」の主語にならない。"}, {"text": "趣味に乗って、駅まで行った。", "explanation": "「趣味」は乗り物ではないので「乗る」と結びつかない。"}, {"text": "趣味を折って、ごみ箱に入れた。", "explanation": "「趣味」は物ではないので「折る」ことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.pro