INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51942, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「私の趣味」で、趣味の持ち主を表す。"}, {"text": "を", "is_correct": false, "explanation": "「私を趣味は」では文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「私で趣味は」では文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「私から趣味は」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「私の趣味」で、趣味の持ち主を表す。", "を": "「私を趣味は」では文が成り立たない。", "で": "「私で趣味は」では文が成り立たない。", "から": "「私から趣味は」では文が成り立たない。"}, "error_tags": {"を": "object_marker", "で": "means_marker", "から": "source_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "仕事", "is_correct": true, "explanation": "楽しみで行う趣味に対し、義務として行う仕事が対義語。"}, {"text": "遊び", "is_correct": false, "explanation": "遊びは趣味に近い意味で、対義語ではない。"}, {"text": "娯楽", "is_correct": false, "explanation": "娯楽は楽しみの活動で、類義語に近い。"}, {"text": "好み", "is_correct": false, "explanation": "好みは趣味に近く、対義語ではない。"}], "correct_answer": "仕事", "explanations": {"仕事": "楽しみで行う趣味に対し、義務として行う仕事が対義語。", "遊び": "遊びは趣味に近い意味で、対義語ではない。", "娯楽": "娯楽は楽しみの活動で、類義語に近い。", "好み": "好みは趣味に近く、対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51942, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「趣味で始めた」で、動機・目的を表す。"}, {"text": "に", "is_correct": false, "explanation": "「趣味に始めた料理」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「趣味へ始めた」は方向の助詞で不自然。"}, {"text": "と", "is_correct": false, "explanation": "「趣味と始めた料理」では意味が通らない。"}], "correct_answer": "で", "explanations": {"で": "「趣味で始めた」で、動機・目的を表す。", "に": "「趣味に始めた料理」では意味が通らない。", "へ": "「趣味へ始めた」は方向の助詞で不自然。", "と": "「趣味と始めた料理」では意味が通らない。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "本業", "is_correct": true, "explanation": "趣味に対し、生計のための本来の仕事である本業が対義的。"}, {"text": "特技", "is_correct": false, "explanation": "特技は得意なことで、趣味の対義語ではない。"}, {"text": "余暇", "is_correct": false, "explanation": "余暇は趣味を行う時間で、対義語ではない。"}, {"text": "習慣", "is_correct": false, "explanation": "習慣は繰り返す行動で、対義語ではない。"}], "correct_answer": "本業", "explanations": {"本業": "趣味に対し、生計のための本来の仕事である本業が対義的。", "特技": "特技は得意なことで、趣味の対義語ではない。", "余暇": "余暇は趣味を行う時間で、対義語ではない。", "習慣": "習慣は繰り返す行動で、対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51942, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "仕事や義務ではなく、個人が楽しみのために行う活動。", "primary_collocate": null, "pronunciation": "しゅみ", "ipa": "ɕɯmi", "syllable_count": 2, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "趣味", "complexity_tier": "T6", "furigana": "趣味[しゅみ]で手作[てづく]りしたアクセサリーを収入[しゅうにゅう]につなげたいなら、オンラインビジネスの構築[こうちく]が有効[ゆうこう]です。", "sentence_source": "mined"}, {"text": "私の趣味は絵だ。", "target_word": "趣味", "complexity_tier": "T1", "furigana": "私[わたし]の趣味[しゅみ]は絵[え]だ。", "sentence_source": "generated"}, {"text": "趣味は何ですか。", "target_word": "趣味", "complexity_tier": "T2", "furigana": "趣味[しゅみ]は何[なん]ですか。", "sentence_source": "generated"}, {"text": "兄は趣味で写真を撮っています。", "target_word": "趣味", "complexity_tier": "T2", "furigana": "兄[あに]は趣味[しゅみ]で写真[しゃしん]を撮[と]っています。", "sentence_source": "generated"}, {"text": "趣味を仕事にするのは難しい。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "趣味[しゅみ]を仕事[しごと]にするのは難[むずか]しい。", "sentence_source": "generated"}, {"text": "休みの日は、趣味の時間を大切にしている。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]は、趣味[しゅみ]の時間[じかん]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "同じ趣味を持つ人と友達になった。", "target_word": "趣味", "complexity_tier": "T3", "furigana": "同[おな]じ趣味[しゅみ]を持[も]つ人[ひと]と友達[ともだち]になった。", "sentence_source": "generated"}, {"text": "趣味で始めた料理が、いつの間にか仕事になった。", "target_word": "趣味", "complexity_tier": "T4", "furigana": "趣味[しゅみ]で始[はじ]めた料理[りょうり]が、いつの間[ま]にか仕事[しごと]になった。", "sentence_source": "generated"}, {"text": "忙しくても、趣味を楽しむ余裕を忘れないようにしている。", "target_word": "趣味", "complexity_tier": "T4", "furigana": "忙[いそが]しくても、趣味[しゅみ]を楽[たの]しむ余裕[よゆう]を忘[わす]れないようにしている。", "sentence_source": "generated"}, {"text": "趣味に使うお金を減らさなければ、貯金はなかなか増えないだろう。", "target_word": "趣味", "complexity_tier": "T5", "furigana": "趣味[しゅみ]に使[つか]うお金[かね]を減[へ]らさなければ、貯金[ちょきん]はなかなか増[ふ]えないだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "趣味嗜好", "label": "派生"}, {"form": "趣味人", "label": "派生"}, {"form": "趣味的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 楽しみのために行う活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51942, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「しゅみ」と読む、聞こえた語そのもの。"}, {"text": "趣旨", "is_correct": false, "explanation": "「しゅし」で、最後の音が「み」ではなく「し」。"}, {"text": "守備", "is_correct": false, "explanation": "「しゅび」で、最後の音が「み」ではなく「び」。"}, {"text": "酒気", "is_correct": false, "explanation": "「しゅき」で、最後の音が「み」ではなく「き」。"}, {"text": "主義", "is_correct": false, "explanation": "「しゅぎ」で、最後の音が「み」ではなく「ぎ」。"}], "explanations": {"趣味": "「しゅみ」と読む、聞こえた語そのもの。", "趣旨": "「しゅし」で、最後の音が「み」ではなく「し」。", "守備": "「しゅび」で、最後の音が「み」ではなく「び」。", "酒気": "「しゅき」で、最後の音が「み」ではなく「き」。", "主義": "「しゅぎ」で、最後の音が「み」ではなく「ぎ」。"}, "sentence_index": null, "correct_answer": "趣味"}, "level_3": {"options": [{"text": "趣味", "is_correct": true, "explanation": "楽しみのための活動を表し、「趣味で手作りした」と自然につながる。"}, {"text": "義務", "is_correct": false, "explanation": "形は合うが意味が合わない。義務で作ったものを収入につなげる文脈にならない。"}, {"text": "命令", "is_correct": false, "explanation": "形は合うが意味が合わない。「命令で手作りした」は楽しみで作った話とずれる。"}, {"text": "規則", "is_correct": false, "explanation": "形は合うが意味が合わない。「規則で手作りした」では文の意味が通らない。"}], "explanations": {"趣味": "楽しみのための活動を表し、「趣味で手作りした」と自然につながる。", "義務": "形は合うが意味が合わない。義務で作ったものを収入につなげる文脈にならない。", "命令": "形は合うが意味が合わない。「命令で手作りした」は楽しみで作った話とずれる。", "規則": "形は合うが意味が合わない。「規則で手作りした」では文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "趣味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、駅で趣味を落としてしまった。", "explanation": "「趣味」は活動の分野であり、物ではないので「落とす」ことはできない。"}, {"text": "母は毎朝、趣味を食べている。", "explanation": "「趣味」は食べ物ではないので「食べる」とは結びつかない。"}, {"text": "趣味が足りないので、もう一杯水を飲んだ。", "explanation": "「趣味」は飲み物のように量が足りなくなるものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51942, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「しゅみ」と読む、聞こえた語そのもの。"}, {"text": "紙", "is_correct": false, "explanation": "「かみ」で、最初の音が「しゅ」ではなく「か」。"}, {"text": "墨", "is_correct": false, "explanation": "「すみ」で、最初の音が「しゅ」ではなく「す」。"}, {"text": "手記", "is_correct": false, "explanation": "「しゅき」で、最後の音が「み」ではなく「き」。"}, {"text": "首位", "is_correct": false, "explanation": "「しゅい」で、最後の音が「み」ではなく「い」。"}], "explanations": {"趣味": "「しゅみ」と読む、聞こえた語そのもの。", "紙": "「かみ」で、最初の音が「しゅ」ではなく「か」。", "墨": "「すみ」で、最初の音が「しゅ」ではなく「す」。", "手記": "「しゅき」で、最後の音が「み」ではなく「き」。", "首位": "「しゅい」で、最後の音が「み」ではなく「い」。"}, "sentence_index": null, "correct_answer": "趣味"}, "level_3": {"options": [{"text": "趣味", "is_correct": true, "explanation": "「同じ趣味を持つ人」で、共通の楽しみを持つ人を表す。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。人が「同じ季節を持つ」とは言わない。"}, {"text": "温度", "is_correct": false, "explanation": "形は合うが意味が合わない。人が「同じ温度を持つ」では友達になる理由にならない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。人が「同じ天気を持つ」とは言わない。"}], "explanations": {"趣味": "「同じ趣味を持つ人」で、共通の楽しみを持つ人を表す。", "季節": "形は合うが意味が合わない。人が「同じ季節を持つ」とは言わない。", "温度": "形は合うが意味が合わない。人が「同じ温度を持つ」では友達になる理由にならない。", "天気": "形は合うが意味が合わない。人が「同じ天気を持つ」とは言わない。"}, "sentence_index": 6, "correct_answer": "趣味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は趣味を着て出かけた。", "explanation": "「趣味」は衣服ではないので「着る」とは結びつかない。"}, {"text": "趣味が降ってきたので傘をさした。", "explanation": "「趣味」は天気現象ではなく、「降る」の主語にならない。"}, {"text": "趣味は学校まで歩いて十分だ。", "explanation": "「趣味」は場所ではないので、距離や時間を述べる文の主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
