INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「学ぶ」の対象を表すのは「を」。"}, {"text": "の", "is_correct": false, "explanation": "「ビジネスの学ぶ」は動詞の前に置けない。"}, {"text": "へ", "is_correct": false, "explanation": "「ビジネスへ学ぶ」は方向の助詞が合わず成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「私はビジネスが学ぶ」では、ビジネスが学ぶ主体になり文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「学ぶ」の対象を表すのは「を」。", "の": "「ビジネスの学ぶ」は動詞の前に置けない。", "へ": "「ビジネスへ学ぶ」は方向の助詞が合わず成り立たない。", "が": "「私はビジネスが学ぶ」では、ビジネスが学ぶ主体になり文が成り立たない。"}, "error_tags": {"の": "wrong_case", "へ": "direction", "が": "subject_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "趣味", "is_correct": true, "explanation": "お金をかせぐ仕事に対し、好きで楽しむ活動で対義的。"}, {"text": "商売", "is_correct": false, "explanation": "お金をかせぐ仕事で、類義語になる。"}, {"text": "給料", "is_correct": false, "explanation": "仕事で得るお金で、対義の関係ではない。"}, {"text": "会議", "is_correct": false, "explanation": "仕事上の話し合いで、対義の関係ではない。"}], "correct_answer": "趣味", "explanations": {"趣味": "お金をかせぐ仕事に対し、好きで楽しむ活動で対義的。", "商売": "お金をかせぐ仕事で、類義語になる。", "給料": "仕事で得るお金で、対義の関係ではない。", "会議": "仕事上の話し合いで、対義の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きくする」の対象を示すのは「を」。"}, {"text": "に", "is_correct": false, "explanation": "「ビジネスに大きくする」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ビジネスの大きくする」は動詞の前で使えない。"}, {"text": "が", "is_correct": false, "explanation": "「大きくする」は他動詞なので「ビジネスが大きくする」は成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「大きくする」の対象を示すのは「を」。", "に": "「ビジネスに大きくする」は文法的に成り立たない。", "の": "「ビジネスの大きくする」は動詞の前で使えない。", "が": "「大きくする」は他動詞なので「ビジネスが大きくする」は成り立たない。"}, "error_tags": {"に": "wrong_case", "の": "wrong_case", "が": "subject_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "プライベート", "is_correct": true, "explanation": "仕事に対する私的な生活で、対義語になる。"}, {"text": "商売", "is_correct": false, "explanation": "お金をかせぐ仕事で、類義語。"}, {"text": "事業", "is_correct": false, "explanation": "商売や活動を指し、類義語。"}, {"text": "社長", "is_correct": false, "explanation": "会社の人を指し、対義の関係ではない。"}], "correct_answer": "プライベート", "explanations": {"プライベート": "仕事に対する私的な生活で、対義語になる。", "商売": "お金をかせぐ仕事で、類義語。", "事業": "商売や活動を指し、類義語。", "社長": "会社の人を指し、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金をかせぐための仕事や活動のことです。", "primary_collocate": null, "pronunciation": "びじねす", "ipa": "bidʑinesɯ", "syllable_count": 4, "sentences": [{"text": "ビジネスは楽しい。", "target_word": "ビジネス", "complexity_tier": "T1", "furigana": "ビジネスは楽[たの]しい。", "sentence_source": "generated"}, {"text": "私はビジネスを学ぶ。", "target_word": "ビジネス", "complexity_tier": "T1", "furigana": "私[わたし]はビジネスを学[まな]ぶ。", "sentence_source": "generated"}, {"text": "母はビジネスをしています。", "target_word": "ビジネス", "complexity_tier": "T2", "furigana": "母[はは]はビジネスをしています。", "sentence_source": "generated"}, {"text": "ビジネスで大切なのは信用です。", "target_word": "ビジネス", "complexity_tier": "T2", "furigana": "ビジネスで大切[たいせつ]なのは信用[しんよう]です。", "sentence_source": "generated"}, {"text": "大学で、ビジネスについて勉強している。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "大学[だいがく]で、ビジネスについて勉強[べんきょう]している。", "sentence_source": "generated"}, {"text": "家族でビジネスをして、お金をかせいだ。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "家族[かぞく]でビジネスをして、お金[かね]をかせいだ。", "sentence_source": "generated"}, {"text": "ビジネスの相手と、値段について話し合った。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "ビジネスの相手[あいて]と、値段[ねだん]について話[はな]し合[あ]った。", "sentence_source": "generated"}, {"text": "ビジネスを大きくするために、人を雇うことにした。", "target_word": "ビジネス", "complexity_tier": "T4", "furigana": "ビジネスを大[おお]きくするために、人[ひと]を雇[やと]うことにした。", "sentence_source": "generated"}, {"text": "彼はビジネスで成功して、有名になったそうだ。", "target_word": "ビジネス", "complexity_tier": "T4", "furigana": "彼[かれ]はビジネスで成功[せいこう]して、有名[ゆうめい]になったそうだ。", "sentence_source": "generated"}, {"text": "学生のうちに小さなビジネスを始めておけば、将来きっと役に立つと思う。", "target_word": "ビジネス", "complexity_tier": "T5", "furigana": "学生[がくせい]のうちに小[ちい]さなビジネスを始[はじ]めておけば、将来[しょうらい]きっと役[やく]に立[た]つと思[おも]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビジネスマン", "label": "派生"}, {"form": "ビジネスパーソン", "label": "派生"}, {"form": "ビジネス街", "label": "派生"}, {"form": "ビジネスホテル", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | お金をかせぐ仕事や商売", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: かせい (Zipf 2.25)']::text[], 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビジネス", "is_correct": true, "explanation": "「楽しい」と評価できる仕事や活動なので意味が合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、物の机が「楽しい」とは意味が合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが、物の鉛筆が「楽しい」とは意味が合わない。"}, {"text": "財布", "is_correct": false, "explanation": "形は合うが、財布が楽しいという意味は合わない。"}], "explanations": {"ビジネス": "「楽しい」と評価できる仕事や活動なので意味が合う。", "机": "形は合うが、物の机が「楽しい」とは意味が合わない。", "鉛筆": "形は合うが、物の鉛筆が「楽しい」とは意味が合わない。", "財布": "形は合うが、財布が楽しいという意味は合わない。"}, "sentence_index": 0, "correct_answer": "ビジネス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ご飯にビジネスを三つ食べて、学校へ行った。", "explanation": "ビジネスは仕事や商売の活動で、食べる物ではない。"}, {"text": "ビジネスは昨日、公園で犬と走っていました。", "explanation": "ビジネスは活動を表し、人や動物のように走る主語にならない。"}, {"text": "このビジネスは重くて、片手で持てません。", "explanation": "ビジネスは形のない活動で、持ち上げる重さを表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビジネス", "is_correct": true, "explanation": "商売で取引する相手なので、値段について話し合うのが自然。"}, {"text": "湯気", "is_correct": false, "explanation": "形は合うが、「湯気の相手」とは言わず意味が通らない。"}, {"text": "瞬き", "is_correct": false, "explanation": "形は合うが、「瞬きの相手」と値段を話し合うことはない。"}, {"text": "雨水", "is_correct": false, "explanation": "形は合うが、「雨水の相手」では意味が通らない。"}], "explanations": {"ビジネス": "商売で取引する相手なので、値段について話し合うのが自然。", "湯気": "形は合うが、「湯気の相手」とは言わず意味が通らない。", "瞬き": "形は合うが、「瞬きの相手」と値段を話し合うことはない。", "雨水": "形は合うが、「雨水の相手」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "ビジネス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生のうちに小さなビジネスを飲んでおけば、将来きっと役に立つと思う。", "explanation": "ビジネスは活動で、飲む物ではないので「飲む」と合わない。"}, {"text": "学生のうちに小さなビジネスを洗っておけば、将来きっと役に立つと思う。", "explanation": "ビジネスは洗える物ではなく、「洗う」とは使えない。"}, {"text": "学生のうちに小さなビジネスを着ておけば、将来きっと役に立つと思う。", "explanation": "ビジネスは衣服ではなく、「着る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は来月、自分のビジネスが始める予定だ。", "corrected_sentence": "姉は来月、自分のビジネスを始める予定だ。", "error_description": "「始める」は他動詞なので、対象のビジネスには「が」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51943, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄は大学を出てすぐ、自分のビジネスが立ち上げた。", "corrected_sentence": "兄は大学を出てすぐ、自分のビジネスを立ち上げた。", "error_description": "「立ち上げる」は他動詞なので、対象は「ビジネスが」ではなく「ビジネスを」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始める」の対象を示す助詞は「を」。"}, {"text": "に", "is_correct": false, "explanation": "「ビジネスに始めた」は文法的に成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ビジネスの始めた」は動詞の前で使えない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「始める」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「始める」の対象を示す助詞は「を」。", "に": "「ビジネスに始めた」は文法的に成り立たない。", "の": "「ビジネスの始めた」は動詞の前で使えない。", "へ": "「へ」は方向を表し、「始める」の対象にはならない。"}, "error_tags": {"に": "wrong_case", "の": "wrong_case", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "プライベート", "is_correct": true, "explanation": "仕事や商売の領域に対し、私的な生活を表す対義語。"}, {"text": "商売", "is_correct": false, "explanation": "ビジネスとほぼ同じ意味で、対義語ではなく類義語。"}, {"text": "経営", "is_correct": false, "explanation": "ビジネスを運営することで、対義の関係ではない。"}, {"text": "会社", "is_correct": false, "explanation": "ビジネスを行う組織で、対義の関係ではない。"}], "correct_answer": "プライベート", "explanations": {"プライベート": "仕事や商売の領域に対し、私的な生活を表す対義語。", "商売": "ビジネスとほぼ同じ意味で、対義語ではなく類義語。", "経営": "ビジネスを運営することで、対義の関係ではない。", "会社": "ビジネスを行う組織で、対義の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「成功させる」の対象を示すのは「を」。"}, {"text": "が", "is_correct": false, "explanation": "「成功させる」は他動詞的な使役なので「ビジネスが成功させる」は成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「ビジネスの成功させる」は動詞の前で使えない。"}, {"text": "と", "is_correct": false, "explanation": "「ビジネスと成功させる」は意味も文法も成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「成功させる」の対象を示すのは「を」。", "が": "「成功させる」は他動詞的な使役なので「ビジネスが成功させる」は成り立たない。", "の": "「ビジネスの成功させる」は動詞の前で使えない。", "と": "「ビジネスと成功させる」は意味も文法も成り立たない。"}, "error_tags": {"が": "subject_marker", "の": "wrong_case", "と": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "ボランティア", "is_correct": true, "explanation": "利益を目的としない活動で、ビジネスの対義語になる。"}, {"text": "営業", "is_correct": false, "explanation": "商売を行うことで、ビジネスと近い意味。"}, {"text": "取引", "is_correct": false, "explanation": "商売上のやりとりで、対義の関係ではない。"}, {"text": "起業", "is_correct": false, "explanation": "ビジネスを始めることで、対義の関係ではない。"}], "correct_answer": "ボランティア", "explanations": {"ボランティア": "利益を目的としない活動で、ビジネスの対義語になる。", "営業": "商売を行うことで、ビジネスと近い意味。", "取引": "商売上のやりとりで、対義の関係ではない。", "起業": "ビジネスを始めることで、対義の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "利益を得ることを目的とした、商品やサービスを売買する活動や組織のこと。", "primary_collocate": null, "pronunciation": "びじねす", "ipa": "bidʑinesɯ", "syllable_count": 4, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "ビジネス", "complexity_tier": "T6", "furigana": "趣味[しゅみ]で手作[てづく]りしたアクセサリーを収入[しゅうにゅう]につなげたいなら、オンラインビジネスの構築[こうちく]が有効[ゆうこう]です。", "sentence_source": "mined"}, {"text": "兄はビジネスを始めた。", "target_word": "ビジネス", "complexity_tier": "T1", "furigana": "兄[あに]はビジネスを始[はじ]めた。", "sentence_source": "generated"}, {"text": "父はビジネスで海外に行きます。", "target_word": "ビジネス", "complexity_tier": "T2", "furigana": "父[ちち]はビジネスで海外[かいがい]に行[い]きます。", "sentence_source": "generated"}, {"text": "小さなビジネスを経営しています。", "target_word": "ビジネス", "complexity_tier": "T2", "furigana": "小[ちい]さなビジネスを経営[けいえい]しています。", "sentence_source": "generated"}, {"text": "新しいビジネスを考えて、友達に話した。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "新[あたら]しいビジネスを考[かんが]えて、友達[ともだち]に話[はな]した。", "sentence_source": "generated"}, {"text": "ビジネスがうまくいって、店が増えた。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "ビジネスがうまくいって、店[みせ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼はビジネスの経験が豊富だ。", "target_word": "ビジネス", "complexity_tier": "T3", "furigana": "彼[かれ]はビジネスの経験[けいけん]が豊富[ほうふ]だ。", "sentence_source": "generated"}, {"text": "ビジネスを成功させるには、お客さんの声を聞くことが大切だ。", "target_word": "ビジネス", "complexity_tier": "T4", "furigana": "ビジネスを成功[せいこう]させるには、お客[きゃく]さんの声[こえ]を聞[き]くことが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "不況のせいで、ビジネスが続けられなくなってしまった。", "target_word": "ビジネス", "complexity_tier": "T4", "furigana": "不況[ふきょう]のせいで、ビジネスが続[つづ]けられなくなってしまった。", "sentence_source": "generated"}, {"text": "ネットで始めたビジネスが急に大きくなり、一人では対応できなくなった。", "target_word": "ビジネス", "complexity_tier": "T5", "furigana": "ネットで始[はじ]めたビジネスが急[きゅう]に大[おお]きくなり、一人[ひとり]では対応[たいおう]できなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビジネスマン", "label": "派生"}, {"form": "ビジネスパーソン", "label": "派生"}, {"form": "ビジネス街", "label": "派生"}, {"form": "ビジネスホテル", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 利益を目的とする商売や事業活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'afb0b9dc-8502-47d9-83d8-0f94025ad970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビジネス", "is_correct": true, "explanation": "収入につなげる活動なので「オンラインビジネス」が意味に合う。"}, {"text": "スポーツ", "is_correct": false, "explanation": "形は合うが、収入につなげる構築という文脈に意味が合わない。"}, {"text": "ダイエット", "is_correct": false, "explanation": "形は合うが、アクセサリーで収入を得る話に意味が合わない。"}, {"text": "マラソン", "is_correct": false, "explanation": "形は合うが、収入につなげる活動の構築という意味に合わない。"}], "explanations": {"ビジネス": "収入につなげる活動なので「オンラインビジネス」が意味に合う。", "スポーツ": "形は合うが、収入につなげる構築という文脈に意味が合わない。", "ダイエット": "形は合うが、アクセサリーで収入を得る話に意味が合わない。", "マラソン": "形は合うが、収入につなげる活動の構築という意味に合わない。"}, "sentence_index": 0, "correct_answer": "ビジネス"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夜ご飯に、小さなビジネスを食べました。", "explanation": "ビジネスは売買する活動や組織で、食べ物ではないので「食べる」とは使えない。"}, {"text": "空に小さなビジネスが三つ浮かんでいる。", "explanation": "ビジネスは活動や組織を表し、空に浮かぶ物体の意味はない。"}, {"text": "このビジネスは雨で、とても冷たいです。", "explanation": "ビジネスは天気や温度を表す言葉ではなく、「雨で冷たい」の主語にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビジネス", "is_correct": true, "explanation": "経験が豊富だと言える、商売や事業の活動なので意味が合う。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが、身長は経験が豊富という言い方に意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気の経験が豊富という意味は不自然。"}, {"text": "誕生日", "is_correct": false, "explanation": "形は合うが、誕生日の経験が豊富という意味は合わない。"}], "explanations": {"ビジネス": "経験が豊富だと言える、商売や事業の活動なので意味が合う。", "身長": "形は合うが、身長は経験が豊富という言い方に意味が合わない。", "天気": "形は合うが、天気の経験が豊富という意味は不自然。", "誕生日": "形は合うが、誕生日の経験が豊富という意味は合わない。"}, "sentence_index": 6, "correct_answer": "ビジネス"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ネットで始めたビジネスが急に赤くなり、一人では食べられなくなった。", "explanation": "ビジネスは色がつく物でも食べ物でもなく、「赤くなる」「食べる」とは使えない。"}, {"text": "ビジネスは毎朝七時に起きて、顔を洗っている。", "explanation": "ビジネスは活動や組織で、人のように起きて顔を洗う主語にはならない。"}, {"text": "このビジネスは机の引き出しに入れてあります。", "explanation": "ビジネスは形のある物ではなく、引き出しに入れることはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達は去年ビジネスに始めて、今は忙しい。", "corrected_sentence": "友達は去年ビジネスを始めて、今は忙しい。", "error_description": "「始める」の対象はビジネスなので、「ビジネスに」ではなく「ビジネスを」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51944, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔父は貿易のビジネスにやっていて、忙しそうだ。", "corrected_sentence": "叔父は貿易のビジネスをやっていて、忙しそうだ。", "error_description": "「やる」の対象を示すには「ビジネスに」ではなく「ビジネスを」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68baf8d1-af76-4644-87f6-d671494844aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
