INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51946, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目標や計画がうまく実現すること。", "primary_collocate": null, "pronunciation": "せいこう", "ipa": "seːkoː", "syllable_count": 4, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "成功", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "成功はチームのおかげです。", "target_word": "成功", "complexity_tier": "T2", "furigana": "成功[せいこう]はチームのおかげです。", "sentence_source": "generated"}, {"text": "成功を祈る。", "target_word": "成功", "complexity_tier": "T1", "furigana": "成功[せいこう]を祈[いの]る。", "sentence_source": "generated"}, {"text": "今回の発売は成功でした。", "target_word": "成功", "complexity_tier": "T2", "furigana": "今回[こんかい]の発売[はつばい]は成功[せいこう]でした。", "sentence_source": "generated"}, {"text": "実験の成功をみんなで喜びました。", "target_word": "成功", "complexity_tier": "T2", "furigana": "実験[じっけん]の成功[せいこう]をみんなで喜[よろこ]びました。", "sentence_source": "generated"}, {"text": "新しい店の宣伝が成功して、客が増えている。", "target_word": "成功", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]の宣伝[せんでん]が成功[せいこう]して、客[きゃく]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "実験に成功した人の話を聞いてみたい。", "target_word": "成功", "complexity_tier": "T3", "furigana": "実験[じっけん]に成功[せいこう]した人[ひと]の話[はなし]を聞[き]いてみたい。", "sentence_source": "generated"}, {"text": "この計画を成功させるために、毎日話し合っています。", "target_word": "成功", "complexity_tier": "T4", "furigana": "この計画[けいかく]を成功[せいこう]させるために、毎日[まいにち]話[はな]し合[あ]っています。", "sentence_source": "generated"}, {"text": "準備をしっかりすれば、成功する可能性は高くなる。", "target_word": "成功", "complexity_tier": "T4", "furigana": "準備[じゅんび]をしっかりすれば、成功[せいこう]する可能性[かのうせい]は高[たか]くなる。", "sentence_source": "generated"}, {"text": "小さな店から始めた彼の成功は、多くの若い人に勇気を与えた。", "target_word": "成功", "complexity_tier": "T5", "furigana": "小[ちい]さな店[みせ]から始[はじ]めた彼[かれ]の成功[せいこう]は、多[おお]くの若[わか]い人[ひと]に勇気[ゆうき]を与[あた]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "成功する", "label": "派生"}, {"form": "成功させる", "label": "派生"}, {"form": "成功率", "label": "派生"}, {"form": "成功者", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目標や計画がうまく実現すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51946, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成功", "is_correct": true, "explanation": "せいこう。聞いた語そのもの。"}, {"text": "製造", "is_correct": false, "explanation": "せいぞう。「こ」が「ぞ」に変わるので別の語。"}, {"text": "清掃", "is_correct": false, "explanation": "せいそう。「こ」が「そ」に変わるので別の語。"}, {"text": "整合", "is_correct": false, "explanation": "せいごう。「こ」が「ご」と濁るので別の語。"}, {"text": "政党", "is_correct": false, "explanation": "せいとう。「こ」が「と」に変わるので別の語。"}], "explanations": {"成功": "せいこう。聞いた語そのもの。", "製造": "せいぞう。「こ」が「ぞ」に変わるので別の語。", "清掃": "せいそう。「こ」が「そ」に変わるので別の語。", "整合": "せいごう。「こ」が「ご」と濁るので別の語。", "政党": "せいとう。「こ」が「と」に変わるので別の語。"}, "sentence_index": null, "correct_answer": "成功"}, "level_3": {"options": [{"text": "成功", "is_correct": true, "explanation": "「成功の鍵」で、マーケティングがうまくいくための要点という意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気の鍵」は写真やマーケティングの話と意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「地震の鍵」は商品を届ける話と意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「季節の鍵」は工夫やマーケティングの内容と意味が合わない。"}], "explanations": {"成功": "「成功の鍵」で、マーケティングがうまくいくための要点という意味に合う。", "天気": "形は合うが、「天気の鍵」は写真やマーケティングの話と意味が合わない。", "地震": "形は合うが、「地震の鍵」は商品を届ける話と意味が合わない。", "季節": "形は合うが、「季節の鍵」は工夫やマーケティングの内容と意味が合わない。"}, "sentence_index": 0, "correct_answer": "成功"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "成功を飲んで、元気になりました。", "explanation": "成功は目標が実現することで、飲み物のような具体物として使えない。"}, {"text": "電車が遅れて約束に間に合わなかったのは、成功でした。", "explanation": "成功は思い通りにうまくいくことなので、困った出来事に使うと意味が合わない。"}, {"text": "この机には成功が三つあります。", "explanation": "成功は数えられる物ではなく、机にある物として使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51946, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成功", "is_correct": true, "explanation": "せいこう。聞いた語そのもの。"}, {"text": "製法", "is_correct": false, "explanation": "せいほう。「こ」が「ほ」に変わるので別の語。"}, {"text": "青銅", "is_correct": false, "explanation": "せいどう。「こ」が「ど」に変わるので別の語。"}, {"text": "盛況", "is_correct": false, "explanation": "せいきょう。「こ」が「きょ」に変わるので別の語。"}, {"text": "西洋", "is_correct": false, "explanation": "せいよう。「こ」が「よ」に変わるので別の語。"}], "explanations": {"成功": "せいこう。聞いた語そのもの。", "製法": "せいほう。「こ」が「ほ」に変わるので別の語。", "青銅": "せいどう。「こ」が「ど」に変わるので別の語。", "盛況": "せいきょう。「こ」が「きょ」に変わるので別の語。", "西洋": "せいよう。「こ」が「よ」に変わるので別の語。"}, "sentence_index": null, "correct_answer": "成功"}, "level_3": {"options": [{"text": "成功", "is_correct": true, "explanation": "「成功した人」で、うまく実現させた人という意味になり、話を聞きたい相手として自然。"}, {"text": "故障", "is_correct": false, "explanation": "形は合うが、人が「故障した」とは言えず意味が合わない。"}, {"text": "停電", "is_correct": false, "explanation": "形は合うが、人が「停電した」とは言えず意味が合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "形は合うが、人が実験に「沸騰した」とは言えず意味が合わない。"}], "explanations": {"成功": "「成功した人」で、うまく実現させた人という意味になり、話を聞きたい相手として自然。", "故障": "形は合うが、人が「故障した」とは言えず意味が合わない。", "停電": "形は合うが、人が「停電した」とは言えず意味が合わない。", "沸騰": "形は合うが、人が実験に「沸騰した」とは言えず意味が合わない。"}, "sentence_index": 6, "correct_answer": "成功"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は試験に落ちて、大きな成功を味わった。", "explanation": "試験に落ちることは失敗で、成功の意味と合わない。"}, {"text": "小さな店から始めた彼は、成功を電車で持って帰った。", "explanation": "成功は持ち運べる物ではなく、物として扱うのは誤り。"}, {"text": "彼の成功は、窓の外で三回鳴った。", "explanation": "成功は音を出すものではなく、鳴るという動作と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_vali