INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51947, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ねらうもの。めあて。", "primary_collocate": null, "pronunciation": "たーげっと", "ipa": "taːɡetto", "syllable_count": 5, "sentences": [{"text": "ターゲットを見る。", "target_word": "ターゲット", "complexity_tier": "T1", "furigana": "ターゲットを見[み]る。", "sentence_source": "generated"}, {"text": "矢がターゲットに当たった。", "target_word": "ターゲット", "complexity_tier": "T2", "furigana": "矢[や]がターゲットに当[あ]たった。", "sentence_source": "generated"}, {"text": "ターゲットは遠くにあります。", "target_word": "ターゲット", "complexity_tier": "T2", "furigana": "ターゲットは遠[とお]くにあります。", "sentence_source": "generated"}, {"text": "彼はターゲットをよく見て、ボールを投げた。", "target_word": "ターゲット", "complexity_tier": "T3", "furigana": "彼[かれ]はターゲットをよく見[み]て、ボールを投[な]げた。", "sentence_source": "generated"}, {"text": "ターゲットまでの距離は十メートルです。", "target_word": "ターゲット", "complexity_tier": "T3", "furigana": "ターゲットまでの距離[きょり]は十[じゅう]メートルです。", "sentence_source": "generated"}, {"text": "弓を引いて、ターゲットの真ん中をねらった。", "target_word": "ターゲット", "complexity_tier": "T3", "furigana": "弓[ゆみ]を引[ひ]いて、ターゲットの真[ま]ん中[なか]をねらった。", "sentence_source": "generated"}, {"text": "ターゲットが動くと、当てるのがとても難しくなる。", "target_word": "ターゲット", "complexity_tier": "T4", "furigana": "ターゲットが動[うご]くと、当[あ]てるのがとても難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "ゲームでは、画面に出たターゲットを早く撃った人が勝つ。", "target_word": "ターゲット", "complexity_tier": "T4", "furigana": "ゲームでは、画面[がめん]に出[で]たターゲットを早[はや]く撃[う]った人[ひと]が勝[か]つ。", "sentence_source": "generated"}, {"text": "練習では、ターゲットに全部当てることを今月の目標にしている。", "target_word": "ターゲット", "complexity_tier": "T4", "furigana": "練習[れんしゅう]では、ターゲットに全部[ぜんぶ]当[あ]てることを今月[こんげつ]の目標[もくひょう]にしている。", "sentence_source": "generated"}, {"text": "選手たちはターゲットの位置を何度も確かめてから、静かに矢を放った。", "target_word": "ターゲット", "complexity_tier": "T5", "furigana": "選手[せんしゅ]たちはターゲットの位置[いち]を何度[なんど]も確[たし]かめてから、静[しず]かに矢[や]を放[はな]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ターゲット層", "label": "派生"}, {"form": "ターゲット広告", "label": "派生"}, {"form": "ターゲティング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ねらって当てる的やめあて", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51947, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ターゲット", "is_correct": true, "explanation": "「ターゲットを見る」で、狙う的を見るという意味になる。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、「空腹を見る」は意味が合わない。"}, {"text": "勇気", "is_correct": false, "explanation": "形は合うが、「勇気を見る」は意味が合わない。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが、「約束を見る」は意味が合わない。"}], "explanations": {"ターゲット": "「ターゲットを見る」で、狙う的を見るという意味になる。", "空腹": "形は合うが、「空腹を見る」は意味が合わない。", "勇気": "形は合うが、「勇気を見る」は意味が合わない。", "約束": "形は合うが、「約束を見る」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "ターゲット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はターゲットを書いて、手紙を送った。", "explanation": "ターゲットは狙う的で、書いて送る物ではない。"}, {"text": "ターゲットを着て、学校へ行った。", "explanation": "ターゲットは狙う的で、着る服ではない。"}, {"text": "このターゲットは甘くて、おいしかった。", "explanation": "ターゲットは的で、味を感じる食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
