INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51948, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目標、対象。特に、ある活動や販売などで狙うべき人や物。", "primary_collocate": null, "pronunciation": "たーげっと", "ipa": "taːɡetto", "syllable_count": 5, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "ターゲット", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "ターゲットは若い人です。", "target_word": "ターゲット", "complexity_tier": "T2", "furigana": "ターゲットは若[わか]い人[ひと]です。", "sentence_source": "generated"}, {"text": "新しいターゲットを決めた。", "target_word": "ターゲット", "complexity_tier": "T2", "furigana": "新[あたら]しいターゲットを決[き]めた。", "sentence_source": "generated"}, {"text": "この広告のターゲットは主婦です。", "target_word": "ターゲット", "complexity_tier": "T2", "furigana": "この広告[こうこく]のターゲットは主婦[しゅふ]です。", "sentence_source": "generated"}, {"text": "ターゲットを絞って、商品を宣伝している。", "target_word": "ターゲット", "complexity_tier": "T3", "furigana": "ターゲットを絞[しぼ]って、商品[しょうひん]を宣伝[せんでん]している。", "sentence_source": "generated"}, {"text": "ターゲットになる客の年齢を調べました。", "target_word": "ターゲット", "complexity_tier": "T3", "furigana": "ターゲットになる客[きゃく]の年齢[ねんれい]を調[しら]べました。", "sentence_source": "generated"}, {"text": "ターゲットが広すぎると、メッセージが伝わりにくい。", "target_word": "ターゲット", "complexity_tier": "T4", "furigana": "ターゲットが広[ひろ]すぎると、メッセージが伝[つた]わりにくい。", "sentence_source": "generated"}, {"text": "このアプリは子どもをターゲットにして作られた。", "target_word": "ターゲット", "complexity_tier": "T4", "furigana": "このアプリは子[こ]どもをターゲットにして作[つく]られた。", "sentence_source": "generated"}, {"text": "店は会社員をターゲットに、昼の安いセットを売り出した。", "target_word": "ターゲット", "complexity_tier": "T5", "furigana": "店[みせ]は会社員[かいしゃいん]をターゲットに、昼[ひる]の安[やす]いセットを売[う]り出[だ]した。", "sentence_source": "generated"}, {"text": "ターゲットとなる客層をはっきりさせてから、広告の内容を考えるべきだ。", "target_word": "ターゲ