INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51948, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ターゲット", "is_correct": true, "explanation": "「ターゲット層」で、商品を届ける狙いの客層という意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気層」は意味が合わない。"}, {"text": "台所", "is_correct": false, "explanation": "形は合うが、「台所層」は意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「地震層」は商品を届ける話と意味が合わない。"}], "explanations": {"ターゲット": "「ターゲット層」で、商品を届ける狙いの客層という意味に合う。", "天気": "形は合うが、「天気層」は意味が合わない。", "台所": "形は合うが、「台所層」は意味が合わない。", "地震": "形は合うが、「地震層」は商品を届ける話と意味が合わない。"}, "sentence_index": 0, "correct_answer": "ターゲット"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ターゲットを食べて、お腹がいっぱいになった。", "explanation": "ターゲットは狙う対象で、食べ物ではない。"}, {"text": "ターゲットが痛くて病院に行った。", "explanation": "ターゲットは体の部位ではなく、痛むものとして使うのは誤り。"}, {"text": "この広告のターゲットは昨日の雨でした。", "explanation": "広告のターゲットは狙う人や物で、天気は当てはまらない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
