INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51949, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つのものをくっつけることです。", "primary_collocate": null, "pronunciation": "つなげる", "ipa": "tsunaɡeɾɯ", "syllable_count": 4, "sentences": [{"text": "ひもをつなげる。", "target_word": "つなげる", "complexity_tier": "T1", "furigana": "ひもをつなげる。", "sentence_source": "generated"}, {"text": "二つのパイプをつなげました。", "target_word": "つなげ", "complexity_tier": "T2", "furigana": "二[ふた]つのパイプをつなげました。", "sentence_source": "generated"}, {"text": "電車を二つつなげて、長くしました。", "target_word": "つなげて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]を二[ふた]つつなげて、長[なが]くしました。", "sentence_source": "generated"}, {"text": "テレビとパソコンをケーブルでつなげた。", "target_word": "つなげた", "complexity_tier": "T3", "furigana": "テレビとパソコンをケーブルでつなげた。", "sentence_source": "generated"}, {"text": "短いロープをつなげて、長いロープを作った。", "target_word": "つなげて", "complexity_tier": "T3", "furigana": "短[みじか]いロープをつなげて、長[なが]いロープを作[つく]った。", "sentence_source": "generated"}, {"text": "机を二つつなげれば、みんなで座れる。", "target_word": "つなげれば", "complexity_tier": "T4", "furigana": "机[つくえ]を二[ふた]つつなげれば、みんなで座[すわ]れる。", "sentence_source": "generated"}, {"text": "切れた糸をつなげるのは、思ったより難しい。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "切[き]れた糸[いと]をつなげるのは、思[おも]ったより難[むずか]しい。", "sentence_source": "generated"}, {"text": "ホースをつなげる前に、水を止めておいてください。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "ホースをつなげる前[まえ]に、水[みず]を止[と]めておいてください。", "sentence_source": "generated"}, {"text": "二つの部屋をつなげる工事が終わり、広い一つの部屋になった。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "二[ふた]つの部屋[へや]をつなげる工事[こうじ]が終[お]わり、広[ひろ]い一[ひと]つの部屋[へや]になった。", "sentence_source": "generated"}, {"text": "壊れた橋をつなげるために、町の人たちが力を合わせて木を運んだ。", "target_word": "つなげる", "complexity_tier": "T5", "furigana": "壊[こわ]れた橋[はし]をつなげるために、町[まち]の人[ひと]たちが力[ちから]を合[あ]わせて木[き]を運[はこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つなげて", "label": "活用"}, {"form": "つなげない", "label": "活用"}, {"form": "つなげられる", "label": "活用"}, {"form": "繋がる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 二つのものをくっつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51949, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つなげる", "is_correct": true, "explanation": "ひもを結んでくっつけるという意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが意味が合わない。ひもは食べ物ではない。"}, {"text": "飲む", "is_correct": false, "explanation": "形は合うが意味が合わない。ひもは飲めない。"}, {"text": "読む", "is_correct": false, "explanation": "形は合うが意味が合わない。ひもは読む対象ではない。"}], "explanations": {"つなげる": "ひもを結んでくっつけるという意味に合う。", "食べる": "形は合うが意味が合わない。ひもは食べ物ではない。", "飲む": "形は合うが意味が合わない。ひもは飲めない。", "読む": "形は合うが意味が合わない。ひもは読む対象ではない。"}, "sentence_index": 0, "correct_answer": "つなげる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "はさみでひもをつなげて、短くした。", "explanation": "「つなげる」はくっつける意味で、切って短くする意味には使えない。"}, {"text": "ご飯をつなげて、お腹がいっぱいになった。", "explanation": "「つなげる」は食べる意味ではないので、ご飯を食べる場面に使うのは誤り。"}, {"text": "手紙をつなげて、友達に送った。", "explanation": "「つなげる」は送る意味ではないので、手紙を出す場面に使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51949, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つなげる", "is_correct": true, "explanation": "切れた糸をくっつけるのは難しいという意味に合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが意味が合わない。糸を食べるのが難しいという話にはならない。"}, {"text": "割る", "is_correct": false, "explanation": "形は合うが意味が合わない。切れた糸を割るという内容は成り立たない。"}, {"text": "聞く", "is_correct": false, "explanation": "形は合うが意味が合わない。糸は聞く対象ではない。"}], "explanations": {"つなげる": "切れた糸をくっつけるのは難しいという意味に合う。", "食べる": "形は合うが意味が合わない。糸を食べるのが難しいという話にはならない。", "割る": "形は合うが意味が合わない。切れた糸を割るという内容は成り立たない。", "聞く": "形は合うが意味が合わない。糸は聞く対象ではない。"}, "sentence_index": 6, "correct_answer": "つなげる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本をつなげて、一晩で全部読んだ。", "explanation": "「つなげる」はくっつける意味で、本を読む場面には使えない。"}, {"text": "紙をはさみでつなげて、二つにした。", "explanation": "「つなげる」はくっつける意味で、切って二つにする意味には使えない。"}, {"text": "窓をつなげて、風を入れた。", "explanation": "「つなげる」は窓を開ける意味ではなく、風を入れる場面に使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51949, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの机がつなげて、大きなテーブルにした。", "corrected_sentence": "二つの机をつなげて、大きなテーブルにした。", "error_description": "「つなげる」の対象は「を」で示す。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "つなげ", "is_correct": true, "explanation": "「ました」に続くのは連用形の「つなげ」。"}, {"text": "つなげる", "is_correct": false, "explanation": "辞書形に「ました」は続かず合わない。"}, {"text": "つなげた", "is_correct": false, "explanation": "た形に「ました」は続かず合わない。"}, {"text": "つなげない", "is_correct": false, "explanation": "否定形に「ました」は続かず合わない。"}], "correct_form": "つなげ", "base_form": "つなげる", "form_label": "連用形（ます形）", "sentence_index": 1, "explanations": {"つなげ": "「ました」に続くのは連用形の「つなげ」。", "つなげる": "辞書形に「ました」は続かず合わない。", "つなげた": "た形に「ました」は続かず合わない。", "つなげない": "否定形に「ました」は続かず合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51949, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "切れたロープがつなげるのは、思ったより大変だ。", "corrected_sentence": "切れたロープをつなげるのは、思ったより大変だ。", "error_description": "「つなげる」の対象は「を」で示す。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "つなげる", "is_correct": true, "explanation": "「前に」に続くのは辞書形で、ここに合う。"}, {"text": "つなげた", "is_correct": false, "explanation": "「前に」はた形に続かず合わない。"}, {"text": "つなげて", "is_correct": false, "explanation": "て形に「前に」は続かず合わない。"}, {"text": "つなげれば", "is_correct": false, "explanation": "仮定形に「前に」は続かず合わない。"}], "correct_form": "つなげる", "base_form": "つなげる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"つなげる": "「前に」に続くのは辞書形で、ここに合う。", "つなげた": "「前に」はた形に続かず合わない。", "つなげて": "て形に「前に」は続かず合わない。", "つなげれば": "仮定形に「前に」は続かず合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「成功につなげる」は結びつける先を表す。"}, {"text": "を", "is_correct": false, "explanation": "「努力を成功をつなげる」と「を」が重なり誤り。"}, {"text": "が", "is_correct": false, "explanation": "「努力を成功がつなげる」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「成功のつなげる」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「成功につなげる」は結びつける先を表す。", "を": "「努力を成功をつなげる」と「を」が重なり誤り。", "が": "「努力を成功がつなげる」は文として成り立たない。", "の": "「成功のつなげる」は文として成り立たない。"}, "error_tags": {"を": "object_marker_misuse", "が": "subject_marker_misuse", "の": "possessive_misuse"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "切り離す", "is_correct": true, "explanation": "結びつけるものを離すので、「つなげる」の反対の意味になる。"}, {"text": "結びつける", "is_correct": false, "explanation": "「つなげる」とほぼ同じ意味で、反対ではない。"}, {"text": "深める", "is_correct": false, "explanation": "程度を強める意味で、結びつける・離すの関係はない。"}, {"text": "続ける", "is_correct": false, "explanation": "継続する意味で、「つなげる」の反対ではない。"}], "correct_answer": "切り離す", "explanations": {"切り離す": "結びつけるものを離すので、「つなげる」の反対の意味になる。", "結びつける": "「つなげる」とほぼ同じ意味で、反対ではない。", "深める": "程度を強める意味で、結びつける・離すの関係はない。", "続ける": "継続する意味で、「つなげる」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「二つの話をつなげる」は対象を表す。"}, {"text": "の", "is_correct": false, "explanation": "「二つの話のうまくつなげられなかった」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「二つの話へうまくつなげられなかった」は対象を表せず不自然。"}, {"text": "ので", "is_correct": false, "explanation": "「二つの話ので」は名詞に直接つかず文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「二つの話をつなげる」は対象を表す。", "の": "「二つの話のうまくつなげられなかった」は文として成り立たない。", "へ": "「二つの話へうまくつなげられなかった」は対象を表せず不自然。", "ので": "「二つの話ので」は名詞に直接つかず文として成り立たない。"}, "error_tags": {"の": "possessive_misuse", "へ": "direction", "ので": "conjunction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分ける", "is_correct": true, "explanation": "結びつけるものを分けるので、「つなげる」の反対の意味になる。"}, {"text": "結ぶ", "is_correct": false, "explanation": "「つなげる」に近い意味で、反対ではない。"}, {"text": "重ねる", "is_correct": false, "explanation": "上に積む意味で、結びつける・離すの関係はない。"}, {"text": "深める", "is_correct": false, "explanation": "程度を強める意味で、反対語ではない。"}], "correct_answer": "分ける", "explanations": {"分ける": "結びつけるものを分けるので、「つなげる」の反対の意味になる。", "結ぶ": "「つなげる」に近い意味で、反対ではない。", "重ねる": "上に積む意味で、結びつける・離すの関係はない。", "深める": "程度を強める意味で、反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "離れているものを一つに結びつける。", "primary_collocate": null, "pronunciation": "つなげる", "ipa": "tsunaɡeɾɯ", "syllable_count": 4, "sentences": [{"text": "趣味で手作りしたアクセサリーを収入につなげたいなら、オンラインビジネスの構築が有効です。", "target_word": "つなげたい", "complexity_tier": "T6", "furigana": "趣味[しゅみ]で手作[てづく]りしたアクセサリーを収入[しゅうにゅう]につなげたいなら、オンラインビジネスの構築[こうちく]が有効[ゆうこう]です。", "sentence_source": "mined"}, {"text": "努力を成功につなげる。", "target_word": "つなげる", "complexity_tier": "T1", "furigana": "努力[どりょく]を成功[せいこう]につなげる。", "sentence_source": "generated"}, {"text": "経験を仕事につなげたいです。", "target_word": "つなげたい", "complexity_tier": "T2", "furigana": "経験[けいけん]を仕事[しごと]につなげたいです。", "sentence_source": "generated"}, {"text": "二つの意見をつなげて、新しい案を作りました。", "target_word": "つなげて", "complexity_tier": "T3", "furigana": "二[ふた]つの意見[いけん]をつなげて、新[あたら]しい案[あん]を作[つく]りました。", "sentence_source": "generated"}, {"text": "離れて暮らす家族をつなげるアプリを作った。", "target_word": "つなげる", "complexity_tier": "T3", "furigana": "離[はな]れて暮[く]らす家族[かぞく]をつなげるアプリを作[つく]った。", "sentence_source": "generated"}, {"text": "人と人をつなげる場所として、このカフェは作られた。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "人[ひと]と人[ひと]をつなげる場所[ばしょ]として、このカフェは作[つく]られた。", "sentence_source": "generated"}, {"text": "小さな成功を大きな自信につなげることが大切です。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "小[ちい]さな成功[せいこう]を大[おお]きな自信[じしん]につなげることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "二つの話をうまくつなげられなかったので、先生に相談した。", "target_word": "つなげられなかった", "complexity_tier": "T4", "furigana": "二[ふた]つの話[はなし]をうまくつなげられなかったので、先生[せんせい]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "話をつなげるのが上手な人は、会議でも信頼されやすい。", "target_word": "つなげる", "complexity_tier": "T4", "furigana": "話[はなし]をつなげるのが上手[じょうず]な人[ひと]は、会議[かいぎ]でも信頼[しんらい]されやすい。", "sentence_source": "generated"}, {"text": "バラバラだった情報を一つにつなげれば、全体の流れが見えてくる。", "target_word": "つなげれば", "complexity_tier": "T5", "furigana": "バラバラだった情報[じょうほう]を一[ひと]つにつなげれば、全体[ぜんたい]の流[なが]れが見[み]えてくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "つなげて", "label": "活用"}, {"form": "つなげない", "label": "活用"}, {"form": "つなげられる", "label": "活用"}, {"form": "繋がる", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 離れたものを結びつける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "つなげたい", "is_correct": true, "explanation": "手作りの品を収入に結びつけたいという意味に合う。"}, {"text": "隠したい", "is_correct": false, "explanation": "形は合うが意味が合わない。収入に隠すという内容は成り立たない。"}, {"text": "捨てたい", "is_correct": false, "explanation": "形は合うが意味が合わない。収入に捨てるでは文意が通らない。"}, {"text": "洗いたい", "is_correct": false, "explanation": "形は合うが意味が合わない。収入に洗うという内容は成り立たない。"}], "explanations": {"つなげたい": "手作りの品を収入に結びつけたいという意味に合う。", "隠したい": "形は合うが意味が合わない。収入に隠すという内容は成り立たない。", "捨てたい": "形は合うが意味が合わない。収入に捨てるでは文意が通らない。", "洗いたい": "形は合うが意味が合わない。収入に洗うという内容は成り立たない。"}, "sentence_index": 0, "correct_answer": "つなげたい"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ドアをつなげて、部屋に入った。", "explanation": "「つなげる」は結びつける意味で、ドアを開ける意味には使えない。"}, {"text": "牛乳をつなげて、全部飲んだ。", "explanation": "「つなげる」は結びつける意味で、飲む場面には使えない。"}, {"text": "窓をつなげて、風を部屋に入れた。", "explanation": "「つなげる」は窓を開ける意味ではないので、風を入れる場面に使うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "つなげる", "is_correct": true, "explanation": "小さな成功を自信に結びつけるという意味に合う。"}, {"text": "隠す", "is_correct": false, "explanation": "形は合うが意味が合わない。自信に隠すでは文意が通らない。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが意味が合わない。成功を自信に洗うという内容は成り立たない。"}, {"text": "捨てる", "is_correct": false, "explanation": "形は合うが意味が合わない。成功を自信に捨てるでは意味が通らない。"}], "explanations": {"つなげる": "小さな成功を自信に結びつけるという意味に合う。", "隠す": "形は合うが意味が合わない。自信に隠すでは文意が通らない。", "洗う": "形は合うが意味が合わない。成功を自信に洗うという内容は成り立たない。", "捨てる": "形は合うが意味が合わない。成功を自信に捨てるでは意味が通らない。"}, "sentence_index": 6, "correct_answer": "つなげる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "財布をつなげて、店で買い物をした。", "explanation": "「つなげる」は結びつける意味で、財布を出す・使う場面には合わない。"}, {"text": "電気をつなげて、部屋を暗くした。", "explanation": "「つなげる」は結びつける意味なので、暗くする場面には合わない。"}, {"text": "友達の名前をつなげて、全部忘れた。", "explanation": "「つなげる」は結びつける意味なので、忘れる内容とは矛盾して誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学んだことを仕事がつなげたいです。", "corrected_sentence": "学んだことを仕事につなげたいです。", "error_description": "結びつける先は「仕事に」と言う。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "つなげる", "is_correct": true, "explanation": "文末の普通体の現在形で、「成功につなげる」に合う。"}, {"text": "つなげれば", "is_correct": false, "explanation": "仮定形は文を言い切れず、ここでは合わない。"}, {"text": "つなげられ", "is_correct": false, "explanation": "受身・可能の語幹で、これだけでは文が終わらず合わない。"}, {"text": "つなげさせ", "is_correct": false, "explanation": "使役の語幹で、これだけでは文が終わらず合わない。"}], "correct_form": "つなげる", "base_form": "つなげる", "form_label": "辞書形", "sentence_index": 1, "explanations": {"つなげる": "文末の普通体の現在形で、「成功につなげる」に合う。", "つなげれば": "仮定形は文を言い切れず、ここでは合わない。", "つなげられ": "受身・可能の語幹で、これだけでは文が終わらず合わない。", "つなげさせ": "使役の語幹で、これだけでは文が終わらず合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51950, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小さな努力を結果をつなげることが大切だ。", "corrected_sentence": "小さな努力を結果につなげることが大切だ。", "error_description": "結びつける先は「結果に」と言う。「を」が重なって誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "つなげられなかった", "is_correct": true, "explanation": "「ので」の前で、過去の可能否定として文脈に合う。"}, {"text": "つなげられて", "is_correct": false, "explanation": "「て形」に「ので」は続かず、ここでは合わない。"}, {"text": "つなげられれば", "is_correct": false, "explanation": "仮定形に「ので」は続かず、合わない。"}, {"text": "つなげられなく", "is_correct": false, "explanation": "連用形に「ので」は続かず、合わない。"}], "correct_form": "つなげられなかった", "base_form": "つなげる", "form_label": "可能形・過去否定", "sentence_index": 7, "explanations": {"つなげられなかった": "「ので」の前で、過去の可能否定として文脈に合う。", "つなげられて": "「て形」に「ので」は続かず、ここでは合わない。", "つなげられれば": "仮定形に「ので」は続かず、合わない。", "つなげられなく": "連用形に「ので」は続かず、合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家族の写真」で名詞をつなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「家族を写真です」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、名詞「写真」を修飾できない。"}, {"text": "から", "is_correct": false, "explanation": "「家族から写真です」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「家族の写真」で名詞をつなぐ。", "を": "「家族を写真です」は成り立たない。", "へ": "方向を表す助詞で、名詞「写真」を修飾できない。", "から": "「家族から写真です」は成り立たない。"}, "error_tags": {"を": "object_misuse", "へ": "direction", "から": "source_misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「写真を撮る」で目的語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、「撮る」の目的語にならない。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「写真より撮るときは」は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「写真を撮る」で目的語を示す。", "へ": "方向を表す助詞で、「撮る」の目的語にならない。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "より": "「写真より撮るときは」は文として成り立たない。"}, "error_tags": {"へ": "direction", "ので": "reason_particle_misuse", "より": "comparison_misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "写真は、カメラでうつしたえです。", "primary_collocate": "撮る", "pronunciation": "しゃしん", "ipa": "ɕaɕiɴ", "syllable_count": 3, "sentences": [{"text": "写真を見る。", "target_word": "写真", "complexity_tier": "T1", "furigana": "写真[しゃしん]を見[み]る。", "sentence_source": "generated"}, {"text": "これは家族の写真です。", "target_word": "写真", "complexity_tier": "T2", "furigana": "これは家族[かぞく]の写真[しゃしん]です。", "sentence_source": "generated"}, {"text": "きのう公園で写真を撮りました。", "target_word": "写真", "complexity_tier": "T2", "furigana": "きのう公園[こうえん]で写真[しゃしん]を撮[と]りました。", "sentence_source": "generated"}, {"text": "写真に犬がうつっています。", "target_word": "写真", "complexity_tier": "T3", "furigana": "写真[しゃしん]に犬[いぬ]がうつっています。", "sentence_source": "generated"}, {"text": "壁に家族の写真をかざってあります。", "target_word": "写真", "complexity_tier": "T3", "furigana": "壁[かべ]に家族[かぞく]の写真[しゃしん]をかざってあります。", "sentence_source": "generated"}, {"text": "旅行のとき、たくさん写真を撮って、友達に送った。", "target_word": "写真", "complexity_tier": "T4", "furigana": "旅行[りょこう]のとき、たくさん写真[しゃしん]を撮[と]って、友達[ともだち]に送[おく]った。", "sentence_source": "generated"}, {"text": "写真がきらいな人は、あまりカメラの前に立たない。", "target_word": "写真", "complexity_tier": "T4", "furigana": "写真[しゃしん]がきらいな人[ひと]は、あまりカメラの前[まえ]に立[た]たない。", "sentence_source": "generated"}, {"text": "写真を撮るときは、明るいところに立つとよく写る。", "target_word": "写真", "complexity_tier": "T4", "furigana": "写真[しゃしん]を撮[と]るときは、明[あか]るいところに立[た]つとよく写[うつ]る。", "sentence_source": "generated"}, {"text": "古い写真を見ると、子どものころの楽しかった日を思い出す。", "target_word": "写真", "complexity_tier": "T4", "furigana": "古[ふる]い写真[しゃしん]を見[み]ると、子[こ]どものころの楽[たの]しかった日[ひ]を思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "祖父の部屋には、若いころの祖母が笑っている写真が一枚だけ飾られていた。", "target_word": "写真", "complexity_tier": "T5", "furigana": "祖父[そふ]の部屋[へや]には、若[わか]いころの祖母[そぼ]が笑[わら]っている写真[しゃしん]が一枚[いちまい]だけ飾[かざ]られていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "写真集", "label": "派生"}, {"form": "写真家", "label": "派生"}, {"form": "集合写真", "label": "派生"}, {"form": "写真立て", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | カメラでうつした絵や姿", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: かざっ (Zipf 2.02)']::text[], 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写真", "is_correct": true, "explanation": "見出し語そのもの「しゃしん」。"}, {"text": "車線", "is_correct": false, "explanation": "しゃせん：2拍目が「し」でなく「せ」。"}, {"text": "主審", "is_correct": false, "explanation": "しゅしん：1拍目が「しゃ」でなく「しゅ」。"}, {"text": "家臣", "is_correct": false, "explanation": "かしん：1拍目が「しゃ」でなく「か」。"}, {"text": "保身", "is_correct": false, "explanation": "ほしん：1拍目が「しゃ」でなく「ほ」。"}], "explanations": {"写真": "見出し語そのもの「しゃしん」。", "車線": "しゃせん：2拍目が「し」でなく「せ」。", "主審": "しゅしん：1拍目が「しゃ」でなく「しゅ」。", "家臣": "かしん：1拍目が「しゃ」でなく「か」。", "保身": "ほしん：1拍目が「しゃ」でなく「ほ」。"}, "sentence_index": null, "correct_answer": "写真"}, "level_3": {"options": [{"text": "写真", "is_correct": true, "explanation": "「見る」の対象として意味が合う。"}, {"text": "音", "is_correct": false, "explanation": "形は合うが、音は目で見るものではなく意味が合わない。"}, {"text": "匂い", "is_correct": false, "explanation": "形は合うが、匂いは見るものではなく意味が合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、眠気は見るものではなく意味が合わない。"}], "explanations": {"写真": "「見る」の対象として意味が合う。", "音": "形は合うが、音は目で見るものではなく意味が合わない。", "匂い": "形は合うが、匂いは見るものではなく意味が合わない。", "眠気": "形は合うが、眠気は見るものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "写真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、写真を飲んでから学校へ行きます。", "explanation": "写真は飲むものではなく、「飲む」との組み合わせが誤り。"}, {"text": "昨日の写真は、とても速く走りました。", "explanation": "写真は画像で、乗り物のように走ることはない。"}, {"text": "写真を履いて公園へ行きました。", "explanation": "写真は履く物ではなく、「履く」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "写真", "is_correct": true, "explanation": "見出し語そのもの「しゃしん」。"}, {"text": "車輪", "is_correct": false, "explanation": "しゃりん：2拍目が「し」でなく「り」。"}, {"text": "邪心", "is_correct": false, "explanation": "じゃしん：1拍目が清音「しゃ」でなく濁音「じゃ」。"}, {"text": "指針", "is_correct": false, "explanation": "ししん：1拍目が「しゃ」でなく「し」。"}, {"text": "過信", "is_correct": false, "explanation": "かしん：1拍目が「しゃ」でなく「か」。"}], "explanations": {"写真": "見出し語そのもの「しゃしん」。", "車輪": "しゃりん：2拍目が「し」でなく「り」。", "邪心": "じゃしん：1拍目が清音「しゃ」でなく濁音「じゃ」。", "指針": "ししん：1拍目が「しゃ」でなく「し」。", "過信": "かしん：1拍目が「しゃ」でなく「か」。"}, "sentence_index": null, "correct_answer": "写真"}, "level_3": {"options": [{"text": "写真", "is_correct": true, "explanation": "写真がきらいな人はカメラの前に立たない、と意味がつながる。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが、野菜ぎらいとカメラの前に立たないことは関係なく意味が合わない。"}, {"text": "数学", "is_correct": false, "explanation": "形は合うが、数学ぎらいとカメラの前に立たないことは関係なく意味が合わない。"}, {"text": "犬", "is_correct": false, "explanation": "形は合うが、犬ぎらいとカメラの前に立たないことは関係なく意味が合わない。"}], "explanations": {"写真": "写真がきらいな人はカメラの前に立たない、と意味がつながる。", "野菜": "形は合うが、野菜ぎらいとカメラの前に立たないことは関係なく意味が合わない。", "数学": "形は合うが、数学ぎらいとカメラの前に立たないことは関係なく意味が合わない。", "犬": "形は合うが、犬ぎらいとカメラの前に立たないことは関係なく意味が合わない。"}, "sentence_index": 6, "correct_answer": "写真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父の部屋には、若いころの祖母が笑っている写真が一人で歩いていた。", "explanation": "写真は自分で歩く主語にはならず、「歩く」との組み合わせが誤り。"}, {"text": "祖父は、若いころの祖母が笑っている写真を毎朝着て出かけた。", "explanation": "写真は身に着ける物ではなく、「着る」と結びつかない。"}, {"text": "祖父は、若いころの祖母が笑っている写真を大きな声で歌っていた。", "explanation": "写真は歌うものではなく、「歌う」との組み合わせが誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used,