INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "壁に家族の写真をかぶってあります。", "corrected_sentence": "壁に家族の写真をかざってあります。", "error_description": "「写真をかぶる」は誤り。写真を壁に置いて見せるときは「かざる」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51951, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卒業式で、みんなで写真を引いた。", "corrected_sentence": "卒業式で、みんなで写真を撮った。", "error_description": "「写真を引く」は誤り。写真には「撮る」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「写真の工夫」で名詞をつなぐ。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「写真から工夫」は名詞どうしの結びつきとして成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、名詞「工夫」を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「写真の工夫」で名詞をつなぐ。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "から": "「写真から工夫」は名詞どうしの結びつきとして成り立たない。", "へ": "方向を表す助詞で、名詞「工夫」を修飾できない。"}, "error_tags": {"ので": "reason_particle_misuse", "から": "source_misuse", "へ": "direction"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この写真は」で話題を示す。"}, {"text": "の", "is_correct": false, "explanation": "「この写真の、祖母が…」では文の主題が欠けて成り立たない。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す助詞で、この文では成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「この写真は」で話題を示す。", "の": "「この写真の、祖母が…」では文の主題が欠けて成り立たない。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "へ": "方向を表す助詞で、この文では成り立たない。"}, "error_tags": {"の": "possessive_misuse", "ので": "reason_particle_misuse", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "写真とは、カメラを使って被写体を光で記録した画像のことです。", "primary_collocate": "撮る", "pronunciation": "しゃしん", "ipa": "ɕaɕiɴ", "syllable_count": 3, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "写真", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "写真を撮る。", "target_word": "写真", "complexity_tier": "T1", "furigana": "写真[しゃしん]を撮[と]る。", "sentence_source": "generated"}, {"text": "この写真はきれいです。", "target_word": "写真", "complexity_tier": "T2", "furigana": "この写真[しゃしん]はきれいです。", "sentence_source": "generated"}, {"text": "友達と一緒に写真を撮りました。", "target_word": "写真", "complexity_tier": "T2", "furigana": "友達[ともだち]と一緒[いっしょ]に写真[しゃしん]を撮[と]りました。", "sentence_source": "generated"}, {"text": "旅行で撮った写真を見せてください。", "target_word": "写真", "complexity_tier": "T3", "furigana": "旅行[りょこう]で撮[と]った写真[しゃしん]を見[み]せてください。", "sentence_source": "generated"}, {"text": "写真がうまく撮れるカメラを買った。", "target_word": "写真", "complexity_tier": "T3", "furigana": "写真[しゃしん]がうまく撮[と]れるカメラを買[か]った。", "sentence_source": "generated"}, {"text": "スマホの写真をパソコンに送っておいた。", "target_word": "写真", "complexity_tier": "T3", "furigana": "スマホの写真[しゃしん]をパソコンに送[おく]っておいた。", "sentence_source": "generated"}, {"text": "この写真は、祖母が若いころに撮ったものだそうだ。", "target_word": "写真", "complexity_tier": "T4", "furigana": "この写真[しゃしん]は、祖母[そぼ]が若[わか]いころに撮[と]ったものだそうだ。", "sentence_source": "generated"}, {"text": "写真を撮られるのが苦手で、いつも顔が固くなってしまう。", "target_word": "写真", "complexity_tier": "T4", "furigana": "写真[しゃしん]を撮[と]られるのが苦手[にがて]で、いつも顔[かお]が固[かた]くなってしまう。", "sentence_source": "generated"}, {"text": "古い写真を整理していたら、忘れていた思い出が次々によみがえってきた。", "target_word": "写真", "complexity_tier": "T5", "furigana": "古[ふる]い写真[しゃしん]を整理[せいり]していたら、忘[わす]れていた思[おも]い出[で]が次々[つぎつぎ]によみがえってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "写真集", "label": "派生"}, {"form": "写真家", "label": "派生"}, {"form": "集合写真", "label": "派生"}, {"form": "写真立て", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | カメラで光を記録した画像", "collocate_grounding": {"status": "no_source", "reason": "grounding deferred for this language — no frequency source"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "写真", "is_correct": true, "explanation": "見出し語そのもの「しゃしん」。"}, {"text": "車線", "is_correct": false, "explanation": "しゃせん：2拍目が「し」でなく「せ」。"}, {"text": "車輪", "is_correct": false, "explanation": "しゃりん：2拍目が「し」でなく「り」。"}, {"text": "邪心", "is_correct": false, "explanation": "じゃしん：1拍目が清音「しゃ」でなく濁音「じゃ」。"}, {"text": "指針", "is_correct": false, "explanation": "ししん：1拍目が「しゃ」でなく「し」。"}, {"text": "保身", "is_correct": false, "explanation": "ほしん：1拍目が「しゃ」でなく「ほ」。"}], "explanations": {"写真": "見出し語そのもの「しゃしん」。", "車線": "しゃせん：2拍目が「し」でなく「せ」。", "車輪": "しゃりん：2拍目が「し」でなく「り」。", "邪心": "じゃしん：1拍目が清音「しゃ」でなく濁音「じゃ」。", "指針": "ししん：1拍目が「しゃ」でなく「し」。", "保身": "ほしん：1拍目が「しゃ」でなく「ほ」。"}, "sentence_index": null, "correct_answer": "写真"}, "level_3": {"options": [{"text": "写真", "is_correct": true, "explanation": "商品の魅力を伝える手段として意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、商品の魅力を伝える工夫という意味が合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、魅力を伝えるものではなく意味が合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが、商品の魅力を伝えることと関係なく意味が合わない。"}], "explanations": {"写真": "商品の魅力を伝える手段として意味が合う。", "天気": "形は合うが、商品の魅力を伝える工夫という意味が合わない。", "地震": "形は合うが、魅力を伝えるものではなく意味が合わない。", "洗濯": "形は合うが、商品の魅力を伝えることと関係なく意味が合わない。"}, "sentence_index": 0, "correct_answer": "写真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達と一緒に写真を食べました。", "explanation": "写真は食べるものではなく、「食べる」と組み合わせると意味が成り立たない。"}, {"text": "友達と一緒に写真が走りました。", "explanation": "写真は画像であり、自分で走る主語にはならない。"}, {"text": "友達と一緒に写真を着ました。", "explanation": "写真は身に着ける物ではないので、「着る」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "写真", "is_correct": true, "explanation": "見出し語そのもの「しゃしん」。"}, {"text": "主審", "is_correct": false, "explanation": "しゅしん：1拍目が「しゃ」でなく「しゅ」。"}, {"text": "家臣", "is_correct": false, "explanation": "かしん：1拍目が「しゃ」でなく「か」。"}, {"text": "私心", "is_correct": false, "explanation": "ししん：1拍目が「しゃ」でなく「し」。"}, {"text": "社員", "is_correct": false, "explanation": "しゃいん：2拍目が「し」でなく「い」。"}], "explanations": {"写真": "見出し語そのもの「しゃしん」。", "主審": "しゅしん：1拍目が「しゃ」でなく「しゅ」。", "家臣": "かしん：1拍目が「しゃ」でなく「か」。", "私心": "ししん：1拍目が「しゃ」でなく「し」。", "社員": "しゃいん：2拍目が「し」でなく「い」。"}, "sentence_index": null, "correct_answer": "写真"}, "level_3": {"options": [{"text": "写真", "is_correct": true, "explanation": "スマホに入っていてパソコンに送れるデータとして意味が合う。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、スマホの机は存在せず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、スマホの天気をパソコンに送るという意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節を送るという意味が合わない。"}], "explanations": {"写真": "スマホに入っていてパソコンに送れるデータとして意味が合う。", "机": "形は合うが、スマホの机は存在せず意味が合わない。", "天気": "形は合うが、スマホの天気をパソコンに送るという意味が合わない。", "季節": "形は合うが、季節を送るという意味が合わない。"}, "sentence_index": 6, "correct_answer": "写真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い写真を食べていたら、忘れていた思い出が次々によみがえってきた。", "explanation": "写真は食べるものではなく、「食べる」との組み合わせが誤り。"}, {"text": "古い写真を着ていたら、忘れていた思い出が次々によみがえってきた。", "explanation": "写真は身に着ける物ではなく、「着る」と結びつかない。"}, {"text": "古い写真を沸かしていたら、忘れていた思い出が次々によみがえってきた。", "explanation": "「沸かす」は湯などに使う語で、写真には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51952, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公園で友達と写真を打ちました。", "corrected_sentence": "公園で友達と写真を撮りました。", "error_description": "「写真を打つ」は不自然。写真には「撮る」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
