INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「先生に届ける」で届ける相手を示す。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "ほど", "is_correct": false, "explanation": "「先生ほど宿題を」は相手を示せず成り立たない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と共に使うため、ここでは成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「先生に届ける」で届ける相手を示す。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "ほど": "「先生ほど宿題を」は相手を示せず成り立たない。", "しか": "「しか」は否定と共に使うため、ここでは成り立たない。"}, "error_tags": {"ので": "reason_particle_misuse", "ほど": "degree_misuse", "しか": "negation_required"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "届ける（渡す側）の反対で、受ける側の動作。"}, {"text": "渡す", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "贈る", "is_correct": false, "explanation": "人に物をあげる意味で、届けるの反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "届ける（渡す側）の反対で、受ける側の動作。", "渡す": "届けるに近い意味で、反対ではない。", "運ぶ": "届けるに近い意味で、反対ではない。", "贈る": "人に物をあげる意味で、届けるの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「各家庭に届ける」で届ける相手を示す。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "ながら", "is_correct": false, "explanation": "同時動作を表す語で、名詞「各家庭」に直接つかない。"}, {"text": "ほど", "is_correct": false, "explanation": "「各家庭ほど届ける」は相手を示せず成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「各家庭に届ける」で届ける相手を示す。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "ながら": "同時動作を表す語で、名詞「各家庭」に直接つかない。", "ほど": "「各家庭ほど届ける」は相手を示せず成り立たない。"}, "error_tags": {"ので": "reason_particle_misuse", "ながら": "simultaneity_misuse", "ほど": "degree_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "届ける（渡す側）の反対で、受ける側の動作。"}, {"text": "配る", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "持つ", "is_correct": false, "explanation": "手に持つ意味で、届けるの反対ではない。"}, {"text": "贈る", "is_correct": false, "explanation": "人に物をあげる意味で、届けるの反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "届ける（渡す側）の反対で、受ける側の動作。", "配る": "届けるに近い意味で、反対ではない。", "持つ": "手に持つ意味で、届けるの反対ではない。", "贈る": "人に物をあげる意味で、届けるの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "だれかに何かを持って行って、あたえる。", "primary_collocate": null, "pronunciation": "とどける", "ipa": "todokeɾɯ", "syllable_count": 4, "sentences": [{"text": "本を届ける。", "target_word": "届ける", "complexity_tier": "T1", "furigana": "本[ほん]を届[とど]ける。", "sentence_source": "generated"}, {"text": "先生に宿題を届けました。", "target_word": "届け", "complexity_tier": "T2", "furigana": "先生[せんせい]に宿題[しゅくだい]を届[とど]けました。", "sentence_source": "generated"}, {"text": "母にお弁当を届けた。", "target_word": "届けた", "complexity_tier": "T2", "furigana": "母[はは]にお弁当[べんとう]を届[とど]けた。", "sentence_source": "generated"}, {"text": "隣の家に、おみやげを届けに行きます。", "target_word": "届け", "complexity_tier": "T3", "furigana": "隣[となり]の家[いえ]に、おみやげを届[とど]けに行[い]きます。", "sentence_source": "generated"}, {"text": "忘れた傘を駅まで届けてあげた。", "target_word": "届けて", "complexity_tier": "T3", "furigana": "忘[わす]れた傘[かさ]を駅[えき]まで届[とど]けてあげた。", "sentence_source": "generated"}, {"text": "病気の友達にノートを届けてあげたい。", "target_word": "届けて", "complexity_tier": "T3", "furigana": "病気[びょうき]の友達[ともだち]にノートを届[とど]けてあげたい。", "sentence_source": "generated"}, {"text": "祖母に届けるはずの荷物が、まだ家に残っている。", "target_word": "届ける", "complexity_tier": "T4", "furigana": "祖母[そぼ]に届[とど]けるはずの荷物[にもつ]が、まだ家[いえ]に残[のこ]っている。", "sentence_source": "generated"}, {"text": "朝早く、牛乳を各家庭に届ける仕事をしている。", "target_word": "届ける", "complexity_tier": "T4", "furigana": "朝早[あさはや]く、牛乳[ぎゅうにゅう]を各家庭[かくかてい]に届[とど]ける仕事[しごと]をしている。", "sentence_source": "generated"}, {"text": "届ける相手が留守だったので、荷物を管理人に預けた。", "target_word": "届ける", "complexity_tier": "T4", "furigana": "届[とど]ける相手[あいて]が留守[るす]だったので、荷物[にもつ]を管理人[かんりにん]に預[あず]けた。", "sentence_source": "generated"}, {"text": "寒い夜に、温かいスープを一人暮らしの老人に届けるボランティアが、町で始まった。", "target_word": "届ける", "complexity_tier": "T5", "furigana": "寒[さむ]い夜[よる]に、温[あたた]かいスープを一人暮[ひとりぐ]らしの老人[ろうじん]に届[とど]けるボランティアが、町[まち]で始[はじ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "届けた", "label": "活用"}, {"form": "届けて", "label": "活用"}, {"form": "届けられる", "label": "活用"}, {"form": "届く", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 人に物を持って行って渡す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "届ける", "is_correct": true, "explanation": "本を持って行って渡すという意味が合う。"}, {"text": "食べる", "is_correct": false, "explanation": "形は合うが、本を食べるという意味が合わない。"}, {"text": "履く", "is_correct": false, "explanation": "形は合うが、本を履くという意味が合わない。"}, {"text": "飲む", "is_correct": false, "explanation": "形は合うが、本を飲むという意味が合わない。"}], "explanations": {"届ける": "本を持って行って渡すという意味が合う。", "食べる": "形は合うが、本を食べるという意味が合わない。", "履く": "形は合うが、本を履くという意味が合わない。", "飲む": "形は合うが、本を飲むという意味が合わない。"}, "sentence_index": 0, "correct_answer": "届ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "隣の家を、おみやげに届けに行きます。", "explanation": "届ける相手は「に」、物は「を」で示す。ここでは助詞が逆で意味が成り立たない。"}, {"text": "隣の家に、時間を届けに行きます。", "explanation": "時間は持って行って渡せる物ではなく、「届ける」の対象にならない。"}, {"text": "おみやげが隣の家を届けに行きます。", "explanation": "届ける側と届けられる物が逆で、おみやげが家を届けることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "届ける", "is_correct": true, "explanation": "祖母に荷物を持って行くはずという意味が合う。"}, {"text": "笑う", "is_correct": false, "explanation": "形は合うが、祖母に笑うはずの荷物では意味が合わない。"}, {"text": "怒る", "is_correct": false, "explanation": "形は合うが、祖母に怒るはずの荷物では意味が合わない。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、祖母に眠るはずの荷物では意味が合わない。"}], "explanations": {"届ける": "祖母に荷物を持って行くはずという意味が合う。", "笑う": "形は合うが、祖母に笑うはずの荷物では意味が合わない。", "怒る": "形は合うが、祖母に怒るはずの荷物では意味が合わない。", "眠る": "形は合うが、祖母に眠るはずの荷物では意味が合わない。"}, "sentence_index": 6, "correct_answer": "届ける"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い夜に、温かいスープを一人暮らしの老人を届けるボランティアが、町で始まった。", "explanation": "届ける相手は「に」で示すが、「老人を」だと老人が届けられる物になり意味が誤り。"}, {"text": "寒い夜に、温かいスープを一人暮らしの老人に届くボランティアが、町で始まった。", "explanation": "「スープを」を目的語に取るのは他動詞「届ける」で、自動詞「届く」は使えない。"}, {"text": "寒い夜に、一人暮らしの老人にスープの寒さを届けるボランティアが、町で始まった。", "explanation": "寒さは持って行って渡せる物ではなく、「届ける」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達に本を届いてあげた。", "corrected_sentence": "友達に本を届けてあげた。", "error_description": "「本を」の目的語を取るのは他動詞「届ける」で、自動詞「届く」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "届け", "is_correct": true, "explanation": "「ました」に続くのは連用形（ます形の語幹）。"}, {"text": "届ける", "is_correct": false, "explanation": "終止形は「ました」に直接つながらない。"}, {"text": "届けて", "is_correct": false, "explanation": "て形は「ました」に直接つながらない。"}, {"text": "届けた", "is_correct": false, "explanation": "た形は「ました」に直接つながらない。"}], "correct_form": "届け", "base_form": "届ける", "form_label": "連用形（ます形）", "sentence_index": 1, "explanations": {"届け": "「ました」に続くのは連用形（ます形の語幹）。", "届ける": "終止形は「ました」に直接つながらない。", "届けて": "て形は「ました」に直接つながらない。", "届けた": "た形は「ました」に直接つながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51953, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朝、新聞を隣の家で届けた。", "corrected_sentence": "朝、新聞を隣の家に届けた。", "error_description": "届ける相手や場所には「で」でなく「に」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "届ける", "is_correct": true, "explanation": "「仕事」を修飾する連体形で、牛乳を配る仕事になる。"}, {"text": "届けよう", "is_correct": false, "explanation": "意向形は名詞「仕事」を直接修飾できない。"}, {"text": "届けろ", "is_correct": false, "explanation": "命令形は名詞「仕事」を修飾できない。"}, {"text": "届けさせ", "is_correct": false, "explanation": "使役の語幹で、名詞を直接修飾できない。"}], "correct_form": "届ける", "base_form": "届ける", "form_label": "連体形（辞書形）", "sentence_index": 7, "explanations": {"届ける": "「仕事」を修飾する連体形で、牛乳を配る仕事になる。", "届けよう": "意向形は名詞「仕事」を直接修飾できない。", "届けろ": "命令形は名詞「仕事」を修飾できない。", "届けさせ": "使役の語幹で、名詞を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「ターゲット層に届ける」で届ける相手を示す。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "ほど", "is_correct": false, "explanation": "「層ほど届ける」は相手を示せず成り立たない。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と共に使うため、ここでは成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「ターゲット層に届ける」で届ける相手を示す。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "ほど": "「層ほど届ける」は相手を示せず成り立たない。", "しか": "「しか」は否定と共に使うため、ここでは成り立たない。"}, "error_tags": {"ので": "reason_particle_misuse", "ほど": "degree_misuse", "しか": "negation_required"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "届ける（渡す側）の反対で、受ける側の動作。"}, {"text": "渡す", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "運ぶ", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "預ける", "is_correct": false, "explanation": "人に任せる意味で、届けるの反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "届ける（渡す側）の反対で、受ける側の動作。", "渡す": "届けるに近い意味で、反対ではない。", "運ぶ": "届けるに近い意味で、反対ではない。", "預ける": "人に任せる意味で、届けるの反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「多くの人に届ける」で届ける相手を示す。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接つかず、ここでは文法的に成り立たない。"}, {"text": "ながら", "is_correct": false, "explanation": "同時動作を表す語で、名詞「人」に直接つかない。"}, {"text": "ほど", "is_correct": false, "explanation": "「人ほど届けたい」は相手を示せず成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「多くの人に届ける」で届ける相手を示す。", "ので": "名詞に直接つかず、ここでは文法的に成り立たない。", "ながら": "同時動作を表す語で、名詞「人」に直接つかない。", "ほど": "「人ほど届けたい」は相手を示せず成り立たない。"}, "error_tags": {"ので": "reason_particle_misuse", "ながら": "simultaneity_misuse", "ほど": "degree_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受け取る", "is_correct": true, "explanation": "届ける（渡す側）の反対で、受ける側の動作。"}, {"text": "配る", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "送る", "is_correct": false, "explanation": "届けるに近い意味で、反対ではない。"}, {"text": "納める", "is_correct": false, "explanation": "決まった所へ渡す意味で、届けるの反対ではない。"}], "correct_answer": "受け取る", "explanations": {"受け取る": "届ける（渡す側）の反対で、受ける側の動作。", "配る": "届けるに近い意味で、反対ではない。", "送る": "届けるに近い意味で、反対ではない。", "納める": "決まった所へ渡す意味で、届けるの反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物や情報を相手に送り届ける。", "primary_collocate": null, "pronunciation": "とどける", "ipa": "todokeɾɯ", "syllable_count": 4, "sentences": [{"text": "成功の鍵は、商品の魅力を伝える写真の工夫と、ターゲット層に届けるマーケティングです。", "target_word": "届ける", "complexity_tier": "T6", "furigana": "成功[せいこう]の鍵[かぎ]は、商品[しょうひん]の魅力[みりょく]を伝[つた]える写真[しゃしん]の工夫[くふう]と、ターゲット層[そう]に届[とど]けるマーケティングです。", "sentence_source": "mined"}, {"text": "花を届ける。", "target_word": "届ける", "complexity_tier": "T1", "furigana": "花[はな]を届[とど]ける。", "sentence_source": "generated"}, {"text": "荷物を家まで届けました。", "target_word": "届け", "complexity_tier": "T2", "furigana": "荷物[にもつ]を家[いえ]まで届[とど]けました。", "sentence_source": "generated"}, {"text": "友達に手紙を届けた。", "target_word": "届けた", "complexity_tier": "T2", "furigana": "友達[ともだち]に手紙[てがみ]を届[とど]けた。", "sentence_source": "generated"}, {"text": "お客さんに、できたてのパンを届けています。", "target_word": "届けて", "complexity_tier": "T3", "furigana": "お客[きゃく]さんに、できたてのパンを届[とど]けています。", "sentence_source": "generated"}, {"text": "この会社は、全国に新鮮な野菜を届けている。", "target_word": "届けて", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、全国[ぜんこく]に新鮮[しんせん]な野菜[やさい]を届[とど]けている。", "sentence_source": "generated"}, {"text": "忘れ物を届けてくれた人にお礼を言った。", "target_word": "届けて", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]を届[とど]けてくれた人[ひと]にお礼[れい]を言[い]った。", "sentence_source": "generated"}, {"text": "私たちの思いを、多くの人に届けたいと考えている。", "target_word": "届けたい", "complexity_tier": "T4", "furigana": "私[わたし]たちの思[おも]いを、多[おお]くの人[ひと]に届[とど]けたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "配達員は、雨の日でも荷物を時間どおりに届けなければならない。", "target_word": "届けなければ", "complexity_tier": "T4", "furigana": "配達員[はいたついん]は、雨[あめ]の日[ひ]でも荷物[にもつ]を時間[じかん]どおりに届[とど]けなければならない。", "sentence_source": "generated"}, {"text": "ニュースを正しく視聴者に届けるのが、放送局の大切な役割だ。", "target_word": "届ける", "complexity_tier": "T4", "furigana": "ニュースを正[ただ]しく視聴者[しちょうしゃ]に届[とど]けるのが、放送局[ほうそうきょく]の大切[たいせつ]な役割[やくわり]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "届けた", "label": "活用"}, {"form": "届けて", "label": "活用"}, {"form": "届けられる", "label": "活用"}, {"form": "届く", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 物や情報を相手まで送る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fadb3909-14e2-49bc-a4d8-0691c24c9708') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "届ける", "is_correct": true, "explanation": "ターゲット層に商品の魅力を送り届けるという意味が合う。"}, {"text": "眠る", "is_correct": false, "explanation": "形は合うが、ターゲット層に眠るマーケティングでは意味が合わない。"}, {"text": "怒る", "is_correct": false, "explanation": "形は合うが、ターゲット層に怒るマーケティングでは意味が合わない。"}, {"text": "座る", "is_correct": false, "explanation": "形は合うが、ターゲット層に座るマーケティングでは意味が合わない。"}], "explanations": {"届ける": "ターゲット層に商品の魅力を送り届けるという意味が合う。", "眠る": "形は合うが、ターゲット層に眠るマーケティングでは意味が合わない。", "怒る": "形は合うが、ターゲット層に怒るマーケティングでは意味が合わない。", "座る": "形は合うが、ターゲット層に座るマーケティングでは意味が合わない。"}, "sentence_index": 0, "correct_answer": "届ける"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "背が高いので、一番上の棚に手を届けた。", "explanation": "「届ける」は物や情報を相手に送ることで、手が届く意味では「届く」を使う。"}, {"text": "友達に、きのうの時間を届けた。", "explanation": "時間は持って行って渡せる物ではなく、「届ける」の対象にならない。"}, {"text": "手紙が友達を届けた。", "explanation": "届ける側と届けられる物が逆で、手紙が人を届けることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "届けて", "is_correct": true, "explanation": "忘れ物を持って来てくれたという意味が合う。"}, {"text": "食べて", "is_correct": false, "explanation": "形は合うが、忘れ物を食べてくれた人にお礼という意味が合わない。"}, {"text": "飲んで", "is_correct": false, "explanation": "形は合うが、忘れ物を飲むという意味が合わない。"}, {"text": "壊して", "is_correct": false, "explanation": "形は合うが、壊してくれた人にお礼を言う意味が合わない。"}], "explanations": {"届けて": "忘れ物を持って来てくれたという意味が合う。", "食べて": "形は合うが、忘れ物を食べてくれた人にお礼という意味が合わない。", "飲んで": "形は合うが、忘れ物を飲むという意味が合わない。", "壊して": "形は合うが、壊してくれた人にお礼を言う意味が合わない。"}, "sentence_index": 6, "correct_answer": "届けて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "放送局は、ニュースを正しく視聴者を届けるのが大切な役割だ。", "explanation": "「届ける」の相手は「に」で示し、視聴者を届ける物にすると意味が誤り。"}, {"text": "手が届けるほど近くに、放送局の建物が見える。", "explanation": "距離が届く意味には自動詞「届く」を使い、「届ける」は使えない。"}, {"text": "放送局は、ニュースを雨に届けるのが大切な役割だ。", "explanation": "雨は情報を受け取る相手ではなく、「届ける」の相手として不適切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友達に花を届いた。", "corrected_sentence": "友達に花を届けた。", "error_description": "「花を」の目的語を取るのは他動詞「届ける」で、自動詞「届く」は使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "届ける", "is_correct": true, "explanation": "文末の終止形で、「花を届ける。」と文が完結する。"}, {"text": "届け", "is_correct": false, "explanation": "連用形だけでは文が終わらず、この位置では使えない。"}, {"text": "届けたり", "is_correct": false, "explanation": "「たり」は並列の途中形で、文末では使えない。"}, {"text": "届けさせ", "is_correct": false, "explanation": "使役の語幹で、このままでは文が終わらない。"}], "correct_form": "届ける", "base_form": "届ける", "form_label": "終止形", "sentence_index": 1, "explanations": {"届ける": "文末の終止形で、「花を届ける。」と文が完結する。", "届け": "連用形だけでは文が終わらず、この位置では使えない。", "届けたり": "「たり」は並列の途中形で、文末では使えない。", "届けさせ": "使役の語幹で、このままでは文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51954, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生が家まで忘れ物を届いてくれた。", "corrected_sentence": "先生が家まで忘れ物を届けてくれた。", "error_description": "「忘れ物を」を目的語に取るのは他動詞「届ける」で、自動詞「届く」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "届けたい", "is_correct": true, "explanation": "「と考えている」の前で願望を表すたい形になる。"}, {"text": "届けて", "is_correct": false, "explanation": "て形は「と考えている」に直接つながらない。"}, {"text": "届けたり", "is_correct": false, "explanation": "「たり」は並列の途中形で、この位置では使えない。"}, {"text": "届けさせ", "is_correct": false, "explanation": "使役の語幹で、「と」に直接つながらない。"}], "correct_form": "届けたい", "base_form": "届ける", "form_label": "たい形", "sentence_index": 7, "explanations": {"届けたい": "「と考えている」の前で願望を表すたい形になる。", "届けて": "て形は「と考えている」に直接つながらない。", "届けたり": "「たり」は並列の途中形で、この位置では使えない。", "届けさせ": "使役の語幹で、「と」に直接つながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740e7614-18a3-4a59-9c43-96d9d4a68f47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51955, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "発信する内容を示す「を」が合う。"}, {"text": "の", "is_correct": false, "explanation": "「情報の発信しています」は動詞の前で誤り。"}, {"text": "と", "is_correct": false, "explanation": "「情報と発信しています」は意味が通らない。"}, {"text": "や", "is_correct": false, "explanation": "「情報や発信しています」は並列にならず誤り。"}], "correct_answer": "を", "explanations": {"を": "発信する内容を示す「を」が合う。", "の": "「情報の発信しています」は動詞の前で誤り。", "と": "「情報と発信しています」は意味が通らない。", "や": "「情報や発信しています」は並列にならず誤り。"}, "error_tags": {"の": "possessive_misuse", "と": "conjunction_misuse", "や": "listing_misuse"}, "sentence_index": 3}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受信", "is_correct": true, "explanation": "情報を出す発信と、受け取る受信が反対の関係。"}, {"text": "送信", "is_correct": false, "explanation": "発信と近い意味で、反対ではない。"}, {"text": "配信", "is_correct": false, "explanation": "情報を送り出す点で近く、反対ではない。"}, {"text": "通信", "is_correct": false, "explanation": "やり取り全般で、発信の反対ではない。"}], "correct_answer": "受信", "explanations": {"受信": "情報を出す発信と、受け取る受信が反対の関係。", "送信": "発信と近い意味で、反対ではない。", "配信": "情報を送り出す点で近く、反対ではない。", "通信": "やり取り全般で、発信の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51955, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「始める」の対象を示す「を」が合う。"}, {"text": "が", "is_correct": false, "explanation": "「発信が始めて」は他動詞「始める」と合わず誤り。"}, {"text": "に", "is_correct": false, "explanation": "「発信に始めて」は文法的に誤り。"}, {"text": "と", "is_correct": false, "explanation": "「発信と始めて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「始める」の対象を示す「を」が合う。", "が": "「発信が始めて」は他動詞「始める」と合わず誤り。", "に": "「発信に始めて」は文法的に誤り。", "と": "「発信と始めて」は意味が通らない。"}, "error_tags": {"が": "subject_misuse", "に": "target_misuse", "と": "conjunction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受信", "is_correct": true, "explanation": "外に出す発信と、受け取る受信が反対の関係。"}, {"text": "発表", "is_correct": false, "explanation": "広く知らせる点で近く、反対ではない。"}, {"text": "返信", "is_correct": false, "explanation": "返事を送ることで、発信の反対ではない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で送り出す点で近く、反対ではない。"}], "correct_answer": "受信", "explanations": {"受信": "外に出す発信と、受け取る受信が反対の関係。", "発表": "広く知らせる点で近く、反対ではない。", "返信": "返事を送ることで、発信の反対ではない。", "放送": "電波で送り出す点で近く、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51955, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分から情報を外に出すこと。", "primary_collocate": null, "pronunciation": "はっしん", "ipa": "haɕːiɴ", "syllable_count": 4, "sentences": [{"text": "毎日発信する。", "target_word": "発信", "complexity_tier": "T1", "furigana": "毎日[まいにち]発信[はっしん]する。", "sentence_source": "generated"}, {"text": "情報を発信します。", "target_word": "発信", "complexity_tier": "T2", "furigana": "情報[じょうほう]を発信[はっしん]します。", "sentence_source": "generated"}, {"text": "発信は楽しいです。", "target_word": "発信", "complexity_tier": "T2", "furigana": "発信[はっしん]は楽[たの]しいです。", "sentence_source": "generated"}, {"text": "市は外国語で情報を発信しています。", "target_word": "発信", "complexity_tier": "T3", "furigana": "市[し]は外国語[がいこくご]で情報[じょうほう]を発信[はっしん]しています。", "sentence_source": "generated"}, {"text": "私は発信するのが少し苦手だ。", "target_word": "発信", "complexity_tier": "T3", "furigana": "私[わたし]は発信[はっしん]するのが少[すこ]し苦手[にがて]だ。", "sentence_source": "generated"}, {"text": "学校の情報をホームページで発信している。", "target_word": "発信", "complexity_tier": "T3", "furigana": "学校[がっこう]の情報[じょうほう]をホームページで発信[はっしん]している。", "sentence_source": "generated"}, {"text": "発信することで、新しい出会いが生まれた。", "target_word": "発信", "complexity_tier": "T3", "furigana": "発信[はっしん]することで、新[あたら]しい出会[であ]いが生[う]まれた。", "sentence_source": "generated"}, {"text": "発信を始めてから、毎日が忙しくなった。", "target_word": "発信", "complexity_tier": "T3", "furigana": "発信[はっしん]を始[はじ]めてから、毎日[まいにち]が忙[いそが]しくなった。", "sentence_source": "generated"}, {"text": "発信しなければ、自分の考えは誰にも伝わらない。", "target_word": "発信", "complexity_tier": "T4", "furigana": "発信[はっしん]しなければ、自分[じぶん]の考[かんが]えは誰[だれ]にも伝[つた]わらない。", "sentence_source": "generated"}, {"text": "小さな町の魅力が、地元の若者によって発信された。", "target_word": "発信", "complexity_tier": "T4", "furigana": "小[ちい]さな町[まち]の魅力[みりょく]が、地元[じもと]の若者[わかもの]によって発信[はっしん]された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発信する", "label": "活用"}, {"form": "発信者", "label": "派生"}, {"form": "発信源", "label": "派生"}, {"form": "発信元", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 情報を自分から外へ出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51955, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "発信", "is_correct": true, "explanation": "「はっしん」で、聞かせた語そのもの。"}, {"text": "発見", "is_correct": false, "explanation": "「はっけん」で、し→けの一音だけ違う。"}, {"text": "発散", "is_correct": false, "explanation": "「はっさん」で、し→さの一音だけ違う。"}, {"text": "発禁", "is_correct": false, "explanation": "「はっきん」で、し→きの一音だけ違う。"}], "explanations": {"発信": "「はっしん」で、聞かせた語そのもの。", "発見": "「はっけん」で、し→けの一音だけ違う。", "発散": "「はっさん」で、し→さの一音だけ違う。", "発禁": "「はっきん」で、し→きの一音だけ違う。"}, "sentence_index": null, "correct_answer": "発信"}, "level_3": {"options": [{"text": "発信", "is_correct": true, "explanation": "毎日情報を外に出すという意味で自然。"}, {"text": "消滅", "is_correct": false, "explanation": "形は合うが、消える意味なので「毎日」と合わず意味が通らない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、卒業は一度きりのことで「毎日」と合わず意味が通らない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、毎日結婚するのは意味として成り立たない。"}], "explanations": {"発信": "毎日情報を外に出すという意味で自然。", "消滅": "形は合うが、消える意味なので「毎日」と合わず意味が通らない。", "卒業": "形は合うが、卒業は一度きりのことで「毎日」と合わず意味が通らない。", "結婚": "形は合うが、毎日結婚するのは意味として成り立たない。"}, "sentence_index": 0, "correct_answer": "発信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は駅で友達からの電話を発信して、話をした。", "explanation": "「発信」は自分から出すことなので、受ける電話には使えない。"}, {"text": "発信をかぶって、外に出かけた。", "explanation": "「発信」は物ではなく行為なので、かぶる対象にならない。"}, {"text": "冷蔵庫の中の発信が腐ってしまった。", "explanation": "「発信」は食べ物ではないので、腐るものとして使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51955, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "発信", "is_correct": true, "explanation": "「はっしん」で、聞かせた語そのもの。"}, {"text": "迫真", "is_correct": false, "explanation": "「はくしん」で、っ→くの一音だけ違う。"}, {"text": "半身", "is_correct": false, "explanation": "「はんしん」で、っ→んの一音だけ違う。"}, {"text": "発汗", "is_correct": false, "explanation": "「はっかん」で、し→かの一音だけ違う。"}], "explanations": {"発信": "「はっしん」で、聞かせた語そのもの。", "迫真": "「はくしん」で、っ→くの一音だけ違う。", "半身": "「はんしん」で、っ→んの一音だけ違う。", "発汗": "「はっかん」で、し→かの一音だけ違う。"}, "sentence_index": null, "correct_answer": "発信"}, "level_3": {"options": [{"text": "発信", "is_correct": true, "explanation": "情報を出すことで新しい出会いが生まれるという流れに合う。"}, {"text": "落下", "is_correct": false, "explanation": "形は合うが、落ちる意味なので出会いが生まれる理由にならず意味が合わない。"}, {"text": "停止", "is_correct": false, "explanation": "形は合うが、止める意味なので出会いが生まれる流れに合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "形は合うが、お湯が煮え立つ意味なので出会いが生まれる理由にならない。"}], "explanations": {"発信": "情報を出すことで新しい出会いが生まれるという流れに合う。", "落下": "形は合うが、落ちる意味なので出会いが生まれる理由にならず意味が合わない。", "停止": "形は合うが、止める意味なので出会いが生まれる流れに合わない。", "沸騰": "形は合うが、お湯が煮え立つ意味なので出会いが生まれる理由にならない。"}, "sentence_index": 6, "correct_answer": "発信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、友達から来たメールを発信して、とても嬉しかった。", "explanation": "「発信」は送り出すことなので、来たメールを受け取る意味には使えない。"}, {"text": "この発信は三キロもあって、持つのが大変だ。", "explanation": "「発信」は行為なので、重さがあって持つ物としては使えない。"}, {"text": "彼は発信を履いて、山に登った。", "explanation": "「発信」は履き物ではないので、履く対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
