INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51956, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「発信する前に」と時を表す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「前を内容を」と「を」が重なり誤り。"}, {"text": "が", "is_correct": false, "explanation": "「前が内容を確認して」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「前と内容を確認して」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「発信する前に」と時を表す「に」が合う。", "を": "「前を内容を」と「を」が重なり誤り。", "が": "「前が内容を確認して」は文として成り立たない。", "と": "「前と内容を確認して」は意味が通らない。"}, "error_tags": {"を": "object_misuse", "が": "subject_misuse", "と": "conjunction_misuse"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受信", "is_correct": true, "explanation": "メッセージを送り出す発信と、受け取る受信が反対の関係。"}, {"text": "発表", "is_correct": false, "explanation": "広く知らせる点で近く、反対ではない。"}, {"text": "返信", "is_correct": false, "explanation": "返事を送ることで、発信の反対ではない。"}, {"text": "放送", "is_correct": false, "explanation": "電波で送り出す点で近く、反対ではない。"}], "correct_answer": "受信", "explanations": {"受信": "メッセージを送り出す発信と、受け取る受信が反対の関係。", "発表": "広く知らせる点で近く、反対ではない。", "返信": "返事を送ることで、発信の反対ではない。", "放送": "電波で送り出す点で近く、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51956, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "自分の考えや情報を、相手に伝えるために送り出すこと。", "primary_collocate": null, "pronunciation": "はっしん", "ipa": "haɕːiɴ", "syllable_count": 4, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "発信", "complexity_tier": "T6", "furigana": "誰[だれ]に何[なに]を求[もと]めているか分析[ぶんせき]し、適切[てきせつ]な言葉[ことば]で発信[はっしん]することで、小[ちい]さくても確実[かくじつ]なファンを獲得[かくとく]できます。", "sentence_source": "mined"}, {"text": "毎日ブログで発信しています。", "target_word": "発信", "complexity_tier": "T2", "furigana": "毎日[まいにち]ブログで発信[はっしん]しています。", "sentence_source": "generated"}, {"text": "考えを発信する。", "target_word": "発信", "complexity_tier": "T1", "furigana": "考[かんが]えを発信[はっしん]する。", "sentence_source": "generated"}, {"text": "発信が好きです。", "target_word": "発信", "complexity_tier": "T2", "furigana": "発信[はっしん]が好[す]きです。", "sentence_source": "generated"}, {"text": "彼女は動画で意見を発信している。", "target_word": "発信", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は動画[どうが]で意見[いけん]を発信[はっしん]している。", "sentence_source": "generated"}, {"text": "発信の仕方を学びたい。", "target_word": "発信", "complexity_tier": "T3", "furigana": "発信[はっしん]の仕方[しかた]を学[まな]びたい。", "sentence_source": "generated"}, {"text": "発信できるようになって、友達が増えた。", "target_word": "発信", "complexity_tier": "T3", "furigana": "発信[はっしん]できるようになって、友達[ともだち]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "発信する前に内容を確認してください。", "target_word": "発信", "complexity_tier": "T3", "furigana": "発信[はっしん]する前[まえ]に内容[ないよう]を確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "企業が積極的に発信しなければ、商品の良さは伝わらない。", "target_word": "発信", "complexity_tier": "T4", "furigana": "企業[きぎょう]が積極的[せっきょくてき]に発信[はっしん]しなければ、商品[しょうひん]の良[よ]さは伝[つた]わらない。", "sentence_source": "generated"}, {"text": "誰かが発信したメッセージが、多くの人の心を動かした。", "target_word": "発信", "complexity_tier": "T4", "furigana": "誰[だれ]かが発信[はっしん]したメッセージが、多[おお]くの人[ひと]の心[こころ]を動[うご]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発信する", "label": "活用"}, {"form": "発信者", "label": "派生"}, {"form": "発信源", "label": "派生"}, {"form": "発信力", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 考えや情報を相手へ送り出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51956, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "発信", "is_correct": true, "explanation": "「はっしん」で、聞かせた語そのもの。"}, {"text": "発見", "is_correct": false, "explanation": "「はっけん」で、し→けの一音だけ違う。"}, {"text": "発散", "is_correct": false, "explanation": "「はっさん」で、し→さの一音だけ違う。"}, {"text": "発禁", "is_correct": false, "explanation": "「はっきん」で、し→きの一音だけ違う。"}], "explanations": {"発信": "「はっしん」で、聞かせた語そのもの。", "発見": "「はっけん」で、し→けの一音だけ違う。", "発散": "「はっさん」で、し→さの一音だけ違う。", "発禁": "「はっきん」で、し→きの一音だけ違う。"}, "sentence_index": null, "correct_answer": "発信"}, "level_3": {"options": [{"text": "発信", "is_correct": true, "explanation": "適切な言葉で考えを送り出すという意味で、文脈に合う。"}, {"text": "受信", "is_correct": false, "explanation": "形は合うが、受け取る意味なのでファンを獲得する流れに合わない。"}, {"text": "削除", "is_correct": false, "explanation": "形は合うが、消す意味なのでファンの獲得につながらず意味が合わない。"}, {"text": "停止", "is_correct": false, "explanation": "形は合うが、止める意味なので適切な言葉で行う内容に合わない。"}], "explanations": {"発信": "適切な言葉で考えを送り出すという意味で、文脈に合う。", "受信": "形は合うが、受け取る意味なのでファンを獲得する流れに合わない。", "削除": "形は合うが、消す意味なのでファンの獲得につながらず意味が合わない。", "停止": "形は合うが、止める意味なので適切な言葉で行う内容に合わない。"}, "sentence_index": 0, "correct_answer": "発信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達から届いたメールを発信して、返事を書いた。", "explanation": "「発信」は自分から送り出すことなので、届いたメールを受け取る場面には使えない。"}, {"text": "昨日から発信が痛くて、薬を飲んだ。", "explanation": "「発信」は体の部分ではなく行為なので、「痛い」の主語にならない。"}, {"text": "机の上の発信を拭いて、きれいにした。", "explanation": "「発信」は物ではなく行為を表すので、拭く対象にできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51956, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "発信", "is_correct": true, "explanation": "「はっしん」で、聞かせた語そのもの。"}, {"text": "迫真", "is_correct": false, "explanation": "「はくしん」で、っ→くの一音だけ違う。"}, {"text": "半身", "is_correct": false, "explanation": "「はんしん」で、っ→んの一音だけ違う。"}, {"text": "発汗", "is_correct": false, "explanation": "「はっかん」で、し→かの一音だけ違う。"}], "explanations": {"発信": "「はっしん」で、聞かせた語そのもの。", "迫真": "「はくしん」で、っ→くの一音だけ違う。", "半身": "「はんしん」で、っ→んの一音だけ違う。", "発汗": "「はっかん」で、し→かの一音だけ違う。"}, "sentence_index": null, "correct_answer": "発信"}, "level_3": {"options": [{"text": "発信", "is_correct": true, "explanation": "できるようになったことで友達が増えるという流れに合う。"}, {"text": "削除", "is_correct": false, "explanation": "形は合うが、消す意味なので友達が増える理由として意味が合わない。"}, {"text": "中止", "is_correct": false, "explanation": "形は合うが、やめる意味なので友達が増える流れに合わない。"}, {"text": "破損", "is_correct": false, "explanation": "形は合うが、壊れる意味で「できる」と合わず意味が通らない。"}], "explanations": {"発信": "できるようになったことで友達が増えるという流れに合う。", "削除": "形は合うが、消す意味なので友達が増える理由として意味が合わない。", "中止": "形は合うが、やめる意味なので友達が増える流れに合わない。", "破損": "形は合うが、壊れる意味で「できる」と合わず意味が通らない。"}, "sentence_index": 6, "correct_answer": "発信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎朝、新聞を発信して、ニュースを読んでいる。", "explanation": "「発信」は送り出すことで、新聞を手に取って読む行為には使えない。"}, {"text": "発信を食べるのが好きで、毎日買っている。", "explanation": "「発信」は行為なので、食べる対象にならない。"}, {"text": "発信の色がとても赤くて、きれいな花だ。", "explanation": "「発信」は色を持つ物ではないので、花の色の説明に使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
