INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51957, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある人やものをとても好きな人のこと。", "primary_collocate": null, "pronunciation": "ふぁん", "ipa": "ɸaɴ", "syllable_count": 2, "sentences": [{"text": "彼はアニメのファンだ。", "target_word": "ファン", "complexity_tier": "T1", "furigana": "彼[かれ]はアニメのファンだ。", "sentence_source": "generated"}, {"text": "ファンになりました。", "target_word": "ファン", "complexity_tier": "T2", "furigana": "ファンになりました。", "sentence_source": "generated"}, {"text": "この漫画のファンは多いです。", "target_word": "ファン", "complexity_tier": "T2", "furigana": "この漫画[まんが]のファンは多[おお]いです。", "sentence_source": "generated"}, {"text": "母は昔から韓国ドラマのファンだ。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "母[はは]は昔[むかし]から韓国[かんこく]ドラマのファンだ。", "sentence_source": "generated"}, {"text": "ファンの友達と、コンサートに行ってきた。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "ファンの友達[ともだち]と、コンサートに行[い]ってきた。", "sentence_source": "generated"}, {"text": "この店のファンになって、毎週通っている。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "この店[みせ]のファンになって、毎週[まいしゅう]通[かよ]っている。", "sentence_source": "generated"}, {"text": "私もそのチームのファンになりたい。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "私[わたし]もそのチームのファンになりたい。", "sentence_source": "generated"}, {"text": "ファンだからこそ、新しい曲が少し心配になる。", "target_word": "ファン", "complexity_tier": "T4", "furigana": "ファンだからこそ、新[あたら]しい曲[きょく]が少[すこ]し心配[しんぱい]になる。", "sentence_source": "generated"}, {"text": "先生はこの本のファンだと言っていた。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "先生[せんせい]はこの本[ほん]のファンだと言[い]っていた。", "sentence_source": "generated"}, {"text": "彼女の歌に感動して、ファンになる人が増えている。", "target_word": "ファン", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の歌[うた]に感動[かんどう]して、ファンになる人[ひと]が増[ふ]えている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファンクラブ", "label": "派生"}, {"form": "ファンレター", "label": "派生"}, {"form": "ファン層", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ある対象がとても好きな人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51957, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ファン", "is_correct": true, "explanation": "「ふぁん」で、聞かせた語そのもの。"}, {"text": "パン", "is_correct": false, "explanation": "「ぱん」で、ふぁ→ぱの一音だけ違う。"}, {"text": "蘭", "is_correct": false, "explanation": "「らん」で、ふぁ→らの一音だけ違う。"}, {"text": "湾", "is_correct": false, "explanation": "「わん」で、ふぁ→わの一音だけ違う。"}, {"text": "缶", "is_correct": false, "explanation": "「かん」で、ふぁ→かの一音だけ違う。"}], "explanations": {"ファン": "「ふぁん」で、聞かせた語そのもの。", "パン": "「ぱん」で、ふぁ→ぱの一音だけ違う。", "蘭": "「らん」で、ふぁ→らの一音だけ違う。", "湾": "「わん」で、ふぁ→わの一音だけ違う。", "缶": "「かん」で、ふぁ→かの一音だけ違う。"}, "sentence_index": null, "correct_answer": "ファン"}, "level_3": {"options": [{"text": "ファン", "is_correct": true, "explanation": "アニメが好きな人という意味で文脈に合う。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、「彼はアニメの値段だ」は人の説明にならず意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「彼」が天気だという意味になり合わない。"}, {"text": "地震", "is_correct": false, "explanation": "形は合うが、「彼」が地震だという意味になり合わない。"}], "explanations": {"ファン": "アニメが好きな人という意味で文脈に合う。", "値段": "形は合うが、「彼はアニメの値段だ」は人の説明にならず意味が合わない。", "天気": "形は合うが、「彼」が天気だという意味になり合わない。", "地震": "形は合うが、「彼」が地震だという意味になり合わない。"}, "sentence_index": 0, "correct_answer": "ファン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は毎朝、ファンを食べてから学校へ行く。", "explanation": "「ファン」は人を表すので、食べ物のように食べることはできない。"}, {"text": "彼はこの問題のファンで、答えがわからない。", "explanation": "「ファン」は好きな対象への熱意を表すので、わからない問題の説明には使えない。"}, {"text": "このファンはとても甘くて、おいしいお菓子だ。", "explanation": "「ファン」は好きな人を表すので、甘いお菓子として使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXC