INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51957, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ファン", "is_correct": true, "explanation": "「ふぁん」で、聞かせた語そのもの。"}, {"text": "班", "is_correct": false, "explanation": "「はん」で、ふぁ→はの一音だけ違う。"}, {"text": "バン", "is_correct": false, "explanation": "「ばん」で、ふぁ→ばの一音だけ違う。"}, {"text": "ガン", "is_correct": false, "explanation": "「がん」で、ふぁ→がの一音だけ違う。"}, {"text": "タン", "is_correct": false, "explanation": "「たん」で、ふぁ→たの一音だけ違う。"}], "explanations": {"ファン": "「ふぁん」で、聞かせた語そのもの。", "班": "「はん」で、ふぁ→はの一音だけ違う。", "バン": "「ばん」で、ふぁ→ばの一音だけ違う。", "ガン": "「がん」で、ふぁ→がの一音だけ違う。", "タン": "「たん」で、ふぁ→たの一音だけ違う。"}, "sentence_index": null, "correct_answer": "ファン"}, "level_3": {"options": [{"text": "ファン", "is_correct": true, "explanation": "チームが好きな人になりたいという意味で自然。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、チームの机になりたいは意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、チームの季節になりたいは意味が合わない。"}, {"text": "食器", "is_correct": false, "explanation": "形は合うが、チームの食器になりたいは意味が合わない。"}], "explanations": {"ファン": "チームが好きな人になりたいという意味で自然。", "机": "形は合うが、チームの机になりたいは意味が合わない。", "季節": "形は合うが、チームの季節になりたいは意味が合わない。", "食器": "形は合うが、チームの食器になりたいは意味が合わない。"}, "sentence_index": 6, "correct_answer": "ファン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨夜、ファンが降って、道が濡れた。", "explanation": "「ファン」は人を指すので、雨のように降るものとしては使えない。"}, {"text": "私は一日に三回、ファンを磨いて、歯をきれいにする。", "explanation": "「ファン」は人なので、歯磨きの道具のように磨くことはできない。"}, {"text": "彼は昨日の宿題のファンを忘れて、先生に怒られた。", "explanation": "「ファン」は人を指すので、宿題の一部として忘れる物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validat