INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51958, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定の人物や作品、活動などを熱心に応援したり、好んだりする人のこと。", "primary_collocate": null, "pronunciation": "ふぁん", "ipa": "ɸaɴ", "syllable_count": 2, "sentences": [{"text": "誰に何を求めているか分析し、適切な言葉で発信することで、小さくても確実なファンを獲得できます。", "target_word": "ファン", "complexity_tier": "T6", "furigana": "誰[だれ]に何[なに]を求[もと]めているか分析[ぶんせき]し、適切[てきせつ]な言葉[ことば]で発信[はっしん]することで、小[ちい]さくても確実[かくじつ]なファンを獲得[かくとく]できます。", "sentence_source": "mined"}, {"text": "私はこの歌手のファンです。", "target_word": "ファン", "complexity_tier": "T2", "furigana": "私[わたし]はこの歌手[かしゅ]のファンです。", "sentence_source": "generated"}, {"text": "ファンが増えた。", "target_word": "ファン", "complexity_tier": "T1", "furigana": "ファンが増[ふ]えた。", "sentence_source": "generated"}, {"text": "彼にはファンが多い。", "target_word": "ファン", "complexity_tier": "T1", "furigana": "彼[かれ]にはファンが多[おお]い。", "sentence_source": "generated"}, {"text": "ファンの声を大切にしている。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "ファンの声[こえ]を大切[たいせつ]にしている。", "sentence_source": "generated"}, {"text": "彼女のファンになって、十年がたった。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のファンになって、十年[じゅうねん]がたった。", "sentence_source": "generated"}, {"text": "試合のあと、ファンに手を振った。", "target_word": "ファン", "complexity_tier": "T2", "furigana": "試合[しあい]のあと、ファンに手[て]を振[ふ]った。", "sentence_source": "generated"}, {"text": "ファンからの手紙を読んで、涙が出た。", "target_word": "ファン", "complexity_tier": "T3", "furigana": "ファンからの手紙[てがみ]を読[よ]んで、涙[なみだ]が出[で]た。", "sentence_source": "generated"}, {"text": "ファンがいなければ、この歌手は続けられなかっただろう。", "target_word": "ファン", "complexity_tier": "T4", "furigana": "ファンがいなければ、この歌手[かしゅ]は続[つづ]けられなかっただろう。", "sentence_source": "generated"}, {"text": "多くのファンに愛される選手になりたい。", "target_word": "ファン", "complexity_tier": "T4", "furigana": "多[おお]くのファンに愛[あい]される選手[せんしゅ]になりたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ファンクラブ", "label": "派生"}, {"form": "ファンレター", "label": "派生"}, {"form": "ファン層", "label": "派生"}, {"form": "ファン心理", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人物や作品を熱心に応援する人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51958, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ファン", "is_correct": true, "explanation": "「ふぁん」で、聞かせた語そのもの。"}, {"text": "パン", "is_correct": false, "explanation": "「ぱん」で、ふぁ→ぱの一音だけ違う。"}, {"text": "蘭", "is_correct": false, "explanation": "「らん」で、ふぁ→らの一音だけ違う。"}, {"text": "湾", "is_correct": false, "explanation": "「わん」で、ふぁ→わの一音だけ違う。"}, {"text": "缶", "is_correct": false, "explanation": "「かん」で、ふぁ→かの一音だけ違う。"}], "explanations": {"ファン": "「ふぁん」で、聞かせた語そのもの。", "パン": "「ぱん」で、ふぁ→ぱの一音だけ違う。", "蘭": "「らん」で、ふぁ→らの一音だけ違う。", "湾": "「わん」で、ふぁ→わの一音だけ違う。", "缶": "「かん」で、ふぁ→かの一音だけ違う。"}, "sentence_index": null, "correct_answer": "ファン"}, "level_3": {"options": [{"text": "ファン", "is_correct": true, "explanation": "応援してくれる人を獲得するという意味で文脈に合う。"}, {"text": "借金", "is_correct": false, "explanation": "形は合うが、「確実な借金を獲得」は意味が合わない。"}, {"text": "赤字", "is_correct": false, "explanation": "形は合うが、赤字を獲得するのは意味が合わない。"}, {"text": "風邪", "is_correct": false, "explanation": "形は合うが、発信の結果として獲得するものではなく意味が合わない。"}], "explanations": {"ファン": "応援してくれる人を獲得するという意味で文脈に合う。", "借金": "形は合うが、「確実な借金を獲得」は意味が合わない。", "赤字": "形は合うが、赤字を獲得するのは意味が合わない。", "風邪": "形は合うが、発信の結果として獲得するものではなく意味が合わない。"}, "sentence_index": 0, "correct_answer": "ファン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日、ファンを三つ食べて、おなかがいっぱいになった。", "explanation": "「ファン」は人を表すので、食べ物のように数えて食べることはできない。"}, {"text": "あの歌手が大嫌いなので、私は昔からそのファンだ。", "explanation": "「ファン」は好きで応援する人なので、大嫌いという理由とは矛盾する。"}, {"text": "ファンが痛くなったので、病院で薬をもらった。", "explanation": "「ファン」は体の部分ではないので、痛くなる主語として使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51958, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ファン", "is_correct": true, "explanation": "「ふぁん」で、聞かせた語そのもの。"}, {"text": "班", "is_correct": false, "explanation": "「はん」で、ふぁ→はの一音だけ違う。"}, {"text": "バン", "is_correct": false, "explanation": "「ばん」で、ふぁ→ばの一音だけ違う。"}, {"text": "ガン", "is_correct": false, "explanation": "「がん」で、ふぁ→がの一音だけ違う。"}, {"text": "タン", "is_correct": false, "explanation": "「たん」で、ふぁ→たの一音だけ違う。"}], "explanations": {"ファン": "「ふぁん」で、聞かせた語そのもの。", "班": "「はん」で、ふぁ→はの一音だけ違う。", "バン": "「ばん」で、ふぁ→ばの一音だけ違う。", "ガン": "「がん」で、ふぁ→がの一音だけ違う。", "タン": "「たん」で、ふぁ→たの一音だけ違う。"}, "sentence_index": null, "correct_answer": "ファン"}, "level_3": {"options": [{"text": "ファン", "is_correct": true, "explanation": "試合のあとに手を振る相手として自然。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが、机に手を振るのは意味が合わない。"}, {"text": "時計", "is_correct": false, "explanation": "形は合うが、時計に手を振るのは意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、天気に手を振るのは意味が合わない。"}], "explanations": {"ファン": "試合のあとに手を振る相手として自然。", "机": "形は合うが、机に手を振るのは意味が合わない。", "時計": "形は合うが、時計に手を振るのは意味が合わない。", "天気": "形は合うが、天気に手を振るのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "ファン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道を歩いていたら、ファンにかまれて足が腫れた。", "explanation": "「ファン」は応援する人を指すので、かみつく動物の意味では使えない。"}, {"text": "冷たいファンを一杯飲んで、のどのかわきを止めた。", "explanation": "「ファン」は人なので、飲み物のように飲むことはできない。"}, {"text": "駅のファンは十時に出発して、東京へ向かった。", "explanation": "「ファン」は人を指すので、駅から出発する乗り物の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2ce1361-c406-4b52-ad3a-774114edd608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_