INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51959, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お店の品物を、たくさんの人に知ってもらうための工夫や活動のこと。", "primary_collocate": null, "pronunciation": "まーけてぃんぐ", "ipa": "maːketʲiŋɡɯ", "syllable_count": 6, "sentences": [{"text": "お店のマーケティングを考えます。", "target_word": "マーケティング", "complexity_tier": "T2", "furigana": "お店[みせ]のマーケティングを考[かんが]えます。", "sentence_source": "generated"}, {"text": "マーケティングが大切です。", "target_word": "マーケティング", "complexity_tier": "T2", "furigana": "マーケティングが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "父のパン屋は、マーケティングが上手だ。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "父[ちち]のパン屋[や]は、マーケティングが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "マーケティングのおかげで、お客さんが増えた。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "マーケティングのおかげで、お客[きゃく]さんが増[ふ]えた。", "sentence_source": "generated"}, {"text": "小さな店でも、マーケティングを工夫している。", "target_word": "マーケティング", "complexity_tier": "T3", "furigana": "小[ちい]さな店[みせ]でも、マーケティングを工夫[くふう]している。", "sentence_source": "generated"}, {"text": "商品を知ってもらうために、マーケティングを始めた。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "商品[しょうひん]を知[し]ってもらうために、マーケティングを始[はじ]めた。", "sentence_source": "generated"}, {"text": "私は店のマーケティングについて、友達に相談した。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "私[わたし]は店[みせ]のマーケティングについて、友達[ともだち]に相談[そうだん]した。", "sentence_source": "generated"}, {"text": "マーケティングを学べば、店の商品をもっと知ってもらえる。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "マーケティングを学[まな]べば、店[みせ]の商品[しょうひん]をもっと知[し]ってもらえる。", "sentence_source": "generated"}, {"text": "マーケティングの本を読んで、ポスターを作ってみた。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "マーケティングの本[ほん]を読[よ]んで、ポスターを作[つく]ってみた。", "sentence_source": "generated"}, {"text": "商店街のマーケティングは、みんなで話し合って決められた。", "target_word": "マーケティング", "complexity_tier": "T4", "furigana": "商店街[しょうてんがい]のマーケティングは、みんなで話[はな]し合[あ]って決[き]められた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "マーケター", "label": "派生"}, {"form": "マーケティング戦略", "label": "派生"}, {"form": "ネットマーケティング", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 店の品を知ってもらう工夫や活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a39150a-21a7-47ec-ad3d-64f57f18784e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
